IF RawIn >= Neutral THEN
    Delta := INT_TO_REAL(10000 - Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
ELSE
    Delta := INT_TO_REAL(Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
END_IF;

IF ABS(OutPct) <= Deadband THEN
    OutPct := 0.0;
END_IF;

// 🛡️ Limitation de plage : une valeur brute hors plage nominale ne doit jamais
// produire une consigne supérieure à ±100 %. Ce garde-fou protège les
// consommateurs en aval, notamment la translation M3.
OutPct := LIMIT(-100.0, OutPct, 100.0);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Brake) ===

// 🛑 1. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
        State := E_State.DONE;
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
        State := E_State.BUSY;
    END_IF;
ELSE
    // 🆕 REX 2026-07-08 : Sécurité positive - fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY);
Done := (State = E_State.DONE);

// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (NOT BrakeCmd AND ContactorFeedback);  // commandé collé mais retour "relâché"
        ContactorCheck.StuckOpen   := (BrakeCmd AND NOT ContactorFeedback);  // commandé relâché mais retour "collé"
        ErrorId := ErrorId OR 16#0001;
    ELSIF ResetEdge.Q THEN
        ContactorCheck.StuckClosed := FALSE;
        ContactorCheck.StuckOpen   := FALSE;
        ErrorId := ErrorId AND 16#FFFE;
    END_IF;
ELSE
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
    ErrorId := ErrorId AND 16#FFFE;   // Bypass actif : efface/maintient à 0 le bit 0
END_IF;

// 🧾 5. ARBITRAGE ERROR / STATEATERROR (figé jusqu'à acquittement)
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🛡️ 6. SORTIE SÛRE SUR DÉFAUT (Partie3 §9 étape 7 — ajout revue de code 2026-07-01)
// Incohérence commande/retour détectée : on ne peut plus se fier à la séquence temporisée
// normale (le contacteur suspect biaiserait la logique) → position sûre par défaut (collé).
IF Error THEN
    BrakeCmd := FALSE;
END_IF;

// 🛑 1. GATE DE SÉCURITÉ
IF NOT Enable OR NOT EmergencyStopOk THEN
    IF (State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    State := E_State.DISABLED;
    M1SlipDetected := FALSE; // 🔧 REX 2026-07-07
    // Les requêtes internes sont réinitialisées
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

// 🟢 ÉTAT INITIAL READY SI DISABLED PRÉCÉDEMMENT
IF State = E_State.DISABLED THEN
    State := E_State.READY;
END_IF;

// 🔑 2. GESTION DU RESET (FRONT MONTANT)
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 (ignore toutes les erreurs benne)
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFA; // Efface les bits 0 et 2 (Timeout, Limites)
END_IF;

// 📏 3. DÉTECTION D'INCOHÉRENCE AU BOOT (PREMIER CYCLE API)
IF FirstCycle THEN
    FirstCycle := FALSE;
    IF Config.CoherenceLimitM > 0.01 THEN
        IF BucketState.IsOpen AND NOT BucketState.IsClosed THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Open) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSIF BucketState.IsClosed AND NOT BucketState.IsOpen THEN
            IF ABS(CablePosM2 - BucketState.LastPosM2Close) > Config.CoherenceLimitM THEN
                BucketState.StateIncoherent := TRUE;
            END_IF;
        ELSE
            // Si l'état n'a jamais été initialisé (les deux FALSE/TRUE), on signale une incohérence
            BucketState.StateIncoherent := TRUE;
        END_IF;
    ELSE
        // Limite non configurée ou invalide, par précaution on force l'incohérence
        BucketState.StateIncoherent := TRUE;
    END_IF;
END_IF;

// Met à jour le bit1 d'erreur si incohérence détectée
IF BucketState.StateIncoherent THEN
    ErrorId := ErrorId OR 16#0002;
    // 🆕 REX 2026-07-08 : Force l'état inconnu (ni ouvert ni fermé) si incohérence active
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧲 3bis. GARDE-FOU CODEURS NON RÉFÉRENCÉS (bit 3) — REX 2026-07-07
// CablePosM1/CablePosM2 ne sont fiables que si le homing (Partie10) a été fait sur les 2 treuils.
// Continu (pas de front Reset) : se lève/efface tout seul selon l'état réel du homing.
IF NOT HomedM1 OR NOT HomedM2 THEN
    ErrorId := ErrorId OR 16#0008;
ELSE
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🆕 3bis-bis. CONFIRMATION MANUELLE POSITION OUVERTE (mise en service, REX 2026-07-08) — voir bandeau
// Action de CONFIRMATION pure (aucun mouvement, ne pilote pas M2) : mémorise BucketState.IsOpen
// directement, à utiliser juste après le référencement des codeurs (M1=M2, benne physiquement
// ouvert vérifié par l'opérateur). Gardée comme BtnConfirmCoherence (FB_Encoder_Homing) : front,
// MAINT_N1/N2 uniquement, codeurs déjà référencés, treuils à l'arrêt (pas de séquence en cours).
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.LastPosM2Close := CablePosM2 - Config.OffsetOpenM + Config.OffsetCloseM; // 🆕 Initialisation théorique cohérente avec les offsets configurés
    BucketState.StateIncoherent := FALSE;
    ErrorId := 16#0000;             // 🆕 REX 2026-07-08 : Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // 🆕 REX 2026-07-08 : Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 🆕 3bis-ter. CONFIRMATION MANUELLE POSITION FERMÉE (mise en service, REX 2026-07-08)
// Même principe que ConfirmOpenPosition, mais pour initialiser le benne comme FERMÉ.
ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2)
   AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.LastPosM2Open := CablePosM2 - Config.OffsetCloseM + Config.OffsetOpenM; // 🆕 Initialisation théorique cohérente avec les offsets configurés
    BucketState.StateIncoherent := FALSE;
    ErrorId := 16#0000;             // 🆕 REX 2026-07-08 : Réinitialisation complète des défauts benne lors du référencement manuel
    CloseReq := FALSE;              // 🆕 REX 2026-07-08 : Reset des demandes en attente pour éviter les démarrages intempestifs
    OpenReq := FALSE;
END_IF;

// 🔍 3ter. MÉCA C COUCHE 1 — GLISSEMENT M1 PENDANT BUSY (bit4) — REX 2026-07-07
// M1 doit rester immobile pendant que M2 bouge seul. Référence prise à l'entrée en Busy.
BusyEdge(CLK := (State = E_State.BUSY));
IF BusyEdge.Q THEN
    M1RefPosM := CablePosM1;
    M2StartPosM := CablePosM2;   // 🆕 REX 2026-07-08 — borne le recul autorisé (voir §6 CASE BUSY)
    // 🆕 REX 2026-07-08 (demande utilisateur) : mémorise l'état d'origine (restauré si recul complet
    // jusqu'à M2StartPosM, voir §6 CASE BUSY) puis passe en position transitoire dès le démarrage du
    // mouvement — ni ouvert ni fermé pendant le trajet, quel que soit l'état mémorisé avant.
    WasOpenAtStart := BucketState.IsOpen;
    WasClosedAtStart := BucketState.IsClosed;
    LeftStartSinceArm := FALSE;
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := FALSE;
END_IF;

IF (State = E_State.BUSY) AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM) AND NOT InhibitM1 THEN
    ErrorId := ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFEF;
END_IF;
M1SlipDetected := (ErrorId AND 16#0010) <> 16#0000;

// 🚨 4. SURVEILLANCE DES LIMITES DE PLACEMENT (Limites dépassées - bit 2)
// On s'assure que l'écart réel M1/M2 ne dépasse pas les offsets de configuration + marge de sécurité de 1m
MaxAllowedOffset := MAX(ABS(Config.OffsetOpenM), ABS(Config.OffsetCloseM)) + 1.0;
IF (ABS(CablePosM1 - CablePosM2) > MaxAllowedOffset) AND NOT InhibitM1 AND NOT InhibitM2 THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// ⏲️ 5. SURVEILLANCE TIMEOUT MOUVEMENT (bit 0)
// Déclenche si le mouvement actif (M2_StartStop = TRUE) dure plus longtemps que le timeout
TonTimeout(IN := (State = E_State.BUSY AND M2_StartStop), PT := CfgTimeoutDuration);
IF TonTimeout.Q THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;

// ❌ Évaluation des erreurs graves (Timeout, Limites dépassées, Codeur(s) non référencé(s), ou Glissement M1)
SevereError := (ErrorId AND 16#001D) <> 16#0000;

IF SevereError THEN
    IF (State = E_State.BUSY) OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    M2_StartStop := FALSE;
    M2_Direction := 0;
    M2_ForceSlowSpeed := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    // On repasse en READY et attend un Reset
    State := E_State.READY;
END_IF;

// 🎛️ 6. MACHINE À ÉTATS DE COMMANDE
CASE State OF
    E_State.READY:
        Ready := TRUE;
        Busy := FALSE;
        Done := FALSE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // 🔧 REX 2026-07-07 : pas de mouvement en cours

        // 🆕 REX 2026-07-08 : demande benne acceptée UNIQUEMENT si M1 ET M2 sont à l'arrêt (tous
        // modes) — évite qu'un mouvement en cours sur l'un des deux treuils "traverse" l'armement
        // du benne (audit sécurité). Ni mémorisation de la requête, ni démarrage tant que ce
        // n'est pas vrai — l'opérateur doit refaire la demande une fois les treuils arrêtés.
        IF NOT M1_Busy AND NOT M2_Busy THEN
            // Mémorisation des requêtes IHM (l'une annule l'autre)
            IF CmdClose_IHM AND NOT SevereError THEN
                CloseReq := TRUE;
                OpenReq := FALSE;
            ELSIF CmdOpen_IHM AND NOT SevereError THEN
                OpenReq := TRUE;
                CloseReq := FALSE;
            END_IF;

            // Condition d'activation du mouvement (Requête IHM + Validation Joystick dans le bon sens)
            // ⚠️ REX 2026-07-07 : sens inversés (enroulage ferme désormais, déroulage ouvre)
            IF CloseReq AND JoystickY_StartStop AND (JoystickY_Direction = 1) THEN
                State := E_State.BUSY;
            ELSIF OpenReq AND JoystickY_StartStop AND (JoystickY_Direction = -1) THEN
                State := E_State.BUSY;
            END_IF;
        END_IF;

    E_State.BUSY:
        Ready := TRUE;
        Busy := TRUE;
        Done := FALSE;
        M2_ForceSlowSpeed := TRUE; // Vitesse lente forcée sans contacteurs

        // 📏 REX 2026-07-07 : distance restante avant cible, pour affichage IHM (aiguille/jauge)
        // Toujours positive, décroît vers 0 à mesure que M2 approche la cible.
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
        ELSE
            RemainingTravelM := 0.0;
        END_IF;

        // Interlock Homme-mort joystick
        // 🆕 REX 2026-07-08 : sens inverse autorisé (recul/annulation partielle) pendant CloseReq/
        // OpenReq, mais BORNÉ à la position de départ (M2StartPosM, mémorisée à l'entrée en Busy) —
        // ne permet jamais de dépasser cette position dans le sens opposé au sens principal.
        IF NOT JoystickY_StartStop THEN
            // Si relâchement du joystick, arrêt temporaire du mouvement
            M2_StartStop := FALSE;
            M2_Direction := 0;
        ELSIF CloseReq THEN
            IF (JoystickY_Direction = 1) THEN
                // Sens principal (fermeture) : M2 enroule (monte) — REX 2026-07-07
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSIF (JoystickY_Direction = -1) AND (CablePosM2 > M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de ré-ouverture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSE
                // Mauvais sens, ou position de départ déjà atteinte en reculant : arrêt
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSIF OpenReq THEN
            IF (JoystickY_Direction = -1) THEN
                // Sens principal (ouverture) : M2 déroule (descend) — REX 2026-07-07
                M2_StartStop := TRUE;
                M2_Direction := -1;
            ELSIF (JoystickY_Direction = 1) AND (CablePosM2 < M2StartPosM) THEN
                // Sens inverse : recul autorisé UNIQUEMENT tant qu'on n'est pas revenu à la position
                // de départ (pas au-delà, donc pas de re-fermeture complète depuis ici)
                M2_StartStop := TRUE;
                M2_Direction := 1;
            ELSE
                M2_StartStop := FALSE;
                M2_Direction := 0;
            END_IF;
        ELSE
            M2_StartStop := FALSE;
            M2_Direction := 0;
        END_IF;

        // 🆕 REX 2026-07-08 : détecte qu'on a réellement quitté la position de départ (évite que le
        // test de retour ci-dessous ne se déclenche instantanément au 1er cycle de Busy, où
        // CablePosM2 = M2StartPosM par définition).
        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Condition d'arrêt automatique de la fermeture
        IF CloseReq THEN
            // Cible atteinte : M2 a assez enroulé (CablePosM2 croissant) — REX 2026-07-07
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique fermé
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                CloseReq := FALSE;
                State := E_State.DONE;
            // 🆕 REX 2026-07-08 (demande utilisateur) : recul complet jusqu'à la position de départ —
            // restaure l'état d'origine (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                CloseReq := FALSE;
                State := E_State.DONE;
            END_IF;
        END_IF;

        // Condition d'arrêt automatique de l'ouverture
        IF OpenReq THEN
            // Cible atteinte : M2 a assez déroulé (CablePosM2 décroissant) — REX 2026-07-07
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                // Mémorisation de l'état physique ouvert
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE; // recalage réussi

                OpenReq := FALSE;
                State := E_State.DONE;
            // 🆕 REX 2026-07-08 (demande utilisateur) : recul complet jusqu'à la position de départ —
            // restaure l'état d'origine (physiquement, on est revenu là où on a commencé)
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_StartStop := FALSE;
                M2_Direction := 0;

                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;

                OpenReq := FALSE;
                State := E_State.DONE;
            END_IF;
        END_IF;

    E_State.DONE:
        Ready := TRUE;
        Busy := FALSE;
        Done := TRUE;
        M2_StartStop := FALSE;
        M2_Direction := 0;
        M2_ForceSlowSpeed := FALSE;
        RemainingTravelM := 0.0; // 🔧 REX 2026-07-07 : cible atteinte

        // Attente du relâchement de la validation joystick pour repasser à READY
        IF NOT JoystickY_StartStop THEN
            State := E_State.READY;
        END_IF;
END_CASE;

// 📤 7. GESTION DES SORTIES D'ÉTAT GLOBALES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Détermination de l'offset actif pour le synchronisme de FB_WinchSync ET pour l'affichage IHM
// (M2PositionCorrected, côté PRG_09_Supervision).
// 🔧 REX 2026-07-08 : ajout de CloseReq/OpenReq (pas seulement IsClosed/IsOpen, qui sont FALSE
// pendant TOUT le trajet depuis le REX du 2026-07-08 sur l'état transitoire) — sinon
// ActiveOffsetM restait figé sur OffsetOpenM (défaut) pendant le trajet entier d'une fermeture,
// donc M2PositionCorrected = CablePosM2 brut tout du long, avec un saut brutal uniquement à
// l'arrivée (constat terrain) au lieu de converger progressivement vers M1 pendant l'enroulage.
IF State = E_State.BUSY THEN
    // 🔧 REX 2026-07-08 : pendant le déplacement, l'offset actif suit la différence réelle
    // de câble (M2 - M1) afin que la position corrigée de M2 reste stable (égale à M1, cad la hauteur du benne)
    // sans à-coup, tandis que le câble brut de M2 montre son enroulement.
    ActiveOffsetM := CablePosM2 - CablePosM1;
ELSIF CloseReq OR BucketState.IsClosed THEN
    ActiveOffsetM := Config.OffsetCloseM;
ELSE
    // Par défaut, ou en cours/état d'ouverture, on applique l'offset ouvert
    ActiveOffsetM := Config.OffsetOpenM;
END_IF;

// === IMPLEMENTATION ===

// 1. 🛡️ GATE
IF NOT GVL_Simulation.SimulationModeActive THEN
    Sequencer(Start := FALSE, Abort := TRUE, CaseId := CaseId,
              StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
              ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report);

    SimGateOk := FALSE;
    RETURN;
END_IF;

// Gate spécifique Bucket : refuse si M1 ou M2 sont en simulation réelle (Sûreté)
SimGateOk := NOT GVL_Simulation.BusEncoderM1IsReal AND NOT GVL_Simulation.BusEncoderM2IsReal;

// 🔧 REX 2026-07-17 : garde-fou REFERENCE TO — PRG_00_Inputs (qui appelle cette suite via
// FB_PLC_Tests_Management) s'exécute AVANT PRG_06_WinchControl dans l'ordre du scan (00 avant 06).
// GVL_Simulation.LinkBucket/LinkWinchM2 ne sont assignés qu'en fin de PRG_06_WinchControl -> au tout
// premier scan, ces références sont encore invalides. Déréférencer instBucket.xxx sans ce garde
// provoquait une EXCEPTION RUNTIME CODESYS (accès référence invalide) au démarrage de la simulation.
IF NOT __ISVALIDREF(instBucket) OR NOT __ISVALIDREF(instWinchM2) THEN
    Busy := FALSE;
    RETURN;
END_IF;

// 2. 📋 TABLES
IF NOT TableReady THEN
    Report.Name := 'Bucket Validation';

    // Cas de tests
    CaseTable[1].Name := 'TC-B1 Glissement Modéré';
    CaseTable[1].FirstStep := StepB1Setup;

    CaseTable[2].Name := 'TC-B2 Glissement Critique';
    CaseTable[2].FirstStep := StepB2Setup;

    CaseTable[3].Name := 'TC-B3 Butée Haute Dynamique';
    CaseTable[3].FirstStep := StepB3Setup;

    CaseTable[4].Name := 'TC-B4 Cohérence Boot';
    CaseTable[4].FirstStep := StepB4Setup;

    CaseTable[5].Name := 'TC-B5 Homing & Inhibition';
    CaseTable[5].FirstStep := StepB5Setup;

    CaseTable[6].Name := 'TC-B6 Homme-Mort & Recul';
    CaseTable[6].FirstStep := StepB6Setup;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES CHECKS
    // ─────────────────────────────────────────────────────────────
    // Chk 1: Attente état sain
    CheckTable[1].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[1].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[1].ProbeIdx := SigHealthyIdle;
    CheckTable[1].ExpectedBool := TRUE;

    // Chk 2: Bucket Busy
    CheckTable[2].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[2].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[2].ProbeIdx := SigBucketBusy;
    CheckTable[2].ExpectedBool := TRUE;

    // Chk 3: Glissement M1 détecté
    CheckTable[3].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[3].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[3].ProbeIdx := SigM1SlipDetected;
    CheckTable[3].ExpectedBool := TRUE;

    // Chk 4: Bit ErrorId 4 levé (16#0010)
    CheckTable[4].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[4].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[4].ProbeIdx := SigBucketErrorId;
    CheckTable[4].Mask := 16#0010;

    // Chk 5: Coupure immédiate M2
    CheckTable[5].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[5].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[5].ProbeIdx := SigM2StartStop;
    CheckTable[5].ExpectedBool := FALSE;

    // Chk 6: SafeStop M1 activé
    CheckTable[6].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[6].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[6].ProbeIdx := SigM1SafeStop;
    CheckTable[6].ExpectedBool := TRUE;

    // Chk 7: PowerCutOff M1 NON activé (Couche 1 seulement)
    CheckTable[7].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[7].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[7].ProbeIdx := SigM1PowerCutOff;
    CheckTable[7].ExpectedBool := FALSE;

    // Chk 8: PowerCutOff M1 activé (Couche 2)
    CheckTable[8].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[8].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[8].ProbeIdx := SigM1PowerCutOff;
    CheckTable[8].ExpectedBool := TRUE;

    // Chk 9: Défaut Safety M1 Bit 9 (16#0200)
    CheckTable[9].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[9].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[9].ProbeIdx := SigSafetyM1ErrorId;
    CheckTable[9].Mask := 16#0200;

    // Chk 10: limite haute d'exploitation standard (8,0 m)
    CheckTable[10].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[10].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[10].ProbeIdx := SigM2TopLimit;
    CheckTable[10].RealMin := 8.0;
    CheckTable[10].RealMax := 8.1;

    // Chk 11: Bucket fermé mémorisé
    CheckTable[11].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[11].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[11].ProbeIdx := SigBucketIsClosed;
    CheckTable[11].ExpectedBool := TRUE;

    // Chk 12: limite haute décalée par la benne fermée (+10 m → 18 m)
    CheckTable[12].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[12].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[12].ProbeIdx := SigM2TopLimit;
    CheckTable[12].RealMin := 18.0;
    CheckTable[12].RealMax := 18.1;

    // Chk 13: Erreur Bucket active
    CheckTable[13].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[13].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[13].ProbeIdx := SigBucketError;
    CheckTable[13].ExpectedBool := TRUE;

    // Chk 14: Bit ErrorId 1 levé (Incohérence boot)
    CheckTable[14].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[14].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[14].ProbeIdx := SigBucketErrorId;
    CheckTable[14].Mask := 16#0002;

    // Chk 15: États mémorisés forcés à FALSE
    CheckTable[15].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[15].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[15].ProbeIdx := SigBucketIsOpen;
    CheckTable[15].ExpectedBool := FALSE;

    // Chk 16: Idem pour IsClosed
    CheckTable[16].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[16].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[16].ProbeIdx := SigBucketIsClosed;
    CheckTable[16].ExpectedBool := FALSE;

    // Chk 17: Bucket ouvert mémorisé après recalage
    CheckTable[17].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[17].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[17].ProbeIdx := SigBucketIsOpen;
    CheckTable[17].ExpectedBool := TRUE;

    // Chk 18: Bit ErrorId 3 levé (Non référencé)
    CheckTable[18].Kind := E_TestCheckKind.WORD_MASK_ALL;
    CheckTable[18].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[18].ProbeIdx := SigBucketErrorId;
    CheckTable[18].Mask := 16#0008;

    // Chk 19: Bucket non opérationnel
    CheckTable[19].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[19].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[19].ProbeIdx := SigHealthyIdle;
    CheckTable[19].ExpectedBool := FALSE;

    // Chk 20: Glissement M1 ignoré pendant inhibition
    CheckTable[20].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[20].Mode := E_TestCheckMode.CHECK_NEVER_DURING;
    CheckTable[20].ProbeIdx := SigM1SlipDetected;
    CheckTable[20].ExpectedBool := TRUE;

    // Chk 21: Mouvement terminé
    CheckTable[21].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[21].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[21].ProbeIdx := SigBucketDone;
    CheckTable[21].ExpectedBool := TRUE;

    // Chk 22: Direction M2 = -1 (Déroulage)
    CheckTable[22].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[22].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[22].ProbeIdx := SigM2Direction;
    CheckTable[22].ExpectedDint := -1;

    // Chk 23: M2 ne dépasse pas la position de départ (Sonde Real)
    CheckTable[23].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[23].Mode := E_TestCheckMode.CHECK_NEVER_DURING;
    CheckTable[23].ProbeIdx := SigM2CablePos;
    CheckTable[23].RealMin := 0.0; // Valeur relative simulée ici
    CheckTable[23].RealMax := 0.1;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES ÉTAPES (StepTable)
    // ─────────────────────────────────────────────────────────────
    // TC-B1 : Glissement Modéré
    StepTable[StepB1Setup].Name := 'Tcb1 Setup saine';
    StepTable[StepB1Setup].CaseId := 1;
    StepTable[StepB1Setup].StimulusId := 1;
    StepTable[StepB1Setup].CheckIdx[1] := 1;
    StepTable[StepB1Setup].TimeoutPT := T#12s;
    StepTable[StepB1Setup].NextOnPass := StepB1Trigger;
    StepTable[StepB1Setup].NextOnFail := StepB1Teardown;
    StepTable[StepB1Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB1Trigger].Name := 'Tcb1 Trigger fermeture';
    StepTable[StepB1Trigger].CaseId := 1;
    StepTable[StepB1Trigger].StimulusId := 2;
    StepTable[StepB1Trigger].CheckIdx[1] := 2;
    StepTable[StepB1Trigger].TimeoutPT := T#5s;
    StepTable[StepB1Trigger].NextOnPass := StepB1Slip;
    StepTable[StepB1Trigger].NextOnFail := StepB1Teardown;
    StepTable[StepB1Trigger].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB1Slip].Name := 'Tcb1 Detection glissement';
    StepTable[StepB1Slip].CaseId := 1;
    StepTable[StepB1Slip].StimulusId := 3;
    StepTable[StepB1Slip].CheckIdx[1] := 3;
    StepTable[StepB1Slip].CheckIdx[2] := 5;
    StepTable[StepB1Slip].CheckIdx[3] := 6;
    StepTable[StepB1Slip].CheckIdx[4] := 7;
    StepTable[StepB1Slip].TimeoutPT := T#2s;
    StepTable[StepB1Slip].NextOnPass := StepB1Teardown;
    StepTable[StepB1Slip].NextOnFail := StepB1Teardown;
    StepTable[StepB1Slip].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB1Teardown].Name := 'Tcb1 Teardown';
    StepTable[StepB1Teardown].CaseId := 1;
    StepTable[StepB1Teardown].StimulusId := 1;
    StepTable[StepB1Teardown].CheckIdx[1] := 1;
    StepTable[StepB1Teardown].TimeoutPT := T#12s;
    StepTable[StepB1Teardown].NextOnPass := StepB2Setup;
    StepTable[StepB1Teardown].NextOnFail := StepB2Setup;
    StepTable[StepB1Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B2 : Glissement Critique
    StepTable[StepB2Setup].Name := 'Tcb2 Setup saine';
    StepTable[StepB2Setup].CaseId := 2;
    StepTable[StepB2Setup].StimulusId := 1;
    StepTable[StepB2Setup].CheckIdx[1] := 1;
    StepTable[StepB2Setup].TimeoutPT := T#12s;
    StepTable[StepB2Setup].NextOnPass := StepB2Trigger;
    StepTable[StepB2Setup].NextOnFail := StepB2Teardown;
    StepTable[StepB2Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB2Trigger].Name := 'Tcb2 Trigger fermeture';
    StepTable[StepB2Trigger].CaseId := 2;
    StepTable[StepB2Trigger].StimulusId := 2;
    StepTable[StepB2Trigger].CheckIdx[1] := 2;
    StepTable[StepB2Trigger].TimeoutPT := T#5s;
    StepTable[StepB2Trigger].NextOnPass := StepB2CriticalSlip;
    StepTable[StepB2Trigger].NextOnFail := StepB2Teardown;
    StepTable[StepB2Trigger].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB2CriticalSlip].Name := 'Tcb2 Escalade PowerCutOff';
    StepTable[StepB2CriticalSlip].CaseId := 2;
    StepTable[StepB2CriticalSlip].StimulusId := 4;
    StepTable[StepB2CriticalSlip].CheckIdx[1] := 3;
    StepTable[StepB2CriticalSlip].CheckIdx[2] := 8;
    StepTable[StepB2CriticalSlip].CheckIdx[3] := 9;
    StepTable[StepB2CriticalSlip].TimeoutPT := T#2s;
    StepTable[StepB2CriticalSlip].NextOnPass := StepB2Teardown;
    StepTable[StepB2CriticalSlip].NextOnFail := StepB2Teardown;
    StepTable[StepB2CriticalSlip].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB2Teardown].Name := 'Tcb2 Teardown';
    StepTable[StepB2Teardown].CaseId := 2;
    StepTable[StepB2Teardown].StimulusId := 1;
    StepTable[StepB2Teardown].CheckIdx[1] := 1;
    StepTable[StepB2Teardown].TimeoutPT := T#12s;
    StepTable[StepB2Teardown].NextOnPass := StepB3Setup;
    StepTable[StepB2Teardown].NextOnFail := StepB3Setup;
    StepTable[StepB2Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B3 : Butée Haute Dynamique
    StepTable[StepB3Setup].Name := 'Tcb3 Setup saine';
    StepTable[StepB3Setup].CaseId := 3;
    StepTable[StepB3Setup].StimulusId := 1;
    StepTable[StepB3Setup].CheckIdx[1] := 1;
    StepTable[StepB3Setup].TimeoutPT := T#12s;
    StepTable[StepB3Setup].NextOnPass := StepB3CheckOpenLimit;
    StepTable[StepB3Setup].NextOnFail := StepB3Teardown;
    StepTable[StepB3Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3CheckOpenLimit].Name := 'Tcb3 Verif Limite Standard';
    StepTable[StepB3CheckOpenLimit].CaseId := 3;
    StepTable[StepB3CheckOpenLimit].StimulusId := 0;
    StepTable[StepB3CheckOpenLimit].CheckIdx[1] := 10;
    StepTable[StepB3CheckOpenLimit].TimeoutPT := T#1s;
    StepTable[StepB3CheckOpenLimit].NextOnPass := StepB3CloseAction;
    StepTable[StepB3CheckOpenLimit].NextOnFail := StepB3Teardown;
    StepTable[StepB3CheckOpenLimit].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3CloseAction].Name := 'Tcb3 Mouvement Fermeture';
    StepTable[StepB3CloseAction].CaseId := 3;
    StepTable[StepB3CloseAction].StimulusId := 5;
    StepTable[StepB3CloseAction].CheckIdx[1] := 11;
    StepTable[StepB3CloseAction].TimeoutPT := T#15s;
    StepTable[StepB3CloseAction].NextOnPass := StepB3CheckClosedLimit;
    StepTable[StepB3CloseAction].NextOnFail := StepB3Teardown;
    StepTable[StepB3CloseAction].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3CheckClosedLimit].Name := 'Tcb3 Verif Limite Decalee';
    StepTable[StepB3CheckClosedLimit].CaseId := 3;
    StepTable[StepB3CheckClosedLimit].StimulusId := 0;
    StepTable[StepB3CheckClosedLimit].CheckIdx[1] := 12;
    StepTable[StepB3CheckClosedLimit].TimeoutPT := T#1s;
    StepTable[StepB3CheckClosedLimit].NextOnPass := StepB3Teardown;
    StepTable[StepB3CheckClosedLimit].NextOnFail := StepB3Teardown;
    StepTable[StepB3CheckClosedLimit].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB3Teardown].Name := 'Tcb3 Teardown';
    StepTable[StepB3Teardown].CaseId := 3;
    StepTable[StepB3Teardown].StimulusId := 1;
    StepTable[StepB3Teardown].CheckIdx[1] := 1;
    StepTable[StepB3Teardown].TimeoutPT := T#12s;
    StepTable[StepB3Teardown].NextOnPass := StepB4Setup;
    StepTable[StepB3Teardown].NextOnFail := StepB4Setup;
    StepTable[StepB3Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B4 : Cohérence Boot
    StepTable[StepB4Setup].Name := 'Tcb4 Setup saine';
    StepTable[StepB4Setup].CaseId := 4;
    StepTable[StepB4Setup].StimulusId := 1;
    StepTable[StepB4Setup].CheckIdx[1] := 1;
    StepTable[StepB4Setup].TimeoutPT := T#12s;
    StepTable[StepB4Setup].NextOnPass := StepB4BootIncoherent;
    StepTable[StepB4Setup].NextOnFail := StepB4Teardown;
    StepTable[StepB4Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB4BootIncoherent].Name := 'Tcb4 Injection Drift Boot';
    StepTable[StepB4BootIncoherent].CaseId := 4;
    StepTable[StepB4BootIncoherent].StimulusId := 6;
    StepTable[StepB4BootIncoherent].CheckIdx[1] := 13;
    StepTable[StepB4BootIncoherent].CheckIdx[2] := 14;
    StepTable[StepB4BootIncoherent].CheckIdx[3] := 15;
    StepTable[StepB4BootIncoherent].CheckIdx[4] := 16;
    StepTable[StepB4BootIncoherent].TimeoutPT := T#2s;
    StepTable[StepB4BootIncoherent].NextOnPass := StepB4Recalage;
    StepTable[StepB4BootIncoherent].NextOnFail := StepB4Teardown;
    StepTable[StepB4BootIncoherent].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB4Recalage].Name := 'Tcb4 Recalage Manuel';
    StepTable[StepB4Recalage].CaseId := 4;
    StepTable[StepB4Recalage].StimulusId := 7;
    StepTable[StepB4Recalage].CheckIdx[1] := 17;
    StepTable[StepB4Recalage].CheckIdx[2] := 1;
    StepTable[StepB4Recalage].TimeoutPT := T#2s;
    StepTable[StepB4Recalage].NextOnPass := StepB4Teardown;
    StepTable[StepB4Recalage].NextOnFail := StepB4Teardown;
    StepTable[StepB4Recalage].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB4Teardown].Name := 'Tcb4 Teardown';
    StepTable[StepB4Teardown].CaseId := 4;
    StepTable[StepB4Teardown].StimulusId := 1;
    StepTable[StepB4Teardown].CheckIdx[1] := 1;
    StepTable[StepB4Teardown].TimeoutPT := T#12s;
    StepTable[StepB4Teardown].NextOnPass := StepB5Setup;
    StepTable[StepB4Teardown].NextOnFail := StepB5Setup;
    StepTable[StepB4Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B5 : Homing & Inhibition
    StepTable[StepB5Setup].Name := 'Tcb5 Setup saine';
    StepTable[StepB5Setup].CaseId := 5;
    StepTable[StepB5Setup].StimulusId := 1;
    StepTable[StepB5Setup].CheckIdx[1] := 1;
    StepTable[StepB5Setup].TimeoutPT := T#12s;
    StepTable[StepB5Setup].NextOnPass := StepB5LostHoming;
    StepTable[StepB5Setup].NextOnFail := StepB5Teardown;
    StepTable[StepB5Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5LostHoming].Name := 'Tcb5 Perte Homing';
    StepTable[StepB5LostHoming].CaseId := 5;
    StepTable[StepB5LostHoming].StimulusId := 8;
    StepTable[StepB5LostHoming].CheckIdx[1] := 18;
    StepTable[StepB5LostHoming].CheckIdx[2] := 19;
    StepTable[StepB5LostHoming].TimeoutPT := T#2s;
    StepTable[StepB5LostHoming].NextOnPass := StepB5RestoreHoming;
    StepTable[StepB5LostHoming].NextOnFail := StepB5Teardown;
    StepTable[StepB5LostHoming].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5RestoreHoming].Name := 'Tcb5 Rétablissement Homing';
    StepTable[StepB5RestoreHoming].CaseId := 5;
    StepTable[StepB5RestoreHoming].StimulusId := 1; // (Force HomedM1 := TRUE via Reset/Saine)
    StepTable[StepB5RestoreHoming].CheckIdx[1] := 1;
    StepTable[StepB5RestoreHoming].TimeoutPT := T#12s;
    StepTable[StepB5RestoreHoming].NextOnPass := StepB5InhibitM1;
    StepTable[StepB5RestoreHoming].NextOnFail := StepB5Teardown;
    StepTable[StepB5RestoreHoming].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5InhibitM1].Name := 'Tcb5 Inhibition M1';
    StepTable[StepB5InhibitM1].CaseId := 5;
    StepTable[StepB5InhibitM1].StimulusId := 9;
    StepTable[StepB5InhibitM1].CheckIdx[1] := 20;
    StepTable[StepB5InhibitM1].CheckIdx[2] := 21;
    StepTable[StepB5InhibitM1].TimeoutPT := T#15s;
    StepTable[StepB5InhibitM1].NextOnPass := StepB5Teardown;
    StepTable[StepB5InhibitM1].NextOnFail := StepB5Teardown;
    StepTable[StepB5InhibitM1].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB5Teardown].Name := 'Tcb5 Teardown';
    StepTable[StepB5Teardown].CaseId := 5;
    StepTable[StepB5Teardown].StimulusId := 1;
    StepTable[StepB5Teardown].CheckIdx[1] := 1;
    StepTable[StepB5Teardown].TimeoutPT := T#12s;
    StepTable[StepB5Teardown].NextOnPass := StepB6Setup;
    StepTable[StepB5Teardown].NextOnFail := StepB6Setup;
    StepTable[StepB5Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // TC-B6 : Homme-Mort & Recul
    StepTable[StepB6Setup].Name := 'Tcb6 Setup saine';
    StepTable[StepB6Setup].CaseId := 6;
    StepTable[StepB6Setup].StimulusId := 1;
    StepTable[StepB6Setup].CheckIdx[1] := 1;
    StepTable[StepB6Setup].TimeoutPT := T#12s;
    StepTable[StepB6Setup].NextOnPass := StepB6StartMove;
    StepTable[StepB6Setup].NextOnFail := StepB6Teardown;
    StepTable[StepB6Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6StartMove].Name := 'Tcb6 Lancement Mouvement';
    StepTable[StepB6StartMove].CaseId := 6;
    StepTable[StepB6StartMove].StimulusId := 2;
    StepTable[StepB6StartMove].CheckIdx[1] := 2;
    StepTable[StepB6StartMove].TimeoutPT := T#5s;
    StepTable[StepB6StartMove].NextOnPass := StepB6ReleaseJoy;
    StepTable[StepB6StartMove].NextOnFail := StepB6Teardown;
    StepTable[StepB6StartMove].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6ReleaseJoy].Name := 'Tcb6 Relâchement Homme-Mort';
    StepTable[StepB6ReleaseJoy].CaseId := 6;
    StepTable[StepB6ReleaseJoy].StimulusId := 10;
    StepTable[StepB6ReleaseJoy].CheckIdx[1] := 5;
    StepTable[StepB6ReleaseJoy].TimeoutPT := T#1s;
    StepTable[StepB6ReleaseJoy].NextOnPass := StepB6ReverseJoy;
    StepTable[StepB6ReleaseJoy].NextOnFail := StepB6Teardown;
    StepTable[StepB6ReleaseJoy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6ReverseJoy].Name := 'Tcb6 Commande Opposée';
    StepTable[StepB6ReverseJoy].CaseId := 6;
    StepTable[StepB6ReverseJoy].StimulusId := 11;
    StepTable[StepB6ReverseJoy].CheckIdx[1] := 22;
    StepTable[StepB6ReverseJoy].CheckIdx[2] := 23;
    StepTable[StepB6ReverseJoy].TimeoutPT := T#5s;
    StepTable[StepB6ReverseJoy].NextOnPass := StepB6Teardown;
    StepTable[StepB6ReverseJoy].NextOnFail := StepB6Teardown;
    StepTable[StepB6ReverseJoy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepB6Teardown].Name := 'Tcb6 Teardown';
    StepTable[StepB6Teardown].CaseId := 6;
    StepTable[StepB6Teardown].StimulusId := 1;
    StepTable[StepB6Teardown].CheckIdx[1] := 1;
    StepTable[StepB6Teardown].TimeoutPT := T#12s;
    StepTable[StepB6Teardown].NextOnPass := 0;
    StepTable[StepB6Teardown].NextOnFail := 0;
    StepTable[StepB6Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    TableReady := TRUE;
END_IF;

// 3. 📥 ACQUIRE
ProbeBool[SigHealthyIdle] := NOT instBucket.Error
                             AND NOT _BucketState.StateIncoherent;

ProbeBool[SigBucketBusy]   := instBucket.Busy;
ProbeBool[SigBucketDone]    := instBucket.Done;
ProbeBool[SigBucketError]   := instBucket.Error;
ProbeBool[SigM1SlipDetected] := instBucket.M1SlipDetected;
ProbeBool[SigM1SafeStop]    := PRG_03_Safety.instSafetyWinchM1.SafeStop;
ProbeBool[SigM1PowerCutOff] := PRG_03_Safety.instSafetyWinchM1.PowerCutOff;
ProbeBool[SigBucketIsOpen]  := _BucketState.IsOpen;
ProbeBool[SigBucketIsClosed] := _BucketState.IsClosed;
ProbeBool[SigM2StartStop]   := instBucket.M2_StartStop;
ProbeBool[SigM2ForceSlowSpeed] := instBucket.M2_ForceSlowSpeed;

ProbeDint[SigBucketErrorId] := WORD_TO_DINT(instBucket.ErrorId);
ProbeDint[SigM2Direction]   := INT_TO_DINT(instBucket.M2_Direction);
ProbeDint[SigSafetyM1ErrorId] := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM1.ErrorId);

ProbeReal[SigActiveOffsetM]   := instBucket.ActiveOffsetM;
ProbeReal[SigRemainingTravelM] := instBucket.RemainingTravelM;
ProbeReal[SigM2CablePos]      := PRG_02_Encoders.instEncoderScaleM2.CablePosM;
ProbeReal[SigM2TopLimit]       := instWinchM2.TopLimitM;

// 4. ⚙️ MOTEUR
Sequencer(
    Start := Start,
    Abort := Abort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    InvariantTable := InvariantTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal,
    Report := Report,
    Busy => Busy,
    Done => Done,
    AnyFailed => AnyFailed,
    TerminalState => TerminalState,
    ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId,
    ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode,
    ErrorMessage => ErrorMessage,
    ActiveStimulusId => ActiveStimulusId,
    StepElapsed => StepElapsed
);

// 5. ⚡ STIMULI
CASE ActiveStimulusId OF
    0: // 🔓 Neutre
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;
        JoystickY_Direction := 0;
        ConfirmOpenPosition := FALSE;
        HomedM1 := TRUE;
        InhibitM1 := FALSE;
        GVL_PLC_Tests.OverrideM1Slip := FALSE;
        GVL_PLC_Tests.OverrideM1SlipCritical := FALSE;
        GVL_PLC_Tests.OverrideM2Stuck := FALSE;
        GVL_PLC_Tests.OverrideM2BootDrift := FALSE;

    1: // Reset & Saine
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;
        ConfirmOpenPosition := TRUE; // Forcer état sain
        HomedM1 := TRUE;
        InhibitM1 := FALSE;
        GVL_PLC_Tests.OverrideM1Slip := FALSE;
        GVL_PLC_Tests.OverrideM1SlipCritical := FALSE;
        GVL_PLC_Tests.OverrideM2Stuck := FALSE;
        GVL_PLC_Tests.OverrideM2BootDrift := FALSE;

    2: // Fermeture Nominale
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        ConfirmOpenPosition := FALSE;
        HomedM1 := TRUE;

    3: // Glissement Modéré M1
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1Slip := TRUE;

    4: // Glissement Critique M1
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1SlipCritical := TRUE;

    5: // Fermeture nominale (TC-B3)
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        ConfirmOpenPosition := FALSE;

    6: // Boot Incohérent
        GVL_PLC_Tests.OverrideM2BootDrift := TRUE;
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;

    7: // Recalage manuel
        ConfirmOpenPosition := TRUE;
        CmdOpen_IHM := FALSE;
        CmdClose_IHM := FALSE;
        JoystickY_StartStop := FALSE;

    8: // Perte Homing
        HomedM1 := FALSE;
        CmdClose_IHM := FALSE;
        CmdOpen_IHM := FALSE;

    9: // Inhibition M1 + Mouvement
        InhibitM1 := TRUE;
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := 1;
        GVL_PLC_Tests.OverrideM1Slip := TRUE;

    10: // Relâchement Homme-Mort
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := FALSE;
        JoystickY_Direction := 1;

    11: // Commande opposée
        CmdClose_IHM := TRUE;
        JoystickY_StartStop := TRUE;
        JoystickY_Direction := -1;
END_CASE;

// Liaison IHM / Métier
IF Busy THEN
    instBucket.CmdOpen_IHM := CmdOpen_IHM;
    instBucket.CmdClose_IHM := CmdClose_IHM;
    instBucket.JoystickY_StartStop := JoystickY_StartStop;
    instBucket.JoystickY_Direction := JoystickY_Direction;
    instBucket.ConfirmOpenPosition := ConfirmOpenPosition;
    instBucket.HomedM1 := HomedM1;
    instBucket.InhibitM1 := InhibitM1;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

// === IMPLEMENTATION ===

// 🛑 1. GATES DE SÉCURITÉ ET BLOCAGE
IF NOT Enable OR NOT EmergencyStopOk THEN
    CmdWinchM1_StartStop := FALSE;
    CmdWinchM1_Direction := 0;
    CmdWinchM1_SpeedPct  := 0.0;

    CmdWinchM2_StartStop := FALSE;
    CmdWinchM2_Direction := 0;
    CmdWinchM2_SpeedPct  := 0.0;

    CmdTranslationM3_Start   := FALSE;
    CmdTranslationM3_Target  := 0;
    CmdBucket_Open      := FALSE;
    CmdBucket_Close     := FALSE;
    KoboldContactorCmd  := FALSE;

    State                := E_CycleStep.INIT;
    CycleStep            := E_CycleStep.INIT;
    CycleStateStr        := 'ARRÊT : SÉCURITÉ ABSENTE OU AUTO DÉSACTIVÉ';
    Ready                := FALSE;
    Busy                 := FALSE;
    Done                 := FALSE;
    IsPaused             := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
PauseEdge(CLK := PauseCycle);
AbortEdge(CLK := AbortCycle);

// ⏱️ T36 — surveillance indépendante de la remontée lente : un codeur bloqué
// ne doit jamais laisser le cycle attendre indéfiniment.
StabilizationTimer(IN := (State = E_CycleStep.CTRL_ASCENDING), PT := CtrlAscentTimeout);

// 📏 T43 — comparaison vitesse réelle M1/M2.
// Le contrôle est volontairement désactivé tant que le seuil et la durée ne sont pas définis.
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_CycleStep.CTRL_ASCENDING)
                       AND CycleMotionPermit
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

IF ResetEdge.Q THEN
    Error := FALSE;
    ErrorId := 16#0000;
    IsPaused := FALSE;
    SavedState := E_CycleStep.INIT;
    IF State = E_CycleStep.ERROR_HOLD THEN
        State := E_CycleStep.INIT;
    END_IF;
END_IF;

// 💓 Perte IHM : repli mémorisé. La reconnexion seule ne relance jamais le cycle.
IF NOT HeartbeatIhmOk AND State <> E_CycleStep.ERROR_HOLD THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0020;
    State := E_CycleStep.ERROR_HOLD;
END_IF;

// Défaut de synchronisme : arrêt sûr et acquittement obligatoire.
IF WinchSyncError AND State <> E_CycleStep.ERROR_HOLD THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0002;
    State := E_CycleStep.ERROR_HOLD;
END_IF;

// 🛡️ T43 — écart de vitesse confirmé : arrêt du cycle et ERROR_HOLD.
// La sortie SafeStop reste gérée par les blocs safety métier ; ce bit protège le séquenceur.
IF SpeedMismatchConfirmed AND State <> E_CycleStep.ERROR_HOLD THEN
    Error := TRUE;
    ErrorId := ErrorId OR 16#0010;
    State := E_CycleStep.ERROR_HOLD;
END_IF;

// Gestion de la Pause
IF PauseEdge.Q AND Busy AND NOT IsPaused THEN
    IsPaused := TRUE;
    SavedState := State;
    State := E_CycleStep.ERROR_HOLD; // Fige les mouvements
ELSIF StartEdge.Q AND IsPaused THEN
    IsPaused := FALSE;
    State := SavedState; // Reprise à l'étape sauvegardée
END_IF;

// Gestion de l'Abandon
IF AbortEdge.Q THEN
    IsPaused := FALSE;
    State := E_CycleStep.INIT;
END_IF;

// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état)
CASE State OF

    E_CycleStep.INIT: // 🔄 ÉTAPE 0 : Initialisation et vérifications
        CycleStep := E_CycleStep.INIT;
        CycleStateStr := 'VÉRIFICATION COHÉRENCE SYSTÈME';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;
        CmdTranslationM3_Start   := FALSE;
        CmdBucket_Open      := FALSE;
        CmdBucket_Close     := FALSE;
        KoboldContactorCmd  := FALSE;
        Busy                 := FALSE;
        Done                 := FALSE;

        // Transition si système sain et réarmé (front reset ou démarrage)
        IF StartEdge.Q THEN
            State := E_CycleStep.WORK_POS_SELECT;
        END_IF;

    E_CycleStep.WORK_POS_SELECT: // 📍 ÉTAPE 1 : Sélection position travail
        CycleStep := E_CycleStep.WORK_POS_SELECT;
        CycleStateStr := 'SÉLECTION POSITION TRAVAIL (FOSSE 1 / 2)';
        Busy := TRUE;

        // Choix cible — 🆕 REX 2026-07-18 : zone de travail = P2/P1 (cibles 2/3), ex-Fosse1/Fosse2
        // (cibles 1/2), suite au remap 5 positions Trémie(1)/P2(2)/P1(3)/Maintenance(4)
        IF (SelectedTargetNum_IHM <> 2) AND (SelectedTargetNum_IHM <> 3) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0004; // cible de travail invalide
            State := E_CycleStep.ERROR_HOLD;
        ELSIF SelectedTargetNum_IHM = 2 OR SelectedTargetNum_IHM = 3 THEN
            SelectedWorkTarget := SelectedTargetNum_IHM;
            CmdTranslationM3_Target := SelectedWorkTarget;
            CmdTranslationM3_Start := CycleMotionPermit;

            // Attente positionnement translation
            IF CycleMotionPermit AND ((SelectedWorkTarget = 2 AND Translation_At_P2)
               OR (SelectedWorkTarget = 3 AND Translation_At_P1)) THEN
                CmdTranslationM3_Start := FALSE;
                State := E_CycleStep.DESCENDING_OPEN;
            END_IF;
        END_IF;

    E_CycleStep.DESCENDING_OPEN: // ⬇️ ÉTAPE 2 : Plongée benne ouvert
        CycleStep := E_CycleStep.DESCENDING_OPEN;
        CycleStateStr := 'PLONGÉE BENNE OUVERT';

        // M1 et M2 descendent ensemble (synchro gérée en aval)
        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := -1;
        CmdWinchM1_SpeedPct  := 50.0; // Vitesse de descente 50%

        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := -1;
        CmdWinchM2_SpeedPct  := 50.0;
        KoboldContactorCmd   := TRUE;

        // Transition uniquement sur le retour dédié Kobold.
        IF CycleMotionPermit AND KoboldContactFond THEN
            CmdWinchM1_StartStop := FALSE;
            CmdWinchM2_StartStop := FALSE;
            KoboldContactorCmd := FALSE;
            TouchPositionM := M1_CablePosM; // Mémorisation position contact
            IF LimitLegalDepthM < -0.01 THEN
                RaiseTargetM := MAX(TouchPositionM + 0.5, LimitLegalDepthM + 0.5);
            ELSE
                RaiseTargetM := TouchPositionM + 0.5;
            END_IF;
            State := E_CycleStep.BOTTOM_TOUCH_WAIT;
        ELSIF LimitLegalReached THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0001;
            CmdWinchM1_StartStop := FALSE;
            CmdWinchM2_StartStop := FALSE;
            KoboldContactorCmd := FALSE;
            State := E_CycleStep.ERROR_HOLD;
        END_IF;

    E_CycleStep.BOTTOM_TOUCH_WAIT: // ⏳ ÉTAPE 3 : Temporisation contact fond
        CycleStep := E_CycleStep.BOTTOM_TOUCH_WAIT;
        CycleStateStr := 'REMONTÉE SÉCURISÉE APRÈS CONTACT FOND';

        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := 1;
        CmdWinchM1_SpeedPct := 20.0;
        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := 1;
        CmdWinchM2_SpeedPct := 20.0;

        // Les deux treuils restent synchronisés jusqu'au-dessus de la limite légale.
        IF CycleMotionPermit AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            CmdWinchM1_StartStop := FALSE;
            CmdWinchM2_StartStop := FALSE;
            State := E_CycleStep.SYNCHRO_ADJUST;
        END_IF;

    E_CycleStep.SYNCHRO_ADJUST: // 🪣 ÉTAPE 4 : Fermeture du benne (Excavation)
        CycleStep := E_CycleStep.SYNCHRO_ADJUST;
        CycleStateStr := 'FERMETURE DU GODET / EXCAVATION';

        CmdWinchM1_StartStop := FALSE; // M1 reste immobile

        // Déclenchement fermeture benne
        CmdBucket_Close := TRUE;

        // Transition si benne fermé avec succès
        IF CycleMotionPermit AND Benne_Done AND Benne_IsClosed THEN
            CmdBucket_Close := FALSE;
            State := E_CycleStep.CTRL_ASCENDING;
        END_IF;

    E_CycleStep.CTRL_ASCENDING: // ⬆️ ÉTAPE 5 : Remontée lente de contrôle
        CycleStep := E_CycleStep.CTRL_ASCENDING;
        CycleStateStr := 'REMONTÉE LENTE DE CONTRÔLE';

        // M1 et M2 montent lentement en synchro
        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := 1;
        CmdWinchM1_SpeedPct  := 20.0; // 20% max

        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := 1;
        CmdWinchM2_SpeedPct  := 20.0;

        // 🛡️ Contrôle des deux codeurs : la benne chargée doit remonter avec
        // M1 et M2. Un seul codeur arrivé ne suffit pas.
        IF WinchSyncError OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM) THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008; // stabilisation/désynchronisme après fermeture
            State := E_CycleStep.ERROR_HOLD;
        // Transition uniquement lorsque les deux treuils sont au-dessus de la
        // zone de contrôle et restent synchronisés.
        ELSIF CycleMotionPermit
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_CycleStep.ASCENDING_LOADED;
        ELSIF StabilizationTimer.Q THEN
            Error := TRUE;
            ErrorId := ErrorId OR 16#0008; // un treuil n'a pas atteint la zone de contrôle
            State := E_CycleStep.ERROR_HOLD;
        END_IF;

    E_CycleStep.ASCENDING_LOADED: // 🚀 ÉTAPE 6 : Remontée pleine vitesse
        CycleStep := E_CycleStep.ASCENDING_LOADED;
        CycleStateStr := 'REMONTÉE EN CHARGE';

        CmdWinchM1_StartStop := TRUE;
        CmdWinchM1_Direction := 1;
        CmdWinchM1_SpeedPct  := 70.0; // Grande vitesse 70%

        CmdWinchM2_StartStop := TRUE;
        CmdWinchM2_Direction := 1;
        CmdWinchM2_SpeedPct  := 70.0;

        // 🔧 WINCH-CORE-01 : transition alignée sur la limite haute d'exploitation
        // réellement utilisée par FB_Winch. Aucun seuil dérivé de la cible homing :
        // 8,0 m = exploitation ; 8,5 m = capteur haut/homing uniquement.
        IF CycleMotionPermit AND M1_CablePosM >= CableLimitM1AscentM THEN
            CmdWinchM1_StartStop := FALSE;
            CmdWinchM2_StartStop := FALSE;
            State := E_CycleStep.DRAINING_PAUSE;
        END_IF;

    E_CycleStep.DRAINING_PAUSE: // 💧 ÉTAPE 7 : Égouttage temporisé
        CycleStep := E_CycleStep.DRAINING_PAUSE;
        CycleStateStr := 'ÉGOUTTAGE DU GODET EN COURS';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;

        DrainingTimer(IN := TRUE, PT := DrainingTime);
        IF CycleMotionPermit AND DrainingTimer.Q THEN
            DrainingTimer(IN := FALSE);
            State := E_CycleStep.TRANSLATION_MOVE;
        END_IF;

    E_CycleStep.TRANSLATION_MOVE: // ↔️ ÉTAPE 8 : Déplacement vers trémie
        CycleStep := E_CycleStep.TRANSLATION_MOVE;
        CycleStateStr := 'DÉPLACEMENT VERS TRÉMIE DE VIDANGE';

        CmdTranslationM3_Target := 1; // Trémie — 🆕 REX 2026-07-18 : ex-4, remap 5 positions (AF_Partie-02 v2.12 §3bis)
        CmdTranslationM3_Start := TRUE;

        // Transition si translation arrivé à la trémie
        IF CycleMotionPermit AND Translation_At_Tremie THEN
            CmdTranslationM3_Start := FALSE;
            State := E_CycleStep.DESCENDING_OPEN_DUMP;
        END_IF;

    E_CycleStep.DESCENDING_OPEN_DUMP: // 🗑️ ÉTAPE 9 : Ouverture benne (Vidange)
        CycleStep := E_CycleStep.DESCENDING_OPEN_DUMP;
        CycleStateStr := 'VIDANGE / OUVERTURE DU GODET';

        // Déclenchement ouverture benne
        CmdBucket_Open := TRUE;

        // Transition si benne ouvert avec succès
        IF CycleMotionPermit AND Benne_Done AND Benne_IsOpen THEN
            CmdBucket_Open := FALSE;
            State := E_CycleStep.RETURN_WORK_POS;
        END_IF;

    E_CycleStep.RETURN_WORK_POS: // 🔙 ÉTAPE 10 : Retour fosse de travail
        CycleStep := E_CycleStep.RETURN_WORK_POS;
        CycleStateStr := 'RETOUR VERS FOSSE DE TRAVAIL';

        CmdTranslationM3_Target := SelectedWorkTarget;
        CmdTranslationM3_Start := TRUE;

        // Transition si translation de retour sur sa position de travail
        IF CycleMotionPermit AND ((SelectedWorkTarget = 2 AND Translation_At_P2)
           OR (SelectedWorkTarget = 3 AND Translation_At_P1)) THEN
            CmdTranslationM3_Start := FALSE;
            State := E_CycleStep.READY;
        END_IF;

    E_CycleStep.READY: // 🏁 ÉTAPE 11 : Prêt / Cycle terminé
        CycleStep := E_CycleStep.READY;
        CycleStateStr := 'CYCLE AUTOMATIQUE COMPLÉTÉ - PRÊT';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;
        CmdTranslationM3_Start   := FALSE;
        Done                 := TRUE;
        Busy                 := FALSE;

        // Rebouclage manuel ou auto sur Start
        IF StartEdge.Q THEN
            Done := FALSE;
            State := E_CycleStep.DESCENDING_OPEN;
        END_IF;

    E_CycleStep.ERROR_HOLD: // 🛑 ÉTAPE 12 : Maintien sur arrêt / pause
        CycleStep := E_CycleStep.ERROR_HOLD;
        CycleStateStr := 'CYCLE SUSPENDU (PAUSE OU ARRÊT DE SÉCURITÉ)';

        CmdWinchM1_StartStop := FALSE;
        CmdWinchM2_StartStop := FALSE;
        CmdTranslationM3_Start   := FALSE;

        // Relâchement des commandes benne
        CmdBucket_Open := FALSE;
        CmdBucket_Close := FALSE;
END_CASE;

// 🛑 Relâchement homme-mort : aucune demande d'actionneur ne reste active.
// L'étape est mémorisée et reprend au prochain appui valide.
IF Busy AND NOT CycleMotionPermit THEN
    CmdWinchM1_StartStop := FALSE;
    CmdWinchM2_StartStop := FALSE;
    CmdTranslationM3_Start := FALSE;
    CmdBucket_Open := FALSE;
    CmdBucket_Close := FALSE;
    KoboldContactorCmd := FALSE;
END_IF;

// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();

// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;

// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);

// 4. CONVERSION ET CHARGE DE SECOURS
IF DeltaTimeMs > 0 THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;

// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;

// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_DiagState.DISABLED;
    DeviceJoystick.State := E_DiagState.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CANbusOnline AND DeviceJoystickOnline) THEN
        DeviceJoystick.ErrorId := 16#0000;
        StateAtError := E_DiagState.DISABLED;
    END_IF;
END_IF;

// 🔍 3. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnline THEN
    DeviceJoystick.ErrorId := 16#0001;  (* Perte liaison CAN joystick *)
    DeviceJoystick.Online := FALSE;
ELSE
    DeviceJoystick.Online := TRUE;
    IF ResetEdge.Q THEN
        DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE;
    END_IF;
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnline THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    IF ResetEdge.Q THEN
        DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD;
    END_IF;
END_IF;

// 🚦 4. MACHINE D'ÉTAT JOYSTICK
// REX 2026-07-08 : correction de la précédence d'affichage IHM des états d'erreur.
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_DiagState.ERROR;
    IF StateAtError = E_DiagState.DISABLED THEN
        StateAtError := State;
    END_IF;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_DiagState.INIT;
ELSE
    DeviceJoystick.State := E_DiagState.READY;
END_IF;

State := DeviceJoystick.State;

// 📤 5. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);
Error := DeviceJoystick.Error;
ErrorId := DeviceJoystick.ErrorId;

DeviceCanOpenMaster.Operational := CANbusOnline;
DeviceCanOpenMaster.Online := CANbusOnline;

// Briques génériques pour conformité standard
Busy := FALSE;
Done := FALSE;

// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    State := E_DiagState.DISABLED;
    DeviceVariateur.State := E_DiagState.DISABLED;
    DeviceEncoderM1.State := E_DiagState.DISABLED;
    DeviceEncoderM2.State := E_DiagState.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := DeviceVariateurOnline;
DeviceVariateur.Operational := DeviceVariateur.Online AND (DeviceVariateurState = 8);

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := 16#0010;  (* Perte liaison physique variateur *)
ELSE
    IF ResetEdge.Q THEN
        DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF;
    END_IF;
END_IF;

IF NOT DeviceVariateur.Operational AND DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0011;  (* Variateur pré-opérationnel *)
ELSE
    IF ResetEdge.Q THEN
        DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEE;
    END_IF;
END_IF;

// 🔍 4. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := DeviceEncoderM1Online;
DeviceEncoderM1.Operational := DeviceEncoderM1.Online AND (DeviceEncoderM1State = 8);

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    IF ResetEdge.Q THEN
        DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF;
    END_IF;
END_IF;

IF NOT DeviceEncoderM1.Operational AND DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0021;  (* Encodeur M1 pré-opérationnel *)
ELSE
    IF ResetEdge.Q THEN
        DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDE;
    END_IF;
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := DeviceEncoderM2Online;
DeviceEncoderM2.Operational := DeviceEncoderM2.Online AND (DeviceEncoderM2State = 8);

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    IF ResetEdge.Q THEN
        DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF;
    END_IF;
END_IF;

IF NOT DeviceEncoderM2.Operational AND DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0031;  (* Encodeur M2 pré-opérationnel *)
ELSE
    IF ResetEdge.Q THEN
        DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCE;
    END_IF;
END_IF;

// 🚦 6. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_DiagState.ERROR;
ELSIF NOT DeviceVariateur.Online THEN
    DeviceVariateur.State := E_DiagState.INIT;
ELSIF DeviceVariateur.Operational THEN
    DeviceVariateur.State := E_DiagState.READY;
ELSE
    DeviceVariateur.State := E_DiagState.MONITORING;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_DiagState.ERROR;
ELSIF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.State := E_DiagState.INIT;
ELSIF DeviceEncoderM1.Operational THEN
    DeviceEncoderM1.State := E_DiagState.READY;
ELSE
    DeviceEncoderM1.State := E_DiagState.MONITORING;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_DiagState.ERROR;
ELSIF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.State := E_DiagState.INIT;
ELSIF DeviceEncoderM2.Operational THEN
    DeviceEncoderM2.State := E_DiagState.READY;
ELSE
    DeviceEncoderM2.State := E_DiagState.MONITORING;
END_IF;

// Fige la phase du diagnostic global sur le premier défaut
IF (DeviceVariateur.ErrorId <> 0 OR DeviceEncoderM1.ErrorId <> 0 OR DeviceEncoderM2.ErrorId <> 0) THEN
    IF StateAtError = E_DiagState.DISABLED THEN
        StateAtError := State;
    END_IF;
END_IF;

// 📤 7. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

Error := (DeviceVariateur.Error OR DeviceEncoderM1.Error OR DeviceEncoderM2.Error);

ErrorId := 16#0000;
IF DeviceVariateur.Error THEN
    ErrorId := ErrorId OR 16#00F0;
END_IF;
IF DeviceEncoderM1.Error THEN
    ErrorId := ErrorId OR 16#0F00;
END_IF;
IF DeviceEncoderM2.Error THEN
    ErrorId := ErrorId OR 16#F000;
END_IF;

IF Error THEN
    State := E_DiagState.ERROR;
ELSIF NOT (DeviceVariateur.Operational AND DeviceEncoderM1.Operational AND DeviceEncoderM2.Operational) THEN
    State := E_DiagState.MONITORING;
ELSE
    State := E_DiagState.READY;
END_IF;

DeviceEthercatMaster.Online := DeviceVariateur.Online AND DeviceEncoderM1.Online AND DeviceEncoderM2.Online;
DeviceEthercatMaster.Operational := DeviceVariateur.Operational AND DeviceEncoderM1.Operational AND DeviceEncoderM2.Operational;

Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

// Gate simulation : une suite non exécutable se termine explicitement.
SimGateOk := GVL_Simulation.SimulationModeActive
          AND NOT GVL_Simulation.BusEncoderM1IsReal
          AND NOT GVL_Simulation.BusEncoderM2IsReal;

// Valeurs par défaut de commande : aucun front ne reste actif hors étape dédiée.
M1HomePulse := FALSE;
M2HomePulse := FALSE;
ActiveStimulusId := 0;

IF Abort THEN
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.Aborted := TRUE;
    Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState;
    Report.FailureSummary := 'Encoder/Homing : ABORTED';
    RETURN;
END_IF;

// Démarrage sur front : rapport réinitialisé et mode de maintenance demandé.
IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    ConfigError := FALSE;
    ErrorCode := 0;
    ErrorMessage := '';
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    IF CaseId < 0 OR CaseId > 2 THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ConfigError := TRUE;
        ErrorCode := 3002;
        ErrorMessage := 'Encoder/Homing CaseId invalide';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.TerminalState := TerminalState;
        Report.AnyFailed := TRUE;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        RETURN;
    END_IF;
    IF CaseId = 2 THEN Step := 20; ELSE Step := 10; END_IF;
    Report.Name := 'Encoder/Homing Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailureSummary := '';
    Report.CurrentStepId := Step;
    Report.CurrentCaseId := SEL(Step >= 20, 2, 1);
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Index].Executed := FALSE;
        Report.Steps[Index].Passed := FALSE;
        Report.Steps[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Index].Duration := T#0s;
    END_FOR;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Index].Executed := FALSE;
        Report.Cases[Index].Ok := FALSE;
        Report.Cases[Index].FailedStepId := 0;
        Report.Cases[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Index].Duration := T#0s;
    END_FOR;
    StepStarted := FALSE;
    ResetIssued := FALSE;
ELSIF NOT Start THEN
    StartPrev := FALSE;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.CurrentStepId := Step;
// 🧭 Mapping rapport : étapes 10/11 = TC-E1 ; étapes 20/21/22 = TC-E2.
CurrentCaseId := SEL(Step >= 20, 2, 1);
Report.CurrentCaseId := CurrentCaseId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    CASE Step OF
        10: StepLimit := T#2s;
        11: StepLimit := T#2s;
        20: StepLimit := T#2s;
        21: StepLimit := T#2s;
        22: StepLimit := T#10s;
    ELSE
        ConfigError := TRUE;
        ConfigErrorStepId := Step;
        ErrorCode := 3001;
        ErrorMessage := 'Encoder/Homing étape inconnue';
        StepLimit := T#0s;
    END_CASE;
END_IF;

StepTimer(IN := TRUE, PT := StepLimit);

CASE Step OF
    // TC-E1 : gate et interface IHM nominale accessibles.
    10:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF NOT SimGateOk THEN
            StepFailed := TRUE;
            ErrorCode := 3003;
            ErrorMessage := 'Gate simulation codeurs inactif';
        ELSIF NOT GVL_IHM.M1TreuilRetenue.State.HomingError
           AND NOT GVL_IHM.M2TreuilBenne.State.HomingError THEN
            StepPassed := TRUE;
            Step := 11;
            StepStarted := FALSE;
        END_IF;

    // TC-E1 : vérifier que le rapport IHM des deux treuils existe avant commande.
    11:
        IF (GVL_IHM.M1TreuilRetenue.State.HomingState >= E_State.DISABLED)
           AND (GVL_IHM.M2TreuilBenne.State.HomingState >= E_State.DISABLED) THEN
            StepPassed := TRUE;
            Step := 0;
        END_IF;

    // TC-E2 : fronts BtnHome indépendants, envoyés simultanément.
    20:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF NOT SimGateOk THEN
            StepFailed := TRUE;
            ErrorCode := 3003;
            ErrorMessage := 'Gate simulation codeurs inactif';
        ELSE
            StepPassed := TRUE;
            Step := 21;
            StepStarted := FALSE;
        END_IF;

    21:
        M1HomePulse := TRUE;
        M2HomePulse := TRUE;
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := M1HomePulse;
        GVL_IHM.M2TreuilBenne.Cmd.BtnHome := M2HomePulse;
        StepPassed := TRUE;
        Step := 22;
        StepStarted := FALSE;

    // TC-E2 : aucune attente infinie : les deux instances doivent finir ou déclarer une erreur.
    22:
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
        GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
        IF (GVL_IHM.M1TreuilRetenue.State.HomingDone OR GVL_IHM.M1TreuilRetenue.State.Homed)
           AND (GVL_IHM.M2TreuilBenne.State.HomingDone OR GVL_IHM.M2TreuilBenne.State.Homed) THEN
            StepPassed := TRUE;
            Step := 0;
        ELSIF GVL_IHM.M1TreuilRetenue.State.HomingError OR GVL_IHM.M2TreuilBenne.State.HomingError THEN
            StepFailed := TRUE;
        END_IF;
END_CASE;

// Verdict local de l'étape : PASS, FAIL ou TIMEOUT contrôlé.
IF StepPassed OR StepFailed OR StepTimer.Q THEN
    IF StepPassed THEN
        Report.Steps[Report.CurrentStepId].Passed := TRUE;
        Report.Steps[Report.CurrentStepId].FailReason := E_TestFailReason.FAIL_NONE;
    ELSE
        Report.Steps[Report.CurrentStepId].Passed := FALSE;
        Report.Steps[Report.CurrentStepId].FailReason := SEL(StepFailed, E_TestFailReason.FAIL_TIMEOUT, E_TestFailReason.FAIL_CHECK);
        AnyFailed := TRUE;
    END_IF;
    Report.Steps[Report.CurrentStepId].Executed := TRUE;
    Report.Steps[Report.CurrentStepId].Duration := StepElapsed;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;
    // Un échec ou un timeout termine immédiatement la suite : aucune étape
    // suivante ne doit laisser le banc attendre un signal devenu impossible.
    IF NOT StepPassed THEN
        Step := 0;
    END_IF;
    StepPassed := FALSE;
    StepFailed := FALSE;
    StepTimer(IN := FALSE, PT := StepLimit);
    StepElapsed := T#0s;
    IF Step = 0 THEN
        Busy := FALSE;
        Done := TRUE;
        Report.InProgress := FALSE;
        Report.AnyFailed := AnyFailed;
        Report.AllPassed := NOT AnyFailed;
        Report.TerminalState := SEL(AnyFailed, E_TestTerminalState.TEST_TERMINAL_DONE, E_TestTerminalState.TEST_TERMINAL_FAILED);
        TerminalState := Report.TerminalState;
        IF CurrentCaseId = 1 THEN
            Report.Cases[CurrentCaseId].Name := 'TC-E1 Interface Homing nominale';
        ELSE
            Report.Cases[CurrentCaseId].Name := 'TC-E2 Commandes Home M1/M2';
        END_IF;
        Report.Cases[CurrentCaseId].Executed := TRUE;
        Report.Cases[CurrentCaseId].Ok := NOT AnyFailed;
        Report.Cases[CurrentCaseId].FailedStepId := 0;
        Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_NONE;
        IF AnyFailed THEN
            Report.Cases[CurrentCaseId].FailedStepId := Report.CurrentStepId;
            Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_CHECK;
        END_IF;
        Report.Cases[CurrentCaseId].Duration := Report.Duration;
        IF AnyFailed THEN Report.FailureSummary := 'Encoder/Homing : échec ou timeout'; END_IF;
    ELSE
        StepStarted := FALSE;
    END_IF;
END_IF;

// Limite globale de sécurité de la suite : 30 s maximum.
IF Report.Duration >= T#30s AND Busy THEN
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
    Report.InProgress := FALSE;
    Report.AnyFailed := TRUE;
    Report.AllPassed := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 3002;
    Report.ErrorMessage := 'Watchdog Encoder/Homing expire';
    Report.FailureSummary := Report.ErrorMessage;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

// 🛑 1. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    PresetTriggerCmd := 16#0000; CodeSeqTriggerCmd := 16#0000; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. DIAGNOSTIC BUS / ALARME
IF (AlarmsIn <> 0) OR NOT SlaveOperational THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;
EncoderAvailable := (ErrorId AND 16#0001) = 0;

// 📥 4. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // 🔧 2026-07-03 : sens de comptage géré côté codeur (CoE 6000h bit0,
                          // startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;

// 🔧 5. SÉQUENCE PRESET (écriture bus)
// ✅ Confirmé terrain (2026-07-02) : PresettTrigCmd := 2 déclenche le référencement à
//    PresetValue (valeur de commande, pas un masque de bits — corrige l'hypothèse initiale).
// 🔴 CodeSeqTrigCmd : rôle NON identifié (même par l'utilisateur/terrain) — laissé à 0,
//    PAS piloté tant que sa fonction n'est pas confirmée (fiche technique ou essai dédié).
//    Ne jamais lui donner une valeur arbitraire "au cas où".
PresetReqEdge(CLK := PresetRequest);
PresetAck := FALSE; PresetNak := FALSE; // pulses 1 cycle uniquement
CodeSeqTriggerCmd := 16#0000;           // 🔴 non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // ✅ Valeur confirmée terrain — référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetAck := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetNak := TRUE;
            ErrorId := ErrorId OR 16#0002;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🧾 6. ERROR / STATEATERROR
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := (PresetSeqStep <> 0);
Done := PresetAck;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

// 🛑 1. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
IF NOT Enable OR NOT EmergencyStopOk THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle §3.7 à la prochaine activation
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    RETURN;
END_IF;

Ready := TRUE;

// 🔑 2. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// 🔍 3. COHÉRENCE AU REDÉMARRAGE (§3.7) — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    State := E_State.INIT;
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            ErrorId := ErrorId OR 16#0200;   // bit9 : incohérence codeur au redémarrage
        END_IF;
        InitDone := TRUE;
    END_IF;
ELSE
    IF State = E_State.INIT THEN State := E_State.READY; END_IF;
END_IF;

// ✅ 4. LEVÉE DU DOUTE (BtnConfirmCoherence, §3.7) — indépendant du Reset générique
IF ConfirmCoherenceEdge.Q AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) THEN
    Calib.HomingSuspect := FALSE;
    ErrorId := ErrorId AND 16#FDFF;   // efface bit9
END_IF;

// 🎯 5. DEMANDE DE RÉFÉRENCEMENT (flux nominal)
// 🛡️ Les cibles nominale et unitaire sont rejetées hors du domaine codeur sûr [-99.00;+99.00] m.
// 🔧 REX 2026-07-07 : FwdRevSpeedFeedbackOff remplace (NOT ContactorFeedbackFwd) AND (NOT ContactorFeedbackRev)
// 🌐 BypassGlobal = TRUE → on saute la vérification d'arrêt (mise en service)
ArretConfirme := BypassGlobal OR (FwdRevSpeedFeedbackOff AND BrakeFeedback);

PresetRequest := FALSE;   // Défaut chaque cycle — repose uniquement sur le front HomeEdge ci-dessous
IF HomeEdge.Q AND (State <> E_State.BUSY) THEN
    IF UnitaryMode THEN
        TargetPositionM := CfgHomingTargetM;
    ELSE
        TargetPositionM := CfgTopSensorPosM;
    END_IF;

    // ✅ Homing autorisé en MAINT_N1 et MAINT_N2 — interdit en SEMI_AUTO et en cycle AUTO
    // 🌐 BypassGlobal = TRUE → saute TOUTES les vérifications, force le homing
    IF BypassGlobal THEN
        // Force homing sans condition
        PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PresetValue := PresetValueCalc;
        PresetRequest := TRUE;
        State := E_State.BUSY;
    ELSIF (Mode <> E_Mode.MAINT_N1) AND (Mode <> E_Mode.MAINT_N2) THEN
        ErrorId := ErrorId OR 16#0001;        // bit0 : mode non autorisé (seulement MAINT N1/N2)
    ELSIF UnitaryMode AND (Mode <> E_Mode.MAINT_N2) THEN
        ErrorId := ErrorId OR 16#0001;
    ELSIF UnitaryMode AND NOT WinchSelected THEN
        ErrorId := ErrorId OR 16#0002;        // bit1 : mauvais treuil sélectionné
    ELSIF NOT EncoderAvailable THEN
        ErrorId := ErrorId OR 16#0008;        // bit3 : codeur indisponible
    ELSIF NOT ArretConfirme THEN
        ErrorId := ErrorId OR 16#0004;        // bit2 : arrêt non confirmé (contacteurs/frein)
    ELSIF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        ErrorId := ErrorId OR 16#0010;        // bit4 : cible nominale/unitaire hors limites
    ELSIF NOT BypassGlobal AND NOT UnitaryMode AND (TargetPositionM <> 0.0) AND TopPositionSensor THEN
        // 🔧 CORRIGÉ 2026-07-04 : polarité inversée (testait NOT TopPositionSensor). Convention
        // NAMING_CONVENTION.md : TRUE = sain/non atteint, FALSE = position haute confirmée
        // (contact ouvert) — le Home nominal doit être rejeté tant que TopPositionSensor=TRUE.
        // 🆕 Si TargetPositionM = 0.0 (homing à zéro), on ignore le capteur haut (position courante).
        ErrorId := ErrorId OR 16#0010;        // bit4 : capteur position haute non confirmé
    ELSE
        // ✅ Toutes conditions réunies : calcul de la cible brute et déclenchement
        PresetValueCalc := (PointsPerRev * MultiTurnRevsMax) / 2;               // Centre exact (§3.3)
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PresetValue := PresetValueCalc;
        PresetRequest := TRUE;                // Pulse 1 cycle — FB_Encoder_Abs détecte le front lui-même
        State := E_State.BUSY;
    END_IF;
END_IF;

// ⏳ 6. SUIVI DE LA SÉQUENCE (BUSY → confirmation)
Done := FALSE;
IF State = E_State.BUSY THEN
    IF PresetAck THEN
        Calib.HomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(PresetValueCalc) - TargetPoints);
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := PresetValueCalc;
        Done := TRUE;
        State := E_State.READY;
        // 🔧 REX 2026-07-07 : un homing réussi re-établit la référence tout aussi validement
        // qu'un BtnConfirmCoherence explicite — efface donc aussi bit9 (incohérence redémarrage),
        // sinon ErrorId/Error restait bloqué à TRUE après un homing réussi (jamais mappé vers
        // l'IHM, invisible sauf sur GVL_IHM.Modes.State.AnyFaultActive qui restait à 1 sans raison visible).
        ErrorId := ErrorId AND 16#FDFF;
    ELSIF PresetNak THEN
        ErrorId := ErrorId OR 16#0020;        // bit5 : preset refusé/timeout (voir FB_Encoder_Abs)
        State := E_State.READY;
    END_IF;
END_IF;

// 🧾 7. RESET (front) — efface les bits « dernière tentative rejetée » (pas de cause persistante
// à revérifier ici : le prochain Home réévalue toutes les conditions de zéro, voir §5)
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFC0;   // efface bits 0..5 (garde bit9, levé seulement par BtnConfirmCoherence/Home)
END_IF;

// 📤 8. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// Mise à jour continue du point brut valide connu (hors séquence de homing elle-même)
IF EncoderAvailable AND (State <> E_State.BUSY) THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Busy := (State = E_State.BUSY);
Homed := Calib.Homed AND NOT Calib.HomingSuspect; // 🆕 REX 2026-07-08 : Perd l'état homed si suspect (démarrage ou fonctionnement), restauré après BtnConfirmCoherence
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Safety) ===

// 🛑 1. GATE — expose la dernière valeur plausible connue même désactivé
IF NOT Enable THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    CablePosMSafe := LastPlausibleCablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0, ignore bornage et incohérence
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🔍 3. BORNAGE PHYSIQUE ABSOLU (§3.6) — bit0
IF NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM)) THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 4. RELAIS INCOHÉRENCE REDÉMARRAGE (§3.7, calculée par FB_Encoder_Homing) — bit1
// Pas d'acquittement ici : la levée se fait via BtnConfirmCoherence/nouveau Home côté
// FB_Encoder_Homing (source), ce FB ne fait QUE relayer l'information pour FB_Modes.
IF NOT BypassGlobal THEN
    IF HomingSuspect THEN
        ErrorId := ErrorId OR 16#0002;
    ELSE
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
END_IF;

// 🧊 5. GELER SUR DOUTE (§6) — CablePosMSafe ne suit PAS CablePosM si hors plage
IF (ErrorId AND 16#0001) = 16#0000 THEN
    LastPlausibleCablePosM := CablePosM;
END_IF;
CablePosMSafe := LastPlausibleCablePosM;

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

EncoderIncoherent := Error;
Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2)
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;   // Garde division par zéro (PointsPerRev mal configuré)
END_IF;

// 🛑 1. GATE — désactivation ou AU non réarmé : aucune alarme persistante.
IF NOT Enable OR NOT EmergencyStopOk THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedDeltaMps := 0.0;
    SpeedVariationDetected := FALSE;
    SpeedVariationConfirmed := FALSE;
    SpeedStable := FALSE;
    VariationActive := FALSE;
    HasPreviousSpeed := FALSE;
    VariationTimer(IN := FALSE, PT := SpeedVariationTimeout);
    StabilityTimer(IN := FALSE, PT := SpeedStabilityTimeout);
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;

// 🔑 2. RESET FRONT — l'acquittement n'efface le défaut que si la cause a disparu.
ResetEdge(CLK := Reset);

// 📏 3. CALCUL DE L'ÉCART DE VITESSE — première mesure utilisée comme référence.
IF NOT HasPreviousSpeed THEN
    PreviousSpeedMps := SpeedMps;
    HasPreviousSpeed := TRUE;
    SpeedDeltaMps := 0.0;
ELSE
    SpeedDeltaMps := ABS(SpeedMps - PreviousSpeedMps);
    PreviousSpeedMps := SpeedMps;
END_IF;

// 🔍 4. DÉTECTION BRUTE + FILTRE TEMPOREL — pas de déclenchement si la durée vaut zéro.
VariationActive := HasPreviousSpeed
                   AND (SpeedVariationThresholdMps >= 0.0)
                   AND (SpeedVariationTimeout > T#0ms)
                   AND (SpeedDeltaMps > SpeedVariationThresholdMps);
SpeedVariationDetected := VariationActive;

VariationTimer(IN := VariationActive, PT := SpeedVariationTimeout);
SpeedVariationConfirmed := VariationTimer.Q;
StabilityTimer(IN := HasPreviousSpeed AND NOT VariationActive AND (SpeedStabilityTimeout > T#0ms), PT := SpeedStabilityTimeout);
SpeedStable := StabilityTimer.Q;

IF SpeedVariationConfirmed THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT VariationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📤 5. SORTIES D'ÉTAT — diagnostic standard, aucune commande mouvement.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

T := TIME_TO_REAL(TimeConst) / 1000.0; // ms → s

IF T <= 0.0 OR CycleTimeS <= 0.0 THEN
    ValueOut := ValueIn;
ELSE
    Alpha    := CycleTimeS / (T + CycleTimeS);
    ValueOut := Alpha * ValueIn + (1.0 - Alpha) * ValueOut;
END_IF;

// ═══════════════════════════════════════════════════════════════
// 1. 🛡️ GATE
// ═══════════════════════════════════════════════════════════════
IF NOT GVL_Simulation.SimulationModeActive THEN
    Sequencer(Start := FALSE, Abort := TRUE, CaseId := CaseId,
              StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
              ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report);
    GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
    GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
    GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;
    Busy := FALSE; Done := TRUE; AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.InProgress := FALSE; Report.Aborted := TRUE; Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState; Report.FailureSummary := 'Heartbeat : NOT SimulationModeActive';
    RETURN;
END_IF;

SimGateOk := GVL_Simulation.SimulationModeActive
          AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal
          AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal
          AND NOT GVL_Simulation.SensorBrakeThermalIsReal
          AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal;

IF Abort OR NOT SimGateOk THEN
    GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
    GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
    GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;
    IF Busy THEN GVL_IHM.Modes.Cmd.SelMode := StimModeRequest; END_IF;
    Busy := FALSE; Done := TRUE; AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.InProgress := FALSE; Report.Aborted := TRUE; Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState; Report.FailureSummary := 'Heartbeat : ABORTED or SimGateOk=FALSE';
    RETURN;
END_IF;

IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE; Done := FALSE; AnyFailed := FALSE; ConfigError := FALSE;
    ErrorCode := 0; ErrorMessage := '';
    StepElapsed := T#0s;
    StimModeRequest := GVL_IHM.Modes.Cmd.SelMode;

    Report.Name := 'Heartbeat Validation';
    Report.InProgress := TRUE; Report.AllPassed := FALSE; Report.AnyFailed := FALSE; Report.Aborted := FALSE;
    Report.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Report.ErrorCode := 0; Report.ErrorMessage := ''; Report.FailureSummary := '';
    Report.FailedTestCase := 0; Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
END_IF;
IF NOT Start THEN StartPrev := FALSE; END_IF;

IF NOT Busy THEN RETURN; END_IF;

// ═══════════════════════════════════════════════════════════════
// 2. 📋 TABLES (remplissage unique)
// ═══════════════════════════════════════════════════════════════
IF NOT TableReady THEN
    Report.Name := 'Heartbeat Validation';

    // ── Cas de tests ──
    CaseTable[1].Name := 'TC-H1 Heartbeat sain';      CaseTable[1].FirstStep := StepTcH1Setup;
    CaseTable[2].Name := 'TC-H2 Perte IHM 2s';        CaseTable[2].FirstStep := StepTcH2Setup;
    CaseTable[3].Name := 'TC-H3 Reprise sans redem';  CaseTable[3].FirstStep := StepTcH3Setup;
    CaseTable[4].Name := 'TC-H4 Reset conscient';     CaseTable[4].FirstStep := StepTcH4Setup;
    CaseTable[5].Name := 'TC-H5 Escalade Meca B M3';  CaseTable[5].FirstStep := StepTcH5Setup;

    // ── Checks (index = ligne CheckTable) ──
    // 1: HeartbeatIhmOk = TRUE
    CheckTable[1].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[1].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[1].ProbeIdx := SigHeartbeatIhmOk;        CheckTable[1].ExpectedBool := TRUE;
    // 2: bit0 Safety M1 = 0
    CheckTable[2].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[2].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[2].ProbeIdx := SigSafetyM1ErrorId;        CheckTable[2].Mask := 16#0001;
    // 3: bit0 Safety M2 = 0
    CheckTable[3].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[3].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[3].ProbeIdx := SigSafetyM2ErrorId;        CheckTable[3].Mask := 16#0001;
    // 4: bit0 Safety M3 = 0
    CheckTable[4].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[4].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[4].ProbeIdx := SigSafetyM3ErrorId;        CheckTable[4].Mask := 16#0001;
    // 5: bit5 Cycle = 0
    CheckTable[5].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[5].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[5].ProbeIdx := SigCycleErrorId;           CheckTable[5].Mask := 16#0020;

    // 6: HeartbeatIhmOk = FALSE
    CheckTable[6].Kind := E_TestCheckKind.BOOL_EQUAL;    CheckTable[6].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[6].ProbeIdx := SigHeartbeatIhmOk;         CheckTable[6].ExpectedBool := FALSE;
    // 7: HeartbeatIhmTimeout = TRUE
    CheckTable[7].Kind := E_TestCheckKind.BOOL_EQUAL;    CheckTable[7].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[7].ProbeIdx := SigHeartbeatIhmTimeout;    CheckTable[7].ExpectedBool := TRUE;
    // 8: bit0 Safety M1 = 1
    CheckTable[8].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[8].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[8].ProbeIdx := SigSafetyM1ErrorId;        CheckTable[8].Mask := 16#0001;
    // 9: bit0 Safety M2 = 1
    CheckTable[9].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[9].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[9].ProbeIdx := SigSafetyM2ErrorId;        CheckTable[9].Mask := 16#0001;
    // 10: bit0 Safety M3 = 1
    CheckTable[10].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[10].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[10].ProbeIdx := SigSafetyM3ErrorId;       CheckTable[10].Mask := 16#0001;
    // 11: bit5 Cycle = 1
    CheckTable[11].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[11].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[11].ProbeIdx := SigCycleErrorId;          CheckTable[11].Mask := 16#0020;

    // 12: SafeStop M1 (via Error)
    CheckTable[12].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[12].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[12].ProbeIdx := SigSafetyM1ErrorId;       CheckTable[12].ExpectedBool := TRUE;
    // 13: SafeStop M2
    CheckTable[13].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[13].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[13].ProbeIdx := SigSafetyM2ErrorId;       CheckTable[13].ExpectedBool := TRUE;
    // 14: SafeStop M3
    CheckTable[14].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[14].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[14].ProbeIdx := SigSafetyM3ErrorId;       CheckTable[14].ExpectedBool := TRUE;

    // 15: HeartbeatIhmOk = TRUE (reprise)
    CheckTable[15].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[15].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[15].ProbeIdx := SigHeartbeatIhmOk;        CheckTable[15].ExpectedBool := TRUE;
    // 16-19: bit0 M1/M2/M3 = 1, bit5 Cycle = 1 (mémorisation)
    CheckTable[16].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[16].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[16].ProbeIdx := SigSafetyM1ErrorId;       CheckTable[16].Mask := 16#0001;
    CheckTable[17].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[17].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[17].ProbeIdx := SigSafetyM2ErrorId;       CheckTable[17].Mask := 16#0001;
    CheckTable[18].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[18].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[18].ProbeIdx := SigSafetyM3ErrorId;       CheckTable[18].Mask := 16#0001;
    CheckTable[19].Kind := E_TestCheckKind.WORD_MASK_ANY; CheckTable[19].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[19].ProbeIdx := SigCycleErrorId;          CheckTable[19].Mask := 16#0020;

    // 20: Reset → bit0 M1/M2/M3 = 0, bit5 Cycle = 0
    CheckTable[20].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[20].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[20].ProbeIdx := SigSafetyM1ErrorId;         CheckTable[20].Mask := 16#0001;
    CheckTable[21].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[21].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[21].ProbeIdx := SigSafetyM2ErrorId;         CheckTable[21].Mask := 16#0001;
    CheckTable[22].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[22].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[22].ProbeIdx := SigSafetyM3ErrorId;         CheckTable[22].Mask := 16#0001;
    CheckTable[23].Kind := E_TestCheckKind.WORD_MASK_NONE; CheckTable[23].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[23].ProbeIdx := SigCycleErrorId;            CheckTable[23].Mask := 16#0020;

    // 24: TC-H5 Méca B M3 — PowerCutOffActive = TRUE
    CheckTable[24].Kind := E_TestCheckKind.BOOL_EQUAL;   CheckTable[24].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[24].ProbeIdx := SigPowerCutOffActive;     CheckTable[24].ExpectedBool := TRUE;

    // ── Étapes ──
    // TC-H1
    StepTable[StepTcH1Setup].Name := 'H1 Setup SEMI_AUTO + toggle sain';
    StepTable[StepTcH1Setup].CaseId := 1; StepTable[StepTcH1Setup].StimulusId := 1;
    StepTable[StepTcH1Setup].CheckIdx[1] := 1; StepTable[StepTcH1Setup].CheckIdx[2] := 2;
    StepTable[StepTcH1Setup].CheckIdx[3] := 3; StepTable[StepTcH1Setup].CheckIdx[4] := 4;
    StepTable[StepTcH1Setup].CheckIdx[5] := 5;
    StepTable[StepTcH1Setup].TimeoutPT := T#5s; StepTable[StepTcH1Setup].NextOnPass := StepTcH1WaitToggle;
    StepTable[StepTcH1Setup].NextOnFail := StepTcH1Teardown; StepTable[StepTcH1Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH1WaitToggle].Name := 'H1 Attente 1er front post-boot';
    StepTable[StepTcH1WaitToggle].CaseId := 1; StepTable[StepTcH1WaitToggle].StimulusId := 1;
    StepTable[StepTcH1WaitToggle].CheckIdx[1] := 1;
    StepTable[StepTcH1WaitToggle].TimeoutPT := T#4s; StepTable[StepTcH1WaitToggle].NextOnPass := StepTcH1Assert;
    StepTable[StepTcH1WaitToggle].NextOnFail := StepTcH1Teardown; StepTable[StepTcH1WaitToggle].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH1Assert].Name := 'H1 Assert bit0=0 & bit5=0';
    StepTable[StepTcH1Assert].CaseId := 1; StepTable[StepTcH1Assert].StimulusId := 1;
    StepTable[StepTcH1Assert].CheckIdx[1] := 2; StepTable[StepTcH1Assert].CheckIdx[2] := 3;
    StepTable[StepTcH1Assert].CheckIdx[3] := 4; StepTable[StepTcH1Assert].CheckIdx[4] := 5;
    StepTable[StepTcH1Assert].TimeoutPT := T#2s; StepTable[StepTcH1Assert].NextOnPass := StepTcH1Teardown;
    StepTable[StepTcH1Assert].NextOnFail := StepTcH1Teardown; StepTable[StepTcH1Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH1Teardown].Name := 'H1 Teardown';
    StepTable[StepTcH1Teardown].CaseId := 1; StepTable[StepTcH1Teardown].StimulusId := 0;
    StepTable[StepTcH1Teardown].DwellPT := T#200ms; StepTable[StepTcH1Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH1Teardown].NextOnPass := 0; StepTable[StepTcH1Teardown].NextOnFail := 0;

    // TC-H2
    StepTable[StepTcH2Setup].Name := 'H2 Setup toggle figé';
    StepTable[StepTcH2Setup].CaseId := 2; StepTable[StepTcH2Setup].StimulusId := 2;
    StepTable[StepTcH2Setup].TimeoutPT := T#1s; StepTable[StepTcH2Setup].NextOnPass := StepTcH2Freeze;
    StepTable[StepTcH2Setup].NextOnFail := StepTcH2Teardown; StepTable[StepTcH2Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH2Freeze].Name := 'H2 Figer toggle > 2s timeout';
    StepTable[StepTcH2Freeze].CaseId := 2; StepTable[StepTcH2Freeze].StimulusId := 2;
    StepTable[StepTcH2Freeze].TimeoutPT := T#3s; StepTable[StepTcH2Freeze].NextOnPass := StepTcH2Assert;
    StepTable[StepTcH2Freeze].NextOnFail := StepTcH2Teardown; StepTable[StepTcH2Freeze].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH2Assert].Name := 'H2 Assert bit0=1 & SafeStop';
    StepTable[StepTcH2Assert].CaseId := 2; StepTable[StepTcH2Assert].StimulusId := 2;
    StepTable[StepTcH2Assert].CheckIdx[1] := 6;  StepTable[StepTcH2Assert].CheckIdx[2] := 7;
    StepTable[StepTcH2Assert].CheckIdx[3] := 8;  StepTable[StepTcH2Assert].CheckIdx[4] := 9;
    StepTable[StepTcH2Assert].CheckIdx[5] := 10; StepTable[StepTcH2Assert].CheckIdx[6] := 11;
    StepTable[StepTcH2Assert].CheckIdx[7] := 12; StepTable[StepTcH2Assert].CheckIdx[8] := 13;
    StepTable[StepTcH2Assert].CheckIdx[9] := 14;
    StepTable[StepTcH2Assert].TimeoutPT := T#3s; StepTable[StepTcH2Assert].NextOnPass := StepTcH2Teardown;
    StepTable[StepTcH2Assert].NextOnFail := StepTcH2Teardown; StepTable[StepTcH2Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH2Teardown].Name := 'H2 Teardown';
    StepTable[StepTcH2Teardown].CaseId := 2; StepTable[StepTcH2Teardown].StimulusId := 0;
    StepTable[StepTcH2Teardown].DwellPT := T#200ms; StepTable[StepTcH2Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH2Teardown].NextOnPass := 0; StepTable[StepTcH2Teardown].NextOnFail := 0;

    // TC-H3
    StepTable[StepTcH3Setup].Name := 'H3 Setup reprise toggle';
    StepTable[StepTcH3Setup].CaseId := 3; StepTable[StepTcH3Setup].StimulusId := 3;
    StepTable[StepTcH3Setup].TimeoutPT := T#1s; StepTable[StepTcH3Setup].NextOnPass := StepTcH3Resume;
    StepTable[StepTcH3Setup].NextOnFail := StepTcH3Teardown; StepTable[StepTcH3Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH3Resume].Name := 'H3 Reprise toggle > 2s';
    StepTable[StepTcH3Resume].CaseId := 3; StepTable[StepTcH3Resume].StimulusId := 3;
    StepTable[StepTcH3Resume].TimeoutPT := T#3s; StepTable[StepTcH3Resume].NextOnPass := StepTcH3Assert;
    StepTable[StepTcH3Resume].NextOnFail := StepTcH3Teardown; StepTable[StepTcH3Resume].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH3Assert].Name := 'H3 Assert bit0=1 & bit5=1';
    StepTable[StepTcH3Assert].CaseId := 3; StepTable[StepTcH3Assert].StimulusId := 3;
    StepTable[StepTcH3Assert].CheckIdx[1] := 15; StepTable[StepTcH3Assert].CheckIdx[2] := 16;
    StepTable[StepTcH3Assert].CheckIdx[3] := 17; StepTable[StepTcH3Assert].CheckIdx[4] := 18;
    StepTable[StepTcH3Assert].CheckIdx[5] := 19;
    StepTable[StepTcH3Assert].TimeoutPT := T#3s; StepTable[StepTcH3Assert].NextOnPass := StepTcH3Teardown;
    StepTable[StepTcH3Assert].NextOnFail := StepTcH3Teardown; StepTable[StepTcH3Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH3Teardown].Name := 'H3 Teardown';
    StepTable[StepTcH3Teardown].CaseId := 3; StepTable[StepTcH3Teardown].StimulusId := 0;
    StepTable[StepTcH3Teardown].DwellPT := T#200ms; StepTable[StepTcH3Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH3Teardown].NextOnPass := 0; StepTable[StepTcH3Teardown].NextOnFail := 0;

    // TC-H4
    StepTable[StepTcH4Setup].Name := 'H4 Setup reset pulse';
    StepTable[StepTcH4Setup].CaseId := 4; StepTable[StepTcH4Setup].StimulusId := 4;
    StepTable[StepTcH4Setup].TimeoutPT := T#1s; StepTable[StepTcH4Setup].NextOnPass := StepTcH4Reset;
    StepTable[StepTcH4Setup].NextOnFail := StepTcH4Teardown; StepTable[StepTcH4Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH4Reset].Name := 'H4 Pulse Reset IHM & Cycle';
    StepTable[StepTcH4Reset].CaseId := 4; StepTable[StepTcH4Reset].StimulusId := 4;
    StepTable[StepTcH4Reset].TimeoutPT := T#2s; StepTable[StepTcH4Reset].NextOnPass := StepTcH4Assert;
    StepTable[StepTcH4Reset].NextOnFail := StepTcH4Teardown; StepTable[StepTcH4Reset].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH4Assert].Name := 'H4 Assert bit0=0 & bit5=0';
    StepTable[StepTcH4Assert].CaseId := 4; StepTable[StepTcH4Assert].StimulusId := 1; // retour toggle sain
    StepTable[StepTcH4Assert].CheckIdx[1] := 20; StepTable[StepTcH4Assert].CheckIdx[2] := 21;
    StepTable[StepTcH4Assert].CheckIdx[3] := 22; StepTable[StepTcH4Assert].CheckIdx[4] := 23;
    StepTable[StepTcH4Assert].TimeoutPT := T#3s; StepTable[StepTcH4Assert].NextOnPass := StepTcH4Teardown;
    StepTable[StepTcH4Assert].NextOnFail := StepTcH4Teardown; StepTable[StepTcH4Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH4Teardown].Name := 'H4 Teardown';
    StepTable[StepTcH4Teardown].CaseId := 4; StepTable[StepTcH4Teardown].StimulusId := 0;
    StepTable[StepTcH4Teardown].DwellPT := T#200ms; StepTable[StepTcH4Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH4Teardown].NextOnPass := 0; StepTable[StepTcH4Teardown].NextOnFail := 0;

    // TC-H5
    StepTable[StepTcH5Setup].Name := 'H5 Setup Meca B M3 frein open';
    StepTable[StepTcH5Setup].CaseId := 5; StepTable[StepTcH5Setup].StimulusId := 5;
    StepTable[StepTcH5Setup].TimeoutPT := T#1s; StepTable[StepTcH5Setup].NextOnPass := StepTcH5MecaB;
    StepTable[StepTcH5Setup].NextOnFail := StepTcH5Teardown; StepTable[StepTcH5Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH5MecaB].Name := 'H5 Perte IHM + M3 open > 3s';
    StepTable[StepTcH5MecaB].CaseId := 5; StepTable[StepTcH5MecaB].StimulusId := 5;
    StepTable[StepTcH5MecaB].TimeoutPT := T#7s; StepTable[StepTcH5MecaB].NextOnPass := StepTcH5Assert;
    StepTable[StepTcH5MecaB].NextOnFail := StepTcH5Teardown; StepTable[StepTcH5MecaB].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH5Assert].Name := 'H5 Assert PowerCutOffActive';
    StepTable[StepTcH5Assert].CaseId := 5; StepTable[StepTcH5Assert].StimulusId := 5;
    StepTable[StepTcH5Assert].CheckIdx[1] := 24;
    StepTable[StepTcH5Assert].TimeoutPT := T#3s; StepTable[StepTcH5Assert].NextOnPass := StepTcH5Teardown;
    StepTable[StepTcH5Assert].NextOnFail := StepTcH5Teardown; StepTable[StepTcH5Assert].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTcH5Teardown].Name := 'H5 Teardown';
    StepTable[StepTcH5Teardown].CaseId := 5; StepTable[StepTcH5Teardown].StimulusId := 0;
    StepTable[StepTcH5Teardown].DwellPT := T#200ms; StepTable[StepTcH5Teardown].TimeoutPT := T#1s;
    StepTable[StepTcH5Teardown].NextOnPass := 0; StepTable[StepTcH5Teardown].NextOnFail := 0;

    TableReady := TRUE;
END_IF;

// ═══════════════════════════════════════════════════════════════
// 3. 📥 ACQUIRE — câblage sondes (1 ligne par signal, pas de logique)
// ═══════════════════════════════════════════════════════════════
ProbeBool[SigHeartbeatIhmOk]       := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk;
ProbeBool[SigHeartbeatIhmTimeout]  := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmTimeout;
ProbeDint[SigSafetyM1ErrorId]      := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM1.ErrorId);
ProbeDint[SigSafetyM2ErrorId]      := WORD_TO_DINT(PRG_03_Safety.instSafetyWinchM2.ErrorId);
ProbeDint[SigSafetyM3ErrorId]      := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeDint[SigCycleErrorId]         := WORD_TO_DINT(PRG_05_Cycle.instCycle.ErrorId);
ProbeBool[SigM1FwdRevSpeedFbOff]   := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff;
ProbeBool[SigM1BrakeFeedback]      := PRG_00_Inputs.M1BrakeFeedback;
ProbeBool[SigM2FwdRevSpeedFbOff]   := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff;
ProbeBool[SigM2BrakeFeedback]      := PRG_00_Inputs.M2BrakeFeedback;
ProbeBool[SigM3BrakeFeedback]      := PRG_00_Inputs.M3BrakeFeedback;
ProbeReal[SigM3DriveActualFreqHz]  := UINT_TO_REAL(PRG_00_Inputs.M3_ActualFrequencyHz_Filtered) / 100.0;
ProbeDint[SigM3DriveStatusWord]    := WORD_TO_DINT(PRG_00_Inputs.M3_StatusWord_Filtered);
ProbeBool[SigPowerCutOffActive]    := GVL_IHM.Modes.State.PowerCutOffActive;

// ═══════════════════════════════════════════════════════════════
// 4. ⚙️ MOTEUR
// ═══════════════════════════════════════════════════════════════
Sequencer(Start := Start, Abort := Abort, CaseId := CaseId,
          StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
          ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report,
          Busy => Busy, Done => Done, AnyFailed => AnyFailed,
          ConfigError => ConfigError, ConfigErrorStepId => ConfigErrorStepId, ConfigErrorCheckIdx => ConfigErrorCheckIdx,
          ActiveStimulusId => ActiveStimulusId, StepElapsed => StepElapsed,
          TerminalState => TerminalState, ErrorCode => ErrorCode, ErrorMessage => ErrorMessage);

// ═══════════════════════════════════════════════════════════════
// 5. ⚡ STIMULI — modèle hybride : TOR état-complet + pulse timer
// ═══════════════════════════════════════════════════════════════
// StimulusId 0 = neutre garanti (tout relâché) — sur Done/Abort par le moteur
GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
GVL_IHM.Modes.Cmd.SelMode := StimModeRequest;
GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
GVL_IHM.Cycle.Cmd.BtnReset := FALSE;

CASE ActiveStimulusId OF
    1: // TC-H1/TC-H4 : toggle sain 500 ms + SEMI_AUTO
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        // Toggle 500 ms
        StimToggleTimer(IN := TRUE, PT := T#500ms);
        IF StimToggleTimer.Q THEN
            GVL_PLC_Tests.OverrideIhmHeartbeatToggle := NOT GVL_PLC_Tests.OverrideIhmHeartbeatToggle;
            StimToggleTimer(IN := FALSE);
        END_IF;

    2: // TC-H2 : toggle figé (perte IHM)
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        // OverrideIhmHeartbeatToggle figé = pas de front

    3: // TC-H3 : reprise toggle sain
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        StimToggleTimer(IN := TRUE, PT := T#500ms);
        IF StimToggleTimer.Q THEN
            GVL_PLC_Tests.OverrideIhmHeartbeatToggle := NOT GVL_PLC_Tests.OverrideIhmHeartbeatToggle;
            StimToggleTimer(IN := FALSE);
        END_IF;

    4: // TC-H4 : pulse reset conscient
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        StimToggleTimer(IN := TRUE, PT := T#500ms);
        IF StimToggleTimer.Q THEN
            GVL_PLC_Tests.OverrideIhmHeartbeatToggle := NOT GVL_PLC_Tests.OverrideIhmHeartbeatToggle;
            StimToggleTimer(IN := FALSE);
        END_IF;
        StimResetPulseTimer(IN := TRUE, PT := T#1500ms);
        IF NOT StimResetPulseTimer.Q THEN
            GVL_IHM.Modes.Cmd.BtnFaultReset := TRUE;
            GVL_IHM.Cycle.Cmd.BtnReset := TRUE;
        END_IF;

    5: // TC-H5 : perte IHM + frein M3 desserré → Méca B
        GVL_PLC_Tests.OverrideIhmHeartbeatActive := TRUE;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        GVL_PLC_Tests.OverrideM3BrakeStuckOpen := TRUE; // frein M3 desserré
        // Toggle figé = perte IHM
END_CASE;

// ═══════════════════════════════════════════════════════════════
// 6. 🛑 Premier échec → fin explicite, stimuli relâchés, rapport figé
// ═══════════════════════════════════════════════════════════════
IF ErrorCode <> 0 THEN
    GVL_PLC_Tests.OverrideIhmHeartbeatActive := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
    GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM1BrakeFeedback := FALSE;
    GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff := FALSE;
    GVL_PLC_Tests.OverrideM2BrakeFeedback := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;
    GVL_IHM.Modes.Cmd.SelMode := StimModeRequest;
    Busy := FALSE; Done := TRUE; AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_FAILED;
    Report.InProgress := FALSE; Report.TerminalState := TerminalState;
END_IF;

// === IMPLEMENTATION ===

// 🛑 Sans Enable, aucune valeur mémorisée ne peut déclarer l'IHM valide.
IF NOT Enable THEN
    HeartbeatIhmOk := FALSE;
    HeartbeatIhmTimeout := TRUE;
    TglHeartbeatPlc := FALSE;
    TimeSinceIhmEdge := T#0s;
    LastIhmToggle := TglHeartbeatIhm;
    IhmEdgeSeen := FALSE;
    IhmTimeoutTon(IN := FALSE, PT := IhmTimeout);
    PlcToggleTon(IN := FALSE, PT := PlcTogglePeriod);
    RETURN;
END_IF;

// 📥 Front par comparaison : l'IHM écrit un BOOL toggle, pas une impulsion courte.
IhmEdgeDetected := (TglHeartbeatIhm <> LastIhmToggle);
LastIhmToggle := TglHeartbeatIhm;
IF IhmEdgeDetected THEN
    IhmEdgeSeen := TRUE;
END_IF;

// ⏱️ Le timer repart à chaque front. Au boot, il atteint le timeout au bout de IhmTimeout.
// HeartbeatIhmOk reste TRUE tant que le timeout n'est pas expiré (boot propre sans alarme au scan 1).
IhmTimeoutTon(IN := NOT IhmEdgeDetected, PT := IhmTimeout);
TimeSinceIhmEdge := IhmTimeoutTon.ET;
HeartbeatIhmTimeout := IhmTimeoutTon.Q;
HeartbeatIhmOk := NOT HeartbeatIhmTimeout;

// 💡 Clignotant PLC indépendant : information de vie pour l'IHM, jamais signal Safety autonome.
PlcToggleTon(IN := NOT PlcToggleTon.Q, PT := PlcTogglePeriod);
IF PlcToggleTon.Q THEN
    TglHeartbeatPlc := NOT TglHeartbeatPlc;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Input) ===

// 1. Inversion NO/NC
ValueRaw := InputRaw XOR InvertLogic;

// 2. Initialisation premier scan & Filtrage anti-rebond
// Au premier scan post-boot, State prend directement la valeur saine brute sans attendre le délai de 20ms,
// ce qui évite d'émettre des fausses alarmes transitoires au démarrage de l'automate.
IF NOT FirstScanDone THEN
    State := ValueRaw;
    FirstScanDone := TRUE;
ELSE
    FilterTon(IN := (ValueRaw <> State), PT := FilterTime);
    IF FilterTon.Q THEN
        State := ValueRaw;   // Une fois à jour, IN redevient FALSE au cycle suivant (ValueRaw=State)
    END_IF;
END_IF;

// 3. Diagnostic voie/carte
IF NOT ChannelOk THEN
    ErrorId := ErrorId OR 16#0001;
    State := FALSE;   // État sûr forcé (Partie6 §1)
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

Error := (ErrorId <> 16#0000);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Joystick) ===

// 🛑 1. GATE (Sécurités et coupures prioritaires)
IF NOT Enable OR NOT EmergencyStopOk OR NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedRef := 0.0; AxisCmdX.Direction := 0;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedRef := 0.0; AxisCmdY.Direction := 0;
    SpeedXPct := 0.0; DirectionX := 0;
    SpeedYPct := 0.0; DirectionY := 0;
    Button := FALSE;
    DeadmanArmed := FALSE;   // 🆕 Désarmé sur toute neutralisation — nouvel appui au neutre exigé
    LeftNeutralSinceArm := FALSE;   // 🔧 2026-07-03terdecies — repart propre au prochain armement
    DeadmanTimer(IN := FALSE, PT := DeadmanRearmTimeout);   // 🆕 2026-07-03decies — pas d'accumulation à froid
    NeutralHoldTimer(IN := FALSE, PT := NeutralHoldTime);   // 🆕 2026-07-03duodecies — idem
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    LastMode := Mode;   // 🆕 REX 2026-07-08 — pas de faux changement détecté à la réactivation
    RETURN;
END_IF;

Ready := TRUE; Busy := TRUE;

// 🔑 2. RESET DÉFAUT (front uniquement + cause disparue, Partie3 §5)
// ⚠️ CORRECTIF (revue de code 2026-07-01) : l'ancienne version effaçait le défaut sur simple
// niveau `Reset AND Error`, sans front ET sans vérifier que la cause (calib hors plage) avait
// disparu — un Reset maintenu (bouton IHM bloqué) effaçait le défaut en boucle même si RawX/Y
// restaient hors plage. Non conforme au guardrail Reset (CLAUDE.md, Partie3 §5).
ResetEdge(CLK := Reset);
IF ResetEdge.Q AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📥 3. ACQUISITION TIMING & BOUTON
CycleTimeCalc();
Button := RawButton;

// 🎯 4. CALIBRATION DYNAMIQUE (Zone RETAIN)
IF BtnCalibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;
        NeutralYMem := RawY;
    ELSE
        // 🔧 CORRECTIF N7 (revue de code) : un seul bit pour une seule cause (Partie3 §3),
        // l'ancienne valeur 16#0003 levait à tort les bits 0 ET 1 pour un même défaut.
        ErrorId := ErrorId OR 16#0001;
    END_IF;
END_IF;
Error := (ErrorId <> 16#0000);
LastCalibrate := BtnCalibrate;

// 🧮 4bis. MISE À L'ÉCHELLE (avant homme-mort — le neutre s'évalue sur les 2 axes déjà deadbandés)
ScaleX(RawIn := RawX, Neutral := NeutralXMem, Deadband := Deadband);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, Deadband := Deadband);

// 🆕 4ter-bis. CHANGEMENT DE MODE (REX 2026-07-08, demande utilisateur) : désarme le homme-mort
// dès que Mode change (MAINT_N1/N2/SEMI_AUTO/AUTO) — évite qu'une commande en cours (manche non
// centré) ne "traverse" le changement de mode et ne soit réinterprétée soudainement dans le
// nouveau contexte de mode (risque de mouvement soudain). Repassage par le neutre + nouvel appui
// bouton exigé, comme n'importe quel désarmement (§4ter ci-dessous).
IF Mode <> LastMode THEN
    DeadmanArmed := FALSE;
    LeftNeutralSinceArm := FALSE;
END_IF;
LastMode := Mode;

// 🆕 4ter-ter. FIN DE CYCLE BENNE (REX 2026-07-08, demande utilisateur) : désarme le homme-mort
// dès que Benne.Busy retombe (cible atteinte ou retour position départ). Sans ça, si l'opérateur
// tient encore le manche poussé (ce qu'il fait pour piloter le benne via M2), les gates
// "NOT Benne.Busy" côté PRG_06_WinchControl s'ouvrent immédiatement pour M1 ET M2 — les deux
// treuils démarrent alors directement sur la commande manche en cours, sans repasser par le
// neutre, et FB_WinchSync (réactivé au même instant) détecte aussitôt un écart de position
// (M1 immobile pendant le cycle, M2 ayant bougé de l'offset benne) → faux défaut synchro.
BenneBusyFallEdge(CLK := BenneBusy);
IF BenneBusyFallEdge.Q THEN
    DeadmanArmed := FALSE;
    LeftNeutralSinceArm := FALSE;
END_IF;

// 🔴 4ter. BOUTON HOMME-MORT (2026-07-03octies + renforcé decies/duodecies/terdecies — voir en-tête)
DeadmanEdge(CLK := RawButton);

// 🔧 2026-07-03terdecies (CORRECTIF review) : `LeftNeutralSinceArm` distingue "vient d'armer,
// n'a pas encore bougé" (NE DOIT PAS désarmer, même après NeutralHoldTime — l'opérateur a le
// temps qu'il veut pour démarrer son geste après l'appui) de "a bougé, PUIS est revenu au
// neutre" (là, `NeutralHoldTime` s'applique normalement, voir plus bas). Sans ce garde-fou, un
// opérateur qui arme puis hésite plus de NeutralHoldTime avant de bouger se faisait désarmer
// silencieusement (fail-safe, mais contredisait l'intention D57).
IF NOT DeadmanArmed THEN
    LeftNeutralSinceArm := FALSE;   // Repos/désarmé : prêt pour le prochain armement
ELSIF NOT ((ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0)) THEN
    LeftNeutralSinceArm := TRUE;    // Armé et a quitté le neutre au moins une fois : geste réellement démarré
END_IF;

// Le neutre doit être TENU `NeutralHoldTime` avant de désarmer (pas juste traversé) — sinon une
// inversion de sens rapide (Fwd→Rev) désarmerait à tort au passage par le neutre. Ne s'applique
// QU'APRÈS un geste réellement démarré (`LeftNeutralSinceArm`), jamais juste après l'armement.
NeutralHoldTimer(IN := DeadmanArmed AND LeftNeutralSinceArm AND (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0),
                 PT := NeutralHoldTime);
IF NeutralHoldTimer.Q THEN
    DeadmanArmed := FALSE;      // Neutre tenu assez longtemps APRÈS un geste démarré = fin réelle
END_IF;
IF DeadmanEdge.Q AND (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0) THEN
    DeadmanArmed := TRUE;       // Appui bouton AU NEUTRE = armement
END_IF;

// 🆕 4quater. RECONFIRMATION PÉRIODIQUE (2026-07-03decies, CORRIGÉ undecies suite review) — tant
// qu'armé ET en mouvement (hors neutre), le bouton doit être soit MAINTENU, soit ré-appuyé, avant
// DeadmanRearmTimeout. ⚠️ CORRECTIF : le 1er jet ne détectait qu'un FRONT (`DeadmanEdge.Q`) — un
// opérateur qui MAINTIENT le bouton enfoncé en continu (réflexe naturel homme-mort) ne générait
// plus jamais de front après le 1er appui → désarmement surprise au bout de 3s MALGRÉ la présence
// continue. Corrigé : `NOT RawButton` (niveau, pas front) — maintenir OU réappuyer dans le délai
// remettent tous les deux `IN` à FALSE (TON.ET repart de 0), seul un RELÂCHEMENT PROLONGÉ désarme.
DeadmanTimer(IN := DeadmanArmed AND NOT ((ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0)) AND NOT RawButton,
             PT := DeadmanRearmTimeout);
IF DeadmanTimer.Q THEN
    DeadmanArmed := FALSE;      // Pas de reconfirmation dans le délai → désarmement (décélération sûre)
END_IF;

// 🕹️ 5. PIPELINE TRAITEMENT — AXE X
IF InvertX THEN
    FilterX(ValueIn := -ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterX(ValueIn := ScaleX.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// 🔴 Cible rampe forcée à 0 tant que le geste n'est pas armé (homme-mort, voir §4ter)
RampX(Target := SEL(DeadmanArmed, 0.0, FilterX.ValueOut), AccelRate := AccelRate, DecelRate := DecelRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

// Mapping Sortie Standardisée Axe X
// 🔧 2026-07-02 : SpeedRef désormais SIGNÉ (plus de ABS) — le signe porte le sens, cohérent
// avec Direction ci-dessous (même seuil 0.1, même variable RampX.Current). StartStop reste
// calculé sur la MAGNITUDE (indépendant du signe) : sinon un mouvement négatif (< -0.1) serait
// à tort interprété comme "pas de mouvement" (StartStop=FALSE) par le test `> 0.1` direct.
AxisCmdX.Enable := TRUE;
AxisCmdX.SpeedRef := RampX.Current;
AxisCmdX.StartStop := (ABS(RampX.Current) > 0.1);

IF RampX.Current > 0.1 THEN     AxisCmdX.Direction := 1;
ELSIF RampX.Current < -0.1 THEN AxisCmdX.Direction := -1;
ELSE AxisCmdX.Direction := 0;   AxisCmdX.SpeedRef := 0.0;
END_IF;

// 🆕 Miroirs maintenance (voir en-tête) — mêmes valeurs, à plat
SpeedXPct := AxisCmdX.SpeedRef;
DirectionX := AxisCmdX.Direction;

// 🕹️ 6. PIPELINE TRAITEMENT — AXE Y (ScaleY déjà calculé en §4bis, avant homme-mort)
IF InvertY THEN
    FilterY(ValueIn := -ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
ELSE
    FilterY(ValueIn := ScaleY.OutPct, TimeConst := FilterTime, CycleTimeS := CycleTimeCalc.CycleTimeS);
END_IF;

// 🔴 Cible rampe forcée à 0 tant que le geste n'est pas armé (homme-mort, voir §4ter)
RampY(Target := SEL(DeadmanArmed, 0.0, FilterY.ValueOut), AccelRate := AccelRate, DecelRate := DecelRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

// Mapping Sortie Standardisée Axe Y
// 🔧 2026-07-02 : voir note axe X ci-dessus (même principe, SpeedRef signé + StartStop sur magnitude)
AxisCmdY.Enable := TRUE;
AxisCmdY.SpeedRef := RampY.Current;
AxisCmdY.StartStop := (ABS(RampY.Current) > 0.1);

IF RampY.Current > 0.1 THEN     AxisCmdY.Direction := 1;
ELSIF RampY.Current < -0.1 THEN AxisCmdY.Direction := -1;
ELSE AxisCmdY.Direction := 0;   AxisCmdY.SpeedRef := 0.0;
END_IF;

// 🆕 Miroirs maintenance (voir en-tête) — mêmes valeurs, à plat
SpeedYPct := AxisCmdY.SpeedRef;
DirectionY := AxisCmdY.Direction;

// 📤 7. VALIDATION DES SORTIES ÉTAT
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
Done := NOT Error;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Modes) ===

// 🛑 1. GATE — repli sur le mode de sécurité de veille (DISABLE) si désactivé
// ou si l'arrêt d'urgence est déclenché.
IF NOT Enable OR NOT EmergencyStopOk THEN
    Mode := E_Mode.DISABLE;
    SyncEnable := TRUE;
    InhibitM1 := FALSE;
    InhibitM2 := FALSE;
    HomingApproachEnable := FALSE;
    JoystickWinchSelectArbitrated := 3; // Par défaut couplé
    MaintenanceM3TargetEnable := FALSE;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 3. GARDE-FOUS
// bit0 : SEMI_AUTO demandé mais défaut codeur présent → refusé, repli MAINT_N1
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 📤 4. ARBITRAGE DU MODE
// 🔧 REX 2026-07-07 : plus de garde-fou mot de passe ici — MAINT_N2 accepté directement,
// l'accès est filtré en amont côté IHM (visibilité des actions selon niveau utilisateur).
IF (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent THEN
    Mode := E_Mode.MAINT_N1;
ELSE
    Mode := SelMode;
END_IF;

// 📤 5. SYNC ENABLE — actionnable en MAINT_N1 OU MAINT_N2 (Décision D_OVERRIDESYNC 2026-07-04)
// Anciennement restreint à MAINT_N2 uniquement, mais l'opérateur peut avoir besoin de la
// procédure de récupération mou câble dès MAINT_N1. 🔧 REX 2026-07-08 : polarité inversée —
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
SyncEnable := NOT ((Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2) AND NOT SelSyncEnable);

// 📤 5bis. INHIBITION TREUIL — mise en service, demande utilisateur (REX 2026-07-08)
// UNIQUEMENT actionnable en MAINT_N2 (contrairement à SyncEnable, actionnable aussi N1) —
// action plus sensible (neutralise complètement un treuil ET sa propre supervision safety),
// réservée au niveau de droits le plus élevé. Centralisé ICI (comme SyncEnable) : aucun
// autre fichier ne doit re-tester Mode=MAINT_N2 pour ce besoin.
InhibitM1 := (Mode = E_Mode.MAINT_N2) AND InhibitM1Request;
InhibitM2 := (Mode = E_Mode.MAINT_N2) AND InhibitM2Request;

// 📤 5ter. OVERRIDE ARRÊT HAUT — mise en service, demande utilisateur (REX 2026-07-08 (2))
// UNIQUEMENT actionnable en MAINT_N2 — remplace l'ancien test direct Mode<>MAINT_N2 dans
// PRG_06_WinchControl.st, qui bypassait l'arrêt normal pour N'IMPORTE QUELLE opération N2.
// Désormais un choix conscient explicite est requis EN PLUS du mode.
HomingApproachEnable := (Mode = E_Mode.MAINT_N2) AND SelHomingApproachEnable;

// 📤 5quater. SÉLECTEUR JOYSTICK — TASK-0001 (2026-07-15)
// M1 seul (=1) ou M2 seul (=2) au joystick est réservé au mode MAINT_N2
// pour éviter de désynchroniser accidentellement les treuils (câble en travers).
// Forcé à Couplé (=3) dans tous les autres modes (MAINT_N1, SEMI_AUTO, DISABLE).
IF Mode = E_Mode.MAINT_N2 THEN
    JoystickWinchSelectArbitrated := JoystickWinchSelectRequest;
ELSE
    JoystickWinchSelectArbitrated := 3; // Couplé forcé
END_IF;

// 📤 5quinquies. CIBLE TRANSLATION "MAINTENANCE" — mise en service, décision client 2026-07-17
// (AF_Partie-02 v2.12 §3bis) : bloquée en MAINT_N1 et SEMI_AUTO, autorisée UNIQUEMENT en MAINT_N2.
// Centralisé ICI (même doctrine que InhibitM1/M2, HomingApproachEnable) : aucun autre fichier ne
// doit re-tester Mode=MAINT_N2 pour ce besoin — PRG_07_TranslationControl consomme ce bit.
MaintenanceM3TargetEnable := (Mode = E_Mode.MAINT_N2);

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

Busy := FALSE;
Done := FALSE;

// Gate simulation : nécessite le joystick simulé (override programmatique) et M1 simulé.
SimGateOk := GVL_Simulation.SimulationModeActive
          AND NOT GVL_Simulation.BusJoystickSignalIsReal
          AND NOT GVL_Simulation.BusEncoderM1IsReal
          AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal;

ActiveStimulusId := 0;

IF Abort THEN
    GVL_PLC_Tests.OverrideJoystickActive := FALSE;
    GVL_PLC_Tests.OverrideContactorFalse := FALSE;
    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Cycle.Cmd.BtnStart := FALSE;
    GVL_PLC_Tests.OverrideHmiCommandPurge := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    Report.Aborted := TRUE;
    Report.AnyFailed := TRUE;
    Report.TerminalState := TerminalState;
    Report.FailureSummary := 'Modes/Homme-mort : ABORTED';
    RETURN;
END_IF;

IF Start AND NOT StartPrev AND NOT Busy THEN
    StartPrev := TRUE;
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    ConfigError := FALSE;
    ErrorCode := 0;
    ErrorMessage := '';
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    IF CaseId < 0 OR CaseId > 12 THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ConfigError := TRUE;
        ErrorCode := 5001;
        ErrorMessage := 'Modes CaseId invalide';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.TerminalState := TerminalState;
        Report.AnyFailed := TRUE;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        RETURN;
    END_IF;
    RequestedCaseId := CaseId;
    CASE RequestedCaseId OF
        1: Step := 10;
        2: Step := 20;
        3: Step := 30;
        4: Step := 40;
        5: Step := 50;
        6: Step := 60;
        7: Step := 70;
        8: Step := 90;
        9: Step := 80;
        10: Step := 90;
        11: Step := 100;
        12: Step := 110;
    ELSE
        Step := 5;
    END_CASE;
    Report.Name := 'Modes / Homme-mort Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailureSummary := '';
    Report.CurrentStepId := Step;
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Index].Executed := FALSE;
        Report.Steps[Index].Passed := FALSE;
        Report.Steps[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Index].Duration := T#0s;
    END_FOR;
    FOR Index := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Index].Executed := FALSE;
        Report.Cases[Index].Ok := FALSE;
        Report.Cases[Index].FailedStepId := 0;
        Report.Cases[Index].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Index].Duration := T#0s;
    END_FOR;
    StepStarted := FALSE;
    GVL_PLC_Tests.OverrideJoystickActive := TRUE;
    GVL_PLC_Tests.OverrideJoystickRawX := 5000;
    GVL_PLC_Tests.OverrideJoystickRawY := 5000;
    GVL_PLC_Tests.OverrideJoystickRawButton := FALSE;
ELSIF NOT Start THEN
    StartPrev := FALSE;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
Report.CurrentStepId := Step;
CurrentCaseId := (Step / 10);
Report.CurrentCaseId := CurrentCaseId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    CASE Step OF
        5: StepLimit := T#5s;         // Préambule : armement contacteur simulé
        10, 20: StepLimit := T#3s;   // Mode appliqué + neutre initial
        11, 21: StepLimit := T#5s;   // Armement + départ mouvement
        12: StepLimit := T#5s;       // TC-M1 uniquement : relâchement → arrêt
        13: StepLimit := T#3s;       // TC-M1 uniquement : neutre tenu >1s (NeutralHoldTime)
        14: StepLimit := T#5s;       // TC-M1 uniquement : reprise → mouvement repart
        30: StepLimit := T#5s;       // SEMI_AUTO atteint
        40: StepLimit := T#3s;       // Simulation OK sans IHM_MANU
        50: StepLimit := T#3s;       // Perte EmergencyStopOk → Mode DISABLE
        51: StepLimit := T#3s;       // FB_Winch neutralisé (State DISABLED)
        52: StepLimit := T#5s;       // Récupération après restauration EmergencyStopOk
        60: StepLimit := T#3s;       // Tentative réelle de démarrage hors SEMI_AUTO (pas de blocage)
        65, 66: StepLimit := T#3s;   // DISABLE explicite + neutralisation des 3 axes
        70, 71: StepLimit := T#2s;   // Bypass codeur hors/dans MAINT_N2
        80: StepLimit := T#2s;       // ConfigError SpeedStep → FB_Winch bit2
        90, 91: StepLimit := T#2s;   // Estimateur descente/montée
        100, 101, 102: StepLimit := T#2s; // Seuil ASCENDING_LOADED
        110, 111: StepLimit := T#2s; // Purge commandes RETAIN
    ELSE
        ConfigError := TRUE;
        ConfigErrorStepId := Step;
        ErrorCode := 4001;
        ErrorMessage := 'Modes/Homme-mort étape inconnue';
        StepLimit := T#0s;
    END_CASE;
END_IF;

StepTimer(IN := TRUE, PT := StepLimit);
NeutralHoldTimer(IN := (Step = 13) AND (ABS(GVL_PLC_Tests.OverrideJoystickRawY - 5000) < 500), PT := T#1200MS);

CASE Step OF
    // ─────────── Préambule : armement contacteur simulé (requis sans hardware) ───────────
    5:
        GVL_IHM.Modes.Cmd.BtnEmergencyArming := TRUE; // pulse réarmement → SimContactorOk → EmergencyStopOk
        IF PRG_00_Inputs.EmergencyStopOk THEN
            GVL_IHM.Modes.Cmd.BtnEmergencyArming := FALSE;
            StepPassed := TRUE;
            Step := 10;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M1 : MAINT_N1 + homme-mort (+ arrêt + reprise) ───────────
    10:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N1;
        GVL_PLC_Tests.OverrideJoystickRawY := 5000; // neutre
        GVL_PLC_Tests.OverrideJoystickRawButton := FALSE;
        IF SimGateOk AND (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N1) THEN
            StepPassed := TRUE;
            Step := 11;
            StepStarted := FALSE;
        END_IF;

    11:
        // Armement (bouton pressé AU NEUTRE) puis débattement Fwd — homme-mort réel de FB_Joystick.
        GVL_PLC_Tests.OverrideJoystickRawButton := TRUE;
        GVL_PLC_Tests.OverrideJoystickRawY := 10000; // plein débattement montée
        IF PRG_06_WinchControl.instWinchM1.RelayFwd THEN
            StepPassed := TRUE;
            Step := 12;
            StepStarted := FALSE;
        END_IF;

    12:
        // Relâchement du bouton homme-mort → le mouvement doit s'arrêter (item "relâchement=arrêt").
        GVL_PLC_Tests.OverrideJoystickRawButton := FALSE;
        IF NOT PRG_06_WinchControl.instWinchM1.RelayFwd THEN
            StepPassed := TRUE;
            Step := 13;
            StepStarted := FALSE;
        END_IF;

    13:
        // Retour + maintien au neutre >NeutralHoldTime (1s en simulation) pour un réarmement propre.
        GVL_PLC_Tests.OverrideJoystickRawY := 5000;
        IF NeutralHoldTimer.Q THEN
            StepPassed := TRUE;
            Step := 14;
            StepStarted := FALSE;
        END_IF;

    14:
        // Reprise : nouvel appui AU NEUTRE puis débattement → mouvement doit repartir.
        GVL_PLC_Tests.OverrideJoystickRawButton := TRUE;
        GVL_PLC_Tests.OverrideJoystickRawY := 10000;
        IF PRG_06_WinchControl.instWinchM1.RelayFwd THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 1 THEN Step := 0; ELSE Step := 20; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M2 : MAINT_N2 + homme-mort ───────────
    20:
        GVL_PLC_Tests.OverrideJoystickRawButton := FALSE;
        GVL_PLC_Tests.OverrideJoystickRawY := 5000;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N2;
        IF SimGateOk AND (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N2) THEN
            StepPassed := TRUE;
            Step := 21;
            StepStarted := FALSE;
        END_IF;

    21:
        GVL_PLC_Tests.OverrideJoystickRawButton := TRUE;
        GVL_PLC_Tests.OverrideJoystickRawY := 10000;
        IF PRG_06_WinchControl.instWinchM1.RelayFwd THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 2 THEN Step := 0; ELSE Step := 30; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M3 : SEMI_AUTO atteignable sans IHM_MANU ───────────
    30:
        GVL_PLC_Tests.OverrideJoystickRawButton := FALSE;
        GVL_PLC_Tests.OverrideJoystickRawY := 5000;
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.SEMI_AUTO;
        IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 3 THEN Step := 0; ELSE Step := 40; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M4 : Simulation fonctionnelle sans IHM_MANU ───────────
    40:
        IF GVL_Simulation.SimulationModeActive AND SimGateOk THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 4 THEN Step := 0; ELSE Step := 50; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M5 : Sécurité active + aucun mouvement sans autorisation de mode ───────────
    50:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N1;
        GVL_PLC_Tests.OverrideContactorFalse := TRUE; // Force EmergencyStopOk := FALSE (voir PRG_00_Inputs)
        IF PRG_04_Modes.instModes.Mode = E_Mode.DISABLE THEN
            StepPassed := TRUE;
            Step := 51;
            StepStarted := FALSE;
        END_IF;

    51:
        IF PRG_06_WinchControl.instWinchM1.State = E_State.DISABLED
           AND NOT PRG_06_WinchControl.instWinchM1.Ready THEN
            StepPassed := TRUE;
            Step := 52;
            StepStarted := FALSE;
        END_IF;

    52:
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        GVL_IHM.Modes.Cmd.BtnFaultReset := TRUE;
        IF PRG_04_Modes.instModes.Mode <> E_Mode.DISABLE THEN
            GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
            StepPassed := TRUE;
            IF RequestedCaseId = 5 THEN Step := 0; ELSE Step := 60; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M6 : Séquenceur (FB_Cycle) ne bloque jamais ───────────
    60:
        // 🔧 REX 2026-07-19 (revue mission IHM_MANU, finding B) : tentative RÉELLE de
        // démarrage (GVL_IHM.Cycle.Cmd.BtnStart, ré-assertée chaque scan pour couvrir l'ordre
        // des tâches) pendant >200 ms hors SEMI_AUTO — instCycle.Enable=FALSE doit la rendre
        // sans effet (Busy reste FALSE), pas un simple instantané qui ne prouverait rien.
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.MAINT_N1;
        GVL_IHM.Cycle.Cmd.BtnStart := TRUE;
        IF (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N1) AND (StepElapsed >= T#200MS) THEN
            GVL_IHM.Cycle.Cmd.BtnStart := FALSE;
            IF NOT PRG_05_Cycle.instCycle.Busy THEN
                StepPassed := TRUE;
                IF RequestedCaseId = 6 THEN Step := 0; ELSE Step := 65; END_IF;
            ELSE
                StepFailed := TRUE;
                Step := 0;
            END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M7 : DISABLE explicite neutralise M1/M2/M3 ───────────
    65:
        GVL_IHM.Modes.Cmd.SelMode := E_Mode.DISABLE;
        IF PRG_04_Modes.instModes.Mode = E_Mode.DISABLE THEN
            StepPassed := TRUE;
            Step := 66;
            StepStarted := FALSE;
        END_IF;

    66:
        IF (PRG_06_WinchControl.instWinchM1.State = E_State.DISABLED)
           AND (PRG_06_WinchControl.instWinchM2.State = E_State.DISABLED)
           AND (PRG_07_TranslationControl.instTranslationM3.State = E_State.DISABLED)
           AND NOT PRG_06_WinchControl.instWinchM1.RelayFwd
           AND NOT PRG_06_WinchControl.instWinchM2.RelayFwd
           AND (PRG_07_TranslationControl.instTranslationM3.DriveControlWord = 0) THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 7 THEN Step := 0; ELSE Step := 70; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M8 : bypass codeur individuel et limité à MAINT_N2 ───────────
    70:
        TestSafetyWinch(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
            SyncEnable := TRUE, JoystickOnline := TRUE, JoystickOperational := TRUE,
            HeartbeatIhmOk := TRUE, EncoderAvailable := FALSE, EncoderFaultBypass := TRUE,
            ThermalFeedback := FALSE, BrakeThermalFeedback := FALSE, SlackCableDetected := FALSE,
            PhaseRotationOk := TRUE, TopPositionSensor := TRUE, InReferencingMode := FALSE,
            CablePosM := 0.0, CfgCableLimitDescentM := -20.0, Direction := 0,
            MovementCommanded := FALSE, Homed := FALSE, HomingSuspect := FALSE, TopLimitM := 8.5,
            FwdRevSpeedFeedbackOff := TRUE, BrakeFeedback := TRUE, JoystickYNeutral := FALSE,
            BenneHoldStillActive := FALSE, ExpectedOtherWinchPosM := 0.0, BenneBusy := FALSE,
            OtherWinchInhibited := TRUE
        );
        IF ((TestSafetyWinch.ErrorId AND 16#0002) <> 0) AND TestSafetyWinch.SafeStop THEN
            StepPassed := TRUE;
            Step := 71;
            StepStarted := FALSE;
        END_IF;

    71:
        TestSafetyWinch(
            Enable := TRUE, Reset := TRUE, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N2,
            SyncEnable := TRUE, JoystickOnline := TRUE, JoystickOperational := TRUE,
            HeartbeatIhmOk := TRUE, EncoderAvailable := FALSE, EncoderFaultBypass := TRUE,
            ThermalFeedback := FALSE, BrakeThermalFeedback := FALSE, SlackCableDetected := FALSE,
            PhaseRotationOk := TRUE, TopPositionSensor := TRUE, InReferencingMode := FALSE,
            CablePosM := 0.0, CfgCableLimitDescentM := -20.0, Direction := 0,
            MovementCommanded := FALSE, Homed := FALSE, HomingSuspect := FALSE, TopLimitM := 8.5,
            FwdRevSpeedFeedbackOff := TRUE, BrakeFeedback := TRUE, JoystickYNeutral := FALSE,
            BenneHoldStillActive := FALSE, ExpectedOtherWinchPosM := 0.0, BenneBusy := FALSE,
            OtherWinchInhibited := TRUE
        );
        IF ((TestSafetyWinch.ErrorId AND 16#0002) = 0) AND NOT TestSafetyWinch.SafeStop THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 8 THEN Step := 0; ELSE Step := 80; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M9 : ConfigError interne remonte dans FB_Winch bit2 ───────────
    80:
        TestWinch(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
            StartStop := TRUE, SafeStop := FALSE, ForbidDescent := FALSE, ForbidAscent := FALSE,
            Direction := 1, SpeedRefPct := 50.0, SpeedStepTable := TestSpeedTable,
            CfgMaxStepDescente := 3, MaxStepAscent := 5, HomingApproachActive := FALSE,
            FwdRevSpeedFeedbackOff := TRUE, BrakeFeedback := TRUE, BypassContactorCheck := TRUE,
            SpeedStepHystMargin := 0.0, Homed := TRUE, HomingSuspect := FALSE,
            CablePosM := 0.0, TopLimitM := 8.0, BottomLimitM := -20.0,
            CfgSlowdownDistanceM := 1.0, CfgSlowSpeedPct := 15.0
        );
        IF ((TestWinch.ErrorId AND 16#0004) <> 0)
           AND NOT TestWinch.RelayFwd AND NOT TestWinch.RelayRev
           AND NOT TestWinch.Contactor1 AND NOT TestWinch.Contactor2
           AND NOT TestWinch.Contactor3 AND NOT TestWinch.Contactor4 THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 9 THEN Step := 0; ELSE Step := 90; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M10 : charge calculée uniquement en montée ───────────
    90:
        TestLoadTable.IsConfigured := TRUE;
        TestLoadTable.LoadPctByStepAndSpeedBand[1][1] := 42.0;
        TestLoadEstimator(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
            ActiveSpeedStep := 1, MeasuredSpeedMps := 0.1, MeasuredSpeedSignedMps := -0.1,
            SpeedConfig := TestSpeedConfig, LoadTable := TestLoadTable
        );
        IF (TestLoadEstimator.EstimatedLoadPct = 0.0) AND NOT TestLoadEstimator.Ascending THEN
            StepPassed := TRUE;
            Step := 91;
            StepStarted := FALSE;
        END_IF;

    91:
        TestLoadEstimator(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
            ActiveSpeedStep := 1, MeasuredSpeedMps := 0.1, MeasuredSpeedSignedMps := 0.1,
            SpeedConfig := TestSpeedConfig, LoadTable := TestLoadTable
        );
        IF (TestLoadEstimator.EstimatedLoadPct = 42.0) AND TestLoadEstimator.Ascending THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 10 THEN Step := 0; ELSE Step := 100; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M11 : seuil ASCENDING_LOADED = limite exploitation ───────────
    100:
        TestCycle(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, CycleMotionPermit := TRUE,
            HeartbeatIhmOk := TRUE, M1_CablePosM := 7.9, M2_CablePosM := 7.9,
            CableLimitM1AscentM := 8.0
        );
        // FB démarre en INIT ; on ne force pas l'état interne (pas d'accès VAR).
        // Vérifie seulement que la condition de transition est évaluée correctement :
        // tant que M1_CablePosM < CableLimitM1AscentM, les sorties StartStop restent TRUE
        IF TestCycle.CmdWinchM1_StartStop AND TestCycle.CmdWinchM2_StartStop THEN
            StepPassed := TRUE;
            Step := 101;
            StepStarted := FALSE;
        END_IF;

    101:
        TestCycle(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, CycleMotionPermit := TRUE,
            HeartbeatIhmOk := TRUE, M1_CablePosM := 8.0, M2_CablePosM := 8.0,
            CableLimitM1AscentM := 8.0
        );
        // M1_CablePosM >= CableLimitM1AscentM : la logique de transition demande l'arrêt
        IF NOT TestCycle.CmdWinchM1_StartStop AND NOT TestCycle.CmdWinchM2_StartStop THEN
            StepPassed := TRUE;
            Step := 102;
            StepStarted := FALSE;
        END_IF;

    102:
        TestCycle(
            Enable := TRUE, Reset := FALSE, EmergencyStopOk := TRUE, CycleMotionPermit := TRUE,
            HeartbeatIhmOk := TRUE, M1_CablePosM := 8.0, M2_CablePosM := 8.0,
            CableLimitM1AscentM := 8.0
        );
        // L'état interne devrait passer à DRAINING_PAUSE, mais on ne peut pas
        // forcer l'état. On vérifie que les sorties restent à l'arrêt.
        IF NOT TestCycle.CmdWinchM1_StartStop AND NOT TestCycle.CmdWinchM2_StartStop THEN
            StepPassed := TRUE;
            IF RequestedCaseId = 11 THEN Step := 0; ELSE Step := 110; END_IF;
            StepStarted := FALSE;
        END_IF;

    // ─────────── TC-M12 : purge commandes RETAIN avant consommation ───────────
    110:
        GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := TRUE;
        GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault := TRUE;
        GVL_IHM.M2TreuilBenne.Cmd.BtnReset := TRUE;
        GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnClose := TRUE;
        GVL_IHM.Cycle.Cmd.BtnStart := TRUE;
        GVL_IHM.TranslationM3.Cmd.BtnFwd := TRUE;
        GVL_PLC_Tests.OverrideHmiCommandPurge := TRUE;
        StepPassed := TRUE;
        Step := 111;
        StepStarted := FALSE;

    111:
        IF NOT GVL_IHM.M1TreuilRetenue.Cmd.BtnHome
           AND NOT GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault
           AND NOT GVL_IHM.M2TreuilBenne.Cmd.BtnReset
           AND NOT GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnClose
           AND NOT GVL_IHM.Cycle.Cmd.BtnStart
           AND NOT GVL_IHM.TranslationM3.Cmd.BtnFwd
           AND GVL_IHM.HmiInitDone THEN
            GVL_PLC_Tests.OverrideHmiCommandPurge := FALSE;
            StepPassed := TRUE;
            Step := 0;
        END_IF;
END_CASE;

// Verdict local de l'étape : PASS, FAIL ou TIMEOUT contrôlé.
IF StepPassed OR StepFailed OR StepTimer.Q THEN
    IF StepPassed THEN
        Report.Steps[Report.CurrentStepId].Passed := TRUE;
        Report.Steps[Report.CurrentStepId].FailReason := E_TestFailReason.FAIL_NONE;
    ELSE
        Report.Steps[Report.CurrentStepId].Passed := FALSE;
        Report.Steps[Report.CurrentStepId].FailReason := SEL(StepFailed, E_TestFailReason.FAIL_TIMEOUT, E_TestFailReason.FAIL_CHECK);
        AnyFailed := TRUE;
    END_IF;
    Report.Steps[Report.CurrentStepId].Executed := TRUE;
    Report.Steps[Report.CurrentStepId].Duration := StepElapsed;
    IF NOT StepPassed THEN
        Step := 0; // Échec ou timeout = fin immédiate, pas d'attente supplémentaire.
    END_IF;
    StepPassed := FALSE;
    StepFailed := FALSE;
    StepTimer(IN := FALSE, PT := StepLimit);
    StepElapsed := T#0s;
    IF Step = 0 THEN
        GVL_PLC_Tests.OverrideJoystickActive := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        GVL_PLC_Tests.OverrideHmiCommandPurge := FALSE;
        GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault := FALSE;
        Busy := FALSE;
        Done := TRUE;
        Report.InProgress := FALSE;
        Report.AnyFailed := AnyFailed;
        Report.AllPassed := NOT AnyFailed;
        Report.TerminalState := SEL(AnyFailed, E_TestTerminalState.TEST_TERMINAL_DONE, E_TestTerminalState.TEST_TERMINAL_FAILED);
        TerminalState := Report.TerminalState;
        Report.Cases[1].Name := 'TC-M1..M12 Modes+WinchCore';
        Report.Cases[1].Executed := TRUE;
        Report.Cases[1].Ok := NOT AnyFailed;
        Report.Cases[1].FailedStepId := 0;
        Report.Cases[1].FailReason := E_TestFailReason.FAIL_NONE;
        IF AnyFailed THEN
            Report.Cases[1].FailedStepId := Report.CurrentStepId;
            Report.Cases[1].FailReason := E_TestFailReason.FAIL_CHECK;
            Report.FailureSummary := CONCAT('Modes/Homme-mort : échec étape ', INT_TO_STRING(Report.CurrentStepId));
        END_IF;
        Report.Cases[1].Duration := Report.Duration;
    ELSE
        StepStarted := FALSE;
    END_IF;
END_IF;

// Limite globale de sécurité de la suite : 90 s maximum.
IF Report.Duration >= T#90s AND Busy THEN
    GVL_PLC_Tests.OverrideJoystickActive := FALSE;
    GVL_PLC_Tests.OverrideContactorFalse := FALSE;
    GVL_PLC_Tests.OverrideHmiCommandPurge := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault := FALSE;
    Busy := FALSE;
    Done := TRUE;
    AnyFailed := TRUE;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
    Report.InProgress := FALSE;
    Report.AnyFailed := TRUE;
    Report.AllPassed := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := 4002;
    Report.ErrorMessage := 'Watchdog Modes/Homme-mort expire';
    Report.FailureSummary := Report.ErrorMessage;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Output) ===

// 1. Inversion NO/NC
State := Command XOR InvertLogic;

// 2. Option blink 1 Hz (diagnostic/visualisation) — modulation à 500ms ON/500ms OFF
IF Blink1Hz AND State THEN
    BlinkTimer(IN := NOT BlinkTimer.Q, PT := T#500ms);
    IF BlinkTimer.Q THEN
        BlinkState := NOT BlinkState;
    END_IF;
    State := BlinkState;
ELSE
    BlinkTimer(IN := FALSE, PT := T#500ms);
    BlinkState := FALSE;
END_IF;

// 3. Double vérification commande/retour (contacteur collé/ne colle pas)
IF UseFeedback THEN
    FeedbackTon(IN := (State <> FeedbackRaw), PT := FeedbackTimeout);
    IF FeedbackTon.Q THEN
        ErrorId := ErrorId OR 16#0001;
        FeedbackOk := FALSE;
    ELSE
        ErrorId := ErrorId AND 16#FFFE;
        FeedbackOk := TRUE;
    END_IF;
ELSE
    FeedbackTon(IN := FALSE, PT := FeedbackTimeout);
    FeedbackOk := TRUE;   // Pas de contrôle demandé — pas d'incohérence à signaler
END_IF;

// 4. Diagnostic voie/carte
IF NOT ChannelOk THEN
    ErrorId := ErrorId OR 16#0002;
ELSE
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

Error := (ErrorId <> 16#0000);

// === IMPLEMENTATION ===
// 1. Détection des commandes HMI
RunAllTrig(CLK := GVL_PLC_Tests.Cmd.RunAll);
AbortTrig(CLK := GVL_PLC_Tests.Cmd.Abort);
ClearReportTrig(CLK := GVL_PLC_Tests.Cmd.ClearReport);

// Remise à zéro des boutons poussoirs HMI
// 🔧 REX 2026-07-16 (demande utilisateur) : CmdRunAll n'est PAS remis à FALSE ici (contrairement
// à l'ancien CmdRunTests, pulse consommé au scan suivant) — il reste TRUE tout le temps du run,
// pratique pour observer en Watch/forçage CODESYS, et ne retombe qu'au Done (cf. CASE ci-dessous).
// R_TRIG garantit qu'un niveau maintenu ne redéclenche pas un 2e run.
IF GVL_PLC_Tests.Cmd.Abort THEN
    GVL_PLC_Tests.Cmd.Abort := FALSE;
END_IF;
IF GVL_PLC_Tests.Cmd.ClearReport THEN
    GVL_PLC_Tests.Cmd.ClearReport := FALSE;
END_IF;

// 2. Machine d'états principale
CASE GVL_PLC_Tests.Status.RunState OF

    // 🔧 REX 2026-07-16 (demande utilisateur) : PASSED/FAILED/ABORTED sont FIGÉS ici (pattern
    // StateAtError, P3 §4) — sans ça, l'état ne durait qu'1 scan (10ms) avant de retomber tout
    // seul à IDLE, invisible en Watch CODESYS. On ne quitte cet état que sur nouveau Start
    // (relance direct un run) ou CmdClearReport (acquittement explicite → retour IDLE).
    E_TestRunState.TESTRUN_IDLE, E_TestRunState.TESTRUN_PASSED, E_TestRunState.TESTRUN_FAILED, E_TestRunState.TESTRUN_ABORTED:
        StartSafety := FALSE;
        AbortSafety := FALSE;
        StartTranslation := FALSE;
        AbortTranslation := FALSE;
        StartBucket := FALSE;
        AbortBucket := FALSE;
        StartEncoder := FALSE;
        AbortEncoder := FALSE;
        StartModes := FALSE;
        AbortModes := FALSE;
        StartHeartbeat := FALSE;
        AbortHeartbeat := FALSE;
        StartFramework := FALSE;
        SuiteElapsed := T#0s;
        SuiteWatchdogExpired := FALSE;

        // 🧪 RunAll prioritaire : démarre une campagne complète depuis Safety.
        IF RunAllTrig.Q THEN
            ChainMode := TRUE;
            CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteSafety;
            RequestedCaseSafety := 0;
            RequestedCaseTranslation := 0;
            RequestedCaseBucket := 0;
            RequestedCaseEncoder := 0;
            RequestedCaseModes := 0;
            RequestedCaseHeartbeat := 0;
            FinalAborted := FALSE;
            FinalAnyFailed := FALSE;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;
            GVL_PLC_Tests.Status.FailureSummary := '';
            StartSafety := TRUE;
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
        // Normalisation des commandes unitaires vers RunSuite.
        ELSIF GVL_PLC_Tests.Cmd.RunSafety THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteSafety;
            GVL_PLC_Tests.Cmd.RunSafety := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunTranslation THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteTranslation;
            GVL_PLC_Tests.Cmd.RunTranslation := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunBucket THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteBucket;
            GVL_PLC_Tests.Cmd.RunBucket := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunEncoder THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteEncoder;
            GVL_PLC_Tests.Cmd.RunEncoder := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunModes THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteModes;
            GVL_PLC_Tests.Cmd.RunModes := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunHeartbeat THEN
            GVL_PLC_Tests.Cmd.RunSuite := GVL_PLC_Tests_Const.SuiteHeartbeat;
            GVL_PLC_Tests.Cmd.RunHeartbeat := FALSE;
        ELSIF GVL_PLC_Tests.Cmd.RunFramework THEN
            StartFramework := TRUE;
            GVL_PLC_Tests.Cmd.RunFramework := FALSE;
        END_IF;

        // Démarrage d'une suite ciblée (Safety)
        IF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteSafety THEN
            IF GVL_Simulation.SimulationModeActive AND instSafetyValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteSafety;
                StartSafety := TRUE;
                RequestedCaseSafety := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := ''; // 🔄 RAZ à chaque nouveau run
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Translation)
        // 🆕 2026-07-22 : CaseId transmis TEL QUEL (0=toutes,1..6) — le manager ne
        // connaît plus aucun détail interne d'étape (audit v1.0 C2). Refus de
        // gate désormais explicite PRECONDITION_FAILED, jamais silencieux (C3).
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteTranslation THEN
            // La suite possède seule sa fixture : même un refus produit un rapport neuf
            // PRECONDITION_FAILED, jamais un Status correct avec un ancien rapport.
            ChainMode := FALSE;
            CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteTranslation;
            StartTranslation := TRUE;
            RequestedCaseTranslation := GVL_PLC_Tests.Cmd.RunCase;
            GVL_PLC_Tests.Status.FailureSummary := '';
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Bucket)
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteBucket THEN
            IF GVL_Simulation.SimulationModeActive AND instBucketValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteBucket;
                StartBucket := TRUE;
                RequestedCaseBucket := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := ''; // 🔄 RAZ à chaque nouveau run
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Codeurs/Homing nominal)
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteEncoder THEN
            IF GVL_Simulation.SimulationModeActive AND instEncoderValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteEncoder;
                StartEncoder := TRUE;
                RequestedCaseEncoder := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := '';
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage d'une suite ciblée (Modes/Homme-mort, post-suppression IHM_MANU)
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteModes THEN
            IF GVL_Simulation.SimulationModeActive AND instModesValidation.SimGateOk THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteModes;
                StartModes := TRUE;
                RequestedCaseModes := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := '';
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;

        // Démarrage suite Heartbeat IHM↔PLC.
        ELSIF GVL_PLC_Tests.Cmd.RunSuite = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
            IF GVL_Simulation.SimulationModeActive
               AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal
               AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal THEN
                ChainMode := FALSE;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteHeartbeat;
                StartHeartbeat := TRUE;
                RequestedCaseHeartbeat := GVL_PLC_Tests.Cmd.RunCase;
                GVL_PLC_Tests.Status.FailureSummary := '';
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
            END_IF;
            GVL_PLC_Tests.Cmd.RunSuite := 0;
            GVL_PLC_Tests.Cmd.RunCase := 0;
        END_IF;

        // 🧪 Smoke test géré directement ici : aucune instance/table/runtime.
        IF StartFramework THEN
            ChainMode := FALSE;
            FrameworkScanCount := 0;
            GVL_PLC_Tests.FrameworkResult.InProgress := TRUE;
            GVL_PLC_Tests.FrameworkResult.AllPassed := FALSE;
            GVL_PLC_Tests.FrameworkResult.AnyFailed := FALSE;
            GVL_PLC_Tests.FrameworkResult.CurrentTestId := 1;
            GVL_PLC_Tests.FrameworkResult.FailedTestId := 0;
            GVL_PLC_Tests.FrameworkResult.TestsPassed := 0;
            GVL_PLC_Tests.FrameworkResult.TestsFailed := 0;
            GVL_PLC_Tests.FrameworkResult.ErrorMessage := '';
            GVL_PLC_Tests.FrameworkResult.RunCounter := GVL_PLC_Tests.FrameworkResult.RunCounter + 1;
            GVL_PLC_Tests.Status.FailureSummary := '';
            CurrentSuiteIdx := 7;
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_RUNNING;
        END_IF;

        // Commande d'effacement du rapport — acquittement explicite, retour à IDLE
        IF ClearReportTrig.Q THEN
            // La réinitialisation des rapports Steps[]/Cases[] est gérée par le moteur
            // au démarrage du run suivant ; ici on remet juste les compteurs IHM et on
            // libère l'état figé PASSED/FAILED/ABORTED.
            GVL_PLC_Tests.Status.CasesTotal := 0;
            GVL_PLC_Tests.Status.CasesPassed := 0;
            GVL_PLC_Tests.Status.CasesFailed := 0;
            GVL_PLC_Tests.Status.FailureSummary := '';
            GVL_PLC_Tests.EventCount := 0;
            GVL_PLC_Tests.EventSequence := 0;
            GVL_PLC_Tests.EventOverflow := FALSE;
            GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_IDLE;
        END_IF;

    E_TestRunState.TESTRUN_RUNNING:
        // Annulation des impulsions de départ
        StartSafety := FALSE;
        StartTranslation := FALSE;
        StartBucket := FALSE;
        StartEncoder := FALSE;
        StartModes := FALSE;
        StartHeartbeat := FALSE;
        StartFramework := FALSE;

        // 🧪 Smoke framework natif : 3 scans, sans appeler aucun moteur de test.
        IF CurrentSuiteIdx = 7 THEN
            FrameworkScanCount := FrameworkScanCount + 1;
            IF FrameworkScanCount >= 3 THEN
                GVL_PLC_Tests.FrameworkResult.InProgress := FALSE;
                GVL_PLC_Tests.FrameworkResult.AllPassed := TRUE;
                GVL_PLC_Tests.FrameworkResult.AnyFailed := FALSE;
                GVL_PLC_Tests.FrameworkResult.TestsPassed := 1;
                GVL_PLC_Tests.FrameworkResult.TestsFailed := 0;
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
            END_IF;
        END_IF;

        // 🛡️ Aucun orchestrateur ne doit attendre Done indéfiniment.
        SuiteElapsed := SuiteElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
        GVL_PLC_Tests.Status.SuiteElapsed := SuiteElapsed;
        IF SuiteElapsed >= DINT_TO_TIME(GVL_PLC_Tests_Const.MaxSuiteDurationMs) THEN
            SuiteWatchdogExpired := TRUE;
            GVL_PLC_Tests.Status.SuiteWatchdogExpired := TRUE;
            IF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSafety THEN
                AbortSafety := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation THEN
                AbortTranslation := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder THEN
                AbortEncoder := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes THEN
                AbortModes := TRUE;
            ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
                AbortHeartbeat := TRUE;
            ELSE
                AbortBucket := TRUE;
            END_IF;
        END_IF;

        // Abandon propre ou perte du mode Simulation — coupe la suite active
        IF AbortTrig.Q OR NOT GVL_Simulation.SimulationModeActive THEN
            AbortSafety := TRUE;
            AbortTranslation := TRUE;
            AbortBucket := TRUE;
            AbortEncoder := TRUE;
            AbortModes := TRUE;
            AbortHeartbeat := TRUE;
        END_IF;

        // Surveillance de la fin d'exécution — Safety d'abord
        IF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSafety AND instSafetyValidation.Done THEN
            AbortSafety := FALSE;
            IF instSafetyValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instSafetyValidation.Report.RunCounter <> LastLoggedSafetyRun THEN
                LastLoggedSafetyRun := instSafetyValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteSafety;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instSafetyValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instSafetyValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instSafetyValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instSafetyValidation.ErrorMessage;
            END_IF;
            IF ChainMode AND (NOT instSafetyValidation.Report.Aborted OR SuiteWatchdogExpired) AND instTranslationValidation.SimGateOk THEN
                // 🔗 Enchaîne vers Translation (continue même si Safety a échoué — logique
                // FAIL_CONTINUE déjà appliquée au niveau des cases/steps, voir §7.3.4)
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteTranslation;
                SuiteElapsed := T#0s;
                StartTranslation := TRUE;
                RequestedCaseTranslation := 0; // Enchaînement RunAll -> toutes les cases Translation
            ELSIF ChainMode AND NOT instSafetyValidation.Report.Aborted AND NOT instTranslationValidation.SimGateOk THEN
                // 🔧 REX 2026-07-16 : bug trouvé — le chaînage sautait la vérification SimGateOk
                // (le démarrage ciblé Cmd.RunSuite=2 la faisait, pas celui-ci). Sans ce garde-fou,
                // Translation démarrait quand même avec FB_Safety_Translation.Enable=FALSE
                // (ManuActive actif) → 3 timeouts silencieux, aucun défaut jamais détectable.
                GVL_PLC_Tests.Cmd.RunAll := FALSE;
                ChainMode := FALSE; // 🔒 Évite d'agréger un rapport Translation périmé (suite jamais lancée ce run)
                IF instSafetyValidation.Report.FailureSummary = '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := 'Translation NON TESTEE (SimGateOk=FALSE — vérifier SimulationModeActive et les E/S M3 non réelles)';
                ELSE
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(instSafetyValidation.Report.FailureSummary, ' || Translation NON TESTEE (SimGateOk=FALSE — vérifier SimulationModeActive et les E/S M3 non réelles)');
                END_IF;
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSE
                FinalAborted := instSafetyValidation.Report.Aborted;
                FinalAnyFailed := instSafetyValidation.AnyFailed;
                GVL_PLC_Tests.Cmd.RunAll := FALSE; // 🔧 Retombe ICI (Done atteint), pas au démarrage
                GVL_PLC_Tests.Status.FailureSummary := instSafetyValidation.Report.FailureSummary;
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;

        // Surveillance de la fin d'exécution — Translation (ciblée ou enchaînée après Safety)
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation AND instTranslationValidation.Done THEN
            AbortTranslation := FALSE;
            IF instTranslationValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instTranslationValidation.Report.RunCounter <> LastLoggedTranslationRun THEN
                LastLoggedTranslationRun := instTranslationValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteTranslation;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instTranslationValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instTranslationValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instTranslationValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instTranslationValidation.ErrorMessage;
            END_IF;
            IF ChainMode AND (NOT instTranslationValidation.Report.Aborted OR SuiteWatchdogExpired) AND instBucketValidation.SimGateOk THEN
                // 🔗 Enchaîne vers Bucket (2026-07-16 : 3e maillon Safety→Translation→Bucket)
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteBucket;
                SuiteElapsed := T#0s;
                StartBucket := TRUE;
                RequestedCaseBucket := 0;
            ELSIF ChainMode AND NOT instTranslationValidation.Report.Aborted AND NOT instBucketValidation.SimGateOk THEN
                // Même garde-fou que Safety→Translation : Bucket ne doit jamais démarrer sans son
                // SimGateOk (refuse si M1/M2 en simulation réelle, voir FB_BucketValidation §1).
                GVL_PLC_Tests.Cmd.RunAll := FALSE;
                ChainMode := FALSE; // 🔒 Évite d'agréger un rapport Bucket périmé (suite jamais lancée ce run)
                IF instSafetyValidation.Report.FailureSummary = '' AND instTranslationValidation.Report.FailureSummary = '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := 'Bucket NON TESTEE (SimGateOk=FALSE — verifier simulation reelle M1/M2)';
                ELSIF instTranslationValidation.Report.FailureSummary = '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(instSafetyValidation.Report.FailureSummary, ' || Bucket NON TESTEE (SimGateOk=FALSE — verifier simulation reelle M1/M2)');
                ELSE
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(instTranslationValidation.Report.FailureSummary, ' || Bucket NON TESTEE (SimGateOk=FALSE — verifier simulation reelle M1/M2)');
                END_IF;
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSE
                // Soit run ciblé (pas de chaînage), soit chaînage interrompu (Translation.Aborted)
                IF ChainMode THEN
                    FinalAborted := instSafetyValidation.Report.Aborted OR instTranslationValidation.Report.Aborted;
                    FinalAnyFailed := instSafetyValidation.AnyFailed OR instTranslationValidation.AnyFailed;
                    IF instSafetyValidation.Report.FailureSummary <> '' AND instTranslationValidation.Report.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(instSafetyValidation.Report.FailureSummary, CONCAT(' || ', instTranslationValidation.Report.FailureSummary));
                    ELSIF instSafetyValidation.Report.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := instSafetyValidation.Report.FailureSummary;
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instTranslationValidation.Report.FailureSummary;
                    END_IF;
                ELSE
                    FinalAborted := instTranslationValidation.Report.Aborted;
                    FinalAnyFailed := instTranslationValidation.AnyFailed;
                    GVL_PLC_Tests.Status.FailureSummary := instTranslationValidation.Report.FailureSummary;
                END_IF;
                GVL_PLC_Tests.Cmd.RunAll := FALSE; // 🔧 Retombe ICI (Done atteint), pas au démarrage
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;

        // Surveillance de la fin d'exécution — Bucket (ciblée, ou dernier maillon de la chaîne)
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteBucket AND instBucketValidation.Done THEN
            AbortBucket := FALSE;
            IF instBucketValidation.TerminalState <> E_TestTerminalState.TEST_TERMINAL_DONE AND instBucketValidation.Report.RunCounter <> LastLoggedBucketRun THEN
                LastLoggedBucketRun := instBucketValidation.Report.RunCounter;
                GVL_PLC_Tests.EventSequence := GVL_PLC_Tests.EventSequence + 1;
                IF GVL_PLC_Tests.EventCount < GVL_PLC_Tests_Const.MaxTestEvents THEN
                    GVL_PLC_Tests.EventCount := GVL_PLC_Tests.EventCount + 1;
                ELSE
                    GVL_PLC_Tests.EventOverflow := TRUE;
                END_IF;
                EventIdx := UDINT_TO_INT(GVL_PLC_Tests.EventSequence MOD INT_TO_UDINT(GVL_PLC_Tests_Const.MaxTestEvents)) + 1;
                GVL_PLC_Tests.EventLog[EventIdx].Sequence := GVL_PLC_Tests.EventSequence;
                GVL_PLC_Tests.EventLog[EventIdx].Severity := E_TestEventSeverity.TEST_EVENT_ERROR;
                GVL_PLC_Tests.EventLog[EventIdx].SuiteId := GVL_PLC_Tests_Const.SuiteBucket;
                GVL_PLC_Tests.EventLog[EventIdx].CaseId := instBucketValidation.Report.CurrentCaseId;
                GVL_PLC_Tests.EventLog[EventIdx].StepId := instBucketValidation.Report.CurrentStepId;
                GVL_PLC_Tests.EventLog[EventIdx].Code := instBucketValidation.ErrorCode;
                GVL_PLC_Tests.EventLog[EventIdx].Message := instBucketValidation.ErrorMessage;
            END_IF;
            IF ChainMode THEN
                // Campagne complète : Bucket terminé → Encoder.
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteEncoder;
                SuiteElapsed := T#0s;
                StartEncoder := TRUE;
                RequestedCaseEncoder := 0;
                // Conserve les verdicts précédents pour le verdict final.
                FinalAborted := FinalAborted OR instSafetyValidation.Report.Aborted OR instTranslationValidation.Report.Aborted OR instBucketValidation.Report.Aborted;
                FinalAnyFailed := FinalAnyFailed OR instSafetyValidation.AnyFailed OR instTranslationValidation.AnyFailed OR instBucketValidation.AnyFailed;
                // 🏷️ Combine jusqu'à 3 résumés intermédiaires.
                GVL_PLC_Tests.Status.FailureSummary := '';
                IF instSafetyValidation.Report.FailureSummary <> '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := instSafetyValidation.Report.FailureSummary;
                END_IF;
                IF instTranslationValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instTranslationValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instTranslationValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
                IF instBucketValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instBucketValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instBucketValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
            ELSE
                FinalAborted := instBucketValidation.Report.Aborted;
                FinalAnyFailed := instBucketValidation.AnyFailed;
                GVL_PLC_Tests.Status.FailureSummary := instBucketValidation.Report.FailureSummary;
                GVL_PLC_Tests.Cmd.RunAll := FALSE;
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat AND instHeartbeatValidation.Done THEN
            AbortHeartbeat := FALSE;
            FinalAborted := FinalAborted OR instHeartbeatValidation.Report.Aborted;
            FinalAnyFailed := FinalAnyFailed OR instHeartbeatValidation.AnyFailed;
            IF instHeartbeatValidation.Report.FailureSummary <> '' THEN
                IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                    GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instHeartbeatValidation.Report.FailureSummary));
                ELSE
                    GVL_PLC_Tests.Status.FailureSummary := instHeartbeatValidation.Report.FailureSummary;
                END_IF;
            END_IF;
            // ChainMode reste mémorisé au terminal pour agréger toute la campagne.
            // Le prochain lancement ciblé le remet explicitement à FALSE.
            GVL_PLC_Tests.Cmd.RunAll := FALSE;
            IF FinalAborted THEN
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
            ELSIF FinalAnyFailed THEN
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
            ELSE
                GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder AND instEncoderValidation.Done THEN
            AbortEncoder := FALSE;
            IF ChainMode THEN
                FinalAborted := FinalAborted OR instEncoderValidation.Report.Aborted;
                FinalAnyFailed := FinalAnyFailed OR instEncoderValidation.AnyFailed;
                IF instEncoderValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instEncoderValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instEncoderValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteModes;
                SuiteElapsed := T#0s;
                StartModes := TRUE;
                RequestedCaseModes := 0;
            ELSE
                FinalAborted := instEncoderValidation.Report.Aborted;
                FinalAnyFailed := instEncoderValidation.AnyFailed;
                GVL_PLC_Tests.Status.FailureSummary := instEncoderValidation.Report.FailureSummary;
            END_IF;
            IF SuiteWatchdogExpired THEN
                GVL_PLC_Tests.Status.FailureSummary := 'Watchdog suite Encoder/Homing expire';
                FinalAborted := FALSE;
                FinalAnyFailed := TRUE;
            END_IF;
            IF NOT ChainMode THEN
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;
        ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes AND instModesValidation.Done THEN
            AbortModes := FALSE;
            IF ChainMode THEN
                FinalAborted := FinalAborted OR instModesValidation.Report.Aborted;
                FinalAnyFailed := FinalAnyFailed OR instModesValidation.AnyFailed;
                IF instModesValidation.Report.FailureSummary <> '' THEN
                    IF GVL_PLC_Tests.Status.FailureSummary <> '' THEN
                        GVL_PLC_Tests.Status.FailureSummary := CONCAT(GVL_PLC_Tests.Status.FailureSummary, CONCAT(' || ', instModesValidation.Report.FailureSummary));
                    ELSE
                        GVL_PLC_Tests.Status.FailureSummary := instModesValidation.Report.FailureSummary;
                    END_IF;
                END_IF;
                CurrentSuiteIdx := GVL_PLC_Tests_Const.SuiteHeartbeat;
                SuiteElapsed := T#0s;
                StartHeartbeat := TRUE;
                RequestedCaseHeartbeat := 0;
            ELSE
                FinalAborted := instModesValidation.Report.Aborted;
                FinalAnyFailed := instModesValidation.AnyFailed;
                GVL_PLC_Tests.Status.FailureSummary := instModesValidation.Report.FailureSummary;
            END_IF;
            IF SuiteWatchdogExpired THEN
                GVL_PLC_Tests.Status.FailureSummary := 'Watchdog suite Modes/Homme-mort expire';
                FinalAborted := FALSE;
                FinalAnyFailed := TRUE;
            END_IF;
            IF NOT ChainMode THEN
                IF FinalAborted THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_ABORTED;
                ELSIF FinalAnyFailed THEN
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_FAILED;
                ELSE
                    GVL_PLC_Tests.Status.RunState := E_TestRunState.TESTRUN_PASSED;
                END_IF;
            END_IF;
        END_IF;

END_CASE;

// 3. Appel des instances de suites
instSafetyValidation(Start := StartSafety, Abort := AbortSafety, CaseId := RequestedCaseSafety);
instTranslationValidation(Start := StartTranslation, Abort := AbortTranslation, CaseId := RequestedCaseTranslation);
instBucketValidation(Start := StartBucket, Abort := AbortBucket, CaseId := RequestedCaseBucket, instBucket := instBucket, instWinchM2 := instWinchM2);
instEncoderValidation(Start := StartEncoder, Abort := AbortEncoder, CaseId := RequestedCaseEncoder);
instModesValidation(Start := StartModes, Abort := AbortModes, CaseId := RequestedCaseModes);
instHeartbeatValidation(Start := StartHeartbeat, Abort := AbortHeartbeat, CaseId := RequestedCaseHeartbeat);

// 4. Centralisation et recopie vers GVL_PLC_Tests
GVL_PLC_Tests.Status.SimulationActive := GVL_Simulation.SimulationModeActive;
GVL_PLC_Tests.Status.SuiteWatchdogExpired := SuiteWatchdogExpired;
GVL_PLC_Tests.SuiteSafetyValidation := instSafetyValidation.Report;
GVL_PLC_Tests.SuiteTranslationValidation := instTranslationValidation.Report;
GVL_PLC_Tests.SuiteTranslationResult := instTranslationValidation.Result; // 🆕 Résultat plat clair
GVL_PLC_Tests.SuiteBucketValidation := instBucketValidation.Report;
GVL_PLC_Tests.SuiteEncoderValidation := instEncoderValidation.Report;
GVL_PLC_Tests.SuiteModesValidation := instModesValidation.Report;
GVL_PLC_Tests.SuiteHeartbeatValidation := instHeartbeatValidation.Report;

// 5. Mise à jour des indicateurs de progression IHM
IF GVL_PLC_Tests.Status.RunState = E_TestRunState.TESTRUN_RUNNING THEN
    GVL_PLC_Tests.Status.ActiveSuiteId := CurrentSuiteIdx;
    // 🧪 L'autotest framework a sa propre progression : ne jamais afficher
    // le rapport Safety résiduel lorsque CurrentSuiteIdx=7.
    IF CurrentSuiteIdx = 7 THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := 'Framework Validation';
        GVL_PLC_Tests.Status.ActiveCaseId := GVL_PLC_Tests.FrameworkResult.CurrentTestId;
        GVL_PLC_Tests.Status.ActiveStepId := GVL_PLC_Tests.FrameworkResult.CurrentTestId;
        GVL_PLC_Tests.Status.StepElapsed := T#0s;
        GVL_PLC_Tests.Status.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
        GVL_PLC_Tests.Status.ErrorCode := GVL_PLC_Tests.FrameworkResult.FailedTestId;
        GVL_PLC_Tests.Status.ErrorMessage := GVL_PLC_Tests.FrameworkResult.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instTranslationValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instTranslationValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instTranslationValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instTranslationValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instTranslationValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instTranslationValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instTranslationValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteBucket THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instBucketValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instBucketValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instBucketValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instBucketValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instBucketValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instBucketValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instBucketValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instEncoderValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instEncoderValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instEncoderValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instEncoderValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instEncoderValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instEncoderValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instEncoderValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instHeartbeatValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instHeartbeatValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instHeartbeatValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instHeartbeatValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instHeartbeatValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instHeartbeatValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instHeartbeatValidation.ErrorMessage;
    ELSIF CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes THEN
        GVL_PLC_Tests.Status.ActiveSuiteName := instModesValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instModesValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instModesValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instModesValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instModesValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instModesValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instModesValidation.ErrorMessage;
    ELSE
        GVL_PLC_Tests.Status.ActiveSuiteName := instSafetyValidation.Report.Name;
        GVL_PLC_Tests.Status.ActiveCaseId := instSafetyValidation.Report.CurrentCaseId;
        GVL_PLC_Tests.Status.ActiveStepId := instSafetyValidation.Report.CurrentStepId;
        GVL_PLC_Tests.Status.StepElapsed := instSafetyValidation.StepElapsed;
        GVL_PLC_Tests.Status.TerminalState := instSafetyValidation.TerminalState;
        GVL_PLC_Tests.Status.ErrorCode := instSafetyValidation.ErrorCode;
        GVL_PLC_Tests.Status.ErrorMessage := instSafetyValidation.ErrorMessage;
    END_IF;
ELSE
    GVL_PLC_Tests.Status.ActiveSuiteId := 0;
    GVL_PLC_Tests.Status.ActiveSuiteName := '';
    GVL_PLC_Tests.Status.ActiveCaseId := 0;
    GVL_PLC_Tests.Status.ActiveCaseName := '';
    GVL_PLC_Tests.Status.ActiveStepId := 0;
    GVL_PLC_Tests.Status.ActiveStepName := '';
    GVL_PLC_Tests.Status.StepElapsed := T#0s;
    GVL_PLC_Tests.Status.StepTimeoutPT := T#0s;
END_IF;

// Agrégation globale des compteurs de cas de tests — seules les suites réellement
// exécutées CE run comptent (ChainMode = les deux ; sinon seule CurrentSuiteIdx)
// pour ne jamais compter les restes d'un run ciblé précédent sur l'autre suite.
PassedCount := 0;
FailedCount := 0;
TotalCount := 0;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteSafety THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instSafetyValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instSafetyValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteTranslation THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instTranslationValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instTranslationValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteBucket THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instBucketValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instBucketValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteEncoder THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instEncoderValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instEncoderValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteModes THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instModesValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instModesValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF ChainMode OR CurrentSuiteIdx = GVL_PLC_Tests_Const.SuiteHeartbeat THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF instHeartbeatValidation.Report.Cases[Idx].Executed THEN
            TotalCount := TotalCount + 1;
            IF instHeartbeatValidation.Report.Cases[Idx].Ok THEN
                PassedCount := PassedCount + 1;
            ELSE
                FailedCount := FailedCount + 1;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

GVL_PLC_Tests.Status.CasesTotal := TotalCount;
GVL_PLC_Tests.Status.CasesPassed := PassedCount;
GVL_PLC_Tests.Status.CasesFailed := FailedCount;

// 💓 Logique du Clignotant visuel d'activité (Heartbeat — Triple clignotement réactif)
IF GVL_PLC_Tests.Status.RunState = E_TestRunState.TESTRUN_RUNNING THEN
    // 1. Détection d'un changement de step réel -> Armement du triple clignotement
    IF GVL_PLC_Tests.Status.ActiveStepId <> LastStepId AND PulseCounter = 0 THEN
        PulseCounter := 1;
        CycleCounter := 0;
        GVL_PLC_Tests.Status.Heartbeat := TRUE;
        LastStepId := GVL_PLC_Tests.Status.ActiveStepId;
    END_IF;

    // 2. Gestion du cycle de clignotement (100ms ON / 100ms OFF x3)
    IF PulseCounter > 0 THEN
        CycleCounter := CycleCounter + 1;
        IF CycleCounter >= 10 THEN
            CycleCounter := 0;
            PulseCounter := PulseCounter + 1;
            IF PulseCounter <= 6 THEN
                // Impulsions impaires = TRUE, paires = FALSE
                GVL_PLC_Tests.Status.Heartbeat := (PulseCounter MOD 2 <> 0);
            ELSE
                // Fin du triple clignotement -> retour à l'état éteint
                PulseCounter := 0;
                GVL_PLC_Tests.Status.Heartbeat := FALSE;
            END_IF;
        END_IF;
    END_IF;
ELSE
    // Forcer à FALSE quand le runner est au repos
    GVL_PLC_Tests.Status.Heartbeat := FALSE;
    LastStepId := 0;
    PulseCounter := 0;
    CycleCounter := 0;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Ramp) ===

// Détection du comportement (Accélération vs Décélération)
// 🔧 CORRECTIF : classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut
// de Target seul (l'ancienne version se trompait lors d'une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);

// === IMPLEMENTATION ===
// 1. 🛡️ GATE
IF NOT GVL_Simulation.SimulationModeActive THEN
    // Abort interne immédiat
    Sequencer(Start := FALSE, Abort := TRUE, CaseId := CaseId,
              StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable, InvariantTable := InvariantTable,
              ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal, Report := Report);

    GVL_PLC_Tests.OverrideChainTrue := FALSE;
    GVL_PLC_Tests.OverrideChainFalse := FALSE;
    GVL_PLC_Tests.OverrideContactorFalse := FALSE;
    ArmRequest := FALSE;
    ResetFaults := FALSE;
    SimGateOk := FALSE;
    RETURN;
END_IF;

// La chaîne d'urgence physique ne doit pas être en mode simulation réelle active (sécurité matérielle)
SimGateOk := NOT GVL_Simulation.SensorEmergencyStopChainIsReal;

// 2. 📋 TABLES (Remplissage déclaratif unique)
IF NOT TableReady THEN
    Report.Name := 'Safety Validation'; // 🏷️ Identifie la suite (SuiteSafetyValidation) sans ambiguïté

    // Cas de tests
    CaseTable[1].Name := 'TC-01 Armement nominal';
    CaseTable[1].FirstStep := StepTc01Setup;

    CaseTable[2].Name := 'TC-02 Redondance';
    CaseTable[2].FirstStep := StepTc02Setup;

    CaseTable[3].Name := 'TC-03 Lockout temporel';
    CaseTable[3].FirstStep := StepTc03Setup;

    // ─────────────────────────────────────────────────────────────
    // 🛡️ INVARIANT DE NON-RÉGRESSION (§7.5.4) — verrouille le correctif du défaut connu
    // (EmergencyArmingLockoutActive posé aussi sur la branche succès). Armé DÈS la
    // confirmation d'armement TC-01, désarmé à l'entrée de TC-02 (portée = le case TC-01
    // uniquement — TC-03 active volontairement le lockout, il ne doit pas être vu comme
    // une violation, d'où le désarmement avant d'y arriver).
    // ─────────────────────────────────────────────────────────────
    InvariantTable[1].Check.Kind := E_TestCheckKind.BOOL_EQUAL;
    InvariantTable[1].Check.ProbeIdx := SigEmergencyArmingLockoutActive;
    InvariantTable[1].Check.ExpectedBool := FALSE;
    InvariantTable[1].ArmAtStepId := StepTc01Confirm;
    InvariantTable[1].DisarmAtStepId := StepTc02Setup;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES CHECKS (CheckTable)
    // ─────────────────────────────────────────────────────────────
    // Chk 1: Attente état sain (HealthyIdle = TRUE)
    CheckTable[1].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[1].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[1].ProbeIdx := SigHealthyIdle;
    CheckTable[1].ExpectedBool := TRUE;

    // Chk 2: Attente armement étape 5
    CheckTable[2].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[2].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[2].ProbeIdx := SigArmingSeqStep;
    CheckTable[2].ExpectedDint := 5;

    // Chk 3: Attente front montant de confirmation AU
    CheckTable[3].Kind := E_TestCheckKind.BOOL_RISING;
    CheckTable[3].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL; // Sera déclenché sur front
    CheckTable[3].ProbeIdx := SigEmergencyStopOk;

    // Chk 4: Fin de l'impulsion (étape 0)
    CheckTable[4].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[4].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[4].ProbeIdx := SigArmingSeqStep;
    CheckTable[4].ExpectedDint := 0;

    // Chk 5: Confirmation AU Ok
    CheckTable[5].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[5].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[5].ProbeIdx := SigEmergencyStopOk;
    CheckTable[5].ExpectedBool := TRUE;

    // Chk 6: Coupure franche (PowerCutOff = TRUE)
    // 🔧 REX 2026-07-17 : CHECK_INSTANT n'évalue qu'une fois, au front montant d'Evaluate
    // (voir FB_TestCheck.st) -- soit le tout 1er scan de l'étape Trip, AVANT que PRG_00_Inputs
    // applique le override OverrideContactorFalse (appliqué APRÈS l'appel instTestsManagement()
    // dans PRG_00_Inputs.st). Le check voyait donc systématiquement la valeur d'avant le trigger.
    // CHECK_WAIT_UNTIL retente chaque scan -> tolère ce décalage d'1 scan structurel.
    CheckTable[6].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[6].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[6].ProbeIdx := SigPowerCutOffAny;
    CheckTable[6].ExpectedBool := TRUE;

    // Chk 7: AU désactivé
    CheckTable[7].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[7].Mode := E_TestCheckMode.CHECK_INSTANT;
    CheckTable[7].ProbeIdx := SigEmergencyStopOk;
    CheckTable[7].ExpectedBool := FALSE;

    // Chk 8: Maintien de la coupure (Latch) avec stabilité 500ms
    CheckTable[8].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[8].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[8].ProbeIdx := SigPowerCutOffAny;
    CheckTable[8].ExpectedBool := TRUE;
    CheckTable[8].StablePT := T#500ms;

    // Chk 9: Détection défaut de redondance
    CheckTable[9].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[9].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[9].ProbeIdx := SigRedundancyFailed;
    CheckTable[9].ExpectedBool := TRUE;

    // Chk 10: Fin réarmement (étape 0) après défaut
    CheckTable[10].Kind := E_TestCheckKind.DINT_EQUAL;
    CheckTable[10].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[10].ProbeIdx := SigArmingSeqStep;
    CheckTable[10].ExpectedDint := 0;

    // Chk 11: Temps de réaction dans la fenêtre [180ms, 260ms]
    CheckTable[11].Kind := E_TestCheckKind.REAL_IN_RANGE;
    CheckTable[11].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[11].ProbeIdx := SigStopwatchMs;
    CheckTable[11].RealMin := 180.0;
    CheckTable[11].RealMax := 260.0;

    // Chk 12: Pas d'erreur parasite (sauf bit 0)
    CheckTable[12].Kind := E_TestCheckKind.WORD_MASK_NONE;
    CheckTable[12].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[12].ProbeIdx := SigErrorId;
    CheckTable[12].Mask := NOT 16#0001; // Tout sauf bit de redondance

    // Chk 13: Échec armement (EmergencyArmingFailed = TRUE)
    CheckTable[13].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[13].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[13].ProbeIdx := SigEmergencyArmingFailed;
    CheckTable[13].ExpectedBool := TRUE;

    // Chk 14: Verrouillage actif (Lockout = TRUE)
    CheckTable[14].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[14].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[14].ProbeIdx := SigEmergencyArmingLockoutActive;
    CheckTable[14].ExpectedBool := TRUE;

    // Chk 15: Interdiction de démarrer pendant Lockout
    CheckTable[15].Kind := E_TestCheckKind.DINT_NOT_EQUAL;
    CheckTable[15].Mode := E_TestCheckMode.CHECK_NEVER_DURING;
    CheckTable[15].ProbeIdx := SigArmingSeqStep;
    CheckTable[15].ExpectedDint := 0;

    // Chk 16: Fin du verrouillage
    CheckTable[16].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[16].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[16].ProbeIdx := SigEmergencyArmingLockoutActive;
    CheckTable[16].ExpectedBool := FALSE;

    // Chk 17: ✅ Chk gagné #3 (§7.4.2) — canal A coupé AVANT canal B pendant l'auto-test
    CheckTable[17].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[17].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[17].ProbeIdx := SigOrderABOk;
    CheckTable[17].ExpectedBool := TRUE;

    // Chk 18: ✅ Chk gagné #4 (§7.4.2) — exactement 2 chutes d'EmergencyChain (1 par canal testé)
    CheckTable[18].Kind := E_TestCheckKind.BOOL_EQUAL;
    CheckTable[18].Mode := E_TestCheckMode.CHECK_WAIT_UNTIL;
    CheckTable[18].ProbeIdx := SigEdgeCountOk;
    CheckTable[18].ExpectedBool := TRUE;

    // ─────────────────────────────────────────────────────────────
    // CONFIGURATION DES ÉTAPES (StepTable)
    // ─────────────────────────────────────────────────────────────
    // --- SCÉNARIO 1 ---
    StepTable[StepTc01Setup].Name := 'TC01 Setup saine';
    StepTable[StepTc01Setup].CaseId := 1;
    StepTable[StepTc01Setup].StimulusId := 1; // Reset défauts
    StepTable[StepTc01Setup].CheckIdx[1] := 1;
    StepTable[StepTc01Setup].TimeoutPT := T#12s;
    StepTable[StepTc01Setup].NextOnPass := StepTc01Arm;
    StepTable[StepTc01Setup].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Arm].Name := 'TC01 Armement seq';
    StepTable[StepTc01Arm].CaseId := 1;
    StepTable[StepTc01Arm].StimulusId := 2; // ArmRequest := TRUE
    StepTable[StepTc01Arm].CheckIdx[1] := 2;
    StepTable[StepTc01Arm].CheckIdx[2] := 3;
    StepTable[StepTc01Arm].CheckIdx[3] := 17; // ✅ Chk gagné #3 : ordre A avant B
    StepTable[StepTc01Arm].CheckIdx[4] := 18; // ✅ Chk gagné #4 : exactement 2 chutes
    StepTable[StepTc01Arm].TimeoutPT := T#10s;
    StepTable[StepTc01Arm].NextOnPass := StepTc01Confirm;
    StepTable[StepTc01Arm].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Arm].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Confirm].Name := 'TC01 Confirm armé';
    StepTable[StepTc01Confirm].CaseId := 1;
    StepTable[StepTc01Confirm].StimulusId := 0; // Relâcher bouton
    StepTable[StepTc01Confirm].CheckIdx[1] := 4;
    StepTable[StepTc01Confirm].CheckIdx[2] := 5;
    StepTable[StepTc01Confirm].TimeoutPT := T#10s;
    StepTable[StepTc01Confirm].NextOnPass := StepTc01Trip;
    StepTable[StepTc01Confirm].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Confirm].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Trip].Name := 'TC01 Trip urg AU';
    StepTable[StepTc01Trip].CaseId := 1;
    StepTable[StepTc01Trip].StimulusId := 3; // AU simulé (OverrideChainFalse := TRUE)
    StepTable[StepTc01Trip].CheckIdx[1] := 6;
    StepTable[StepTc01Trip].TimeoutPT := T#10s;
    StepTable[StepTc01Trip].NextOnPass := StepTc01Instant;
    StepTable[StepTc01Trip].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Trip].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Instant].Name := 'TC01 Coupure inst';
    StepTable[StepTc01Instant].CaseId := 1;
    StepTable[StepTc01Instant].StimulusId := 3; // Reste appuyé
    StepTable[StepTc01Instant].CheckIdx[1] := 7;
    StepTable[StepTc01Instant].TimeoutPT := T#10s;
    StepTable[StepTc01Instant].NextOnPass := StepTc01Latch;
    StepTable[StepTc01Instant].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Instant].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Latch].Name := 'TC01 Auto-maintien';
    StepTable[StepTc01Latch].CaseId := 1;
    StepTable[StepTc01Latch].StimulusId := 0; // Relâcher AU
    StepTable[StepTc01Latch].CheckIdx[1] := 8; // Stable 500ms
    StepTable[StepTc01Latch].TimeoutPT := T#10s;
    StepTable[StepTc01Latch].NextOnPass := StepTc02Setup; // Cas suivant
    StepTable[StepTc01Latch].NextOnFail := StepTc01Teardown;
    StepTable[StepTc01Latch].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc01Teardown].Name := 'TC01 Teardown';
    StepTable[StepTc01Teardown].CaseId := 1;
    StepTable[StepTc01Teardown].StimulusId := 1; // Nettoyage & Reset
    StepTable[StepTc01Teardown].CheckIdx[1] := 1;
    StepTable[StepTc01Teardown].TimeoutPT := T#12s;
    StepTable[StepTc01Teardown].NextOnPass := StepTc02Setup;
    StepTable[StepTc01Teardown].NextOnFail := StepTc02Setup;
    StepTable[StepTc01Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // --- SCÉNARIO 2 ---
    StepTable[StepTc02Setup].Name := 'TC02 Setup saine';
    StepTable[StepTc02Setup].CaseId := 2;
    StepTable[StepTc02Setup].StimulusId := 1;
    StepTable[StepTc02Setup].CheckIdx[1] := 1;
    StepTable[StepTc02Setup].TimeoutPT := T#12s;
    StepTable[StepTc02Setup].NextOnPass := StepTc02Redundancy;
    StepTable[StepTc02Setup].NextOnFail := StepTc02Teardown;
    StepTable[StepTc02Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc02Redundancy].Name := 'TC02 Defaut redond';
    StepTable[StepTc02Redundancy].CaseId := 2;
    StepTable[StepTc02Redundancy].StimulusId := 4; // Contact soudé (OverrideChainTrue := TRUE) + Arm
    StepTable[StepTc02Redundancy].CheckIdx[1] := 9;  // RedundancyFailed := TRUE
    StepTable[StepTc02Redundancy].CheckIdx[2] := 10; // ArmingSeqStep := 0
    StepTable[StepTc02Redundancy].CheckIdx[3] := 11; // Durée dans [180ms, 260ms]
    StepTable[StepTc02Redundancy].CheckIdx[4] := 12; // Pas d'erreur parasite
    StepTable[StepTc02Redundancy].TimeoutPT := T#10s;
    StepTable[StepTc02Redundancy].NextOnPass := StepTc02Teardown;
    StepTable[StepTc02Redundancy].NextOnFail := StepTc02Teardown;
    StepTable[StepTc02Redundancy].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc02Teardown].Name := 'TC02 Teardown';
    StepTable[StepTc02Teardown].CaseId := 2;
    StepTable[StepTc02Teardown].StimulusId := 1;
    StepTable[StepTc02Teardown].CheckIdx[1] := 1;
    StepTable[StepTc02Teardown].TimeoutPT := T#12s;
    StepTable[StepTc02Teardown].NextOnPass := StepTc03Setup;
    StepTable[StepTc02Teardown].NextOnFail := StepTc03Setup;
    StepTable[StepTc02Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // --- SCÉNARIO 3 ---
    StepTable[StepTc03Setup].Name := 'TC03 Reset initial';
    StepTable[StepTc03Setup].CaseId := 3;
    StepTable[StepTc03Setup].StimulusId := 9; // Reset seul, aucune demande d'armement
    StepTable[StepTc03Setup].CheckIdx[1] := 1;
    StepTable[StepTc03Setup].TimeoutPT := T#3s;
    StepTable[StepTc03Setup].NextOnPass := StepTc03ResetRelease;
    StepTable[StepTc03Setup].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03Setup].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03ResetRelease].Name := 'TC03 Front arm panne';
    StepTable[StepTc03ResetRelease].CaseId := 3;
    StepTable[StepTc03ResetRelease].StimulusId := 5; // Reset relâché + contacteur bloqué + front Arm
    StepTable[StepTc03ResetRelease].CheckIdx[1] := 13;
    StepTable[StepTc03ResetRelease].CheckIdx[2] := 14;
    StepTable[StepTc03ResetRelease].TimeoutPT := T#10s;
    StepTable[StepTc03ResetRelease].NextOnPass := StepTc03LockoutWindow;
    StepTable[StepTc03ResetRelease].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03ResetRelease].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03LockoutWindow].Name := 'TC03 Lockout cmd ign';
    StepTable[StepTc03LockoutWindow].CaseId := 3;
    StepTable[StepTc03LockoutWindow].StimulusId := 6; // Force armement pendant lockout
    StepTable[StepTc03LockoutWindow].CheckIdx[1] := 15; // ArmingSeqStep reste à 0 (NEVER_DURING)
    StepTable[StepTc03LockoutWindow].TimeoutPT := T#4800ms;
    StepTable[StepTc03LockoutWindow].NextOnPass := StepTc03LockoutEnd;
    StepTable[StepTc03LockoutWindow].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03LockoutWindow].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03LockoutEnd].Name := 'TC03 Attente fin lockout';
    StepTable[StepTc03LockoutEnd].CaseId := 3;
    StepTable[StepTc03LockoutEnd].StimulusId := 7; // Relâcher contacteur
    StepTable[StepTc03LockoutEnd].CheckIdx[1] := 16; // LockoutActive := FALSE
    StepTable[StepTc03LockoutEnd].TimeoutPT := T#2s;
    StepTable[StepTc03LockoutEnd].NextOnPass := StepTc03PostReArm;
    StepTable[StepTc03LockoutEnd].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03LockoutEnd].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03PostReArm].Name := 'TC03 Re-armement nominal';
    StepTable[StepTc03PostReArm].CaseId := 3;
    StepTable[StepTc03PostReArm].StimulusId := 8; // Armement nominal après fin lockout
    StepTable[StepTc03PostReArm].CheckIdx[1] := 5; // EmergencyStopOk := TRUE
    StepTable[StepTc03PostReArm].TimeoutPT := T#5s;
    StepTable[StepTc03PostReArm].NextOnPass := 0; // Fin de la suite
    StepTable[StepTc03PostReArm].NextOnFail := StepTc03Teardown;
    StepTable[StepTc03PostReArm].FailAction := E_TestFailAction.FAIL_CONTINUE;

    StepTable[StepTc03Teardown].Name := 'TC03 Teardown';
    StepTable[StepTc03Teardown].CaseId := 3;
    StepTable[StepTc03Teardown].StimulusId := 1;
    StepTable[StepTc03Teardown].CheckIdx[1] := 1;
    StepTable[StepTc03Teardown].TimeoutPT := T#12s;
    StepTable[StepTc03Teardown].NextOnPass := 0;
    StepTable[StepTc03Teardown].NextOnFail := 0;
    StepTable[StepTc03Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    TableReady := TRUE;
END_IF;

// 3. 📥 ACQUIRE
ProbeBool[SigHealthyIdle] := NOT PRG_10_Outputs.instSafetyEmergencyManagement.RedundancyTestFailed AND 
                             NOT PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingFailed AND
                             NOT PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingLockoutActive;

ProbeBool[SigEmergencyStopOk] := PRG_00_Inputs.EmergencyStopOk;
ProbeDint[SigArmingSeqStep] := PRG_10_Outputs.instSafetyEmergencyManagement.ArmingSeqStep;
ProbeBool[SigPowerCutOffAny] := NOT PRG_00_Inputs.EmergencyStopOk;
ProbeBool[SigRedundancyFailed] := PRG_10_Outputs.instSafetyEmergencyManagement.RedundancyTestFailed;
ProbeBool[SigEmergencyArmingFailed] := PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingFailed;
ProbeBool[SigEmergencyArmingLockoutActive] := PRG_10_Outputs.instSafetyEmergencyManagement.EmergencyArmingLockoutActive;
ProbeReal[SigStopwatchMs] := DINT_TO_REAL(instStopwatch.ElapsedMs);
ProbeDint[SigErrorId] := WORD_TO_DINT(PRG_10_Outputs.instSafetyEmergencyManagement.ErrorId);
ProbeBool[SigOrderABOk] := instOrderAB.OrderOk;
ProbeBool[SigEdgeCountOk] := instEdgeCountChain.InRange;

// Liaison des instruments de mesure
instStopwatch(
    Arm := (Sequencer.ActiveStimulusId = 4),
    StartEvent := (PRG_10_Outputs.instSafetyEmergencyManagement.ArmingSeqStep = 1),
    StopEvent := PRG_10_Outputs.instSafetyEmergencyManagement.RedundancyTestFailed,
    ExpectedMinMs := 180,
    ExpectedMaxMs := 260
);

// ✅ Chk gagné #3 : canal A coupé avant canal B (armé pendant tout l'auto-test TC-01,
// stimulus 2 = demande d'armement). EventA/B = front montant de "NOT PowerCutOff_X_RQ",
// c'est-à-dire le moment où le canal RETOMBE (auto-test ForceTestA/B de la Logic).
instOrderAB(
    Arm := (Sequencer.ActiveStimulusId = 2),
    EventA := NOT PowerCutOff_A_RQ,
    EventB := NOT PowerCutOff_B_RQ,
    TimeoutPT := T#10s
);

// ✅ Chk gagné #4 : exactement 2 chutes d'EmergencyChain pendant le même auto-test
// (1 pour le test canal A, 1 pour le test canal B — 3 = rebond, 1 = canal non testé)
instEdgeCountChain(
    Arm := (Sequencer.ActiveStimulusId = 2),
    Signal := PRG_00_Inputs.EmergencyChain,
    CountRising := FALSE,
    ExpectedMin := 2,
    ExpectedMax := 2
);

// 4. ⚙️ MOTEUR
Sequencer(
    Start := Start,
    Abort := Abort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    InvariantTable := InvariantTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal,
    Report := Report,
    Busy => Busy,
    Done => Done,
    AnyFailed => AnyFailed,
    TerminalState => TerminalState,
    ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId,
    ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode,
    ErrorMessage => ErrorMessage,
    ActiveStimulusId => ActiveStimulusId,
    StepElapsed => StepElapsed
);

// 5. ⚡ STIMULI
CASE ActiveStimulusId OF
    0: // 🔓 Neutre (tout relâché)
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := FALSE;

    1: // Reset défauts, attente saine
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := TRUE;

    2: // TC-01 : Demande d'armement nominal
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    3: // TC-01 : Coupure franche (AU pressé)
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := TRUE;
        // 🔧 REX 2026-07-16 : OverrideChainFalse seul a 1 scan de retard (instSimSafety lu
        // AVANT instTestsManagement() dans PRG_00_Inputs.st) — incompatible avec le check 6
        // en CHECK_INSTANT. OverrideContactorFalse force EmergencyStopOk directement et
        // tardivement (après instTestsManagement()) → effet le même scan.
        GVL_PLC_Tests.OverrideContactorFalse := TRUE;
        ArmRequest := FALSE;
        ResetFaults := FALSE;

    4: // TC-02 : Contact soudé canal A (OverrideChainTrue) + Armement
        GVL_PLC_Tests.OverrideChainTrue := TRUE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    5: // TC-03 : contacteur bloqué ouvert + front d'armement, reset relâché
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := TRUE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    6: // TC-03 : Tentative armement pendant lockout
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := TRUE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    7: // TC-03 : Relâchement contacteur bloqueur + reset
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := TRUE;

    8: // TC-03 : Réarmement nominal post-lockout
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := TRUE;
        ResetFaults := FALSE;

    9: // TC-03 : reset initial seul, front distinct de l'armement
        GVL_PLC_Tests.OverrideChainTrue := FALSE;
        GVL_PLC_Tests.OverrideChainFalse := FALSE;
        GVL_PLC_Tests.OverrideContactorFalse := FALSE;
        ArmRequest := FALSE;
        ResetFaults := TRUE;
END_CASE;

// Recopie IHM/métier
IF Busy THEN
    GVL_IHM.Modes.Cmd.BtnEmergencyArming := ArmRequest;
    GVL_IHM.Modes.Cmd.BtnFaultReset  := ResetFaults;
END_IF;

// === IMPLEMENTATION ===

// 🛑 1. Appels des instances internes
Logic(
    Enable := Enable,
    Reset := Reset,
    ArmRequest := ArmRequest,
    EmergencyChain := EmergencyChain,
    EmergencyStopOk := EmergencyStopOk,
    PowerCutOffRequest := PowerCutOffRequest,
    BtnEmergencyCutOff := BtnEmergencyCutOff
);

Output(
    Enable := Enable,
    Cmd := Logic.Cmd
);

// 📤 2. Propagation des signaux vers les sorties du bloc parent
Ready := Enable;
Busy  := (Logic.ArmingSeqStep <> 0);
Done  := EmergencyStopOk;
Error := Logic.Error;
ErrorId := Logic.ErrorId;

PowerCutOff_A_RQ   := Output.PowerCutOff_A_RQ;
PowerCutOff_B_RQ   := Output.PowerCutOff_B_RQ;
EmergencyArming_RQ := Output.EmergencyArming_RQ;

ArmingSeqStep                := Logic.ArmingSeqStep;
RedundancyTestFailed         := Logic.RedundancyTestFailed;
EmergencyArmingFailed        := Logic.EmergencyArmingFailed;
EmergencyArmingLockoutActive := Logic.EmergencyArmingLockoutActive;

// === IMPLEMENTATION ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    Cmd.PowerCutOff_A_Cmd := FALSE;
    Cmd.PowerCutOff_B_Cmd := FALSE;
    Cmd.EmergencyArming_Cmd := FALSE;
    ArmingSeqStep := 0;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    RETURN;
END_IF;

ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);

// 🔍 2. ACQUITTEMENT DES DÉFAUTS
IF ResetEdge.Q THEN
    RedundancyTestFailed := FALSE;
    IF EmergencyStopOk THEN
        EmergencyArmingFailed := FALSE;
    END_IF;
END_IF;

// 🚦 3. DÉCLENCHEMENT DE LA SÉQUENCE DE SÉCURITÉ
IF ArmReqEdge.Q AND (ArmingSeqStep = 0) AND EmergencyChain 
   AND NOT EmergencyArmingLockoutActive 
   AND NOT EmergencyStopOk THEN
    ArmingSeqStep := 1;
END_IF;

// ⏱️ Étape 1 : Coupe canal A seul, vérifie que la boucle tombe
TonTestA(IN := (ArmingSeqStep = 1), PT := T#200ms);
IF ArmingSeqStep = 1 THEN
    ForceTestA := TRUE;
    IF TonTestA.Q THEN
        ForceTestA := FALSE;
        IF EmergencyChain THEN
            RedundancyTestFailed := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 2;
        END_IF;
    END_IF;
ELSE
    ForceTestA := FALSE;
END_IF;

// ⏱️ Étape 2 : Restaure A, attend le retour sain de la boucle amont
TonRestoreA(IN := (ArmingSeqStep = 2), PT := T#200ms);
IF (ArmingSeqStep = 2) AND TonRestoreA.Q THEN
    IF EmergencyChain THEN
        ArmingSeqStep := 3;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 3 : Coupe canal B seul, vérifie que la boucle tombe
TonTestB(IN := (ArmingSeqStep = 3), PT := T#200ms);
IF ArmingSeqStep = 3 THEN
    ForceTestB := TRUE;
    IF TonTestB.Q THEN
        ForceTestB := FALSE;
        IF EmergencyChain THEN
            RedundancyTestFailed := TRUE;
            ArmingSeqStep := 0;
        ELSE
            ArmingSeqStep := 4;
        END_IF;
    END_IF;
ELSE
    ForceTestB := FALSE;
END_IF;

// ⏱️ Étape 4 : Restaure B, attend le retour sain de la boucle amont
TonRestoreB(IN := (ArmingSeqStep = 4), PT := T#200ms);
IF (ArmingSeqStep = 4) AND TonRestoreB.Q THEN
    IF EmergencyChain THEN
        ArmingSeqStep := 5;
    ELSE
        ArmingSeqStep := 0;
    END_IF;
END_IF;

// ⏱️ Étape 5 : Les 2 canaux validés -> impulsion réarmement physique (1s)
TonArmingPulse(IN := (ArmingSeqStep = 5), PT := T#1s);
Cmd.EmergencyArming_Cmd := (ArmingSeqStep = 5);
IF (ArmingSeqStep = 5) AND TonArmingPulse.Q THEN
    ArmingSeqStep := 6;
END_IF;

// ⏱️ Étape 6 : Attente confirmation contacteur principal (2s max)
TonArmingConfirm(IN := (ArmingSeqStep = 6), PT := T#2s);
IF ArmingSeqStep = 6 THEN
    IF EmergencyStopOk THEN
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := FALSE;
    ELSIF TonArmingConfirm.Q THEN
        EmergencyArmingFailed := TRUE;
        ArmingSeqStep := 0;
        EmergencyArmingLockoutActive := TRUE;
    END_IF;
END_IF;

// ⏱️ Séquence de verrouillage temporel (5s)
TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := T#5s);
IF TonArmingLockout.Q THEN
    EmergencyArmingLockoutActive := FALSE;
END_IF;

// 📤 4. GÉNÉRATION DES CONSIGNES LOGIQUES
Cmd.PowerCutOff_A_Cmd := NOT PowerCutOffRequest AND NOT ForceTestA AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailed;
Cmd.PowerCutOff_B_Cmd := NOT PowerCutOffRequest AND NOT ForceTestB AND NOT BtnEmergencyCutOff AND NOT RedundancyTestFailed;

// 📤 5. SYNTHÈSE DES ERREURS
ErrorId := 16#0000;
IF RedundancyTestFailed THEN
    ErrorId := ErrorId OR 16#0001;
END_IF;
IF EmergencyArmingFailed THEN
    ErrorId := ErrorId OR 16#0002;
END_IF;

Error := (ErrorId <> 16#0000);

// === IMPLEMENTATION ===

IF NOT Enable THEN
    PowerCutOff_A_RQ   := FALSE;
    PowerCutOff_B_RQ   := FALSE;
    EmergencyArming_RQ := FALSE;
    RETURN;
END_IF;

// Écriture directe des signaux logiques sur les sorties physiques (fail-safe)
PowerCutOff_A_RQ   := Cmd.PowerCutOff_A_Cmd;
PowerCutOff_B_RQ   := Cmd.PowerCutOff_B_Cmd;
EmergencyArming_RQ := Cmd.EmergencyArming_Cmd;

// === IMPLEMENTATION ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Error := FALSE;
    ErrorId := 16#0000;
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    State := E_State.DISABLED;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si actif → force ErrorId = 0 et saute toutes les vérifications
// (les bits d'erreur resteraient coincés si on ne les nettoie pas)
IF BypassGlobal THEN
    ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
END_IF;

// ⚠️ ResetEdge doit être traité même si bypass actif, pour que le reset IHM fonctionne.
// On ne l'exécute que si on n'est PAS en bypass global (sinon ErrorId déjà à 0).
IF NOT BypassGlobal THEN
    // ResetEdge clearing est fait dans chaque bloc individuel ci-dessous.

    // 🔍 2. PERTE COMMUNICATION OPÉRATEUR (bit0) — joystick CAN ou heartbeat IHM.
    IF NOT (BypassProcess OR BypassOperatorComm) THEN
        IF (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
            ErrorId := ErrorId OR 16#0001;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFE; END_IF;

    // 🔍 2bis. PERTE ETHERCAT VARIATEUR M3 (bit1)
    IF NOT (BypassProcess OR BypassDriveComm) THEN
        IF (NOT DriveOnline OR NOT DriveOperational) THEN
            ErrorId := ErrorId OR 16#0002;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFD; END_IF;

    // 🔍 3. MAUVAISE ROTATION DE PHASE (bit2)
    IF NOT (BypassProcess OR BypassPhaseRotation) THEN
        IF NOT PhaseRotationOk THEN
            ErrorId := ErrorId OR 16#0004;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFFB; END_IF;

    // 🔍 3ter. THERMIQUE FREIN COMMUN M1/M2/M3 (bit3)
    IF NOT (BypassSafety OR BypassBrakeThermal) THEN
        IF BrakeThermalFeedback THEN
            ErrorId := ErrorId OR 16#0008;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFF7; END_IF;

    // 🔍 3quater. INCOHÉRENCE À L'ARRÊT (Méca B — bit4)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        IF NOT HeartbeatIhmOk THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > 0.5) OR DriveStatusWord.0 OR NOT BrakeFeedback;
        ELSIF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveB := DriveStatusWord.0 OR NOT BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN ErrorId := ErrorId OR 16#0010; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFEF; END_IF;

    // 🔍 3quinquies. MOUVEMENT NON COMMANDÉ (Méca A — bit5)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF (Direction = 0) AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN ErrorId := ErrorId OR 16#0020; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFDF; END_IF;

    // 🔍 3sexies. DÉPASSEMENT FINS DE COURSE EXTRÊMES (bit6)
    IF (BypassSafety OR BypassLimitSwitch) THEN
        // Nettoye le bit 6 résiduel (posé avant activation du bypass)
        ErrorId := ErrorId AND 16#FFBF;
    ELSE
        IF LimitSwitchFwd OR LimitSwitchRev THEN
            ErrorId := ErrorId OR 16#0040;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FFBF; END_IF;

    // 🔍 3septies. INCOHÉRENCE MOT CAPTEURS POSITION (bit7)
    IF (BypassSafety OR BypassSensorIncoherent) THEN
        // Nettoye le bit 7 résiduel
        ErrorId := ErrorId AND 16#FF7F;
    ELSE
        IF SensorWordIncoherent THEN
            ErrorId := ErrorId OR 16#0080;
        END_IF;
    END_IF;
    IF ResetEdge.Q THEN ErrorId := ErrorId AND 16#FF7F; END_IF;

END_IF; // fin IF NOT BypassGlobal

// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SafeStop := Error OR NOT EmergencyStopOk;

// PowerCutOff actif si thermique frein (bit3), incohérence arrêt (bit4),
// mouvement non commandé (bit5), dépassement de fin de course (bit6),
// ou incohérence mot capteurs position (bit7)
PowerCutOff := (ErrorId AND 16#00F8) <> 16#0000;

// Décapsulage du bitfield ErrorId pour l'IHM
ErrorOperatorComm   := (ErrorId AND 16#0001) <> 16#0000;
ErrorDriveComm      := (ErrorId AND 16#0002) <> 16#0000;
ErrorPhaseRotation  := (ErrorId AND 16#0004) <> 16#0000;
ErrorBrakeThermal   := (ErrorId AND 16#0008) <> 16#0000;
ErrorMecaB          := (ErrorId AND 16#0010) <> 16#0000;
ErrorMecaA          := (ErrorId AND 16#0020) <> 16#0000;
ErrorLimitSwitch    := (ErrorId AND 16#0040) <> 16#0000;
ErrorSensorIncoherent := (ErrorId AND 16#0080) <> 16#0000;

Busy := FALSE;
Done := FALSE;

// 🚦 5. STATE MACHINE (phase diagnostic)
State := E_State.READY;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Safety_Winch) ===

// 🛑 1. GATE — neutralisation si désactivé
IF NOT Enable THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    SafeStop := TRUE;
    ForbidDescent := TRUE;
    PowerCutOff := FALSE;
    MeasuredSpeedMps := 0.0;
    MeasuredSpeedSignedMps := 0.0;
    State := E_State.DISABLED;
    Error := FALSE;
    ErrorId := 16#0000;
    // 🔧 REX 2026-07-08 : force le réarmement (WasArmed→FALSE) via FB_DriftGuard, comportement
    // identique à l'ancien MecaA_Armed/MecaC_Armed := FALSE.
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM);
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := BenneSlipToleranceM);
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    SpeedInitialized := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;
CycleTimeCalc(DefaultValueS := 0.010); // 🔧 REX 2026-07-07 — Méca A

// Détecte la fin du référencement pour éviter le pic de vitesse au cycle de transition (offset appliqué)
IF LastInReferencingMode AND NOT InReferencingMode THEN
    LastCablePosM := CablePosM;
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM); // 🔧 REX 2026-07-08
END_IF;
LastInReferencingMode := InReferencingMode;

// Si le contacteur de puissance est ouvert (EmergencyStopOk = FALSE), on force les sorties de sécurité
// mais on ne fait pas de RETURN pour permettre le diagnostic et l'acquittement (Reset) des défauts.
IF NOT EmergencyStopOk THEN
    DriftGuardA(Arm := FALSE, PositionM := CablePosM, ToleranceM := UncommandedDriftToleranceM); // 🔧 REX 2026-07-08
    DriftGuardC(Arm := FALSE, PositionM := CablePosM, ToleranceM := BenneSlipToleranceM);       // 🔧 REX 2026-07-08
    LastCablePosM := CablePosM;    // 🔧 REX 2026-07-07 (2) : évite le pic de vitesse au premier cycle actif
    SpeedInitialized := FALSE;
END_IF;

// 🔑 2. RESET FRONT — efface le bit dont la cause a disparu
ResetEdge(CLK := Reset);

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🌐 BYPASS GLOBAL : si TRUE, on force ErrorId = 0 ET on saute toute la logique de sécurité
IF BypassGlobal THEN
    ErrorId := 16#0000;
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonMecaE(IN := FALSE);
END_IF;

// 🔍 3. DIAGNOSTIC DU DOMAINE TREUIL (uniquement si bypass global désactivé)
IF NOT BypassGlobal THEN

    IF NOT (BypassProcess OR BypassOperatorComm) AND (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk) THEN
    ErrorId := ErrorId OR 16#0001;       // Perte communication opérateur : joystick CAN ou heartbeat IHM absent
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 3bis. PERTE CODEUR DE CE TREUIL (câblé — lot Codeur 2026-07-02)
// 🔧 WINCH-CORE-01 : le fonctionnement sans codeur reste interdit par défaut.
// Le bypass est individuel, maintenu consciemment depuis l'IHM et strictement limité à MAINT_N2.
// Il ne masque aucun autre défaut du treuil et n'agit jamais sur l'autre instance.
EncoderAvailableEffective := EncoderAvailable
                             OR ((EncoderFaultBypass OR BypassProcess) AND (Mode = E_Mode.MAINT_N2));
IF NOT EncoderAvailableEffective THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF;

// 🔍 3ter. SURCHAUFFE MOTEUR (câblé — I/O réel 2026-07-02) — bit2, participe au SafeStop total
IF NOT BypassSafety AND ThermalFeedback THEN
    ErrorId := ErrorId OR 16#0004;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

// 🔍 3quater. MOU DE CÂBLE (physiquement sur tambour M2, câblé sur les 2 instances Safety)
// Mode NORMAL (SyncEnable=TRUE) → SafeStop M1+M2 (bit3 inclus dans SafeStop)
// Mode RÉCUPÉRATION (SyncEnable=FALSE) → ForbidAscent uniquement (montée interdite, descente OK)
IF NOT BypassProcess AND SlackCableDetected THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q AND NOT SlackCableDetected THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🔍 3quinquies. ROTATION DE PHASE (câblé — I/O réel, commun M1/M2, 2026-07-03octodecies) —
// bit4, participe au SafeStop total (sens moteur potentiellement inversé, danger 2 sens).
IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
    ErrorId := ErrorId OR 16#0010;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFEF;
END_IF;

// 🔍 3sexties. FIN DE COURSE HAUT / CAPTEUR DE POSITION HAUTE (anti-débordement) — bit5
// ⚠️ Convention NAMING_CONVENTION.md : TopPositionSensor TRUE = sain/non atteint (NF), FALSE =
// position haute réellement atteinte (contact ouvert). Si la position haute EST atteinte
// (TopPositionSensor=FALSE), qu'on n'est pas en phase de référencement (homing), ET qu'on
// commande un mouvement vers le haut (Direction > 0), alors on lève le défaut.
IF NOT (BypassProcess OR BypassTopLimitSwitch) AND NOT TopPositionSensor AND NOT InReferencingMode AND (Direction > 0) THEN
    ErrorId := ErrorId OR 16#0020;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFDF;
END_IF;

// 🔍 3septies. LONGUEUR MAX DE CÂBLE (profondeur max autorisée) — bit6
// Sécurité active hors référencement. Si la position de câble descend sous la limite basse physique (CablePosM <= CfgCableLimitDescentM),
// alors on interdit uniquement la descente.
IF NOT (BypassProcess OR BypassCableLimitSwitch) AND (CfgCableLimitDescentM < 0.0) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode THEN
    ErrorId := ErrorId OR 16#0040;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFBF;
END_IF;

// 🔍 3octies. MÉCA A — MOUVEMENT NON COMMANDÉ GÉNÉRAL (REX 2026-07-07) — bit7
// Armé quand tout est physiquement confirmé coupé (contacteurs + frein). Si dérive ou vitesse
// détectée pendant que c'est armé → roue libre / frein insuffisant.
// 🔧 REX 2026-07-08 : dérive factorisée via FB_DriftGuard (CODE/WINCH/) — comportement inchangé,
// seul le check vitesse (MeasuredSpeedMps) reste géré ici (hors périmètre de la brique).
IF NOT SpeedInitialized OR InReferencingMode THEN
    MeasuredSpeedSignedMps := 0.0;
    SpeedInitialized := TRUE;
ELSE
    MeasuredSpeedSignedMps := (CablePosM - LastCablePosM) / CycleTimeCalc.CycleTimeS;
END_IF;
MeasuredSpeedMps := ABS(MeasuredSpeedSignedMps);
LastCablePosM := CablePosM;

DriftGuardA(
    Arm        := FwdRevSpeedFeedbackOff AND BrakeFeedback AND NOT InReferencingMode,
    PositionM  := CablePosM,
    ToleranceM := UncommandedDriftToleranceM
);
MecaADriftM := DriftGuardA.DriftM;   // 🆕 REX 2026-07-08 : diagnostic IHM

IF NOT (BypassSafety OR BypassMecaA) AND (DriftGuardA.Violation OR (FwdRevSpeedFeedbackOff AND BrakeFeedback AND NOT InReferencingMode AND (MeasuredSpeedMps > UncommandedSpeedThresholdMps))) THEN
    ErrorId := ErrorId OR 16#0080;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FF7F;
END_IF;

// 🔍 3nonies. MÉCA B — PILOTAGE ACTIF SANS COMMANDE OPÉRATEUR (REX 2026-07-07) — bit8
// Indépendant de FB_Winch (défense en profondeur). Perte CAN (bit0) OU joystick au neutre ;
// si les contacteurs OU LE FREIN ne confirment pas être retombés/serrés dans PostRampTimeout, défaut.
// 🔧 REX 2026-07-08 (demande utilisateur) : BrakeFeedback ajouté — un frein qui ne confirme pas
// son engagement dans ce délai est tout aussi dangereux qu'un contacteur qui ne retombe pas
// (risque de mouvement/roue libre non détecté). Auparavant seul FwdRevSpeedFeedbackOff était vérifié.
MecaB_NoOperatorCmd := (NOT JoystickOnline) OR (NOT JoystickOperational)
                       OR (NOT HeartbeatIhmOk) OR JoystickYNeutral;
TonMecaB(IN := NOT (BypassSafety OR BypassMecaB) AND MecaB_NoOperatorCmd AND NOT (FwdRevSpeedFeedbackOff AND BrakeFeedback), PT := PostRampTimeout);
MecaBElapsedTime := TonMecaB.ET;   // 🆕 REX 2026-07-08 : diagnostic IHM
IF TonMecaB.Q THEN
    ErrorId := ErrorId OR 16#0100;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FEFF;
END_IF;

// 🔍 3decies. MÉCA C — GLISSEMENT M1 PENDANT BENNE, ESCALADE (REX 2026-07-07) — bit9
// Armé UNIQUEMENT pour l'instance M1 (BenneHoldStillActive câblé sur instBucket.Busy côté M1
// seulement, toujours FALSE côté M2). Tolérance plus large que celle de FB_Bucket (1.0 m) —
// n'intervient que si la couche Benne (SafeStop M1 seul) n'a pas suffi.
// 🔧 REX 2026-07-08 : dérive factorisée via FB_DriftGuard (CODE/WINCH/) — comportement inchangé.
DriftGuardC(
    Arm        := NOT (BypassSafety OR BypassMecaC) AND BenneHoldStillActive,
    PositionM  := CablePosM,
    ToleranceM := BenneSlipToleranceM
);
MecaCDriftM := DriftGuardC.DriftM;   // 🆕 REX 2026-07-08 : diagnostic IHM

IF DriftGuardC.Violation THEN
    ErrorId := ErrorId OR 16#0200;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FDFF;
END_IF;

// 🔍 3undecies. THERMIQUE FREIN COMMUN M1/M2/M3 (REX 2026-07-08, demande utilisateur) — bit10
// Signal commun (1 seul fil, câblé identiquement sur les 3 instances Safety) : sa perte peut
// signifier qu'un frein colle instantanément (frein à manque de courant) → SafeStop ET
// PowerCutOff (voir bandeau en-tête).
IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
    ErrorId := ErrorId OR 16#0400;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FBFF;
END_IF;

// 🔍 3duodecies. MÉCA D — ARRIVÉE CAPTEUR HAUT HORS RÉFÉRENCEMENT (REX 2026-07-08 (3),
// demande utilisateur) — bit11
// Complète le bit5 (ForbidAscent immédiat) : arme la MÊME condition (capteur haut atteint, hors
// homing) mais avec un délai de confirmation, comme Méca B. Si les contacteurs ET le frein ne
// confirment pas être retombés/serrés dans PostRampTimeout après l'arrivée au capteur → défaut
// → SafeStop ET PowerCutOff (la coupure ForbidAscent seule n'a visiblement pas suffi à arrêter
// réellement le treuil : roue libre ou contacteur/frein défaillant).
TonMecaD(
    IN := NOT (BypassSafety OR BypassMecaD) AND ((((NOT TopPositionSensor AND NOT InReferencingMode) 
            OR (Homed AND NOT HomingSuspect AND (CablePosM >= (TopLimitM + 0.10))))
           AND (Direction >= 0)) // 🆕 Neutralise la butée haute en descente (Direction = -1)
          AND NOT (FwdRevSpeedFeedbackOff AND BrakeFeedback)), 
    PT := PostRampTimeout
);
IF TonMecaD.Q THEN
    ErrorId := ErrorId OR 16#0800;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#F7FF;
END_IF;

// 🔍 3terdecies. MÉCA E — ÉCART SYNCHRO M1/M2 CRITIQUE (REX 2026-07-08 (4)) — bits 12/13
// Couche INDÉPENDANTE de FB_WinchSync (écart mineur, 1er niveau) — défense en profondeur pour un
// écart VRAIMENT important. ExpectedOtherWinchPosM est DÉJÀ corrigé de l'offset benne actif par
// l'appelant : comparaison directe valable que le benne soit ouvert, fermé, ou absent du calcul.
// Suppression pendant BenneBusy (trajet actif = écart transitoire normal, pas un défaut),
// InReferencingMode (position pas fiable pendant homing) et OtherWinchInhibited (🆕 REX
// 2026-07-08 (7) : l'autre treuil en maintenance a une position figée, non comparable).
// Bit12 : détection → SafeStop immédiat. Bit13 : escalade si pas confirmé arrêté → PowerCutOff.
IF NOT (BypassProcess OR BypassMecaE) AND SyncEnable AND NOT BenneBusy AND NOT InReferencingMode AND NOT OtherWinchInhibited
   AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
    ErrorId := ErrorId OR 16#1000;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#EFFF;
END_IF;

TonMecaE(IN := NOT (BypassSafety OR BypassMecaE) AND (((ErrorId AND 16#1000) <> 16#0000) AND NOT (FwdRevSpeedFeedbackOff AND BrakeFeedback)),
         PT := PostRampTimeout);
IF TonMecaE.Q THEN
    ErrorId := ErrorId OR 16#2000;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#DFFF;
END_IF;

// 🔍 3quaterdecies — SENS RÉEL OPPOSÉ À LA COMMANDE (bit14)
// Le signe de la vitesse câble est comparé à la direction commandée uniquement pendant un
// mouvement effectivement demandé. La temporisation filtre bruit codeur et inversion transitoire.
OppositeDirectionActive := NOT BypassProcess AND (MovementCommanded AND NOT InReferencingMode
    AND (((Direction > 0) AND (MeasuredSpeedSignedMps < -MovementSpeedThresholdMps))
      OR ((Direction < 0) AND (MeasuredSpeedSignedMps > MovementSpeedThresholdMps))));
TonOppositeDirection(IN := OppositeDirectionActive, PT := OppositeDirectionTimeout);
IF TonOppositeDirection.Q THEN
    ErrorId := ErrorId OR 16#4000;
ELSIF ResetEdge.Q AND NOT OppositeDirectionActive THEN
    ErrorId := ErrorId AND 16#BFFF;
END_IF;

// ⏱️ 3quindecies — ABSENCE DE MOUVEMENT MALGRÉ COMMANDE (bit15)
// Détecte charge coincée, contacteur inefficace ou chaîne mécanique non entraînée. SafeStop seul :
// aucun retour ne justifie une coupure puissance brutale immédiate ; l'escalade reste matérielle.
TonNoMovement(
    IN := NOT BypassProcess AND (MovementCommanded AND NOT InReferencingMode
          AND (ABS(MeasuredSpeedSignedMps) < MovementSpeedThresholdMps)),
    PT := NoMovementTimeout
);
IF TonNoMovement.Q THEN
    ErrorId := ErrorId OR 16#8000;
ELSIF ResetEdge.Q AND (NOT MovementCommanded OR (ABS(MeasuredSpeedSignedMps) >= MovementSpeedThresholdMps)) THEN
    ErrorId := ErrorId AND 16#7FFF;
END_IF;

END_IF; // fin IF NOT BypassGlobal

// 📤 4. ARBITRAGE DES SORTIES MAÎTRESSES
Error := (ErrorId <> 16#0000);       // 🧭 Partie3 §4 : miroir de TOUT le domaine, y compris mou de câble (visible IHM)
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🟧 SafeStop : bits 0/1/2/3/4 (joystick, codeur, thermique moteur, MOU CÂBLE, phases) + 7/8/9
// (Méca A/B/C) + 10 (thermique frein commun) + 11 (Méca D) + 12/13 (🆕 REX 2026-07-08 (4) :
// Méca E, écart synchro critique) ou si contacteur coupé
IF NOT EmergencyStopOk THEN
    SafeStop := TRUE;
ELSIF NOT SyncEnable THEN
    SafeStop := (ErrorId AND 16#FF97) <> 16#0000;   // bit3 exclu → SafeStop normal sans mou câble
ELSE
    SafeStop := (ErrorId AND 16#FF9F) <> 16#0000;   // bit3 inclus → SafeStop complet avec mou câble
END_IF;

// ⬇️ ForbidDescent : bit6 uniquement (limite basse câble) ou si contacteur coupé
ForbidDescent := (ErrorId AND 16#0040) <> 16#0000 OR NOT EmergencyStopOk;

// ⬆️ ForbidAscent : bit5 (fin course haut) OU bit3+(NOT SyncEnable) (récupération mou câble : montée interdite même en récup)
// 🆕 REX 2026-07-08 : Sécurité positive maintenue si capteur haut physiquement activé hors référencement,
// même si l'alarme IHM (bit5) a été acquittée pour permettre la descente.
ForbidAscent := (ErrorId AND 16#0020) <> 16#0000
             OR (NOT TopPositionSensor AND NOT InReferencingMode)
             OR ((ErrorId AND 16#0008) <> 16#0000 AND NOT SyncEnable);

// 🧨 REX 2026-07-07 : PowerCutOff enfin réel — bits 7/8/9 (Méca A/B/C, voir bandeau en-tête).
// Coupure puissance amont : les contacteurs locaux sont déjà confirmés coupés/insuffisants,
// SafeStop seul ne sert à rien dans ces 3 cas précis.
// 🆕 REX 2026-07-08 (demande utilisateur) : bit2 (surchauffe/perte thermique MOTEUR) et bit10
// (surchauffe/perte thermique FREIN commun) ajoutés — un frein à manque de courant peut coller
// instantanément sur perte de son retour thermique : une rampe SafeStop seule ne protège pas la
// mécanique dans ce cas, coupure puissance immédiate nécessaire. Même raisonnement appliqué au
// thermique moteur par cohérence/défense en profondeur (demande explicite).
// 🆕 REX 2026-07-08 (3) : bit11 (Méca D, capteur haut) ajouté — même raisonnement que Méca A/B :
// contacteurs/frein déjà censés être coupés (ForbidAscent immédiat sur capteur), une confirmation
// manquante après délai signifie que la coupure locale n'a pas suffi.
// 🆕 REX 2026-07-08 (4) : bit13 (Méca E escalade) ajouté — PAS bit12 seul (détection immédiate =
// SafeStop uniquement ; PowerCutOff seulement si l'arrêt n'est pas confirmé après délai).
PowerCutOff := (ErrorId AND 16#2F84) <> 16#0000;

// Busy, Done non utilisés mais présents pour conformité (comme FB_DiagCanOpen)
Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_DigitalMirror) ===

IF NOT Enable THEN
    TonMirror(IN := FALSE, PT := MirrorDelay);
    Feedback := Command;   // Hors simulation : miroir idéal (comportement précédent conservé)
    RETURN;
END_IF;

TonMirror(IN := (Command <> Feedback), PT := MirrorDelay);
IF TonMirror.Q THEN
    Feedback := Command;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;

// 🆕 REX 2026-07-08 (4) — injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;

Increment := REAL_TO_UDINT(SpeedRefPct * 0.1 * SpeedScaleFactor);

IF PresetCmd THEN
    RawPos := PresetValue;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
END_IF;

RawPosOut := RawPos;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

// 🔑 Initialise au neutre au premier cycle uniquement — ensuite RawX/RawY/RawButton
// restent forçables librement en instance CODESYS (un Force n'est jamais écrasé par TRUE,
// mais une simple écriture cyclique l'écraserait — donc pas de ré-assignation continue ici).
IF NOT Enable THEN
    FirstCycle := TRUE;
    RETURN;
END_IF;

IF TestOverrideActive THEN
    // 🆕 REX 2026-07-19 : suite PLC_TESTS — écriture CYCLIQUE volontaire (pas de FirstCycle),
    // contrairement au forçage manuel, pour permettre un pilotage dynamique scan par scan.
    RawX := TestOverrideRawX;
    RawY := TestOverrideRawY;
    RawButton := TestOverrideRawButton;
    FirstCycle := FALSE;
ELSIF FirstCycle THEN
    RawX := NeutralRaw;
    RawY := NeutralRaw;
    RawButton := FALSE;
    FirstCycle := FALSE;
END_IF;

// === IMPLEMENTATION ===
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    ContactorLatch := FALSE;
    RETURN;
END_IF;

// 1. La chaîne AU est saine si le PLC maintient les deux relais de coupure de puissance
// AND if no emergency stop button is pressed (BtnEmergencyStop is FALSE)
SimChainOk := PowerCutOff_A AND PowerCutOff_B AND NOT BtnEmergencyStop;

// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure
IF NOT SimChainOk THEN
    ContactorLatch := FALSE;
ELSIF EmergencyArming THEN
    ContactorLatch := TRUE;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Translation) ===

IF NOT Enable THEN
    ElapsedS := 0.0;
    LastTargetNum := TargetNum;
    PosTremie := FALSE; PosPV := FALSE; PosP2 := FALSE; PosP1 := FALSE; PosMaintenance := FALSE;
    RETURN;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);

// 🔁 Changement de cible = nouveau trajet, on repart de zéro
TargetChanged := (TargetNum <> LastTargetNum);
LastTargetNum := TargetNum;
IF TargetChanged THEN
    ElapsedS := 0.0;
END_IF;

// ⏱️ Progression du trajet UNIQUEMENT si un relais de sens est actif (mouvement réel demandé) ;
// à l'arrêt, la progression reste EN PAUSE (pas remise à zéro).
IF (RelayFwd OR RelayRev) AND (ElapsedS < TravelTimeS) THEN
    ElapsedS := ElapsedS + CycleTimeCalc.CycleTimeS;
    IF ElapsedS > TravelTimeS THEN
        ElapsedS := TravelTimeS;
    END_IF;
END_IF;

Reached := (ElapsedS >= TravelTimeS);

// 🆕 REX 2026-07-18 : les capteurs sont codés par progression monotone.
// La simulation doit donc produire un mot valide à chaque instant, et non
// uniquement activer le capteur de la cible. Le mot est :
//   11111 Trémie | 01111 PV | 00111 P2 | 00011 P1 | 00001 approche Maintenance | 00000 Maintenance.
// 🔧 REX 2026-07-21 : au repos / boot (TargetNum = 0), la position neutre par défaut
// est positionnée sur P2 (00111) pour éviter d'être par défaut sur le fin de course extrême Maintenance (00000).
PosTremie := FALSE;
PosPV := FALSE;

IF TargetNum = 0 THEN
    // Position neutre par défaut au boot (P2 = 00111) — évite le fin de course extrême arrière au démarrage
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF TargetNum = 1 THEN
    // Trajet vers Trémie : PV puis Trémie, avec les trois capteurs de droite actifs.
    PosP2 := FALSE; PosP1 := FALSE; PosMaintenance := FALSE;
    IF ElapsedS >= (TravelTimeS - PVLeadTimeS) THEN
        PosPV := TRUE;
        PosP2 := TRUE;
        PosP1 := TRUE;
        PosMaintenance := TRUE;
    END_IF;
    IF Reached THEN
        PosTremie := TRUE;
    END_IF;
ELSIF TargetNum = 2 THEN
    // P2 = 00111
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF TargetNum = 3 THEN
    // P1 = 00011
    PosP2 := FALSE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF TargetNum = 4 THEN
    // Maintenance = 00000 : PosMaintenance reste FALSE pour respecter le codage.
    PosP2 := FALSE;
    PosP1 := FALSE;
    PosMaintenance := FALSE;
ELSE
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_SpeedStep) ===

// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 0. VALIDATION CONFIGURATION (P0.2) — exécutée CHAQUE cycle pour détecter
//    toute corruption IHM/PERSISTENT, même siEnable=FALSE (sorties sûres forcée)
// ─────────────────────────────────────────────────────────────────────────

// 🔧 Bornage systématique MaxStepNumber ∈ [1..5]
IF MaxStepNumber < 1 THEN
    _MaxStepClamped := 1;
ELSIF MaxStepNumber > 5 THEN
    _MaxStepClamped := 5;
ELSE
    _MaxStepClamped := MaxStepNumber;
END_IF;

// 🔍 Validation table ST_SpeedStepTable
// Critères (Partie 9 §2 + audit P0.2) :
// 1. Seuils croissants stricts : StepThreshold_Pct[1] < [2] < [3] < [4] < [5]
// 2. Seuils dans [0..100] %
// 3. HystMargin > 0
// 4. Pour chaque palier 2.._MaxStepClamped : au moins 1 contacteur TRUE (cohérence câblage)
//    Le palier 1 peut légitimement avoir les 4 contacteurs FALSE : résistances rotoriques
//    toutes insérées = vitesse minimale. On ne valide pas les paliers jamais atteignables.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;

// Critère 1 : seuils croissants
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;  // bit0
END_IF;

// Critère 2 : seuils dans [0..100]
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 3 : hystérésis > 0
IF HystMargin <= 0.0 THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;

// Critère 4 : cohérence contacteurs par palier (seulement jusqu'au plafond actif)
IF _ConfigValid THEN
    // Palier 1 : les 4 sorties FALSE sont une configuration valide de vitesse minimale.
    // Palier 2
    IF _MaxStepClamped >= 2 THEN
        IF NOT (Table.P2R1 OR Table.P2R2 OR Table.P2R3 OR Table.P2R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 3
    IF _MaxStepClamped >= 3 THEN
        IF NOT (Table.P3R1 OR Table.P3R2 OR Table.P3R3 OR Table.P3R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 4
    IF _MaxStepClamped >= 4 THEN
        IF NOT (Table.P4R1 OR Table.P4R2 OR Table.P4R3 OR Table.P4R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
    // Palier 5
    IF _MaxStepClamped >= 5 THEN
        IF NOT (Table.P5R1 OR Table.P5R2 OR Table.P5R3 OR Table.P5R4) THEN
            _ConfigValid := FALSE;
            _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
        END_IF;
    END_IF;
END_IF;

// 🛡️ Gestion erreur config : front montant + reset sur front Reset (cause disparue)
// Note : pas d'entrée Reset dédiée (brique réduite) → on réarme quand config redevient valide
//        (front descendant de _ConfigValid). Conforme Partie 3 §5 : cause disparue + front.
_ConfigErrorTrig(CLK := NOT _ConfigValid);  // Front montant = apparition erreur

// Mémoire erreur config : reste TRUE tant que config invalide OU pas de réarmement
// Réarmement = front montant de _ConfigValid (cause disparue) — détecté via _ConfigValidPrev
IF _ConfigErrorTrig.Q THEN
    // Nouvelle erreur : on la mémorise
    _ConfigValidPrev := FALSE;  // Force détection front montant au cycle suivant si redevient valide
ELSIF _ConfigValid AND NOT _ConfigValidPrev THEN
    // Config redevenue valide : front montant → on efface l'erreur (reset sur front)
    _ConfigValidPrev := TRUE;
ELSIF NOT _ConfigValid THEN
    _ConfigValidPrev := FALSE;
END_IF;

// Sorties erreur config (miroir standard Partie 3)
ConfigErrorId := _ConfigErrorIdInt;
ConfigError   := (ConfigErrorId <> 16#0000);

// ─────────────────────────────────────────────────────────────────────────
// 🛑 1. GATE — Enable FALSE OU config invalide = palier 0, sorties sûres
// ─────────────────────────────────────────────────────────────────────────
IF (NOT Enable) OR (NOT _ConfigValid) THEN
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
    SpeedGuardLimited := FALSE;
    RETURN;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🪜 2. SÉLECTION DU PALIER (HYSTERESIS lib Util : IN/HIGH/LOW → OUT)
//    OUT = TRUE tant que IN < LOW (régime "bas") ; OUT bascule à FALSE une fois
//    IN > HIGH (régime "haut" confirmé) ; maintien entre LOW et HIGH (anti-battement).
//    => NOT Hyst_n.OUT = "on a franchi le seuil n vers le haut" (palier n+1 atteint).
// ─────────────────────────────────────────────────────────────────────────
SpeedRefInt := REAL_TO_INT(SpeedRefPct);

Hyst1(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[1] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[1] - HystMargin));
Hyst2(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[2] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[2] - HystMargin));
Hyst3(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[3] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[3] - HystMargin));
Hyst4(IN := SpeedRefInt, HIGH := REAL_TO_INT(Table.StepThreshold_Pct[4] + HystMargin), LOW := REAL_TO_INT(Table.StepThreshold_Pct[4] - HystMargin));

StepNumber := 1;                          // Palier mini dès qu'Enable est actif
IF NOT Hyst1.OUT THEN StepNumber := 2; END_IF;
IF NOT Hyst2.OUT THEN StepNumber := 3; END_IF;
IF NOT Hyst3.OUT THEN StepNumber := 4; END_IF;
IF NOT Hyst4.OUT THEN StepNumber := 5; END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🆕 2bis. PLAFOND (2026-07-03quinquies) — appliqué APRÈS la sélection hystérésis,
// AVANT la lecture table : le 0..100% de la consigne peut réclamer le palier 5,
// mais ne dépassera jamais _MaxStepClamped (ex. limitation couple en descente)
// ─────────────────────────────────────────────────────────────────────────
IF StepNumber > _MaxStepClamped THEN
    StepNumber := _MaxStepClamped;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 🛡️ 2ter. GARDE-FOU VITESSE RÉELLE — limite uniquement la consigne de palier.
// Si la vitesse n'est pas validée stable, seul le palier 1 reste autorisé.
// ─────────────────────────────────────────────────────────────────────────
SpeedGuardLimited := FALSE;
IF SpeedGuardEnable THEN
    IF NOT SpeedGuardReady THEN
        IF StepNumber > 1 THEN
            StepNumber := 1;
            SpeedGuardLimited := TRUE;
        END_IF;
    ELSIF (MeasuredSpeedBand >= 1) AND (MeasuredSpeedBand <= 5) AND (StepNumber > MeasuredSpeedBand) THEN
        StepNumber := MeasuredSpeedBand;
        SpeedGuardLimited := TRUE;
    END_IF;
END_IF;

// ─────────────────────────────────────────────────────────────────────────
// 📤 3. CONTACTEURS — lus dans la table (donnée, jamais codé en dur)
//    CASE couvre explicitement 0..5 : StepNumber=0 → tous FALSE (sécurité)
// ─────────────────────────────────────────────────────────────────────────
CASE StepNumber OF
    0:  // Arrêt / config invalide / Enable=FALSE — sécurité positive
        Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur : valeur StepNumber inattendue → sécurité
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    StepNumber := 0;
END_CASE;

(* ═══════════════════════════════════════════════════════════════
   📝 NOTE D'APPLICATION MANUELLE CODESYS 3.5
   ═══════════════════════════════════════════════════════════════
   1. Ouvrir le POU FB_SpeedStep dans l'arborescence CODESYS (dossier TREUILS)
   2. Copier la partie DECLARATION (lignes 33-58) dans la zone VAR_INPUT/VAR_OUTPUT/VAR
   3. Copier la partie IMPLEMENTATION (lignes 61 à fin) dans le corps ST
   4. Vérifier que la librairie `Util` est référencée (HYSTERESIS, R_TRIG)
   5. Rebuild (F11) → 0 erreur attendue
   6. Vérifier dans FB_Winch que l'instance SpeedStep compile toujours
      (interface compatible : nouvelles sorties ConfigError/ConfigErrorId ajoutées,
       entrées/sorties existantes inchangées)
   ═══════════════════════════════════════════════════════════════ *)

// === IMPLEMENTATION ===
// Toujours mettre à jour les triggers, avec borne validée AVANT l'accès.
ProbeIdxLocal := Config.ProbeIdx;
IF ProbeIdxLocal >= 1 THEN
    IF ProbeIdxLocal <= GVL_PLC_Tests_Const.MaxProbeBool THEN
        RisingTrig(CLK := ProbeBool[ProbeIdxLocal]);
        FallingTrig(CLK := ProbeBool[ProbeIdxLocal]);
    ELSE
        RisingTrig(CLK := FALSE);
        FallingTrig(CLK := FALSE);
    END_IF;
ELSE
    RisingTrig(CLK := FALSE);
    FallingTrig(CLK := FALSE);
END_IF;

EvaluateTrig(CLK := Evaluate);

IF EvaluateTrig.Q THEN
    Passed := FALSE;
    Failed := FALSE;
    Pending := FALSE;
    FailReason := E_TestFailReason.FAIL_NONE;
    StableTimer(IN := FALSE);
END_IF;

// Mise à jour des valeurs observées
IF Config.ProbeIdx >= 1 THEN
    CASE Config.Kind OF
        E_TestCheckKind.BOOL_EQUAL, E_TestCheckKind.BOOL_RISING, E_TestCheckKind.BOOL_FALLING:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                ObservedBool := ProbeBool[ProbeIdxLocal];
            END_IF;
        E_TestCheckKind.DINT_EQUAL, E_TestCheckKind.DINT_NOT_EQUAL, E_TestCheckKind.DINT_IN_RANGE,
        E_TestCheckKind.WORD_MASK_ALL, E_TestCheckKind.WORD_MASK_ANY, E_TestCheckKind.WORD_MASK_NONE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                ObservedDint := ProbeDint[ProbeIdxLocal];
            END_IF;
        E_TestCheckKind.REAL_IN_RANGE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeReal THEN
                ObservedReal := ProbeReal[ProbeIdxLocal];
            END_IF;
    END_CASE;
END_IF;

// Évaluation de la condition logique (Cond)
Cond := FALSE;
IF Config.ProbeIdx >= 1 THEN
    CASE Config.Kind OF
        E_TestCheckKind.BOOL_EQUAL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                Cond := (ObservedBool = Config.ExpectedBool);
            END_IF;

        E_TestCheckKind.BOOL_RISING:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                Cond := RisingTrig.Q;
            END_IF;

        E_TestCheckKind.BOOL_FALLING:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                Cond := FallingTrig.Q;
            END_IF;

        E_TestCheckKind.DINT_EQUAL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := (ObservedDint = Config.ExpectedDint);
            END_IF;

        E_TestCheckKind.DINT_NOT_EQUAL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := (ObservedDint <> Config.ExpectedDint);
            END_IF;

        E_TestCheckKind.DINT_IN_RANGE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := (ObservedDint >= Config.ExpectedMin AND ObservedDint <= Config.ExpectedMax);
            END_IF;

        E_TestCheckKind.WORD_MASK_ALL:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := ((DINT_TO_WORD(ObservedDint) AND Config.Mask) = Config.Mask);
            END_IF;

        E_TestCheckKind.WORD_MASK_ANY:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := ((DINT_TO_WORD(ObservedDint) AND Config.Mask) <> 0);
            END_IF;

        E_TestCheckKind.WORD_MASK_NONE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                Cond := ((DINT_TO_WORD(ObservedDint) AND Config.Mask) = 0);
            END_IF;

        E_TestCheckKind.REAL_IN_RANGE:
            IF Config.ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeReal THEN
                Cond := (ObservedReal >= Config.RealMin AND ObservedReal <= Config.RealMax);
            END_IF;
    END_CASE;
END_IF;

// Application du mode d'évaluation
IF Evaluate THEN
    CASE Config.Mode OF
        E_TestCheckMode.CHECK_INSTANT:
            IF EvaluateTrig.Q THEN
                IF Cond THEN
                    Passed := TRUE;
                    Failed := FALSE;
                    Pending := FALSE;
                ELSE
                    Passed := FALSE;
                    Failed := TRUE;
                    Pending := FALSE;
                    FailReason := E_TestFailReason.FAIL_CHECK;
                END_IF;
            END_IF;

        E_TestCheckMode.CHECK_WAIT_UNTIL:
            IF NOT Passed AND NOT Failed THEN
                StableTimer(IN := Cond, PT := Config.StablePT);
                IF StableTimer.Q THEN
                    Passed := TRUE;
                    Failed := FALSE;
                    Pending := FALSE;
                ELSE
                    Pending := TRUE;
                END_IF;
            END_IF;

        E_TestCheckMode.CHECK_INVARIANT:
            IF NOT Cond THEN
                Passed := FALSE;
                Failed := TRUE;
                Pending := FALSE;
                FailReason := E_TestFailReason.FAIL_INVARIANT;
            ELSE
                Passed := TRUE;
                Failed := FALSE;
                Pending := FALSE;
            END_IF;

        E_TestCheckMode.CHECK_NEVER_DURING:
            IF NOT Failed THEN
                IF Cond THEN
                    Passed := FALSE;
                    Failed := TRUE;
                    Pending := FALSE;
                    FailReason := E_TestFailReason.FAIL_CHECK;
                ELSE
                    Pending := TRUE;
                END_IF;
            END_IF;
    END_CASE;
ELSE
    Passed := FALSE;
    Failed := FALSE;
    Pending := FALSE;
    StableTimer(IN := FALSE);
END_IF;

// === IMPLEMENTATION ===
TrigRising(CLK := Signal);
TrigFalling(CLK := Signal);

IF NOT Arm THEN
    Count := 0;
    InRange := FALSE;
    RETURN;
END_IF;

IF CountRising AND TrigRising.Q THEN
    Count := Count + 1;
ELSIF NOT CountRising AND TrigFalling.Q THEN
    Count := Count + 1;
END_IF;

InRange := (Count >= ExpectedMin AND Count <= ExpectedMax);

// === IMPLEMENTATION ===
TrigA(CLK := EventA);
TrigB(CLK := EventB);

IF NOT Arm THEN
    OrderOk := FALSE;
    Failed  := FALSE;
    HasA    := FALSE;
    Timer(IN := FALSE);
    RETURN;
END_IF;

// Échec immédiat si B se produit avant A
IF TrigB.Q AND NOT HasA THEN
    Failed  := TRUE;
    OrderOk := FALSE;
END_IF;

// Mémorisation de la survenue de A
IF TrigA.Q AND NOT Failed AND NOT OrderOk THEN
    HasA := TRUE;
END_IF;

// Armement du timeout une fois que A s'est produit
Timer(IN := HasA AND NOT OrderOk AND NOT Failed, PT := TimeoutPT);

IF Timer.Q THEN
    Failed  := TRUE;
    OrderOk := FALSE;
END_IF;

// Validation du succès si B arrive après A et dans les temps
IF HasA AND TrigB.Q AND NOT Failed THEN
    OrderOk := TRUE;
END_IF;

// === IMPLEMENTATION ===
StartTrig(CLK := Start);

IF StartTrig.Q AND NOT Busy THEN
    Busy := TRUE;
    Done := FALSE;
    ScanCount := 0;
    Result.InProgress := TRUE;
    Result.AllPassed := FALSE;
    Result.AnyFailed := FALSE;
    Result.CurrentTestId := 1;
    Result.FailedTestId := 0;
    Result.TestsPassed := 0;
    Result.TestsFailed := 0;
    Result.ErrorMessage := '';
    Result.RunCounter := Result.RunCounter + 1;
END_IF;

IF Busy THEN
    ScanCount := ScanCount + 1;
    IF ScanCount >= 3 THEN
        Busy := FALSE;
        Done := TRUE;
        Result.InProgress := FALSE;
        Result.AllPassed := TRUE;
        Result.AnyFailed := FALSE;
        Result.TestsPassed := 1;
        Result.TestsFailed := 0;
    END_IF;
END_IF;

// === IMPLEMENTATION ===
StartTrig(CLK := Start);

// 1. Validation de la configuration sur front de Start
IF StartTrig.Q THEN
    ConfigError := FALSE;
    ConfigErrorStepId := 0;
    ConfigErrorCheckIdx := 0;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    ErrorCode := 0;
    ErrorMessage := '';

    // 🛡️ Résolution interne CaseId → première étape, jamais d'étape exposée.
    RequestedCaseId := CaseId;
    IF CaseId < 0 OR CaseId > GVL_PLC_Tests_Const.MaxTestCases THEN
        ConfigError := TRUE;
        ConfigErrorStepId := CaseId;
        ErrorCode := 1001;
        ErrorMessage := 'CaseId hors limites';
        FirstStepLocal := 0;
    ELSIF CaseId = 0 THEN
        FirstStepLocal := CaseTable[1].FirstStep;
    ELSE
        FirstStepLocal := CaseTable[CaseId].FirstStep;
    END_IF;
    IF NOT ConfigError THEN
        IF FirstStepLocal < 1 OR FirstStepLocal > GVL_PLC_Tests_Const.MaxSteps THEN
            ConfigError := TRUE;
            ConfigErrorStepId := FirstStepLocal;
            ErrorCode := 1001;
            ErrorMessage := 'CaseTable.FirstStep hors limites';
        END_IF;
    END_IF;

    // Validation des étapes
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        IF StepTable[Idx].CaseId > 0 THEN
            // Vérification des NextOn
            IF StepTable[Idx].NextOnPass < 0 OR StepTable[Idx].NextOnPass > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE;
                ConfigErrorStepId := Idx;
            ELSIF StepTable[Idx].NextOnFail < 0 OR StepTable[Idx].NextOnFail > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE;
                ConfigErrorStepId := Idx;
            END_IF;

            // Vérification du Timeout
            IF StepTable[Idx].TimeoutPT <= T#0s THEN
                // Sauf si tous les checks de cette étape sont NEVER_DURING, mais restons stricts : TimeoutPT requis
                ConfigError := TRUE;
                ConfigErrorStepId := Idx;
            END_IF;

            // Vérification des Checks indexés par l'étape
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Kdx := StepTable[Idx].CheckIdx[Jdx];
                IF Kdx > 0 THEN
                    IF Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
                        ConfigError := TRUE;
                        ConfigErrorStepId := Idx;
                        ConfigErrorCheckIdx := Kdx;
                    ELSE
                        // Validation de la sonde associée au check
                        CASE CheckTable[Kdx].Kind OF
                            E_TestCheckKind.BOOL_EQUAL, E_TestCheckKind.BOOL_RISING, E_TestCheckKind.BOOL_FALLING:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeBool THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                END_IF;
                            E_TestCheckKind.DINT_EQUAL, E_TestCheckKind.DINT_NOT_EQUAL, E_TestCheckKind.DINT_IN_RANGE,
                            E_TestCheckKind.WORD_MASK_ALL, E_TestCheckKind.WORD_MASK_ANY, E_TestCheckKind.WORD_MASK_NONE:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeDint THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                END_IF;
                            E_TestCheckKind.REAL_IN_RANGE:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeReal THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                END_IF;
                        END_CASE;
                    END_IF;
                END_IF;
            END_FOR;
        END_IF;
    END_FOR;

    // 🛡️ ConfigError doit toujours produire Done + un état terminal.
    IF ConfigError THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        CurrentStepId := 0;
        StepElapsed := T#0s;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.InProgress := FALSE;
        Report.RunCounter := Report.RunCounter + 1;
        Report.AllPassed := FALSE;
        Report.AnyFailed := TRUE;
        Report.Aborted := FALSE;
        Report.TerminalState := TerminalState;
        IF ErrorCode = 0 THEN
            ErrorCode := 1002;
            ErrorMessage := 'Table de test invalide';
        END_IF;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        Report.FailureSummary := CONCAT('CONFIG_ERROR step ', INT_TO_STRING(ConfigErrorStepId));
        RETURN;
    END_IF;
END_IF;

// 2. Abort (Niveau, priorité absolue)
IF Abort THEN
    IF Busy THEN
        Report.InProgress := FALSE;
        Report.Aborted := TRUE;
        Report.AnyFailed := TRUE;

        // Enregistrement de l'échec de l'étape courante
        IF CurrentStepId >= 1 AND CurrentStepId <= GVL_PLC_Tests_Const.MaxSteps THEN
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := FALSE;
            Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_ABORTED;
            Report.Steps[CurrentStepId].Duration := StepElapsed;
        END_IF;

        // Échec du cas de test en cours
        IF CurrentCaseId >= 1 AND CurrentCaseId <= GVL_PLC_Tests_Const.MaxTestCases THEN
            Report.Cases[CurrentCaseId].Ok := FALSE;
            Report.Cases[CurrentCaseId].FailReason := E_TestFailReason.FAIL_ABORTED;
        END_IF;

        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
        Report.TerminalState := TerminalState;
    END_IF;
    ActiveStimulusId := 0;
    StepStarted := FALSE;
    RETURN;
END_IF;

// 3. Démarrage de la suite
IF StartTrig.Q AND NOT ConfigError THEN
    Busy := TRUE;
    Done := FALSE;
    AnyFailed := FALSE;
    CurrentStepId := FirstStepLocal;
    StepStarted := FALSE;

    // RAZ Rapport
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailedTestCase := 0;
    Report.CurrentStepId := FirstStepLocal;
    IF CurrentStepId >= 1 AND CurrentStepId <= GVL_PLC_Tests_Const.MaxSteps THEN
        Report.CurrentCaseId := StepTable[CurrentStepId].CaseId;
    ELSE
        Report.CurrentCaseId := 0;
    END_IF;
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;

    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Idx].Executed := FALSE;
        Report.Steps[Idx].Passed := FALSE;
        Report.Steps[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Idx].FailedCheckIdx := 0;
        Report.Steps[Idx].FailedInvariantId := 0;
        Report.Steps[Idx].Duration := T#0s;
    END_FOR;

    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Idx].Executed := FALSE;
        Report.Cases[Idx].Ok := FALSE;
        Report.Cases[Idx].FailedStepId := 0;
        Report.Cases[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Idx].Duration := T#0s;
    END_FOR;

    // RAZ Invariants
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxInvariants DO
        InvArmed[Idx] := FALSE;
    END_FOR;
END_IF;

// 4. Moteur d'exécution principal
IF Busy THEN
    // Incrément de la durée globale du run
    Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));

    // Vérification des bornes de l'étape courante (0 est valide et désigne la fin)
    IF CurrentStepId <> 0 AND (CurrentStepId < 1 OR CurrentStepId > GVL_PLC_Tests_Const.MaxSteps) THEN
        Busy := FALSE;
        Done := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        ConfigError := TRUE;
        ConfigErrorStepId := CurrentStepId;
        ErrorCode := 1003;
        ErrorMessage := 'Etape courante hors limites';
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        Report.InProgress := FALSE;
        Report.AnyFailed := TRUE;
        Report.TerminalState := TerminalState;
        Report.ErrorCode := ErrorCode;
        Report.ErrorMessage := ErrorMessage;
        Report.FailureSummary := ErrorMessage;
        RETURN;
    END_IF;

    // 🔒 Fin automatique dès qu'un run ciblé tenterait d'entrer dans le cas suivant.
    IF CurrentStepId > 0 AND RequestedCaseId > 0 THEN
        IF StepTable[CurrentStepId].CaseId <> RequestedCaseId THEN
            CurrentStepId := 0;
            ActiveStimulusId := 0;
            StepStarted := FALSE;
        END_IF;
    END_IF;

    IF CurrentStepId > 0 THEN
    CurrentCaseId := StepTable[CurrentStepId].CaseId;
    ActiveStimulusId := StepTable[CurrentStepId].StimulusId;
    Report.CurrentStepId := CurrentStepId;
    Report.CurrentCaseId := CurrentCaseId;

    IF NOT StepStarted THEN
        StepStarted := TRUE;
        StepElapsed := T#0s;
        DwellTimer(IN := FALSE);
        StepTimer(IN := FALSE);

        // Gestion de l'armement/désarmement des invariants
        FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxInvariants DO
            IF InvariantTable[Idx].ArmAtStepId = CurrentStepId THEN
                InvArmed[Idx] := TRUE;
            END_IF;
            IF InvariantTable[Idx].DisarmAtStepId = CurrentStepId THEN
                InvArmed[Idx] := FALSE;
            END_IF;
        END_FOR;
    END_IF;

    // Incrément de la durée de l'étape courante
    StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));

    // 4.1 Évaluation des invariants actifs
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxInvariants DO
        IF InvArmed[Idx] THEN
            InvChecks[Idx](Config := InvariantTable[Idx].Check, Evaluate := TRUE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            IF InvChecks[Idx].Failed THEN
                // Violation d'invariant -> Transition en échec immédiat
                Report.Steps[CurrentStepId].Executed := TRUE;
                Report.Steps[CurrentStepId].Passed := FALSE;
                Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_INVARIANT;
                Report.Steps[CurrentStepId].FailedInvariantId := Idx;
                Report.Steps[CurrentStepId].Duration := StepElapsed;
                Report.Steps[CurrentStepId].ObservedBool := InvChecks[Idx].ObservedBool;
                Report.Steps[CurrentStepId].ObservedDint := InvChecks[Idx].ObservedDint;
                Report.Steps[CurrentStepId].ObservedReal := InvChecks[Idx].ObservedReal;

                // Désactivation de l'évaluation
                InvChecks[Idx](Config := InvariantTable[Idx].Check, Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);

                // Transition
                IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
                    Busy := FALSE;
                    Done := TRUE;
                    AnyFailed := TRUE;
                    ActiveStimulusId := 0;
                ELSE
                    CurrentStepId := StepTable[CurrentStepId].NextOnFail;
                    StepStarted := FALSE;
                END_IF;
                RETURN;
            END_IF;
        END_IF;
    END_FOR;

    // 4.2 Gestion de la temporisation de Dwell
    DwellTimer(IN := TRUE, PT := StepTable[CurrentStepId].DwellPT);
    IF NOT DwellTimer.Q THEN
        // En attente du Dwell, pas d'évaluation des checks d'étape
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
        END_FOR;
        RETURN;
    END_IF;

    // 4.3 Évaluation des checks d'étape
    AllChecksPassed     := TRUE;
    AnyCheckFailed      := FALSE;
    FailedCheckIdxLocal := 0;
    FailReasonLocal     := E_TestFailReason.FAIL_NONE;
    ObsBoolLocal        := FALSE;
    ObsDintLocal        := 0;
    ObsRealLocal        := 0.0;

    FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
        Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
        IF Kdx < 0 OR Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
            ConfigError := TRUE;
            ConfigErrorStepId := CurrentStepId;
            ConfigErrorCheckIdx := Kdx;
            ErrorCode := 1006;
            ErrorMessage := 'CheckIdx runtime hors limites';
            Busy := FALSE;
            Done := TRUE;
            AnyFailed := TRUE;
            ActiveStimulusId := 0;
            TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
            RETURN;
        END_IF;
        IF Kdx > 0 THEN
            Checks[Jdx](Config := CheckTable[Kdx], Evaluate := TRUE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);

            IF Checks[Jdx].Failed THEN
                AnyCheckFailed := TRUE;
                FailedCheckIdxLocal := Kdx;
                FailReasonLocal := Checks[Jdx].FailReason;
                ObsBoolLocal := Checks[Jdx].ObservedBool;
                ObsDintLocal := Checks[Jdx].ObservedDint;
                ObsRealLocal := Checks[Jdx].ObservedReal;
            ELSIF Checks[Jdx].Pending THEN
                AllChecksPassed := FALSE;
            END_IF;
        END_IF;
    END_FOR;

    // 4.4 Prise de verdict
    IF AnyCheckFailed THEN
        // Échec sur un check d'étape
        Report.Steps[CurrentStepId].Executed := TRUE;
        Report.Steps[CurrentStepId].Passed := FALSE;
        Report.Steps[CurrentStepId].FailReason := FailReasonLocal;
        Report.Steps[CurrentStepId].FailedCheckIdx := FailedCheckIdxLocal;
        Report.Steps[CurrentStepId].Duration := StepElapsed;
        Report.Steps[CurrentStepId].ObservedBool := ObsBoolLocal;
        Report.Steps[CurrentStepId].ObservedDint := ObsDintLocal;
        Report.Steps[CurrentStepId].ObservedReal := ObsRealLocal;

        // Reset checks
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
        END_FOR;

        IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
            Busy := FALSE;
            Done := TRUE;
            AnyFailed := TRUE;
            ActiveStimulusId := 0;
        ELSE
            CurrentStepId := StepTable[CurrentStepId].NextOnFail;
            StepStarted := FALSE;
        END_IF;
        RETURN;
    END_IF;

    StepTimer(IN := TRUE, PT := StepTable[CurrentStepId].TimeoutPT);

    IF AllChecksPassed THEN
        // Succès précoce (vérification MinPT)
        IF StepElapsed < StepTable[CurrentStepId].MinPT THEN
            // Réaction trop rapide = Échec
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := FALSE;
            Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_WINDOW_EARLY;
            Report.Steps[CurrentStepId].Duration := StepElapsed;

            // Reset checks
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            END_FOR;

            IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
                Busy := FALSE;
                Done := TRUE;
                AnyFailed := TRUE;
                ActiveStimulusId := 0;
            ELSE
                CurrentStepId := StepTable[CurrentStepId].NextOnFail;
                StepStarted := FALSE;
            END_IF;
        ELSE
            // Validation étape OK
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := TRUE;
            Report.Steps[CurrentStepId].Duration := StepElapsed;

            // Prendre snapshot du premier check s'il existe
            IF StepTable[CurrentStepId].CheckIdx[1] > 0 THEN
                Report.Steps[CurrentStepId].ObservedBool := Checks[1].ObservedBool;
                Report.Steps[CurrentStepId].ObservedDint := Checks[1].ObservedDint;
                Report.Steps[CurrentStepId].ObservedReal := Checks[1].ObservedReal;
            END_IF;

            // Reset checks
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
            END_FOR;

            CurrentStepId := StepTable[CurrentStepId].NextOnPass;
            StepStarted := FALSE;
        END_IF;
        RETURN;
    END_IF;

    // Gestion du timeout d'étape
    IF StepTimer.Q THEN
        // Si timeout expiré, vérifions si des checks NEVER_DURING sont en attente
        NeverDuringPassed := TRUE;
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
            IF Kdx < 0 OR Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
                ConfigError := TRUE;
                ConfigErrorStepId := CurrentStepId;
                ConfigErrorCheckIdx := Kdx;
                ErrorCode := 1006;
                ErrorMessage := 'CheckIdx timeout hors limites';
                Busy := FALSE;
                Done := TRUE;
                AnyFailed := TRUE;
                ActiveStimulusId := 0;
                TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
                RETURN;
            END_IF;
            IF Kdx > 0 THEN
                IF CheckTable[Kdx].Mode = E_TestCheckMode.CHECK_NEVER_DURING THEN
                    // Jamais violé pendant toute la fenêtre
                    Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
                ELSE
                    // Les autres modes auraient dû passer avant le timeout
                    NeverDuringPassed := FALSE;
                END_IF;
            END_IF;
        END_FOR;

        IF NeverDuringPassed THEN
            // Succès par non-violation
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := TRUE;
            Report.Steps[CurrentStepId].Duration := StepElapsed;

            CurrentStepId := StepTable[CurrentStepId].NextOnPass;
            StepStarted := FALSE;
        ELSE
            // Timeout classique de l'étape
            Report.Steps[CurrentStepId].Executed := TRUE;
            Report.Steps[CurrentStepId].Passed := FALSE;
            Report.Steps[CurrentStepId].FailReason := E_TestFailReason.FAIL_TIMEOUT;
            Report.Steps[CurrentStepId].Duration := StepElapsed;

            IF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
                Busy := FALSE;
                Done := TRUE;
                AnyFailed := TRUE;
                ActiveStimulusId := 0;
            ELSE
                CurrentStepId := StepTable[CurrentStepId].NextOnFail;
                StepStarted := FALSE;
            END_IF;
        END_IF;

        // Reset checks
        FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
            Checks[Jdx](Evaluate := FALSE, ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal);
        END_FOR;
    END_IF;
    END_IF;
END_IF;

// 5. Agrégation des résultats en fin de suite (CurrentStepId = 0)
IF Busy AND CurrentStepId = 0 THEN
    Busy := FALSE;
    Done := TRUE;
    ActiveStimulusId := 0;
    Report.InProgress := FALSE;

    // Agrégation des cas de test
    SuiteAllPassed  := TRUE;
    FirstFailedCase := 0;

    FOR CaseIdx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        CaseStartStep := CaseTable[CaseIdx].FirstStep;
        IF CaseStartStep > 0 THEN
            CaseOk := TRUE;
            CaseExecuted := FALSE;
            CaseFailedStep := 0;
            CaseDuration := T#0s;
            CaseFailReason := E_TestFailReason.FAIL_NONE;

            // 🔒 Parcours borné et index validé AVANT déréférencement.
            // CODESYS peut évaluer StepTable[CaseStep] même si CaseStep=0
            // dans une condition composée : ancienne version = Access Violation CPU.
            CaseStep := CaseStartStep;
            FOR CaseWalkCount := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
                IF CaseStep = 0 THEN
                    EXIT;
                END_IF;
                IF CaseStep < 1 OR CaseStep > GVL_PLC_Tests_Const.MaxSteps THEN
                    ConfigError := TRUE;
                    ConfigErrorStepId := CaseStep;
                    ErrorCode := 1004;
                    ErrorMessage := 'Agregation : etape hors limites';
                    CaseOk := FALSE;
                    EXIT;
                END_IF;
                IF StepTable[CaseStep].CaseId <> CaseIdx THEN
                    EXIT;
                END_IF;

                IF Report.Steps[CaseStep].Executed THEN
                    CaseExecuted := TRUE;
                    CaseDuration := CaseDuration + Report.Steps[CaseStep].Duration;
                    IF NOT Report.Steps[CaseStep].Passed THEN
                        CaseOk := FALSE;
                        CaseFailedStep := CaseStep;
                        CaseFailReason := Report.Steps[CaseStep].FailReason;
                        CaseStep := StepTable[CaseStep].NextOnFail;
                    ELSE
                        CaseStep := StepTable[CaseStep].NextOnPass;
                    END_IF;
                ELSE
                    CaseStep := StepTable[CaseStep].NextOnPass;
                END_IF;
            END_FOR;
            IF CaseStep <> 0 AND CaseWalkCount > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE;
                ConfigErrorStepId := CaseStep;
                ErrorCode := 1005;
                ErrorMessage := 'Agregation : cycle de transitions';
                CaseOk := FALSE;
            END_IF;

            Report.Cases[CaseIdx].Name := CaseTable[CaseIdx].Name; // 🏷️ Lisible directement en Watch, sans chercher l'index
            Report.Cases[CaseIdx].Executed := CaseExecuted;
            Report.Cases[CaseIdx].Ok := CaseExecuted AND CaseOk;
            Report.Cases[CaseIdx].FailedStepId := CaseFailedStep;
            Report.Cases[CaseIdx].FailReason := CaseFailReason;
            Report.Cases[CaseIdx].Duration := CaseDuration;

            IF CaseExecuted AND NOT CaseOk THEN
                SuiteAllPassed := FALSE;
                IF FirstFailedCase = 0 THEN
                    FirstFailedCase := CaseIdx;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;

    Report.AllPassed := SuiteAllPassed;
    Report.AnyFailed := NOT SuiteAllPassed;
    Report.FailedTestCase := FirstFailedCase;
    AnyFailed := NOT SuiteAllPassed;
    IF SuiteAllPassed THEN
        TerminalState := E_TestTerminalState.TEST_TERMINAL_DONE;
    ELSE
        TerminalState := E_TestTerminalState.TEST_TERMINAL_FAILED;
    END_IF;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;

    // 🏷️ Résumé texte de TOUS les cas en échec (pas juste le premier) — évite de
    // parcourir Cases[] un par un en Watch (demande utilisateur 2026-07-16)
    Report.FailureSummary := '';
    FOR CaseIdx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF Report.Cases[CaseIdx].Executed AND NOT Report.Cases[CaseIdx].Ok THEN
            CASE Report.Cases[CaseIdx].FailReason OF
                E_TestFailReason.FAIL_TIMEOUT:      ReasonText := 'FAIL_TIMEOUT';
                E_TestFailReason.FAIL_CHECK:        ReasonText := 'FAIL_CHECK';
                E_TestFailReason.FAIL_INVARIANT:    ReasonText := 'FAIL_INVARIANT';
                E_TestFailReason.FAIL_WINDOW_EARLY: ReasonText := 'FAIL_WINDOW_EARLY';
                E_TestFailReason.FAIL_ABORTED:      ReasonText := 'FAIL_ABORTED';
            ELSE
                ReasonText := 'FAIL_NONE';
            END_CASE;

            EntryText := CONCAT(Report.Cases[CaseIdx].Name, ' (step ');
            EntryText := CONCAT(EntryText, INT_TO_STRING(Report.Cases[CaseIdx].FailedStepId));
            EntryText := CONCAT(EntryText, '): ');
            EntryText := CONCAT(EntryText, ReasonText);

            IF Report.FailureSummary = '' THEN
                Report.FailureSummary := EntryText;
            ELSE
                Report.FailureSummary := CONCAT(Report.FailureSummary, ' | ');
                Report.FailureSummary := CONCAT(Report.FailureSummary, EntryText);
            END_IF;
        END_IF;
    END_FOR;
END_IF;

// === IMPLEMENTATION ===
StartTrig(CLK := Start);

// Gestion de l'arrêt ou de l'inactivité
IF Abort OR (NOT Running AND NOT StartTrig.Q) THEN
    Running := FALSE;
    OutActive := FALSE;
    OutBool := FALSE;
    OutReal := 0.0;
    Done := FALSE;
    Timer(IN := FALSE);
    SeqTimer(IN := FALSE);
    Ramp(RESET := TRUE, IN := 0.0);
    RETURN;
END_IF;

// Lancement sur front montant de Start
IF StartTrig.Q THEN
    Running := TRUE;
    Done := FALSE;
    OutActive := TRUE;
    ActiveIndex := 1;
    Timer(IN := FALSE);
    SeqTimer(IN := FALSE);

    CASE Config.Kind OF
        E_TestStimKind.STIM_PULSE_BOOL:
            OutBool := TRUE;
            Timer(IN := TRUE, PT := Config.PulsePT);

        E_TestStimKind.STIM_RAMP_REAL:
            Ramp(RESET := TRUE, IN := Config.StartReal);
            IF Config.RampPT > T#0s THEN
                // Calcul de la vitesse par seconde
                Rate := ABS(Config.TargetReal - Config.StartReal) / (TIME_TO_REAL(Config.RampPT) / 1000.0);
            ELSE
                Rate := ABS(Config.TargetReal - Config.StartReal);
            END_IF;
            Timer(IN := TRUE, PT := Config.RampPT);

        E_TestStimKind.STIM_SEQUENCE_REAL:
            IF Config.SeqCount >= 1 THEN
                OutReal := Config.SeqValues[1];
                SeqTimer(IN := TRUE, PT := Config.SeqDwellPT);
            ELSE
                Running := FALSE;
                OutActive := FALSE;
                Done := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Éxecution logique quand le stimulus tourne
IF Running THEN
    CASE Config.Kind OF
        E_TestStimKind.STIM_PULSE_BOOL:
            Timer();
            IF Timer.Q THEN
                OutBool := FALSE;
                Running := FALSE;
                OutActive := FALSE;
                Done := TRUE;
                Timer(IN := FALSE);
            END_IF;

        E_TestStimKind.STIM_RAMP_REAL:
            Timer();
            Ramp(RESET := FALSE, IN := Config.TargetReal, ASCEND := Rate, DESCEND := Rate, TIMEBASE := T#1s);
            OutReal := Ramp.OUT;
            IF Timer.Q THEN
                OutReal := Config.TargetReal; // Assure la valeur cible exacte à la fin
                Running := FALSE;
                OutActive := FALSE;
                Done := TRUE;
                Timer(IN := FALSE);
            END_IF;

        E_TestStimKind.STIM_SEQUENCE_REAL:
            SeqTimer();
            IF SeqTimer.Q THEN
                SeqTimer(IN := FALSE);
                ActiveIndex := ActiveIndex + 1;
                IF ActiveIndex > Config.SeqCount OR ActiveIndex > GVL_PLC_Tests_Const.MaxSeqValues THEN
                    Running := FALSE;
                    OutActive := FALSE;
                    Done := TRUE;
                ELSE
                    OutReal := Config.SeqValues[ActiveIndex];
                    SeqTimer(IN := TRUE, PT := Config.SeqDwellPT);
                END_IF;
            END_IF;
    END_CASE;
END_IF;

// === IMPLEMENTATION ===
StartTrig(CLK := StartEvent);
StopTrig(CLK := StopEvent);

IF NOT Arm THEN
    Running := FALSE;
    Done := FALSE;
    InWindow := FALSE;
    ElapsedMs := 0;
    CycleCount := 0;
    RETURN;
END_IF;

IF StartTrig.Q AND NOT Running AND NOT Done THEN
    Running := TRUE;
    CycleCount := 0;
END_IF;

IF Running THEN
    // Incrémente le compteur de cycles
    CycleCount := CycleCount + 1;
    ElapsedMs := UDINT_TO_DINT(CycleCount * INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));

    IF StopTrig.Q THEN
        Running := FALSE;
        Done := TRUE;
        InWindow := (ElapsedMs >= ExpectedMinMs AND ElapsedMs <= ExpectedMaxMs);
    END_IF;
END_IF;

// === IMPLEMENTATION ===
Timer(IN := Active, PT := PT);
Elapsed := Timer.Q;

// === IMPLEMENTATION ===

// 🛑 1. GATE (Enable / EmergencyStopOk) — neutralisation totale, sorties sûres
IF NOT Enable OR NOT EmergencyStopOk THEN
    DriveControlWord := 0; DriveFreqRefHz := 0.0;

    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeCmd := Brake.BrakeCmd;
    BrakeContactorCheck := Brake.ContactorCheck;

    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);

    ArrivalLock := FALSE;

    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);   // MainTask = 10 ms

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 📡 3. CAPTEUR POSITION CIBLE (debounce)
CaptorDebounceTon(IN := PositionSensorTarget, PT := CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;

// ⚙️ 4. CORE — arbitrage rampe : Enable > SafeStop > StartStop
RampTargetPct := 0.0;
IF NOT SafeStop AND StartStop THEN
    // Si butée fin de course extrême atteinte dans le sens de marche demandé, consigne forcée à 0
    // 🌐 BypassLimitSwitch = TRUE → ignore cette protection
    IF NOT BypassLimitSwitch AND ((Direction = 1 AND LimitSwitchFwd) OR (Direction = -1 AND LimitSwitchRev)) THEN
        RampTargetPct := 0.0;
    ELSE
        RampTargetPct := ABS(SpeedRefPct);
    END_IF;
END_IF;

// ⏱️ 4bis. RALENTISSEMENT AUTO À L'APPROCHE (piloté par capteur PV, remplace le timer)
// 🔧 REX 2026-07-18 : ApproachTime (timer générique, toute direction confondue) remplacé par un
// capteur dédié (SlowdownSensor = PV) qui ne déclenche le ralentissement QU'à l'approche de
// Trémie (Direction=1) — décision client (AF_Partie-02 v2.12 §3bis) : PV n'assure le
// ralentissement qu'avant Trémie, jamais dans le sens Maintenance.
IF (Direction = 1) AND SlowdownSensor THEN
    RampTargetPct := LIMIT(0.0, RampTargetPct, ApproachSpeedPct);
END_IF;

// 🎯 4ter. ARRÊT EXACT SUR CAPTEUR (verrouille le sens tant que le capteur cible reste actif)
ArrivalEdge(CLK := TargetReached);
IF ArrivalEdge.Q THEN
    DirectionAtArrival := CommandedDirection;
END_IF;
ArrivalLock := TargetReached AND (Direction = DirectionAtArrival) AND (DirectionAtArrival <> 0);
IF ArrivalLock THEN
    RampTargetPct := 0.0;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(SafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

// 🔒 5. INTERLOCK CHANGEMENT DE SENS — jamais Fwd+Rev simultanés (vitesse confirmée nulle)
IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

MovementRequested := (CommandedDirection <> 0) AND (ABS(SpeedRamp.Current) > 0.1);

// 🔀 5bis. SORTIE PHYSIQUE (ETHERCAT)
DriveFreqRefHz := (ABS(SpeedRamp.Current) / 100.0) * DriveFreqScaleMaxHz;

// Pilotage nominal Given Command 1 (0x3101) :
// 0: None, 1: Forward, 2: Reverse, 7: Reset
IF Reset THEN
    DriveControlWord := 7; // Reset défaut variateur
ELSIF Error THEN
    DriveControlWord := 0; // Arrêt sur défaut
ELSIF MovementRequested THEN
    IF CommandedDirection = 1 THEN
        DriveControlWord := 1; // Marche avant
    ELSIF CommandedDirection = -1 THEN
        DriveControlWord := 2; // Marche arrière
    ELSE
        DriveControlWord := 0;
    END_IF;
ELSE
    DriveControlWord := 0;
END_IF;

// Sécurité : si Fdc extrême atteint dans le sens de marche, coupure commande immédiate (sans rampe ni couple)
// 🌐 BypassLimitSwitch = TRUE → ignore cette protection (test/mise en service)
IF NOT BypassLimitSwitch AND ((CommandedDirection = 1 AND LimitSwitchFwd) OR (CommandedDirection = -1 AND LimitSwitchRev)) THEN
    DriveControlWord := 0;
    DriveFreqRefHz := 0.0;
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
END_IF;

// 🛑 6. FREIN (composé, réutilisé tel quel)
Brake(Enable := TRUE, Reset := Reset, MovementRequested := MovementRequested,
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeCmd := Brake.BrakeCmd;
BrakeContactorCheck := Brake.ContactorCheck;

// 🧾 7. ERRORID (bitfield, cumul)
IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// Défaut variateur (bit3) : lu via EtherCAT (DriveStatusWord.4)
IF DriveStatusWord.4 THEN
    ErrorId := ErrorId OR 16#0008;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFF7;
END_IF;

// 🚧 Défaut fin de course extrême (bit6) — si bypassé, on NETTOIE le bit résiduel
IF BypassLimitSwitch THEN
    ErrorId := ErrorId AND 16#FFBF;   // Nettoie le bit 6 (évite résidu d'avant activation)
ELSE
    IF LimitSwitchFwd OR LimitSwitchRev THEN
        ErrorId := ErrorId OR 16#0040;
    END_IF;
END_IF;
IF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFBF;   // Reset normal (complémentaire)
END_IF;

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// 🚦 8. STATE MACHINE (phase)
IF (NOT StartStop OR SafeStop) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

// 🛡️ 9. SORTIE SÛRE SUR DÉFAUT
IF Error THEN
    DriveControlWord := 0; DriveFreqRefHz := 0.0;
    BrakeCmd := FALSE;
END_IF;

// === IMPLEMENTATION ===
IF RunStart THEN
    Report.Name := 'Translation Validation';
    Report.InProgress := TRUE;
    Report.AllPassed := FALSE;
    Report.AnyFailed := FALSE;
    Report.Aborted := FALSE;
    Report.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Report.ErrorCode := 0;
    Report.ErrorMessage := '';
    Report.FailedTestCase := 0;
    Report.FailureSummary := '';
    Report.CurrentStepId := 0;
    Report.CurrentCaseId := 0;
    Report.Duration := T#0s;
    Report.RunCounter := Report.RunCounter + 1;
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        Report.Steps[Idx].Executed := FALSE;
        Report.Steps[Idx].Passed := FALSE;
        Report.Steps[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Steps[Idx].FailedCheckIdx := 0;
        Report.Steps[Idx].FailedInvariantId := 0;
        Report.Steps[Idx].Duration := T#0s;
    END_FOR;
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        Report.Cases[Idx].Name := CaseTable[Idx].Name;
        Report.Cases[Idx].Executed := FALSE;
        Report.Cases[Idx].Ok := FALSE;
        Report.Cases[Idx].FailedStepId := 0;
        Report.Cases[Idx].FailReason := E_TestFailReason.FAIL_NONE;
        Report.Cases[Idx].Duration := T#0s;
    END_FOR;
    Result.TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    Result.RequestedCaseId := RequestedCaseId;
    Result.ExecutedCaseId := 0;
    Result.AllPassed := FALSE;
    Result.AnyFailed := FALSE;
    Result.FailedCaseId := 0;
    Result.FailedCaseName := '';
    Result.FailReason := E_TestFailReason.FAIL_NONE;
    Result.ErrorCode := 0;
    Result.ErrorMessage := '';
    Result.CasesTotal := 0;
    Result.CasesPassed := 0;
    Result.CasesFailed := 0;
    Result.Duration := T#0s;
    Result.RunCounter := Report.RunCounter;
END_IF;

IF Busy THEN
    Report.Duration := Report.Duration + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
END_IF;

// 🧾 Agrégation incrémentale : validation séparée avant toute indexation.
IF StepVerdict THEN
    IF StepId < 1 OR StepId > GVL_PLC_Tests_Const.MaxSteps THEN
        Report.ErrorCode := 1050;
        Report.ErrorMessage := 'Verdict StepId hors limites';
        Report.AnyFailed := TRUE;
        RETURN;
    END_IF;
    Report.Steps[StepId].Executed := TRUE;
    Report.Steps[StepId].Passed := StepPassed;
    Report.Steps[StepId].FailReason := StepFailReason;
    Report.Steps[StepId].FailedCheckIdx := StepFailedCheckIdx;
    Report.Steps[StepId].Duration := StepDuration;
    Report.Steps[StepId].ObservedBool := StepObservedBool;
    Report.Steps[StepId].ObservedDint := StepObservedDint;
    Report.Steps[StepId].ObservedReal := StepObservedReal;
    Report.CurrentStepId := StepId;
    Report.CurrentCaseId := StepCaseId;

    IF StepCaseId >= 1 THEN
        IF StepCaseId <= GVL_PLC_Tests_Const.MaxTestCases THEN
        IF NOT Report.Cases[StepCaseId].Executed THEN
            Report.Cases[StepCaseId].Executed := TRUE;
            Report.Cases[StepCaseId].Ok := TRUE;
        END_IF;
        Report.Cases[StepCaseId].Duration := Report.Cases[StepCaseId].Duration + StepDuration;
        IF NOT StepPassed THEN
            Report.Cases[StepCaseId].Ok := FALSE;
            IF Report.Cases[StepCaseId].FailedStepId = 0 THEN
                Report.Cases[StepCaseId].FailedStepId := StepId;
                Report.Cases[StepCaseId].FailReason := StepFailReason;
            END_IF;
        END_IF;
        ELSE
            Report.ErrorCode := 1051;
            Report.ErrorMessage := 'Verdict CaseId hors limites';
            Report.AnyFailed := TRUE;
        END_IF;
    ELSE
        Report.ErrorCode := 1051;
        Report.ErrorMessage := 'Verdict CaseId hors limites';
        Report.AnyFailed := TRUE;
    END_IF;
END_IF;

IF Finalize THEN
    Report.InProgress := FALSE;
    Report.TerminalState := TerminalState;
    Report.ErrorCode := ErrorCode;
    Report.ErrorMessage := ErrorMessage;
    Report.Aborted := (TerminalState = E_TestTerminalState.TEST_TERMINAL_ABORTED);
    CasesTotalLocal := 0;
    CasesPassedLocal := 0;
    CasesFailedLocal := 0;
    FirstFailedCase := 0;
    Report.FailureSummary := '';

    FOR CaseIdx := 1 TO GVL_PLC_Tests_Const.MaxTestCases DO
        IF Report.Cases[CaseIdx].Executed THEN
            CasesTotalLocal := CasesTotalLocal + 1;
            IF Report.Cases[CaseIdx].Ok THEN
                CasesPassedLocal := CasesPassedLocal + 1;
            ELSE
                CasesFailedLocal := CasesFailedLocal + 1;
                IF FirstFailedCase = 0 THEN FirstFailedCase := CaseIdx; END_IF;
                CASE Report.Cases[CaseIdx].FailReason OF
                    E_TestFailReason.FAIL_TIMEOUT: ReasonText := 'FAIL_TIMEOUT';
                    E_TestFailReason.FAIL_CHECK: ReasonText := 'FAIL_CHECK';
                    E_TestFailReason.FAIL_INVARIANT: ReasonText := 'FAIL_INVARIANT';
                    E_TestFailReason.FAIL_WINDOW_EARLY: ReasonText := 'FAIL_WINDOW_EARLY';
                    E_TestFailReason.FAIL_ABORTED: ReasonText := 'FAIL_ABORTED';
                ELSE ReasonText := 'FAIL_NONE';
                END_CASE;
                EntryText := CONCAT(Report.Cases[CaseIdx].Name, ' (step ');
                EntryText := CONCAT(EntryText, INT_TO_STRING(Report.Cases[CaseIdx].FailedStepId));
                EntryText := CONCAT(EntryText, '): ');
                EntryText := CONCAT(EntryText, ReasonText);
                IF Report.FailureSummary = '' THEN
                    Report.FailureSummary := EntryText;
                ELSE
                    Report.FailureSummary := CONCAT(Report.FailureSummary, ' | ');
                    Report.FailureSummary := CONCAT(Report.FailureSummary, EntryText);
                END_IF;
            END_IF;
        END_IF;
    END_FOR;

    Report.AllPassed := (TerminalState = E_TestTerminalState.TEST_TERMINAL_DONE)
                     AND (CasesTotalLocal > 0)
                     AND (CasesFailedLocal = 0);
    Report.AnyFailed := NOT Report.AllPassed;
    Report.FailedTestCase := FirstFailedCase;

    Result.TerminalState := TerminalState;
    Result.RequestedCaseId := RequestedCaseId;
    Result.ExecutedCaseId := Report.CurrentCaseId;
    Result.AllPassed := Report.AllPassed;
    Result.AnyFailed := Report.AnyFailed;
    Result.FailedCaseId := FirstFailedCase;
    IF FirstFailedCase > 0 THEN
        Result.FailedCaseName := Report.Cases[FirstFailedCase].Name;
        Result.FailReason := Report.Cases[FirstFailedCase].FailReason;
    ELSE
        Result.FailedCaseName := '';
        Result.FailReason := E_TestFailReason.FAIL_NONE;
    END_IF;
    Result.ErrorCode := ErrorCode;
    Result.ErrorMessage := ErrorMessage;
    Result.CasesTotal := CasesTotalLocal;
    Result.CasesPassed := CasesPassedLocal;
    Result.CasesFailed := CasesFailedLocal;
    Result.Duration := Report.Duration;
    Result.RunCounter := Report.RunCounter;
END_IF;

// === IMPLEMENTATION ===
StartTrig(CLK := Start);
StepVerdict := FALSE;

// 1. 🛑 Abort — niveau, priorité absolue
IF Abort THEN
    IF Busy THEN
        StepVerdict := TRUE;
        VerdictStepId := CurrentStepId;
        VerdictCaseId := CurrentCaseId;
        VerdictPassed := FALSE;
        VerdictFailReason := E_TestFailReason.FAIL_ABORTED;
        VerdictFailedCheckIdx := 0;
        VerdictDuration := StepElapsed;
        VerdictObservedBool := FALSE;
        VerdictObservedDint := 0;
        VerdictObservedReal := 0.0;
        AnyFailed := TRUE;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
    END_IF;
    Busy := FALSE;
    RunDone := TRUE;
    ActiveStimulusId := 0;
    CurrentStepId := 0;
    StepStarted := FALSE;
    RETURN;
END_IF;

// 2. 🟢 Démarrage — résolution CaseId -> 1er step, JAMAIS de FirstStepId externe
IF StartTrig.Q THEN
    ConfigError := FALSE;
    ConfigErrorStepId := 0;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;

    IF CaseId < 0 OR CaseId > 6 THEN
        ConfigError := TRUE;
        ConfigErrorStepId := CaseId;
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        CurrentStepId := 0;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;

    IF CaseId = 0 THEN
        CurrentStepId := CaseTable[1].FirstStep;
    ELSE
        CurrentStepId := CaseTable[CaseId].FirstStep;
    END_IF;

    IF CurrentStepId < 1 OR CurrentStepId > GVL_PLC_Tests_Const.MaxSteps THEN
        ConfigError := TRUE;
        ConfigErrorStepId := CurrentStepId;
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        CurrentStepId := 0;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;

    Busy := TRUE;
    RunDone := FALSE;
    AnyFailed := FALSE;
    StepStarted := FALSE;
    TransitionCount := 0;
END_IF;

IF NOT Busy THEN
    RETURN;
END_IF;

// 3. 🛡️ Garde-fou runtime (défense en profondeur — Plan valide déjà statiquement)
IF CurrentStepId < 1 OR CurrentStepId > GVL_PLC_Tests_Const.MaxSteps THEN
    Busy := FALSE;
    RunDone := TRUE;
    AnyFailed := TRUE;
    ActiveStimulusId := 0;
    ConfigError := TRUE;
    ConfigErrorStepId := CurrentStepId;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
    RETURN;
END_IF;

CurrentCaseId := StepTable[CurrentStepId].CaseId;
ActiveStimulusId := StepTable[CurrentStepId].StimulusId;

IF NOT StepStarted THEN
    StepStarted := TRUE;
    StepElapsed := T#0s;
    DwellTimer(IN := FALSE);
    StepTimer(IN := FALSE);
    FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
        CheckPassed[Jdx] := FALSE;
        CheckFailed[Jdx] := FALSE;
        InstantEvaluated[Jdx] := FALSE;
        StableTimers[Jdx](IN := FALSE);
    END_FOR;
END_IF;

StepElapsed := StepElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));

// 4. 🕐 Dwell (tempo fixe avant évaluation — T#0s = aucune, cas actuel Translation)
DwellTimer(IN := TRUE, PT := StepTable[CurrentStepId].DwellPT);
IF NOT DwellTimer.Q THEN
    RETURN;
END_IF;

// 5. ✅ Évaluation des checks — verrouillage "latch and hold" par check
//    (un check WAIT_UNTIL passé le reste jusqu'à la fin de l'étape, même si
//    la sonde redevient momentanément fausse — sémantique identique à
//    l'ancien FB_TestCheck, réécrite ici sans l'instancier)
FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
    Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
    // 🔒 CODESYS n'assure pas le court-circuit : valider AVANT tout accès.
    IF Kdx < 0 OR Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        ConfigError := TRUE;
        ConfigErrorStepId := CurrentStepId;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;
    IF Kdx > 0 THEN
        Cond := FALSE;
        ProbeIdx := CheckTable[Kdx].ProbeIdx;
        CASE CheckTable[Kdx].Kind OF
            E_TestCheckKind.BOOL_EQUAL:
                IF ProbeIdx >= 1 THEN
                    IF ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeBool THEN
                        ObsBoolArr[Jdx] := ProbeBool[ProbeIdx];
                        Cond := (ObsBoolArr[Jdx] = CheckTable[Kdx].ExpectedBool);
                    END_IF;
                END_IF;
            E_TestCheckKind.WORD_MASK_NONE:
                IF ProbeIdx >= 1 THEN
                    IF ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeDint THEN
                        ObsDintArr[Jdx] := ProbeDint[ProbeIdx];
                        Cond := ((DINT_TO_WORD(ObsDintArr[Jdx]) AND CheckTable[Kdx].Mask) = 0);
                    END_IF;
                END_IF;
            E_TestCheckKind.REAL_IN_RANGE:
                IF ProbeIdx >= 1 THEN
                    IF ProbeIdx <= GVL_PLC_Tests_Const.MaxProbeReal THEN
                        ObsRealArr[Jdx] := ProbeReal[ProbeIdx];
                        Cond := (ObsRealArr[Jdx] >= CheckTable[Kdx].RealMin AND ObsRealArr[Jdx] <= CheckTable[Kdx].RealMax);
                    END_IF;
                END_IF;
            // Kind hors périmètre (voir FB_TranslationTestPlan) -> Cond reste FALSE
        END_CASE;

        IF NOT CheckPassed[Jdx] AND NOT CheckFailed[Jdx] THEN
            CASE CheckTable[Kdx].Mode OF
                E_TestCheckMode.CHECK_INSTANT:
                    IF NOT InstantEvaluated[Jdx] THEN
                        InstantEvaluated[Jdx] := TRUE;
                        IF Cond THEN
                            CheckPassed[Jdx] := TRUE;
                        ELSE
                            CheckFailed[Jdx] := TRUE;
                        END_IF;
                    END_IF;
                E_TestCheckMode.CHECK_WAIT_UNTIL:
                    StableTimers[Jdx](IN := Cond, PT := CheckTable[Kdx].StablePT);
                    IF StableTimers[Jdx].Q THEN
                        CheckPassed[Jdx] := TRUE;
                    END_IF;
            END_CASE;
        END_IF;
    END_IF;
END_FOR;

// 6. 🧾 Agrégat des checks de l'étape
AllChecksLatched := TRUE;
AnyCheckFailedLocal := FALSE;
FailedCheckIdxLocal := 0;
FailedCheckSlotLocal := 0;
FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
    Kdx := StepTable[CurrentStepId].CheckIdx[Jdx];
    IF Kdx > 0 THEN
        IF CheckFailed[Jdx] AND NOT AnyCheckFailedLocal THEN
            AnyCheckFailedLocal := TRUE;
            FailedCheckIdxLocal := Kdx;
            FailedCheckSlotLocal := Jdx; // 🔧 REX : slot RÉEL du check fautif (pas un index figé)
        ELSIF NOT CheckPassed[Jdx] THEN
            AllChecksLatched := FALSE;
        END_IF;
    END_IF;
END_FOR;

// 7. 📸 Verdict
VerdictReached := FALSE;
IF AnyCheckFailedLocal THEN
    VerdictReached := TRUE;
    VerdictPassedLocal := FALSE;
    VerdictReasonLocal := E_TestFailReason.FAIL_CHECK;
    VerdictCheckIdxLocal := FailedCheckIdxLocal;
    // 🔒 Défense en profondeur avant indexation du snapshot fautif.
    IF FailedCheckSlotLocal >= 1 THEN
        IF FailedCheckSlotLocal <= GVL_PLC_Tests_Const.MaxChecksPerStep THEN
            VerdictObsBoolLocal := ObsBoolArr[FailedCheckSlotLocal];
            VerdictObsDintLocal := ObsDintArr[FailedCheckSlotLocal];
            VerdictObsRealLocal := ObsRealArr[FailedCheckSlotLocal];
        ELSE
            VerdictObsBoolLocal := FALSE;
            VerdictObsDintLocal := 0;
            VerdictObsRealLocal := 0.0;
        END_IF;
    ELSE
        VerdictObsBoolLocal := FALSE;
        VerdictObsDintLocal := 0;
        VerdictObsRealLocal := 0.0;
    END_IF;
ELSE
    StepTimer(IN := TRUE, PT := StepTable[CurrentStepId].TimeoutPT);
    IF AllChecksLatched THEN
        VerdictReached := TRUE;
        IF StepElapsed < StepTable[CurrentStepId].MinPT THEN
            VerdictPassedLocal := FALSE;
            VerdictReasonLocal := E_TestFailReason.FAIL_WINDOW_EARLY;
            VerdictCheckIdxLocal := 0;
        ELSE
            VerdictPassedLocal := TRUE;
            VerdictReasonLocal := E_TestFailReason.FAIL_NONE;
            VerdictCheckIdxLocal := 0;
        END_IF;
        VerdictObsBoolLocal := ObsBoolArr[1];
        VerdictObsDintLocal := ObsDintArr[1];
        VerdictObsRealLocal := ObsRealArr[1];
    ELSIF StepTimer.Q THEN
        VerdictReached := TRUE;
        VerdictPassedLocal := FALSE;
        VerdictReasonLocal := E_TestFailReason.FAIL_TIMEOUT;
        VerdictCheckIdxLocal := 0;
        VerdictObsBoolLocal := FALSE;
        VerdictObsDintLocal := 0;
        VerdictObsRealLocal := 0.0;
    END_IF;
END_IF;

IF NOT VerdictReached THEN
    RETURN; // ⏳ Toujours en attente, rien à publier ce scan
END_IF;

// 8. ➡️ Résolution de l'étape suivante — cantonnement de cas ICI (audit v1.0 C2)
IF VerdictPassedLocal THEN
    NextCandidate := StepTable[CurrentStepId].NextOnPass;
ELSIF StepTable[CurrentStepId].FailAction = E_TestFailAction.FAIL_ABORT_SUITE THEN
    NextCandidate := 0;
ELSE
    NextCandidate := StepTable[CurrentStepId].NextOnFail;
END_IF;

// 🔒 Aucun accès StepTable[0] : CODESYS peut évaluer tous les opérandes de AND.
IF NextCandidate <> 0 THEN
    IF NextCandidate < 1 OR NextCandidate > GVL_PLC_Tests_Const.MaxSteps THEN
        Busy := FALSE;
        RunDone := TRUE;
        AnyFailed := TRUE;
        ActiveStimulusId := 0;
        ConfigError := TRUE;
        ConfigErrorStepId := NextCandidate;
        TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        RETURN;
    END_IF;
    // Un cas ciblé ne déborde jamais sur le cas suivant.
    IF CaseId <> 0 THEN
        IF StepTable[NextCandidate].CaseId <> CaseId THEN
            NextCandidate := 0;
        END_IF;
    END_IF;
END_IF;

// 9. 🧾 Publication du verdict pour FB_TranslationReportFinalizer
StepVerdict := TRUE;
VerdictStepId := CurrentStepId;
VerdictCaseId := CurrentCaseId;
VerdictPassed := VerdictPassedLocal;
VerdictFailReason := VerdictReasonLocal;
VerdictFailedCheckIdx := VerdictCheckIdxLocal;
VerdictDuration := StepElapsed;
VerdictObservedBool := VerdictObsBoolLocal;
VerdictObservedDint := VerdictObsDintLocal;
VerdictObservedReal := VerdictObsRealLocal;

IF NOT VerdictPassedLocal THEN
    AnyFailed := TRUE;
END_IF;

// 10. 🔁 Transition bornée (garde runtime contre tout cycle résiduel)
TransitionCount := TransitionCount + 1;
IF TransitionCount > GVL_PLC_Tests_Const.MaxSteps THEN
    Busy := FALSE;
    RunDone := TRUE;
    AnyFailed := TRUE;
    ActiveStimulusId := 0;
    ConfigError := TRUE;
    ConfigErrorStepId := CurrentStepId;
    TerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
    RETURN;
END_IF;
CurrentStepId := NextCandidate;
StepStarted := FALSE;
IF NextCandidate = 0 THEN
    Busy := FALSE;
    RunDone := TRUE;
    ActiveStimulusId := 0; // 🛡️ Garantie structurelle — double garantie avec FB_TranslationTestCleanup
    IF AnyFailed THEN
        TerminalState := E_TestTerminalState.TEST_TERMINAL_FAILED;
    ELSE
        TerminalState := E_TestTerminalState.TEST_TERMINAL_DONE;
    END_IF;
END_IF;

// === IMPLEMENTATION ===
IF Apply THEN
    OverrideAtTremie := FALSE;
    OverrideBrakeStuckOpen := FALSE;
    OverridePhantomFreq := FALSE;
    OverrideSensorsWordActive := FALSE;
    UnderTestDirection := 0;
    UnderTestStartStop := FALSE;
    UnderTestSlowdownSensor := FALSE;
    NeutralConfirmed := TRUE;
ELSE
    NeutralConfirmed := FALSE;
END_IF;

// === IMPLEMENTATION ===
CheckTrig(CLK := CheckRequested);

IF CheckTrig.Q THEN
    IF NOT SimulationModeActive THEN
        FixturePassed := FALSE;
        FixtureFailed := TRUE;
        FailReason := 'Simulation non active (GVL_Simulation.SimulationModeActive=FALSE)';
    ELSIF NOT SimGateOk THEN
        FixturePassed := FALSE;
        FixtureFailed := TRUE;
        FailReason := 'E/S M3 recablees reelles (*IsReal) incompatibles avec le banc de test';
    ELSE
        FixturePassed := TRUE;
        FixtureFailed := FALSE;
        FailReason := '';
    END_IF;
END_IF;

// === IMPLEMENTATION ===

// 1. 📋 CONSTRUCTION (une seule fois, données pures)
IF NOT Built THEN

    // --- Cas de tests ---
    CaseTable[1].Name := 'TC-T1 Fin de course extreme';
