    StepTable[StepTc06Teardown].FailAction := E_TestFailAction.FAIL_CONTINUE;

    // 2. 🔒 VALIDATION — jouée UNE SEULE FOIS ici (les tables sont figées après
    //    construction, revalider chaque scan serait un coût inutile — 128 étapes max)
    ConfigError := FALSE;
ConfigErrorStepId := 0;
ConfigErrorCheckIdx := 0;
ConfigErrorMessage := '';

FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
    IF StepTable[Idx].CaseId > 0 AND NOT ConfigError THEN
        IF StepTable[Idx].NextOnPass < 0 OR StepTable[Idx].NextOnPass > GVL_PLC_Tests_Const.MaxSteps THEN
            ConfigError := TRUE;
            ConfigErrorStepId := Idx;
            ConfigErrorMessage := 'NextOnPass hors limites';
        ELSIF StepTable[Idx].NextOnFail < 0 OR StepTable[Idx].NextOnFail > GVL_PLC_Tests_Const.MaxSteps THEN
            ConfigError := TRUE;
            ConfigErrorStepId := Idx;
            ConfigErrorMessage := 'NextOnFail hors limites';
        ELSIF StepTable[Idx].TimeoutPT <= T#0s THEN
            ConfigError := TRUE;
            ConfigErrorStepId := Idx;
            ConfigErrorMessage := 'TimeoutPT requis (> 0s)';
        ELSE
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                Kdx := StepTable[Idx].CheckIdx[Jdx];
                IF Kdx > 0 AND NOT ConfigError THEN
                    IF Kdx > GVL_PLC_Tests_Const.MaxChecks THEN
                        ConfigError := TRUE;
                        ConfigErrorStepId := Idx;
                        ConfigErrorCheckIdx := Kdx;
                        ConfigErrorMessage := 'CheckIdx hors limites';
                    ELSE
                        // 📌 Périmètre restreint : seuls ces 3 Kind / 2 Mode sont supportés
                        CASE CheckTable[Kdx].Kind OF
                            E_TestCheckKind.BOOL_EQUAL:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeBool THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                    ConfigErrorMessage := 'ProbeIdx BOOL hors limites';
                                END_IF;
                            E_TestCheckKind.WORD_MASK_NONE:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeDint THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                    ConfigErrorMessage := 'ProbeIdx DINT hors limites';
                                END_IF;
                            E_TestCheckKind.REAL_IN_RANGE:
                                IF CheckTable[Kdx].ProbeIdx < 1 OR CheckTable[Kdx].ProbeIdx > GVL_PLC_Tests_Const.MaxProbeReal THEN
                                    ConfigError := TRUE;
                                    ConfigErrorStepId := Idx;
                                    ConfigErrorCheckIdx := Kdx;
                                    ConfigErrorMessage := 'ProbeIdx REAL hors limites';
                                END_IF;
                        ELSE
                            ConfigError := TRUE;
                            ConfigErrorStepId := Idx;
                            ConfigErrorCheckIdx := Kdx;
                            ConfigErrorMessage := 'Kind non supporte par ce moteur dedie';
                        END_CASE;

                        IF NOT ConfigError THEN
                            IF CheckTable[Kdx].Mode <> E_TestCheckMode.CHECK_WAIT_UNTIL AND CheckTable[Kdx].Mode <> E_TestCheckMode.CHECK_INSTANT THEN
                                ConfigError := TRUE;
                                ConfigErrorStepId := Idx;
                                ConfigErrorCheckIdx := Kdx;
                                ConfigErrorMessage := 'Mode non supporte par ce moteur dedie';
                            END_IF;
                        END_IF;
                    END_IF;
                END_IF;
            END_FOR;
        END_IF;
    END_IF;
END_FOR;

// Cohérence CaseTable[1..6] <-> StepTable (chaque case doit démarrer sur SON setup)
IF NOT ConfigError THEN
    FOR Idx := 1 TO 6 DO
        IF CaseTable[Idx].FirstStep < 1 OR CaseTable[Idx].FirstStep > GVL_PLC_Tests_Const.MaxSteps THEN
            ConfigError := TRUE;
            ConfigErrorStepId := CaseTable[Idx].FirstStep;
            ConfigErrorMessage := 'CaseTable.FirstStep hors limites';
        ELSIF StepTable[CaseTable[Idx].FirstStep].CaseId <> Idx THEN
            ConfigError := TRUE;
            ConfigErrorStepId := CaseTable[Idx].FirstStep;
            ConfigErrorMessage := 'CaseTable.FirstStep ne pointe pas vers SON case';
        END_IF;
    END_FOR;
END_IF;

// 🔒 Validation structurelle complémentaire : stimulus connu, étape utile,
// cibles configurées et changement de case réservé au teardown (Pass=Fail).
IF NOT ConfigError THEN
    FOR Idx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
        IF StepTable[Idx].CaseId > 0 AND NOT ConfigError THEN
            IF StepTable[Idx].StimulusId < 0 OR StepTable[Idx].StimulusId > 13 THEN
                ConfigError := TRUE; ConfigErrorStepId := Idx;
                ConfigErrorMessage := 'StimulusId hors plage Translation 0..13';
            END_IF;
            HasCheck := FALSE;
            FOR Jdx := 1 TO GVL_PLC_Tests_Const.MaxChecksPerStep DO
                HasCheck := HasCheck OR (StepTable[Idx].CheckIdx[Jdx] > 0);
            END_FOR;
            IF NOT HasCheck AND StepTable[Idx].DwellPT <= T#0s THEN
                ConfigError := TRUE; ConfigErrorStepId := Idx;
                ConfigErrorMessage := 'Etape sans check ni dwell explicite';
            END_IF;
            // 🔒 Branches imbriquées : aucun StepTable[0], sans supposer AND court-circuité.
            IF StepTable[Idx].NextOnPass > 0 THEN
                Kdx := StepTable[Idx].NextOnPass;
                IF StepTable[Kdx].CaseId = 0 THEN
                    ConfigError := TRUE; ConfigErrorStepId := Idx;
                    ConfigErrorMessage := 'NextOnPass vise une etape non configuree';
                END_IF;
            END_IF;
            IF StepTable[Idx].NextOnFail > 0 AND NOT ConfigError THEN
                Kdx := StepTable[Idx].NextOnFail;
                IF StepTable[Kdx].CaseId = 0 THEN
                    ConfigError := TRUE; ConfigErrorStepId := Idx;
                    ConfigErrorMessage := 'NextOnFail vise une etape non configuree';
                ELSIF StepTable[Kdx].CaseId <> StepTable[Idx].CaseId THEN
                    IF StepTable[Idx].NextOnPass <> StepTable[Idx].NextOnFail THEN
                        ConfigError := TRUE; ConfigErrorStepId := Idx;
                        ConfigErrorMessage := 'Echec quitte le case sans teardown commun';
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

// 🔁 Chaque chemin nominal Case→fin doit sortir en <= MaxSteps transitions.
IF NOT ConfigError THEN
    FOR Idx := 1 TO 6 DO
        WalkStep := CaseTable[Idx].FirstStep;
        FOR WalkIdx := 1 TO GVL_PLC_Tests_Const.MaxSteps DO
            IF WalkStep = 0 THEN EXIT; END_IF;
            // 🔒 Valider la borne avant de déréférencer WalkStep.
            IF WalkStep < 1 OR WalkStep > GVL_PLC_Tests_Const.MaxSteps THEN
                ConfigError := TRUE; ConfigErrorStepId := WalkStep;
                ConfigErrorMessage := 'Chemin nominal hors limites';
                EXIT;
            END_IF;
            IF StepTable[WalkStep].CaseId = 0 THEN
                ConfigError := TRUE; ConfigErrorStepId := WalkStep;
                ConfigErrorMessage := 'Chemin nominal non configure';
                EXIT;
            END_IF;
            WalkStep := StepTable[WalkStep].NextOnPass;
        END_FOR;
        IF WalkStep <> 0 AND NOT ConfigError THEN
            ConfigError := TRUE; ConfigErrorStepId := WalkStep;
            ConfigErrorMessage := 'Cycle nominal ou chemin sans sortie';
        END_IF;
    END_FOR;
END_IF;

    Ready := NOT ConfigError;
    Built := TRUE;
END_IF;

// === IMPLEMENTATION ===
StartTrig(CLK := Start);
StartRejected := FALSE;
ExecutorStart := FALSE;
ExecutorAbort := FALSE;
RunStartPulse := FALSE;
FinalizePulse := FALSE;
CleanupRequest := (RuntimeState = RuntimeCleanup)
               OR (RuntimeState = RuntimeWaitNeutral)
               OR (RuntimeState = RuntimeVerify);

// 🎮 Un Start pendant un run/cleanup est refusé sans modifier le run actif.
IF StartTrig.Q AND RuntimeState <> RuntimeIdle AND RuntimeState <> RuntimeTerminal THEN
    StartRejected := TRUE;
END_IF;

// 🚪 Fixture appelée CHAQUE scan : son R_TRIG interne est ainsi toujours réarmé.
instFixture(CheckRequested := StartTrig.Q,
            SimulationModeActive := SimulationModeActive,
            SimGateOk := SimGateOk);

// 🟢 Nouveau run accepté depuis IDLE ou TERMINAL.
IF StartTrig.Q AND (RuntimeState = RuntimeIdle OR RuntimeState = RuntimeTerminal) THEN
    RunStartPulse := TRUE;
    Done := FALSE;
    SuiteElapsed := T#0s;
    NeutralWaitScans := 0;
    CleanupElapsedScans := 0;
    PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_NONE;
    PendingErrorCode := 0;
    PendingErrorMessage := '';

    IF PlanConfigError THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1002;
        PendingErrorMessage := CONCAT('Table invalide : ', PlanConfigErrorMessage);
        RuntimeState := RuntimeCleanup;
    ELSIF CaseId < 0 OR CaseId > 6 THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1001;
        PendingErrorMessage := 'CaseId invalide (attendu 0..6)';
        RuntimeState := RuntimeCleanup;
    ELSIF instFixture.FixtureFailed THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_PRECONDITION_FAILED;
        PendingErrorCode := 1010;
        PendingErrorMessage := CONCAT('PRECONDITION_FAILED : ', instFixture.FailReason);
        RuntimeState := RuntimeCleanup;
    ELSE
        ExecutorStart := TRUE;
        RuntimeState := RuntimeRun;
    END_IF;
END_IF;

// 🛡️ Causes de sortie du RUN : watchdog > gate perdue > abort opérateur.
IF RuntimeState = RuntimeRun THEN
    SuiteElapsed := SuiteElapsed + UDINT_TO_TIME(INT_TO_UDINT(GVL_PLC_Tests_Const.TaskCycleMs));
    IF SuiteElapsed >= DINT_TO_TIME(WatchdogLimitMs) THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_WATCHDOG_TIMEOUT;
        PendingErrorCode := 1020;
        PendingErrorMessage := 'Watchdog suite Translation expire';
    ELSIF NOT SimulationModeActive OR NOT SimGateOk THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_PRECONDITION_FAILED;
        PendingErrorCode := 1011;
        PendingErrorMessage := 'Gate Translation perdue pendant le run';
    ELSIF Abort THEN
        ExecutorAbort := TRUE;
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_ABORTED;
        PendingErrorCode := 1030;
        PendingErrorMessage := 'Abandon operateur';
    END_IF;
END_IF;

// 🪜 L'exécuteur ne possède que les étapes, jamais le terminal public.
instExecutor(
    Start := ExecutorStart,
    Abort := ExecutorAbort,
    CaseId := CaseId,
    StepTable := StepTable,
    CheckTable := CheckTable,
    CaseTable := CaseTable,
    ProbeBool := ProbeBool,
    ProbeDint := ProbeDint,
    ProbeReal := ProbeReal
);

IF RuntimeState = RuntimeRun AND instExecutor.RunDone THEN
    IF PendingTerminalState = E_TestTerminalState.TEST_TERMINAL_NONE THEN
        PendingTerminalState := instExecutor.TerminalState;
        IF instExecutor.ConfigError THEN
            PendingErrorCode := 1003;
            PendingErrorMessage := 'Garde-fou runtime : transition invalide';
        END_IF;
    END_IF;
    RuntimeState := RuntimeCleanup;
    NeutralWaitScans := 0;
END_IF;

// 🧹 Tous les chemins imposent au moins deux scans complets au neutre.
IF RuntimeState = RuntimeCleanup THEN
    CleanupRequest := TRUE;
    NeutralWaitScans := 0;
    CleanupElapsedScans := 0;
    RuntimeState := RuntimeWaitNeutral;
ELSIF RuntimeState = RuntimeWaitNeutral THEN
    CleanupRequest := TRUE;
    NeutralWaitScans := NeutralWaitScans + 1;
    CleanupElapsedScans := CleanupElapsedScans + 1;
    IF NeutralWaitScans >= 2 THEN
        RuntimeState := RuntimeVerify;
    END_IF;
ELSIF RuntimeState = RuntimeVerify THEN
    CleanupRequest := TRUE;
    CleanupElapsedScans := CleanupElapsedScans + 1;
    IF NeutralConfirmed THEN
        FinalizePulse := TRUE;
        RuntimeState := RuntimeTerminal;
        Done := TRUE;
    ELSIF CleanupElapsedScans >= CleanupTimeoutScans THEN
        PendingTerminalState := E_TestTerminalState.TEST_TERMINAL_CONFIG_ERROR;
        PendingErrorCode := 1040;
        PendingErrorMessage := 'Cleanup Translation non confirme';
        FinalizePulse := TRUE;
        RuntimeState := RuntimeTerminal;
        Done := TRUE;
    END_IF;
END_IF;

// 📊 Le rapport consomme directement chaque verdict, même consécutif.
instFinalizer(
    RunStart := RunStartPulse,
    RequestedCaseId := CaseId,
    Busy := (RuntimeState = RuntimeRun),
    StepVerdict := instExecutor.StepVerdict,
    StepId := instExecutor.VerdictStepId,
    StepCaseId := instExecutor.VerdictCaseId,
    StepPassed := instExecutor.VerdictPassed,
    StepFailReason := instExecutor.VerdictFailReason,
    StepFailedCheckIdx := instExecutor.VerdictFailedCheckIdx,
    StepDuration := instExecutor.VerdictDuration,
    StepObservedBool := instExecutor.VerdictObservedBool,
    StepObservedDint := instExecutor.VerdictObservedDint,
    StepObservedReal := instExecutor.VerdictObservedReal,
    Finalize := FinalizePulse,
    TerminalState := PendingTerminalState,
    ErrorCode := PendingErrorCode,
    ErrorMessage := PendingErrorMessage,
    StepTable := StepTable,
    CaseTable := CaseTable,
    Report := Report,
    Result := Result
);

// 📤 Publication : Busy inclut cleanup ; aucun stimulus métier hors RUN.
Busy := (RuntimeState = RuntimeRun)
     OR (RuntimeState = RuntimeCleanup)
     OR (RuntimeState = RuntimeWaitNeutral)
     OR (RuntimeState = RuntimeVerify);
IF RuntimeState = RuntimeRun THEN
    ActiveStimulusId := instExecutor.ActiveStimulusId;
ELSE
    ActiveStimulusId := 0;
END_IF;
StepElapsed := instExecutor.StepElapsed;
TerminalState := Result.TerminalState;
AnyFailed := Result.AnyFailed;
ConfigError := PlanConfigError OR instExecutor.ConfigError;
IF PlanConfigError THEN
    ConfigErrorStepId := PlanConfigErrorStepId;
    ConfigErrorCheckIdx := PlanConfigErrorCheckIdx;
ELSE
    ConfigErrorStepId := instExecutor.ConfigErrorStepId;
    ConfigErrorCheckIdx := 0;
END_IF;
ErrorCode := Result.ErrorCode;
ErrorMessage := Result.ErrorMessage;

// === IMPLEMENTATION ===

// 1. 🛡️ GATE Niveau 1/2 — calculé en continu (lu par le manager Niveau 3, même hors Busy)
// Refuse si un des équipements M3 est déjà recâblé réel.
SimGateOk := NOT GVL_Simulation.SensorTranslationPositionIsReal
         AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal
         AND NOT GVL_Simulation.BusVariateurM3IsReal;

// 2. 📋 PLAN — construction (une fois) + validation ; les index de sondes
//    sont transmis ICI, jamais relus depuis l'instance.
instPlan(
    SigHealthyIdle := SigHealthyIdle, SigLimitSwitchError := SigLimitSwitchError,
    SigPowerCutOff := SigPowerCutOff, SigErrorIdT1NoParasite := SigErrorIdT1NoParasite,
    SigMecaBError := SigMecaBError, SigErrorIdT2NoParasite := SigErrorIdT2NoParasite,
    SigMecaAError := SigMecaAError, SigErrorIdT3NoParasite := SigErrorIdT3NoParasite,
    SigDecoderIncoherent := SigDecoderIncoherent, SigLimitFwd := SigLimitFwd,
    SigLimitRev := SigLimitRev, SigSensorIncoherentErr := SigSensorIncoherentErr,
    SigErrorIdT5NoParasite := SigErrorIdT5NoParasite, SigSlowdownFreqHz := SigSlowdownFreqHz,
    StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable
);

// 3. 📥 ACQUIRE — sondes réelles + instance isolée TC-T6 (pilotée par le
//    stimulus décidé au scan précédent, cf. §5 STIMULI)
ProbeBool[SigHealthyIdle]      := NOT PRG_03_Safety.instSafetyTranslationM3.Error;
ProbeBool[SigLimitSwitchError] := PRG_03_Safety.instSafetyTranslationM3.ErrorLimitSwitch;
ProbeBool[SigPowerCutOff]      := PRG_03_Safety.instSafetyTranslationM3.PowerCutOff;
ProbeDint[SigErrorIdT1NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigMecaBError]       := PRG_03_Safety.instSafetyTranslationM3.ErrorMecaB;
ProbeDint[SigErrorIdT2NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigMecaAError]       := PRG_03_Safety.instSafetyTranslationM3.ErrorMecaA;
ProbeDint[SigErrorIdT3NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);
ProbeBool[SigDecoderIncoherent]   := PRG_00_Inputs.instPositionDecoder.Incoherent;
ProbeBool[SigLimitFwd]            := PRG_00_Inputs.instPositionDecoder.LimitSwitchFwd;
ProbeBool[SigLimitRev]            := PRG_00_Inputs.instPositionDecoder.LimitSwitchRev;
ProbeBool[SigSensorIncoherentErr] := PRG_03_Safety.instSafetyTranslationM3.ErrorSensorIncoherent;
ProbeDint[SigErrorIdT5NoParasite] := WORD_TO_DINT(PRG_03_Safety.instSafetyTranslationM3.ErrorId);

instTranslationUnderTest(
    Enable := TRUE, Reset := ResetFaults, EmergencyStopOk := TRUE, Mode := E_Mode.MAINT_N1,
    StartStop := UnderTestStartStop, SafeStop := FALSE,
    Direction := UnderTestDirection, SpeedRefPct := 100.0,
    PositionSensorTarget := FALSE, SlowdownSensor := UnderTestSlowdownSensor,
    LimitSwitchFwd := FALSE, LimitSwitchRev := FALSE,
    DriveStatusWord := 0, DriveActualFreqHz := 0.0,
    BypassContactorCheck := TRUE, BrakeFeedback := FALSE
);
ProbeReal[SigSlowdownFreqHz] := instTranslationUnderTest.DriveFreqRefHz;

// 4. ♻️ RUNTIME — cycle de vie complet (Fixture -> Executor -> Finalize)
instRuntime(
    Start := Start, Abort := Abort, CaseId := CaseId,
    PlanConfigError := instPlan.ConfigError,
    PlanConfigErrorStepId := instPlan.ConfigErrorStepId,
    PlanConfigErrorCheckIdx := instPlan.ConfigErrorCheckIdx,
    PlanConfigErrorMessage := instPlan.ConfigErrorMessage,
    SimulationModeActive := GVL_Simulation.SimulationModeActive,
    SimGateOk := SimGateOk,
    NeutralConfirmed := NeutralConfirmedPrevious,
    StepTable := StepTable, CheckTable := CheckTable, CaseTable := CaseTable,
    ProbeBool := ProbeBool, ProbeDint := ProbeDint, ProbeReal := ProbeReal,
    Report := Report, Result := Result,
    Busy => Busy, Done => Done, AnyFailed => AnyFailed,
    ActiveStimulusId => ActiveStimulusId, StepElapsed => StepElapsed,
    TerminalState => TerminalState, ConfigError => ConfigError,
    ConfigErrorStepId => ConfigErrorStepId, ConfigErrorCheckIdx => ConfigErrorCheckIdx,
    ErrorCode => ErrorCode, ErrorMessage => ErrorMessage
);

// 5. ⚡ STIMULI — vecteur complet : neutre d'abord, surcharge ensuite.
//    Aucun champ ne dépend de la branche ou du scan précédent.
GVL_PLC_Tests.OverrideM3AtTremie := FALSE;
GVL_PLC_Tests.OverrideM3BrakeStuckOpen := FALSE;
GVL_PLC_Tests.OverrideM3PhantomFreq := FALSE;
GVL_PLC_Tests.OverrideM3SensorsWordActive := FALSE;
GVL_PLC_Tests.OverrideM3SensorsWord := 0;
UnderTestDirection := 0;
UnderTestStartStop := FALSE;
UnderTestSlowdownSensor := FALSE;
ResetFaults := FALSE;

IF NOT instRuntime.CleanupRequest THEN
    CASE ActiveStimulusId OF
        1: ResetFaults := TRUE; // Setup/teardown : reset sur front externe conditionné
        2: GVL_PLC_Tests.OverrideM3AtTremie := TRUE;
        3: GVL_PLC_Tests.OverrideM3BrakeStuckOpen := TRUE;
        4: GVL_PLC_Tests.OverrideM3PhantomFreq := TRUE;
        5: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#11111;
        6: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#01111;
        7: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00111;
        8: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00011;
        9: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00001;
        10: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#00000;
        11: GVL_PLC_Tests.OverrideM3SensorsWordActive := TRUE; GVL_PLC_Tests.OverrideM3SensorsWord := 2#10101;
        12: UnderTestDirection := 1; UnderTestStartStop := TRUE;
        13: UnderTestDirection := 1; UnderTestStartStop := TRUE; UnderTestSlowdownSensor := TRUE;
    END_CASE;
END_IF;

// 🧹 Confirmation calculée APRÈS écriture du vecteur neutre ; consommée
// par le runtime au scan suivant pour garantir la propagation cyclique.
instCleanup(Apply := instRuntime.CleanupRequest);
NeutralConfirmedPrevious := instCleanup.NeutralConfirmed
    AND NOT GVL_PLC_Tests.OverrideM3AtTremie
    AND NOT GVL_PLC_Tests.OverrideM3BrakeStuckOpen
    AND NOT GVL_PLC_Tests.OverrideM3PhantomFreq
    AND NOT GVL_PLC_Tests.OverrideM3SensorsWordActive
    AND (GVL_PLC_Tests.OverrideM3SensorsWord = 0)
    AND (UnderTestDirection = 0)
    AND NOT UnderTestStartStop
    AND NOT UnderTestSlowdownSensor
    AND NOT ResetFaults;

// Recopie IHM/métier — reset partagé avec la suite Safety (même domaine
// "sécurité/métier", voir PRG_09_Supervision.FaultMachineReset_IHM), sans
// conflit car les suites s'exécutent toujours de façon mutuellement exclusive
// (FB_PLC_Tests_Management n'active qu'une suite à la fois).
IF Busy THEN
    GVL_IHM.Modes.Cmd.BtnFaultReset := ResetFaults;
END_IF;

// === IMPLEMENTATION ===

// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchFwd := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchRev := (NOT Incoherent) AND (SensorsWord = 2#00000);

IF NOT Enable OR NOT EmergencyStopOk THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    SpeedStep(Enable := FALSE, SpeedRefPct := 0.0, Table := SpeedStepTable, HystMargin := SpeedStepHystMargin);
    StepNumber := SpeedStep.StepNumber;
    Brake(Enable := FALSE, Reset := FALSE, MovementRequested := FALSE, ContactorFeedback := BrakeFeedback,
          DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
          DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout);
    BrakeCmd := Brake.BrakeCmd;
    BrakeContactorCheck := Brake.ContactorCheck;
    CommandedDirection := 0;
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    SpeedRamp(Target := 0.0, AccelRate := CfgRampAccelRate, DecelRate := CfgRampDecelFastRate, CycleTimeS := CycleTimeCalc.CycleTimeS);
    State := E_State.DISABLED;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

// 🧹 Initialisation au premier scan : purge des résidus RAM d'un Online Change / Warm Start et évitement des alarmes transitoires
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
CycleTimeCalc(DefaultValueS := 0.010);

ResetEdge(CLK := Reset);

DirectionChangePending := (Direction <> CommandedDirection) AND (CommandedDirection <> 0);

// 🆕 Mou de câble (ForbidDescent) et Fin de course haut (ForbidAscent) intégrés à une VRAIE
// décélération rapide (comme SafeStop) :
// - ForbidDescent est INHIBÉ si CommandedDirection = 1 (montée libre pour reprendre le mou)
// - ForbidAscent est INHIBÉ si CommandedDirection = -1 (descente libre pour dégager le câble)
EffectiveSafeStop := SafeStop 
                     OR (ForbidDescent AND (CommandedDirection <> 1))
                     OR (ForbidAscent AND (CommandedDirection <> -1));

RampTargetPct := 0.0;
IF NOT EffectiveSafeStop AND StartStop AND NOT DirectionChangePending THEN
    RampTargetPct := ABS(SpeedRefPct);

    // 🆕 RALENTISSEMENT AUTOMATIQUE SUR BORDURES (si référencé et non suspect)
    // Permet d'approcher les fins de course / limites en vitesse lente de façon progressive
    IF Homed AND NOT HomingSuspect THEN
        // En montée (engagement ou mouvement actif), ralentit à l'approche de la limite haute
        IF ((CommandedDirection = 1) OR (Direction = 1)) AND (CablePosM >= (TopLimitM - CfgSlowdownDistanceM)) THEN
            RampTargetPct := MIN(RampTargetPct, CfgSlowSpeedPct);
        END_IF;

        // En descente (engagement ou mouvement actif), ralentit à l'approche de la limite basse
        IF ((CommandedDirection = -1) OR (Direction = -1)) AND (CablePosM <= (BottomLimitM + CfgSlowdownDistanceM)) THEN
            RampTargetPct := MIN(RampTargetPct, CfgSlowSpeedPct);
        END_IF;
    END_IF;
END_IF;

SpeedRamp(Target := RampTargetPct,
          AccelRate := CfgRampAccelRate,
          DecelRate := SEL(EffectiveSafeStop, CfgRampDecelNormalRate, CfgRampDecelFastRate),
          CycleTimeS := CycleTimeCalc.CycleTimeS);

IF Direction <> CommandedDirection THEN
    IF CommandedDirection = 0 AND Direction <> 0 THEN
        CommandedDirection := Direction;
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    ELSIF ABS(SpeedRamp.Current) < 0.1 THEN
        DirectionChangeDelay(IN := TRUE, PT := DirectionInterlockDelay);
        IF DirectionChangeDelay.Q THEN
            CommandedDirection := Direction;
            DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
        END_IF;
    ELSE
        DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
    END_IF;
ELSE
    DirectionChangeDelay(IN := FALSE, PT := DirectionInterlockDelay);
END_IF;

// 🆕 Plafond dynamique de palier (CfgMaxStepDescente en descente, Palier 1 si non référencé ou douteux,
// Palier 1 en approche homing, MaxStepAscent en montée normale — 🔧 REX 2026-07-15 (9))
IF NOT Homed OR HomingSuspect THEN
    // 🆕 Bypass.Global = TRUE → pas de limitation, on applique la règle normale
    IF BypassGlobal THEN
        ActiveMaxStep := SEL(CommandedDirection = -1, MaxStepAscent, CfgMaxStepDescente);
    ELSE
        ActiveMaxStep := 1;
    END_IF;
ELSIF CommandedDirection = -1 THEN
    ActiveMaxStep := CfgMaxStepDescente;
ELSIF (CommandedDirection = 1) AND HomingApproachActive THEN
    ActiveMaxStep := 1;
ELSIF CommandedDirection = 1 THEN
    ActiveMaxStep := MaxStepAscent;
ELSE
    ActiveMaxStep := 5;
END_IF;

SpeedStep(Enable := (ABS(SpeedRamp.Current) > 0.1), SpeedRefPct := ABS(SpeedRamp.Current),
          Table := SpeedStepTable, HystMargin := SpeedStepHystMargin,
          MaxStepNumber := ActiveMaxStep,
          MeasuredSpeedBand := MeasuredSpeedBand,
          SpeedGuardEnable := SpeedGuardEnable,
          SpeedGuardReady := SpeedGuardReady);
StepNumber := SpeedStep.StepNumber;
SpeedGuardLimited := SpeedStep.SpeedGuardLimited;
Contactor1 := SpeedStep.Contactor1;
Contactor2 := SpeedStep.Contactor2;
Contactor3 := SpeedStep.Contactor3;
Contactor4 := SpeedStep.Contactor4;

RelayFwd := (CommandedDirection = 1) AND (StepNumber > 0);
RelayRev := (CommandedDirection = -1) AND (StepNumber > 0);

IF ForbidDescent THEN
    RelayRev := FALSE;
END_IF;

IF ForbidAscent THEN
    RelayFwd := FALSE;
END_IF;

Brake(Enable := TRUE, Reset := Reset, MovementRequested := (RelayFwd OR RelayRev),
      ContactorFeedback := BrakeFeedback,
      DelayContactClose := BrakeDelayContactClose, DelayMagnetise := BrakeDelayMagnetise,
      DelayMotorDecel := BrakeDelayMotorDecel, FeedbackTimeout := BrakeFeedbackTimeout,
      BypassContactorCheck := BypassContactorCheck);
BrakeCmd := Brake.BrakeCmd;
BrakeContactorCheck := Brake.ContactorCheck;

// 🔧 REX 2026-07-07 : vérification UNIQUEMENT à l'arrêt commandé (plus de détail par sens —
// voir bandeau en-tête). AllContactorsCommandedOff = tout ce que FB_Winch commande est à FALSE.
AllContactorsCommandedOff := (NOT RelayFwd) AND (NOT RelayRev)
                             AND (NOT Contactor1) AND (NOT Contactor2) AND (NOT Contactor3) AND (NOT Contactor4);

ContactorsCheck.Command  := NOT AllContactorsCommandedOff;   // TRUE = au moins un contacteur commandé
ContactorsCheck.Feedback := NOT FwdRevSpeedFeedbackOff;      // TRUE = au moins un contacteur pas retombé
TonContactorsDropped(IN := AllContactorsCommandedOff AND NOT FwdRevSpeedFeedbackOff, PT := ContactorFeedbackTimeout);
IF TonContactorsDropped.Q THEN
    ContactorsCheck.StuckClosed := TRUE;
ELSIF ResetEdge.Q THEN
    ContactorsCheck.StuckClosed := FALSE;
END_IF;
ContactorsCheck.StuckOpen := FALSE; // Non applicable avec ce retour (pas de confirmation par sens, voir bandeau)

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et saute toute la logique d'erreur
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

IF NOT BypassGlobal THEN
    IF Brake.Error THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🧪 Simulation (GVL_Simulation.SensorMxContactorFeedbackIsReal, passé par l'appelant via
// BypassContactorCheck) — sans contacteurs réels câblés/cohérents en essai, StuckClosed
// se déclenche à tort et bloque RelayFwd/RelayRev (voir Error plus bas).
// 🔧 REX 2026-07-07 : bit2 (ex-RevContactorCheck) libre/inutilisé, fusionné dans bit1.
IF NOT BypassContactorCheck THEN
    IF ContactorsCheck.StuckClosed THEN
        ErrorId := ErrorId OR 16#0002;
    ELSIF ResetEdge.Q THEN
        ErrorId := ErrorId AND 16#FFFD;
    END_IF;
ELSE
    ErrorId := ErrorId AND 16#FFFD;   // Bypass actif : efface/maintient à 0 le bit1
END_IF;

// 🪜 WINCH-CORE-01 : remonte le défaut de configuration interne de FB_SpeedStep.
// Le bit reste mémorisé après correction de la table ; cause disparue + nouveau front Reset
// sont obligatoires avant de rendre le treuil disponible, conformément à Partie 3 §5.
IF SpeedStep.ConfigError THEN
    ErrorId := ErrorId OR 16#0004;    // bit2 = table/plafond/hystérésis invalide
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFB;
END_IF;

END_IF; // fin IF NOT BypassGlobal

Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

IF (NOT StartStop OR EffectiveSafeStop OR DirectionChangePending) AND ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.STOPPING;
ELSIF ABS(SpeedRamp.Current) > 0.1 THEN
    State := E_State.BUSY;
ELSE
    State := E_State.READY;
END_IF;

Busy := (State = E_State.BUSY) OR (State = E_State.STOPPING);
Done := FALSE;

IF Error THEN
    RelayFwd := FALSE;
    RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE;
END_IF;

// 🛑 1. GATE — aucune estimation lorsque le bloc est désactivé ou l'AU absent.
IF NOT Enable OR NOT EmergencyStopOk THEN
    Ready := FALSE;
    Busy := FALSE;
    Done := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    State := E_State.DISABLED;
    SpeedBand := 0;
    EstimatedLoadPct := 0.0;
    Configured := FALSE;
    Ascending := FALSE;
    HasPreviousBand := FALSE;
    RETURN;
END_IF;

Ready := TRUE;
Busy := FALSE;
Done := FALSE;
State := E_State.READY;
ResetEdge(CLK := Reset);
Configured := LoadTable.IsConfigured;
// 📈 WINCH-CORE-01 : l'estimation de charge n'a de sens qu'en montée.
// La bande de vitesse reste calculée pour le diagnostic et le garde-fou de palier,
// mais EstimatedLoadPct est forcée à zéro à l'arrêt et en descente.
Ascending := (MeasuredSpeedSignedMps > 0.0);

// 📏 2. CLASSEMENT DE LA VITESSE — hystérésis autour des 4 frontières.
IF (MeasuredSpeedMps < 0.0) OR (SpeedConfig.MaxMeasuredSpeedMps <= 0.0) THEN
    ErrorId := ErrorId OR 16#0001;
    SpeedBand := 0;
ELSIF NOT HasPreviousBand THEN
    IF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[1] THEN
        PreviousSpeedBand := 1;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[2] THEN
        PreviousSpeedBand := 2;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[3] THEN
        PreviousSpeedBand := 3;
    ELSIF MeasuredSpeedMps <= SpeedConfig.SpeedBandMaxMps[4] THEN
        PreviousSpeedBand := 4;
    ELSE
        PreviousSpeedBand := 5;
    END_IF;
    HasPreviousBand := TRUE;
    SpeedBand := PreviousSpeedBand;
ELSE
    // 🔒 Valider l'état mémorisé avant toute indexation dynamique.
    IF PreviousSpeedBand < 1 OR PreviousSpeedBand > 5 THEN
        PreviousSpeedBand := 1;
        ErrorId := ErrorId OR 16#0001;
    END_IF;

    // CODESYS ne garantit pas le court-circuit des expressions AND :
    // chaque borne est donc testée dans une branche séparée avant accès.
    IF PreviousSpeedBand < 5 THEN
        IF MeasuredSpeedMps > (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand]
                               + SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand + 1;
        END_IF;
    END_IF;
    IF PreviousSpeedBand > 1 THEN
        IF MeasuredSpeedMps < (SpeedConfig.SpeedBandMaxMps[PreviousSpeedBand - 1]
                               - SpeedConfig.SpeedBandHysteresisMps) THEN
            PreviousSpeedBand := PreviousSpeedBand - 1;
        END_IF;
    END_IF;
    SpeedBand := PreviousSpeedBand;
END_IF;

// 📊 3. LECTURE TABLE — bornes séparées avant l'accès au tableau 5x5.
EstimatedLoadPct := 0.0;
IF Configured THEN
    IF Ascending THEN
        IF ActiveSpeedStep >= 1 THEN
            IF ActiveSpeedStep <= 5 THEN
                IF SpeedBand >= 1 THEN
                    IF SpeedBand <= 5 THEN
                        SelectedLoadPct := LoadTable.LoadPctByStepAndSpeedBand[ActiveSpeedStep][SpeedBand];
                        IF (SelectedLoadPct < 0.0) OR (SelectedLoadPct > 100.0) THEN
                            ErrorId := ErrorId OR 16#0001;
                        ELSE
                            EstimatedLoadPct := SelectedLoadPct;
                        END_IF;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 📤 4. SORTIES D'ÉTAT ET ACQUITTEMENT.
IF ResetEdge.Q AND (ErrorId <> 16#0000) AND (MeasuredSpeedMps >= 0.0) THEN
    ErrorId := 16#0000;
END_IF;
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_WinchSync) ===

// 🛑 1. GATE
IF NOT Enable OR NOT EmergencyStopOk THEN
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    State := E_State.DISABLED;
    DeltaPosM := 0.0;
    SyncActive := FALSE;
    SyncWarn := FALSE;
    Error := FALSE;
    ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
State := E_State.READY;

// 🔑 2. RESET FRONT
ResetEdge(CLK := Reset);

// 🌐 BYPASS GLOBAL : force ErrorId = 0 et ignore toute la surveillance synchro
IF BypassGlobal THEN
    ErrorId := 16#0000;
END_IF;

// 🎚️ 3. SyncActive SELON MODE (Partie9 §9, décisions actées 2026-07-02)
CASE Mode OF
    E_Mode.MAINT_N1:
        SyncActive := TRUE;                  // Imposée, non désactivable (sécurité maintenue N1)
    E_Mode.MAINT_N2:
        SyncActive := SyncEnable;             // 🔧 REX 2026-07-08 : ex-NOT OverrideSync, polarité déjà positive
    ELSE
        SyncActive := TRUE;                  // MANUEL/SEMI_AUTO : pas de logique dédiée (FB_Cycle absent), actif par prudence
END_CASE;

// 🌐 BYPASS GLOBAL : si actif, on saute TOUTE la logique d'écart
IF NOT BypassGlobal THEN

// 📏 4. ÉCART M1/M2 — fiable UNIQUEMENT si les 2 treuils sont homés
IF HomedM1 AND HomedM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;

// 🔍 5. DÉTECTION ÉCART HORS TOLÉRANCE — bit0
// 🔧 REX 2026-07-08 (5) : filtre temporel (même pattern que MismatchTimer bit1) — absorbe le
// transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2), évite le blocage
// intempestif constaté sur incident terrain (0.24m transitoire).
DeviationActive := SyncActive AND HomedM1 AND HomedM2 AND (DeltaPosM > CfgSyncToleranceM);
DeviationTimer(IN := DeviationActive, PT := T#800ms);  // 🔧 théorique, à ajuster sur site — absorbe le transitoire mécanique normal d'arrêt (coast-down différentiel M1/M2)
IF DeviationTimer.Q THEN
    ErrorId := ErrorId OR 16#0001;
ELSIF ResetEdge.Q AND NOT DeviationActive THEN
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// 🔍 5bis. COHÉRENCE DES COMMANDES SÉCURITÉ — bit1
// Vérifie que les commandes envoyées aux deux treuils sont identiques (sens et contacteurs)
// Filtre de 500ms pour tolérer les transitions et rampes.
MismatchActive := SyncActive AND (
    (RelayFwdM1 <> RelayFwdM2) OR
    (RelayRevM1 <> RelayRevM2) OR
    (Contactor1_M1 <> Contactor1_M2) OR
    (Contactor2_M1 <> Contactor2_M2) OR
    (Contactor3_M1 <> Contactor3_M2) OR
    (Contactor4_M1 <> Contactor4_M2)
);

MismatchTimer(IN := MismatchActive, PT := T#500ms);

IF MismatchTimer.Q THEN
    ErrorId := ErrorId OR 16#0002;
ELSIF ResetEdge.Q THEN
    ErrorId := ErrorId AND 16#FFFD;
END_IF; // fin du IF MismatchActive

END_IF; // fin IF NOT BypassGlobal

// 📤 6. SORTIES ÉTAT
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

SyncWarn := Error;   // ⚠️ IHM uniquement — voir en-tête, pas de SafeStop
Busy := FALSE;
Done := FALSE;

// === IMPLEMENTATION (corps du PROGRAM PRG_00_Inputs) ===

// 🧹 WINCH-CORE-01 — PURGE COMMANDES IHM RETAIN AU BOOT
// PRG_00 est exécuté avant PRG_01..PRG_10 : aucune commande mémorisée ne peut donc
// produire un front ou un mouvement pendant le premier scan. Les états sûrs maintenus
// (`BtnEmergencyCutOff`, inhibitions) ne sont volontairement pas effacés.
// L'override permet uniquement à la suite PLC de rejouer ce scénario en simulation.
IF NOT HmiCommandsInitialized
   OR (GVL_Simulation.SimulationModeActive AND GVL_PLC_Tests.OverrideHmiCommandPurge) THEN
    GVL_IHM.HmiInitDone := FALSE;

    GVL_IHM.Modes.Cmd.BtnFaultReset := FALSE;
    GVL_IHM.Modes.Cmd.BtnModeReset := FALSE;
    GVL_IHM.Modes.Cmd.BtnEmergencyArming := FALSE;

    GVL_IHM.M1TreuilRetenue.Cmd.BtnReset := FALSE;
    GVL_IHM.M1TreuilRetenue.Cmd.BtnHome := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault := FALSE;
    GVL_IHM.M1TreuilRetenue.Cmd.BtnConfirmCoherence := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnReset := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnHome := FALSE;
    GVL_IHM.M2TreuilBenne.Bypass.EncoderFault := FALSE;
    GVL_IHM.M2TreuilBenne.Cmd.BtnConfirmCoherence := FALSE;

    GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnOpen := FALSE;
    GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnClose := FALSE;
    GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnReset := FALSE;
    GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos := FALSE;
    GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos := FALSE;

    GVL_IHM.Cycle.Cmd.BtnStart := FALSE;
    GVL_IHM.Cycle.Cmd.BtnPause := FALSE;
    GVL_IHM.Cycle.Cmd.BtnAbort := FALSE;
    GVL_IHM.Cycle.Cmd.BtnReset := FALSE;

    GVL_IHM.TranslationM3.Cmd.SelPositioning := FALSE;
    GVL_IHM.TranslationM3.Cmd.BtnFwd := FALSE;
    GVL_IHM.TranslationM3.Cmd.BtnRev := FALSE;
    GVL_IHM.JOY1Joystick.Cmd.BtnCalibrate := FALSE;

    HmiCommandsInitialized := TRUE;
    GVL_IHM.HmiInitDone := TRUE;
END_IF;

// 🛑 ─── COMMUN ────────────────────────────────────────────────────────────
// 🧪 Simulation : chaque OR ci-dessous force le capteur à son état "sain" (famille
// sécurité, TRUE=OK) quand SimulationModeActive ET que ce capteur précis n'est
// pas encore câblé réellement (GVL_Simulation.Bus*/Sensor*IsReal). Voir DOC/AF_Partie-13_Fonction_Simulation_v1.2.md.

// Simulation de la chaîne de sécurité AU / réarmement (Lot 1)
instSimSafety(
    Enable          := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorEmergencyStopChainIsReal,
    PowerCutOff_A   := PowerCutOff_A_RQ,
    PowerCutOff_B   := PowerCutOff_B_RQ,
    EmergencyArming := EmergencyArming_RQ,
    BtnEmergencyStop := GVL_PLC_Tests.OverrideChainFalse
);

instEmergencyStopOk(InputRaw := EmergencyStopOk_DI OR instSimSafety.SimContactorOk, FilterTime := T#20MS);
EmergencyStopOk := instEmergencyStopOk.State;

// 🔧 REX 2026-07-07 : boucle AU (coup-de-poing + contact PLC) — distincte du contacteur de
// puissance ci-dessus. Réutilise le même flag simulation (même sous-système physique AU).
instEmergencyChain(InputRaw := EmergencyChainOK_DI OR instSimSafety.SimChainOk, FilterTime := T#20MS);
EmergencyChain := instEmergencyChain.State;

// 🔧 REX 2026-07-07 : M1_M2_SlackCableSwitch_DI → M2_SlackCableSwitch_DI (capteur physiquement
// uniquement sur le tambour M2, le préfixe M1_M2_ ne reflétait pas la réalité du câblage)
instSlackCableSwitch(InputRaw := M2_SlackCableSwitch_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorSlackCableIsReal), FilterTime := T#20MS);
SlackCableSwitch := instSlackCableSwitch.State;

// 🪨 Kobold : entrée dédiée, distincte du mou de câble.
// Adresse terrain : KoboldContactFond_DI = %IX0.5.
instKoboldContactFond(
    InputRaw := KoboldContactFond_DI
                OR (GVL_Simulation.SimulationModeActive
                    AND NOT GVL_Simulation.SensorKoboldContactFondIsReal
                    AND GVL_Simulation.SimKoboldContactFondValue),
    FilterTime := T#20MS);
KoboldContactFond := instKoboldContactFond.State;

// 🆕 REX 2026-07-08 (4) : cohérence simulation (demande utilisateur) — l'ancien câblage forçait
// TopPositionSensor à TOUJOURS TRUE (sain) en simulation, quelle que soit la position codeur :
// impossible de tester bit5/Méca D (capteur haut) en simulation, il ne se déclenchait JAMAIS.
// Dérivé désormais de la position M1 simulée (référence de l'ensemble, voir FB_Bucket/
// ActiveOffsetM) — 1 cycle de retard (PRG_00 avant PRG_02 dans l'ordre de tâche), négligeable,
// même principe déjà assumé ailleurs (EncoderFaultPresent, BenneHoldStillActive).
SimTopSensorTriggered := (NOT PRG_04_Modes.instModes.InhibitM1 AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM >= _WinchM1CfgPersist.CfgTopSensorPos_M))
                      OR (NOT PRG_04_Modes.instModes.InhibitM2 AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM >= _WinchM2CfgPersist.CfgTopSensorPos_M));
instTopPositionSensor(InputRaw := M1_M2_TopPositionSensor_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTopPositionIsReal AND NOT SimTopSensorTriggered), FilterTime := T#20MS);
TopPositionSensor := instTopPositionSensor.State;

instCtrlPhaseRotation(InputRaw := CtrlPhaseRotation_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorPhaseRotationIsReal), FilterTime := T#20MS);
PhaseRotationOk := instCtrlPhaseRotation.State;

// 🆕 REX 2026-07-08 : thermique frein commun M1/M2/M3 (1 seul fil, voir bandeau ci-dessus)
instBrakeThermalFeedback(InputRaw := BrakeThermalFeedback_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorBrakeThermalIsReal), FilterTime := T#20MS);
BrakeThermalFeedback := instBrakeThermalFeedback.State;

// 🪝 ─── WINCH M1 ──────────────────────────────────────────────────────────
// 🧪 Simulation des retours contacteurs M1 (retombés si aucun sens/vitesse commandé)
M1_FwdRevSpeedFeedbackOff_Simulated := NOT (PRG_10_Outputs.M1RelayFwd OR PRG_10_Outputs.M1RelayRev OR PRG_10_Outputs.M1SpeedContactor1 OR PRG_10_Outputs.M1SpeedContactor2 OR PRG_10_Outputs.M1SpeedContactor3 OR PRG_10_Outputs.M1SpeedContactor4);
instM1FwdRevSpeedFeedbackOff(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal, M1_FwdRevSpeedFeedbackOff_DI, M1_FwdRevSpeedFeedbackOff_Simulated), FilterTime := T#20MS);
M1FwdRevSpeedFeedbackOff := instM1FwdRevSpeedFeedbackOff.State;

instM1Thermal(InputRaw := M1_ThermalFeedback_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM1ThermalIsReal), FilterTime := T#20MS);
M1ThermalFeedback := instM1Thermal.State;

// 🧪 Simulation du retour frein M1 (fermé si commande inactive)
M1BrakeFeedback_Simulated := NOT PRG_10_Outputs.M1BrakeCmd;
instM1BrakeFeedback(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal, M1_BrakeFeedback_DI, M1BrakeFeedback_Simulated), FilterTime := T#20MS);
M1BrakeFeedback := instM1BrakeFeedback.State;

// 🪝 ─── WINCH M2 ──────────────────────────────────────────────────────────
// 🧪 Simulation des retours contacteurs M2 (retombés si aucun sens/vitesse commandé)
M2_FwdRevSpeedFeedbackOff_Simulated := NOT (PRG_10_Outputs.M2RelayFwd OR PRG_10_Outputs.M2RelayRev OR PRG_10_Outputs.M2SpeedContactor1 OR PRG_10_Outputs.M2SpeedContactor2 OR PRG_10_Outputs.M2SpeedContactor3 OR PRG_10_Outputs.M2SpeedContactor4);
instM2FwdRevSpeedFeedbackOff(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal, M2_FwdRevSpeedFeedbackOff_DI, M2_FwdRevSpeedFeedbackOff_Simulated), FilterTime := T#20MS);
M2FwdRevSpeedFeedbackOff := instM2FwdRevSpeedFeedbackOff.State;

instM2Thermal(InputRaw := M2_ThermalFeedback_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM2ThermalIsReal), FilterTime := T#20MS);
M2ThermalFeedback := instM2Thermal.State;

// 🧪 Simulation du retour frein M2 (fermé si commande inactive)
M2BrakeFeedback_Simulated := NOT PRG_10_Outputs.M2BrakeCmd;
instM2BrakeFeedback(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal, M2_BrakeFeedback_DI, M2BrakeFeedback_Simulated), FilterTime := T#20MS);
M2BrakeFeedback := instM2BrakeFeedback.State;

// ↔️ ─── TRANSLATION M3 ────────────────────────────────────────────────────────
// 🧪 Simulation dynamique du trajet M3 (FB_Sim_Translation, non prioritaire — voir DOC/AF_Partie-13_Fonction_Simulation_v1.2.md
// §Translation). Appelée AVANT les FB_Input pour que ses sorties soient à jour au même cycle
// (sinon décalage d'1 cycle sur le OR ci-dessous). Remplace le forçage manuel en vue instance.
// 🔧 L'ancien mode relais DEGRADED_IO est supprimé. La simulation déduit directement le sens de
// `M3_CommandWord`, variable PDO EtherCAT réellement envoyée en Auto comme en Manuel.
// Lecture décalée d'1 cycle (10 ms, M3_CommandWord réécrit en position
// 10 par PRG_10_Outputs après ce PRG_00) — négligeable devant TravelTimeS (8s).
instSimTranslation(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTranslationPositionIsReal,
    TargetNum   := GVL_Translation_M3_Stub.StubTranslationPositionSelect_IHM,
    RelayFwd    := M3_CommandWord = 1,
    RelayRev    := M3_CommandWord = 2,
    TravelTimeS := 8.0
);

instTranslationPosTremie(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTranslationPositionIsReal, PosTremie_DI, instSimTranslation.PosTremie), FilterTime := T#20MS);
TranslationPosTremie := instTranslationPosTremie.State;

instTranslationPosPV(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTranslationPositionIsReal, GVL_Translation_M3_Stub.PosPV_DI, instSimTranslation.PosPV), FilterTime := T#20MS);
TranslationPosPV := instTranslationPosPV.State;

instTranslationPosP2(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTranslationPositionIsReal, PosFosse2_DI, instSimTranslation.PosP2), FilterTime := T#20MS);
TranslationPosP2 := instTranslationPosP2.State;

instTranslationPosP1(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTranslationPositionIsReal, PosFosse1_DI, instSimTranslation.PosP1), FilterTime := T#20MS);
TranslationPosP1 := instTranslationPosP1.State;

instTranslationPosMaintenance(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTranslationPositionIsReal, PosMaintenance_DI, instSimTranslation.PosMaintenance), FilterTime := T#20MS);
TranslationPosMaintenance := instTranslationPosMaintenance.State;

// 🆕 REX 2026-07-21 : Décodage immédiat du mot 5 capteurs position M3 (scan position 0)
instPositionDecoder(
    SensorTremie      := TranslationPosTremie,
    SensorPV          := TranslationPosPV,
    SensorP2          := TranslationPosP2,
    SensorP1          := TranslationPosP1,
    SensorMaintenance := TranslationPosMaintenance
);

// 🧪 Simulation du retour frein M3 (fermé/NC=TRUE si commande inactive)
M3BrakeFeedback_Simulated := NOT PRG_07_TranslationControl.instTranslationM3.BrakeCmd;
instM3BrakeFeedback(InputRaw := SEL(GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal, M3_BrakeFeedback_DI, M3BrakeFeedback_Simulated), FilterTime := T#20MS);
M3BrakeFeedback := instM3BrakeFeedback.State;

// 🧪 Simulation/Filtrage des retours variateur EtherCAT M3 (lecture seule physique contournée)
IF GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BusVariateurM3IsReal THEN
    M3_ActualFrequencyHz_Filtered := M3_SetpointFrequencyHz;

    // Status Word : Bit0 (Operation), Bit7 (Operation Enable)
    IF M3_CommandWord = 1 THEN
        M3_StatusWord_Filtered := 16#0081; // Operation + Operation Enable
    ELSIF M3_CommandWord = 2 THEN
        M3_StatusWord_Filtered := 16#0089; // Operation + Operation Enable + Reverse (bit3)
    ELSE
        M3_StatusWord_Filtered := 16#0080; // Stopped + Operation Enable
    END_IF;
ELSE
    M3_ActualFrequencyHz_Filtered := M3_ActualFrequencyHz;
    M3_StatusWord_Filtered        := M3_StatusWord;
END_IF;

// 🧪 Appel de la suite globale de tests de validation automate
instTestsManagement(instBucket := GVL_Simulation.LinkBucket, instWinchM2 := GVL_Simulation.LinkWinchM2);

// Surcharges (overrides) demandées par le banc de tests automatique
IF GVL_PLC_Tests.OverrideChainTrue THEN
    EmergencyChain := TRUE;
END_IF;
IF GVL_PLC_Tests.OverrideChainFalse THEN
    EmergencyChain := FALSE;
END_IF;
IF GVL_PLC_Tests.OverrideContactorFalse THEN
    EmergencyStopOk := FALSE;
ELSIF GVL_PLC_Tests.OverrideEmergencyStopOkTrue THEN
    EmergencyStopOk := TRUE;
END_IF;

// Surcharges (overrides) du banc de tests — Translation M3 (niveau capteur amont uniquement)
IF GVL_PLC_Tests.OverrideM3AtTremie THEN
    TranslationPosTremie := TRUE; // 🧪 Simule le Fdc extrême avant sans attendre le trajet simulé complet
END_IF;
// 🆕 REX 2026-07-18 : force les 5 capteurs position depuis un mot de test (indépendant du temps
// de trajet simulé) — seul moyen de tester les 6 mots valides ET les combinaisons incohérentes.
IF GVL_PLC_Tests.OverrideM3SensorsWordActive THEN
    TranslationPosTremie      := GVL_PLC_Tests.OverrideM3SensorsWord.4;
    TranslationPosPV          := GVL_PLC_Tests.OverrideM3SensorsWord.3;
    TranslationPosP2          := GVL_PLC_Tests.OverrideM3SensorsWord.2;
    TranslationPosP1          := GVL_PLC_Tests.OverrideM3SensorsWord.1;
    TranslationPosMaintenance := GVL_PLC_Tests.OverrideM3SensorsWord.0;
END_IF;
IF GVL_PLC_Tests.OverrideM3BrakeStuckOpen THEN
    M3BrakeFeedback := TRUE; // 🧪 Simule Méca B : retour frein resté desserré malgré commande fermée
END_IF;
IF GVL_PLC_Tests.OverrideM3PhantomFreq THEN
    M3_ActualFrequencyHz_Filtered := 100; // 🧪 Simule Méca A : 1.00Hz mesuré malgré arrêt commandé (seuil 0.5Hz)
END_IF;

// 🛡️ Surcharges retours arrêt M1/M2 — polarité inverse : arrêt confirmé = TRUE.
IF GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff THEN
    M1FwdRevSpeedFeedbackOff := GVL_PLC_Tests.OverrideM1FwdRevSpeedFbOff;
END_IF;
IF GVL_PLC_Tests.OverrideM1BrakeFeedback THEN
    M1BrakeFeedback := GVL_PLC_Tests.OverrideM1BrakeFeedback;
END_IF;
IF GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff THEN
    M2FwdRevSpeedFeedbackOff := GVL_PLC_Tests.OverrideM2FwdRevSpeedFbOff;
END_IF;
IF GVL_PLC_Tests.OverrideM2BrakeFeedback THEN
    M2BrakeFeedback := GVL_PLC_Tests.OverrideM2BrakeFeedback;
END_IF;

// === IMPLEMENTATION (corps du PROGRAM PRG_01_Diagnostics) ===

// 🧪 0. Simulation Joystick (Lot 3, priorité — voir CODE/SIMULATION/FB_Sim_Joystick.st) : appelée
// AVANT FB_Joystick_0 pour que ses sorties soient à jour au même cycle. Remplace l'ancien bypass
// homme-mort codé en dur dans FB_Joystick (GVL_DEBUG.DBG_DeadmanBypass_TEST) : quand
// NOT BusJoystickSignalIsReal, ses sorties remplacent les entrées brutes ci-dessous ; le homme-mort
// réel de FB_Joystick n'est plus jamais contourné.
// 🆕 REX 2026-07-08 : gardé désormais par BusJoystickSignalIsReal (PAS BusJoystickIsReal, qui ne
// couvre que le bus CANopen ci-dessous) — granularité séparée demandée par l'utilisateur : tester
// le signal joystick réel sans dépendre du diagnostic bus/nœud CANopen (encore simulé sain).
instSimJoystick(
    Enable          := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BusJoystickSignalIsReal,
    NeutralRaw      := GVL_Simulation.TstJoystickForceNeutralRaw,
    MaxRaw          := GVL_Simulation.TstJoystickForceMaxRaw,
    // 🆕 REX 2026-07-19 : pilotage programmatique par la suite PLC_TESTS (SUITE_MODES)
    TestOverrideActive    := GVL_PLC_Tests.OverrideJoystickActive,
    TestOverrideRawX      := GVL_PLC_Tests.OverrideJoystickRawX,
    TestOverrideRawY      := GVL_PLC_Tests.OverrideJoystickRawY,
    TestOverrideRawButton := GVL_PLC_Tests.OverrideJoystickRawButton
);

// 1. Diagnostics CANopen — 🆕 REX 2026-07-08 : gardé par BusJoystickIsReal UNIQUEMENT (bus/nœud),
// indépendant de BusJoystickSignalIsReal (signal brut ci-dessus) — granularité séparée.
// 🆕 REX 2026-07-22 : bypass DÉCOUPLÉ de SimulationModeActive — BusJoystickIsReal seul pilote
// désormais ce bypass diag, pour rester actif même simulation globale coupée (banc sans bus
// CANopen câblé). Repasser BusJoystickIsReal := TRUE au câblage réel du bus/nœud CANopen.
instDiagCanOpen(
    Enable := TRUE,
    Reset := PRG_09_Supervision.FaultMachineReset_IHM,
    CANbusOnline := (CANbus.GetBusState() = 1) OR (NOT GVL_Simulation.BusJoystickIsReal) OR GVL_IHM.Network.Bypass.Global, // 1 = ACTIVE (ou bypass)
    DeviceJoystickOnline := (JOY1_JOYSTICK_MCB560_CO4201A.GetDeviceState() = DEVICE_STATE.RUNNING) OR (NOT GVL_Simulation.BusJoystickIsReal) OR GVL_IHM.Network.Bypass.Global
);

// 2. Diagnostics EtherCAT (variateur + 2 codeurs)
// 🆕 REX 2026-07-22 : bypass DÉCOUPLÉ de SimulationModeActive — Bus<Device>IsReal seul pilote
// désormais ce bypass diag par device, pour rester actif même simulation globale coupée (banc
// sans bus EtherCAT câblé). Repasser chaque Bus<Device>IsReal := TRUE au câblage réel.
instDiagEthercat(
    Enable := TRUE,
    Reset := PRG_09_Supervision.FaultMachineReset_IHM,          // 🔑 Bouton général machine
    DeviceVariateurOnline := (AC600_ECAT_Drive.GetDeviceState() = DEVICE_STATE.RUNNING) OR (NOT GVL_Simulation.BusVariateurM3IsReal) OR GVL_IHM.Network.Bypass.Global,
    DeviceVariateurState := SEL((NOT GVL_Simulation.BusVariateurM3IsReal) OR (AC600_ECAT_Drive.GetDeviceState() = DEVICE_STATE.RUNNING) OR GVL_IHM.Network.Bypass.Global, 0, 8),
    DeviceEncoderM1Online := (COD1_CODEUR.GetDeviceState() = DEVICE_STATE.RUNNING) OR (NOT GVL_Simulation.BusEncoderM1IsReal) OR GVL_IHM.Network.Bypass.Global,
    DeviceEncoderM1State := SEL((NOT GVL_Simulation.BusEncoderM1IsReal) OR (COD1_CODEUR.GetDeviceState() = DEVICE_STATE.RUNNING) OR GVL_IHM.Network.Bypass.Global, 0, 8),
    DeviceEncoderM2Online := (COD2_CODEUR.GetDeviceState() = DEVICE_STATE.RUNNING) OR (NOT GVL_Simulation.BusEncoderM2IsReal) OR GVL_IHM.Network.Bypass.Global,
    DeviceEncoderM2State := SEL((NOT GVL_Simulation.BusEncoderM2IsReal) OR (COD2_CODEUR.GetDeviceState() = DEVICE_STATE.RUNNING) OR GVL_IHM.Network.Bypass.Global, 0, 8)
);

// 💓 2bis. Heartbeat IHM↔PLC — appelé avant PRG_03_Safety pour fournir le statut même cycle.
// 🆕 REX 2026-07-22 : bypass DÉCOUPLÉ de SimulationModeActive — BusIhmHeartbeatIsReal seul
// pilote désormais ce bypass, pour rester actif même simulation globale coupée (IHM réelle pas
// encore câblée niveau visu). Sans IHM réelle sur banc, BlinkClock fournit un toggle sain ;
// mettre BusIhmHeartbeatIsReal := TRUE dès que la visu toggle réellement TglHeartbeatIhm.
instIhmHeartbeat(
    Enable := TRUE,
    TglHeartbeatIhm := SEL(GVL_PLC_Tests.OverrideIhmHeartbeatActive,
                              SEL(NOT GVL_Simulation.BusIhmHeartbeatIsReal,
                                  GVL_IHM.Commun.TglHeartbeatIhm,
                                  GVL_Global.BlinkClock),
                              GVL_PLC_Tests.OverrideIhmHeartbeatToggle),
    IhmTimeout := T#2s,
    PlcTogglePeriod := T#500ms
);

// 3. Acquisition Joystick — RawX/RawY/RawButton simulés (instSimJoystick) quand NOT BusJoystickSignalIsReal
// 🔴🔧 REX 2026-07-07 — TEST BANC UNIQUEMENT, PAS DE VALEUR PRODUCTION :
//    DeadmanRearmTimeout 10s → 5min, NeutralHoldTime 500ms → 1s (confort d'essai, moins de
//    réappuis/traversées à gérer). ⚠️ RÉDUIT RÉELLEMENT LA SÉCURITÉ HOMME-MORT — à repasser
//    impérativement à T#10S / T#500MS (ou retirer ces 2 lignes, le FB reprend ses défauts sûrs)
//    avant toute mise en service réelle avec la machine.
FB_Joystick_0(
    Enable              := TRUE,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    Mode                := PRG_04_Modes.instModes.Mode,  // 🆕 REX 2026-07-08 : désarme le homme-mort au changement de mode
    // 🆕 REX 2026-07-08 : PRG_01 (position 1) s'exécute AVANT PRG_06 (position 6) — BenneBusy lu
    // ici reflète donc le Busy du scan PRÉCÉDENT (retard d'1 scan, ~10ms, sur la détection du front
    // descendant). Sans impact pratique : très inférieur aux temps de réponse frein/contacteurs
    // (100-300ms, voir FB_Brake) — la commande n'a pas le temps de produire un mouvement réel.
    BenneBusy         := PRG_06_WinchControl.instBucket.Busy,
    NeutralXMem         := _JoystickNeutralX,
    NeutralYMem         := _JoystickNeutralY,
    BusCanOpenOP        := instDiagCanOpen.DeviceCanOpenMaster,
    JoystickOP          := instDiagCanOpen.DeviceJoystick,
    RawX                := SEL(instSimJoystick.Enable, JoyXRaw_ANA1, instSimJoystick.RawX),
    RawY                := SEL(instSimJoystick.Enable, JoyYRaw_ANA2, instSimJoystick.RawY),
    RawButton           := SEL(instSimJoystick.Enable, JoyBtnRaw, instSimJoystick.RawButton),
    BtnCalibrate           := GVL_IHM.JOY1Joystick.Cmd.BtnCalibrate,
    InvertX             := _JoystickInvertX,       // 🔧 REX 2026-07-21 : depuis GVL_PERSISTENT
    InvertY             := _JoystickInvertY,       // 🔧 idem
    Deadband            := _JoystickDeadband_Pct,  // 🔧 REX 2026-07-21 : depuis GVL_PERSISTENT
    FilterTime          := _JoystickFilterTime,    // 🔧 idem
    AccelRate           := _JoystickAccelRate_Pct, // 🔧 idem
    DecelRate           := _JoystickDecelRate_Pct, // 🔧 idem
    // 🛡️ Délais de sécurité Homme-Mort : temporisations courtes (10s/500ms) si joystick réel, longues (5min/1s) si simulé
    DeadmanRearmTimeout := SEL(NOT GVL_Simulation.SimulationModeActive OR GVL_Simulation.BusJoystickSignalIsReal, T#5M, T#10S),
    NeutralHoldTime     := SEL(NOT GVL_Simulation.SimulationModeActive OR GVL_Simulation.BusJoystickSignalIsReal, T#1S, T#500MS)
);

// === IMPLEMENTATION (corps du PROGRAM PRG_02_Encoders) ===

// 🔧 REX 2026-07-16 : ex-EncoderM1_IsReal/EncoderM2_IsReal ("Conditional Bypass Doctrine") RETIRÉS — plus
// aucun consommateur une fois le bypass Homing IHM_MANU supprimé (voir fin de fichier, ex-bloc
// IF PRG_10_Outputs.ManuActive THEN ... HomingEncoder_M1/M2 ... END_IF).

// 🔧 REX 2026-07-15 (4) — CORRECTIF COMPILATION : ex-SEL(ManuActive, ...) référençait
// PRG_10_Outputs.SpeedRefPct, supprimé lors du passage de Manu sur FB_Winch (REX 2026-07-15 (2)).
// Plus besoin de distinguer Auto/Manu ici : instWinchM1/M2.SpeedRamp.Current est désormais LA
// vitesse rampée réelle dans les DEUX cas (FB_Winch pilote M1/M2 qu'on soit en Auto ou en Manu).
M1_SimSpeedPct := PRG_06_WinchControl.instWinchM1.SpeedRamp.Current;
M2_SimSpeedPct := PRG_06_WinchControl.instWinchM2.SpeedRamp.Current;

// 1. SIMULATION SUR BANC DE TEST (Lot 2, granularité indépendante M1/M2 — voir DOC/AF_Partie-13_Fonction_Simulation_v1.2.md)
// 🔧 REX 2026-07-08 : RawPos (VAR_IN_OUT) référence _SimEncoderRawPosM1/M2 —
// survit à un reset froid comme le ferait un vrai codeur absolu physique (voir GVL_PERSISTENT.st).
instSimEncoderM1(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BusEncoderM1IsReal,
    // 🔧 REX 2026-07-15 (2) : lit directement instWinchM1 (PRG_06_WinchControl) — M1 est désormais
    // piloté par FB_Winch en Auto ET en Manu (ex-SimM1Fwd_Eff/PRG_10_Outputs retiré, obsolète) :
    // RelayFwd/RelayRev respectent déjà SafeStop/ForbidAscent/ForbidDescent nativement, plus besoin
    // de signaux Sim dédiés.
    RelayFwd    := PRG_06_WinchControl.instWinchM1.RelayFwd,
    RelayRev    := PRG_06_WinchControl.instWinchM1.RelayRev,
    SpeedRefPct := M1_SimSpeedPct,
    PresetCmd   := (COD1_PresettTrigCmd = 2),
    PresetValue := COD1_PresetValue,
    SpeedScaleFactor := GVL_Simulation.TstEncoderSpeedFactor,  // 🔧 REX 2026-07-07 : confort de test
    // 🆕 REX 2026-07-08 (4) : injection saut de test (Concept 1 / Méca E) — 4096 = PointsPerRev/CableM_PerRev (8192/2.0)
    TestOffsetCmd := GVL_Simulation.TstInjectSyncDeviationM1,
    TestOffsetPts := REAL_TO_DINT(GVL_Simulation.TstSyncDeviationOffsetM * 4096.0),
    RawPos      := _SimEncoderRawPosM1
);
instSimEncoderM2(
    Enable      := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BusEncoderM2IsReal,
    // 🔧 REX 2026-07-15 (2) : idem M1 ci-dessus, lit instWinchM2 (ex-SimM2Fwd_Eff retiré).
    RelayFwd    := PRG_06_WinchControl.instWinchM2.RelayFwd,
    RelayRev    := PRG_06_WinchControl.instWinchM2.RelayRev,
    SpeedRefPct := M2_SimSpeedPct,
    PresetCmd   := (COD2_PresettTrigCmd = 2),
    PresetValue := COD2_PresetValue,
    SpeedScaleFactor := GVL_Simulation.TstEncoderSpeedFactor,  // 🔧 REX 2026-07-07 : confort de test
    // 🆕 REX 2026-07-08 (4) : injection saut de test (Concept 1 / Méca E)
    TestOffsetCmd := GVL_Simulation.TstInjectSyncDeviationM2,
    TestOffsetPts := REAL_TO_DINT(GVL_Simulation.TstSyncDeviationOffsetM * 4096.0),
    RawPos      := _SimEncoderRawPosM2
);

// Aiguillage (par device — 🔧 REX 2026-07-07 : ne PAS utiliser Operational, forcé à TRUE en
// simulation par PRG_01_Diagnostics [SEL sur BusEncoderMxIsReal] pour ne pas remonter de faux
// défaut bus — ça sélectionnait donc systématiquement COD1/COD2_PosValue [réel, figé à 0] au
// lieu de la position simulée, bloquant tout homing/mouvement testé en simulation.
IF (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BusEncoderM1IsReal) THEN
    M1_RawPosToUse := instSimEncoderM1.RawPosOut;
ELSE
    M1_RawPosToUse := COD1_PosValue;
END_IF;

IF (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.BusEncoderM2IsReal) THEN
    M2_RawPosToUse := instSimEncoderM2.RawPosOut;
ELSE
    M2_RawPosToUse := COD2_PosValue;
END_IF;

// 2. TREUIL M1 (Abs → Homing → Scale)
// 🔧 REX 2026-07-07 : Homing appelé AVANT Scale (et non l'inverse) — Scale lit HomingRefRaw en
// entrée ; si Scale s'exécutait avant Homing, un homing réussi au cycle N ne serait répercuté
// sur CablePosM qu'au cycle N+1, alors que instHomingM1.Busy (→ InReferencingMode côté
// FB_Safety_Winch) retombe dès le cycle N — décalage d'1 cycle qui désynchronise le garde-fou
// anti-transition de Méca A (bit7) et provoque un faux déclenchement PowerCutOff au cycle N+1
// (saut de position vu hors fenêtre "référencement en cours"). Homing ne dépend d'aucune sortie
// de Scale (RawPos vient d'instEncoderAbsM1) : aucune dépendance circulaire, réordonnancement sûr.
instEncoderAbsM1(
    Enable              := TRUE,
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Mode                := PRG_04_Modes.instModes.Mode,
    RawPosIn            := M1_RawPosToUse,
    AlarmsIn            := SEL(instSimEncoderM1.Enable, COD1_Alarms, 0),
    WarningsIn          := SEL(instSimEncoderM1.Enable, COD1_Warnings, 0),
    SlaveOperational    := PRG_01_Diagnostics.instDiagEthercat.DeviceEncoderM1.Operational OR instSimEncoderM1.Enable,
    PresetRequest       := instHomingM1.PresetRequest,
    PresetValue         := instHomingM1.PresetValue
);
COD1_PresettTrigCmd := instEncoderAbsM1.PresetTriggerCmd;
COD1_CodeSeqTrigCmd := instEncoderAbsM1.CodeSeqTriggerCmd;
COD1_PresetValue    := instEncoderAbsM1.PresetValueOut;

instHomingM1(
    Enable               := TRUE,
    Calib                := _CalibM1,
    Reset                := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk      := PRG_00_Inputs.EmergencyStopOk,
    Mode                 := PRG_04_Modes.instModes.Mode,
    Home                 := GVL_IHM.M1TreuilRetenue.Cmd.BtnHome OR GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero,
    UnitaryMode          := (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N2)
                            AND (PRG_04_Modes.instModes.JoystickWinchSelectArbitrated <> 3),
    WinchSelected        := (PRG_04_Modes.instModes.JoystickWinchSelectArbitrated = 1),
    CfgHomingTargetM        := _WinchM1CfgPersist.CfgHomingTarget_M,
    BtnConfirmCoherence     := GVL_IHM.M1TreuilRetenue.Cmd.BtnConfirmCoherence,
    TopPositionSensor    := PRG_00_Inputs.TopPositionSensor,
    CfgTopSensorPosM   := SEL(GVL_IHM.M1TreuilRetenue.Cmd.BtnHomingAtZero, _WinchM1CfgPersist.CfgTopSensorPos_M, 0.0),
    FwdRevSpeedFeedbackOff := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff,
    BrakeFeedback        := PRG_00_Inputs.M1BrakeFeedback,
    RawPos               := instEncoderAbsM1.RawPos,
    EncoderAvailable     := instEncoderAbsM1.EncoderAvailable,
    PresetAck            := instEncoderAbsM1.PresetAck,
    PresetNak            := instEncoderAbsM1.PresetNak,
    PointsPerRev         := 8192,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := 2.0,
    BypassGlobal         := GVL_IHM.M1TreuilRetenue.Bypass.Global
);

instEncoderScaleM1(
    RawPos          := instEncoderAbsM1.RawPos,
    HomingRefRaw    := instHomingM1.HomingRefRaw,
    CableM_PerRev   := 2.0,
    PointsPerRev    := 8192
);

// 3. TREUIL M2 (Abs → Homing → Scale)
instEncoderAbsM2(
    Enable              := TRUE,
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Mode                := PRG_04_Modes.instModes.Mode,
    RawPosIn            := M2_RawPosToUse,
    AlarmsIn            := SEL(instSimEncoderM2.Enable, COD2_Alarms, 0),
    WarningsIn          := SEL(instSimEncoderM2.Enable, COD2_Warnings, 0),
    SlaveOperational    := PRG_01_Diagnostics.instDiagEthercat.DeviceEncoderM2.Operational OR instSimEncoderM2.Enable,
    PresetRequest       := instHomingM2.PresetRequest,
    PresetValue         := instHomingM2.PresetValue
);
COD2_PresettTrigCmd := instEncoderAbsM2.PresetTriggerCmd;
COD2_CodeSeqTrigCmd := instEncoderAbsM2.CodeSeqTriggerCmd;
COD2_PresetValue    := instEncoderAbsM2.PresetValueOut;

instHomingM2(
    Enable               := TRUE,
    Calib                := _CalibM2,
    Reset                := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk      := PRG_00_Inputs.EmergencyStopOk,
    Mode                 := PRG_04_Modes.instModes.Mode,
    Home                 := GVL_IHM.M2TreuilBenne.Cmd.BtnHome OR GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero, // 🔧 REX 2026-07-07 : fusion GVL_Encoder_Stub → GVL_IHM
    UnitaryMode          := (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N2)
                            AND (PRG_04_Modes.instModes.JoystickWinchSelectArbitrated <> 3),
    WinchSelected        := (PRG_04_Modes.instModes.JoystickWinchSelectArbitrated = 2),
    CfgHomingTargetM        := _WinchM2CfgPersist.CfgHomingTarget_M,
    BtnConfirmCoherence     := GVL_IHM.M2TreuilBenne.Cmd.BtnConfirmCoherence, // 🔧 REX 2026-07-07 : fusion GVL_Encoder_Stub → GVL_IHM
    TopPositionSensor    := PRG_00_Inputs.TopPositionSensor,
    CfgTopSensorPosM   := SEL(GVL_IHM.M2TreuilBenne.Cmd.BtnHomingAtZero, _WinchM2CfgPersist.CfgTopSensorPos_M, 0.0),
    FwdRevSpeedFeedbackOff := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback        := PRG_00_Inputs.M2BrakeFeedback,
    RawPos               := instEncoderAbsM2.RawPos,
    EncoderAvailable     := instEncoderAbsM2.EncoderAvailable,
    PresetAck            := instEncoderAbsM2.PresetAck,
    PresetNak            := instEncoderAbsM2.PresetNak,
    PointsPerRev         := 8192,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := 2.0,
    BypassGlobal         := GVL_IHM.M2TreuilBenne.Bypass.Global
);

instEncoderScaleM2(
    RawPos          := instEncoderAbsM2.RawPos,
    HomingRefRaw    := instHomingM2.HomingRefRaw,
    CableM_PerRev   := 2.0,
    PointsPerRev    := 8192
);

// 4. SÉCURITÉ DE BORNAGE ET INCOHÉRENCE
instEncoderSafetyM1(
    Enable          := TRUE,
    Reset           := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
    Mode            := PRG_04_Modes.instModes.Mode,
    CablePosM       := instEncoderScaleM1.CablePosM,
    HomingSuspect   := instHomingM1.HomingSuspect,
    PositionMinM    := -99.0,
    PositionMaxM    := 99.0,
    BypassGlobal    := GVL_IHM.M1TreuilRetenue.Bypass.Global
);
EncoderFaultPresentM1 := instEncoderSafetyM1.EncoderIncoherent;

instEncoderSafetyM2(
    Enable          := TRUE,
    Reset           := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
    Mode            := PRG_04_Modes.instModes.Mode,
    CablePosM       := instEncoderScaleM2.CablePosM,
    HomingSuspect   := instHomingM2.HomingSuspect,
    PositionMinM    := -99.0,
    PositionMaxM    := 99.0,
    BypassGlobal    := GVL_IHM.M2TreuilBenne.Bypass.Global
);
EncoderFaultPresentM2 := instEncoderSafetyM2.EncoderIncoherent;

EncoderFaultPresent := EncoderFaultPresentM1 OR EncoderFaultPresentM2;

// === IMPLEMENTATION (corps du PROGRAM PRG_03_Safety) ===
// 1. Sécurité Treuil M1 instSafetyWinchM1( // 🔧 REX 2026-07-15 (2) — SIMPLIFICATION : IHM_MANU pilote désormais M1 via FB_Winch // (PRG_06_WinchControl), qui a BESOIN d'un SafeStop/ForbidAscent/ForbidDescent réels pour // rampé/ralentir proprement (ex-doctrine "Conditional Bypass" devenue obsolète et RETIRÉE // ici : chaque capteur/retour a DÉJÀ sa propre granularité réel/simulé — GVL_Simulation. // BusEncoderM1IsReal, SensorM1ContactorFeedbackIsReal, SensorM1ThermalIsReal, SensorTopPositionIsReal, // SensorSlackCableIsReal — un composant simulé est déjà forcé "sain" en amont (PRG_00_Inputs/ // PRG_02_Encoders), donc Enable n'a plus besoin de bypasser tout le domaine : un vrai défaut // sur un composant RÉEL protège, un composant SIMULÉ ne fait jamais défaut de lui-même). Enable := NOT PRG_04_Modes.instModes.InhibitM1, // 🆕 REX 2026-07-08 : Inhibit (MAINT_N2) uniquement Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, SyncEnable := PRG_04_Modes.instModes.SyncEnable, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Operational, HeartbeatIhmOk := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk, EncoderAvailable := PRG_02_Encoders.instEncoderAbsM1.EncoderAvailable, EncoderFaultBypass := GVL_IHM.M1TreuilRetenue.Bypass.EncoderFault, ThermalFeedback := NOT PRG_00_Inputs.M1ThermalFeedback, BrakeThermalFeedback := NOT PRG_00_Inputs.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 SlackCableDetected := NOT PRG_00_Inputs.SlackCableSwitch, PhaseRotationOk := PRG_00_Inputs.PhaseRotationOk, TopPositionSensor := PRG_00_Inputs.TopPositionSensor, InReferencingMode := PRG_02_Encoders.instHomingM1.Busy, CablePosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM, CfgCableLimitDescentM := _WinchM1CfgPersist.CfgCableLimitDescent_M, Direction := PRG_06_WinchControl.M1_Direction_Active, Mo