HM.M1TreuilRetenue.Bypass.MecaA, BypassMecaB := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaB, BypassMecaC := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaC, BypassMecaD := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaD, BypassMecaE := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.MecaE, BypassSafety := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.Safety, BypassProcess := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.Process, BypassTopLimitSwitch := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.TopLimitSwitch, BypassCableLimitSwitch := GVL_IHM.M1TreuilRetenue.Bypass.Global OR GVL_IHM.M1TreuilRetenue.Bypass.CableLimitSwitch );
// 2. Sécurité Treuil M2 instSafetyWinchM2( // 🔧 REX 2026-07-15 (2) — même simplification que M1 ci-dessus (voir bandeau instSafetyWinchM1). Enable := NOT PRG_04_Modes.instModes.InhibitM2, // 🆕 REX 2026-07-08 : Inhibit (MAINT_N2) uniquement Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, SyncEnable := PRG_04_Modes.instModes.SyncEnable, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Operational, HeartbeatIhmOk := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk, EncoderAvailable := PRG_02_Encoders.instEncoderAbsM2.EncoderAvailable, EncoderFaultBypass := GVL_IHM.M2TreuilBenne.Bypass.EncoderFault, ThermalFeedback := NOT PRG_00_Inputs.M2ThermalFeedback, BrakeThermalFeedback := NOT PRG_00_Inputs.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 SlackCableDetected := NOT PRG_00_Inputs.SlackCableSwitch, PhaseRotationOk := PRG_00_Inputs.PhaseRotationOk, TopPositionSensor := PRG_00_Inputs.TopPositionSensor, InReferencingMode := PRG_02_Encoders.instHomingM2.Busy, CablePosM := PRG_02_Encoders.instEncoderScaleM2.CablePosM, CfgCableLimitDescentM := _WinchM2CfgPersist.CfgCableLimitDescent_M, Direction := PRG_06_WinchControl.M2_Direction_Active, MovementCommanded := PRG_06_WinchControl.instWinchM2.RelayFwd OR PRG_06_WinchControl.instWinchM2.RelayRev, Homed := PRG_02_Encoders.instHomingM2.Homed, HomingSuspect := PRG_02_Encoders.instHomingM2.HomingSuspect, TopLimitM := _WinchM2CfgPersist.CfgTopSensorPos_M, // 🔧 REX 2026-07-07 — Méca A/B (voir FB_Safety_Winch bandeau en-tête) — Méca C NON applicable // à M2 (c'est M2 qui bouge pendant le benne, BenneHoldStillActive reste FALSE) FwdRevSpeedFeedbackOff := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff, BrakeFeedback := PRG_00_Inputs.M2BrakeFeedback, // 🔧 REX 2026-07-19 : idem M1 (voir bandeau instSafetyWinchM1 ci-dessus) — suppression IHM_MANU. JoystickYNeutral := (ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef) < 0.1), BenneHoldStillActive := FALSE, // 🔧 REX 2026-07-08 (5) : BUG CORRIGÉ — oublié côté M2 lors de l'ajout initial Méca E. // ExpectedOtherWinchPosM valait 0.0 par défaut (non câblé) → Méca E comparait CablePosM2 // à 0 au lieu de M1, déclenchement permanent dès que M2 > CriticalSyncToleranceM (2.0m) // du zéro codeur. M1 corrigé de l'offset benne actif, ramené dans le référentiel M2. ExpectedOtherWinchPosM := PRG_02_Encoders.instEncoderScaleM1.CablePosM + PRG_06_WinchControl.instBucket.ActiveOffsetM, BenneBusy := PRG_06_WinchControl.instBucket.Busy, CriticalSyncToleranceM := _WinchCriticalSyncTolerance_M, OtherWinchInhibited := PRG_04_Modes.instModes.InhibitM1, // 🆕 REX 2026-07-08 (7) BypassGlobal := GVL_IHM.M2TreuilBenne.Bypass.Global, BypassOperatorComm := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.OperatorComm, BypassPhaseRotation := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.PhaseRotation, BypassBrakeThermal := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.BrakeThermal, BypassMecaA := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaA, BypassMecaB := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaB, BypassMecaC := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaC, BypassMecaD := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaD, BypassMecaE := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.MecaE, BypassSafety := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.Safety, BypassProcess := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.Process, BypassTopLimitSwitch := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.TopLimitSwitch, BypassCableLimitSwitch := GVL_IHM.M2TreuilBenne.Bypass.Global OR GVL_IHM.M2TreuilBenne.Bypass.CableLimitSwitch );
// 2bis. Moniteurs vitesse — diagnostic seul ; seuils désactivés jusqu'à T45. instSpeedMonitorM1( Enable := NOT PRG_04_Modes.instModes.InhibitM1, Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, SpeedMps := instSafetyWinchM1.MeasuredSpeedMps, SpeedVariationThresholdMps := 0.0, SpeedVariationTimeout := T#0ms, SpeedStabilityTimeout := T#0ms ); instSpeedMonitorM2( Enable := NOT PRG_04_Modes.instModes.InhibitM2, Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, SpeedMps := instSafetyWinchM2.MeasuredSpeedMps, SpeedVariationThresholdMps := 0.0, SpeedVariationTimeout := T#0ms, SpeedStabilityTimeout := T#0ms );
// 2ter. Estimation charge — information empirique, jamais une fonction safety. instLoadEstimatorM1( Enable := NOT PRG_04_Modes.instModes.InhibitM1, Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, ActiveSpeedStep := PRG_06_WinchControl.instWinchM1.StepNumber, MeasuredSpeedMps := instSafetyWinchM1.MeasuredSpeedMps, MeasuredSpeedSignedMps:= instSafetyWinchM1.MeasuredSpeedSignedMps, SpeedConfig := _WinchSpeedConfig, LoadTable := _WinchLoadEstimateTable ); instLoadEstimatorM2( Enable := NOT PRG_04_Modes.instModes.InhibitM2, Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, ActiveSpeedStep := PRG_06_WinchControl.instWinchM2.StepNumber, MeasuredSpeedMps := instSafetyWinchM2.MeasuredSpeedMps, MeasuredSpeedSignedMps:= instSafetyWinchM2.MeasuredSpeedSignedMps, SpeedConfig := _WinchSpeedConfig, LoadTable := _WinchLoadEstimateTable );
// 3. Sécurité Translation M3 instSafetyTranslationM3( // 🔧 REX 2026-07-16 — SIMPLIFICATION : IHM_MANU pilote désormais M3 via FB_Translation // (PRG_07_TranslationControl), qui a BESOIN d'un SafeStop réel pour rampé/arrêter proprement // (ex-"Conditional Bypass Doctrine" RETIRÉE ici, même traitement que instSafetyWinchM1/M2 — // voir REX 2026-07-15 (2) plus haut). Pas d'InhibitM3 dans FB_Modes (contrairement à // InhibitM1/M2) : Enable inconditionnel, comme en Auto. Enable := TRUE, Reset := PRG_09_Supervision.FaultMachineReset_IHM, EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk, Mode := PRG_04_Modes.instModes.Mode, JoystickOnline := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Online, JoystickOperational := PRG_01_Diagnostics.instDiagCanOpen.DeviceJoystick.Operational, HeartbeatIhmOk := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk, PhaseRotationOk := PRG_00_Inputs.PhaseRotationOk, BrakeThermalFeedback := NOT PRG_00_Inputs.BrakeThermalFeedback, // 🆕 REX 2026-07-08 — commun M1/M2/M3 DriveOnline := PRG_01_Diagnostics.instDiagEthercat.DeviceVariateur.Online, DriveOperational := PRG_01_Diagnostics.instDiagEthercat.DeviceVariateur.Operational, DriveStatusWord := PRG_00_Inputs.M3_StatusWord_Filtered, DriveActualFreqHz := UINT_TO_REAL(PRG_00_Inputs.M3_ActualFrequencyHz_Filtered) / 100.0, BrakeFeedback := PRG_00_Inputs.M3BrakeFeedback, BrakeCmd := PRG_07_TranslationControl.instTranslationM3.BrakeCmd, Direction := PRG_07_TranslationControl.M3_Direction_Active, // 🆕 REX 2026-07-18 : limites extrêmes dérivées du décodage 5 capteurs (mot valide), plus // câblées directement sur un capteur brut — voir FB_Translation_PositionDecoder. LimitSwitchFwd := PRG_00_Inputs.instPositionDecoder.LimitSwitchFwd, LimitSwitchRev := PRG_00_Inputs.instPositionDecoder.LimitSwitchRev, SensorWordIncoherent := PRG_00_Inputs.instPositionDecoder.Incoherent, // 🔧 Bypass des surveillances (GVL_IHM.TranslationM3.Bypass - pilotés IHM) BypassGlobal := GVL_IHM.TranslationM3.Bypass.Global, BypassOperatorComm := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.OperatorComm, BypassDriveComm := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.DriveComm, BypassPhaseRotation := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.PhaseRotation, BypassBrakeThermal := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.BrakeThermal, BypassMecaB := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.MecaB, BypassMecaA := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.MecaA, BypassLimitSwitch := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch, BypassSensorIncoherent:= GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.SensorIncoherent, BypassSafety := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.Safety, BypassProcess := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.Process );

// === IMPLEMENTATION (corps du PROGRAM PRG_04_Modes) ===

// 🆕 Exclusion mutuelle des inhibitions de treuils (soit M1, soit M2, jamais les deux)
IF GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit AND GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit THEN
    // Si M1 était déjà activé, on rejette la demande sur M2 (M2 retombe à FALSE)
    IF PrevInhibitM1 THEN
        GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit := FALSE;
    // Si M2 était déjà activé, on rejette la demande sur M1 (M1 retombe à FALSE)
    ELSIF PrevInhibitM2 THEN
        GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit := FALSE;
    // repli de sécurité si les deux s'activent de façon synchrone sans transition
    ELSE
        GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit := FALSE;
        GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit := FALSE;
    END_IF;
END_IF;

PrevInhibitM1 := GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit;
PrevInhibitM2 := GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit;

// 🆕 Si l'un des treuils est inhibé, synchro impossible par nature -> reset case IHM à TRUE
// (🔧 REX 2026-07-08 : polarité inversée, TRUE = état neutre "synchro voulue")
IF GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit OR GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit THEN
    GVL_IHM.M1M2Sync.Cmd.SelSyncEnable := TRUE;
END_IF;

instModes(
    Enable              := TRUE,
    Reset               := GVL_IHM.Modes.Cmd.BtnModeReset,  // 🔧 REX 2026-07-07 : dédié, jamais mélangé au reset défauts général
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    SelMode         := GVL_Modes_Stub.ModeRequest_IHM,      // 🖥️ Sélecteur IHM
    SelSyncEnable   := GVL_Modes_Stub.SyncEnableRequest_IHM,
    InhibitM1Request    := GVL_IHM.M1TreuilRetenue.Cmd.BtnInhibit, // 🆕 REX 2026-07-08 : IHM réelle, pas GVL_Modes_Stub
    InhibitM2Request    := GVL_IHM.M2TreuilBenne.Cmd.BtnInhibit, // 🆕 REX 2026-07-08 : IHM réelle, pas GVL_Modes_Stub
    SelHomingApproachEnable := GVL_IHM.Commun.Cfg.SelHomingApproachEnable, // 🆕 REX 2026-07-08 (2)
    EncoderFaultPresent := PRG_02_Encoders.EncoderFaultPresent,   // 1 cycle de retard (reçu de PRG_02_Encoders)
    JoystickWinchSelectRequest := GVL_IHM.Modes.Cmd.SelJoystickWinch // 🆕 TASK-0001, rapatrié depuis IHM_MANU (2026-07-19)
);

// === IMPLEMENTATION (corps du PROGRAM PRG_05_Cycle) ===

// 🕹️ Interface unique de commande cycle depuis GVL_IHM.
CmdStartCycle_IHM := GVL_IHM.Cycle.Cmd.BtnStart;
CmdPauseCycle_IHM := GVL_IHM.Cycle.Cmd.BtnPause;
CmdAbortCycle_IHM := GVL_IHM.Cycle.Cmd.BtnAbort;
CmdResetCycle_IHM := GVL_IHM.Cycle.Cmd.BtnReset;
SetDepthM      := GVL_IHM.Cycle.Cfg.SetDepth_M;
SetOffsetM     := GVL_IHM.Cycle.Cfg.SetOffset_M;
GVL_Simulation.SimKoboldContactFondValue := GVL_IHM.Cycle.Test.KoboldContactFond;
CycleMotionPermit := PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                     AND PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop;

// Appel du séquenceur de cycle principal avec tous ses raccordements
instCycle(
    // 🔧 REX 2026-07-19 : suppression IHM_MANU — Mode=SEMI_AUTO suffit seul (les modes
    // sont mutuellement exclusifs dans FB_Modes, plus besoin d'un flag ManuActive séparé).
    Enable              := (PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO),
    CycleMotionPermit   := CycleMotionPermit,
    HeartbeatIhmOk      := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk,
    Reset               := CmdResetCycle_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,

    StartCycle          := CmdStartCycle_IHM,
    PauseCycle          := CmdPauseCycle_IHM,
    AbortCycle          := CmdAbortCycle_IHM,

    SetDepthM        := SetDepthM,
    SetOffsetM       := SetOffsetM,
    SelectedTargetNum_IHM := GVL_IHM.TranslationM3.Cmd.SelTarget,

    // Retour dédié Kobold — distinct du mou de câble.
    KoboldContactFond   := PRG_00_Inputs.KoboldContactFond,
    LimitLegalReached   := GVL_IHM.Commun.LimitLegalReached,
    LimitLegalDepthM    := GVL_IHM.Commun.Cfg.LimitLegalDepthMinAllowed_M,
    WinchSyncError      := PRG_06_WinchControl.instWinchSync.Error,
    WinchSyncDeltaM     := PRG_06_WinchControl.instWinchSync.DeltaPosM,
    M1_CablePosM        := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    M2_CablePosM        := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    M1_MeasuredSpeedMps := PRG_03_Safety.instSafetyWinchM1.MeasuredSpeedMps,
    M2_MeasuredSpeedMps := PRG_03_Safety.instSafetyWinchM2.MeasuredSpeedMps,
    SpeedMismatchThresholdMps := SpeedMismatchThresholdMps,
    SpeedMismatchTimeout      := SpeedMismatchTimeout,
    CableLimitM1AscentM       := _WinchM1CfgPersist.CfgCableLimitAscent_M,

    // Position translation — 🆕 REX 2026-07-18 : Fosse1/Fosse2 renommés P1/P2 (AF_Partie-02 v2.12 §3bis)
    Translation_At_P1       := PRG_00_Inputs.TranslationPosP1,
    Translation_At_P2       := PRG_00_Inputs.TranslationPosP2,
    Translation_At_Maintenance := PRG_00_Inputs.TranslationPosMaintenance,
    Translation_At_Tremie   := PRG_00_Inputs.TranslationPosTremie,
    Translation_Busy        := PRG_07_TranslationControl.instTranslationM3.Busy,
    Translation_Done        := PRG_07_TranslationControl.instTranslationM3.Done,

    // Mouvements mâchoires benne (gérés par instBucket)
    Benne_Busy        := PRG_06_WinchControl.instBucket.Busy,
    Benne_Done        := PRG_06_WinchControl.instBucket.Done,
    Benne_IsOpen      := _BucketState.IsOpen,
    Benne_IsClosed    := _BucketState.IsClosed
);

GVL_IHM.Cycle.State.SpeedMismatch_Mps       := instCycle.SpeedMismatchMps;
GVL_IHM.Cycle.State.SpeedMismatchActive     := instCycle.SpeedMismatchActive;
GVL_IHM.Cycle.State.SpeedMismatchConfirmed  := instCycle.SpeedMismatchConfirmed;

// 🧹 Les commandes restent impulsionnelles même si GVL_IHM est RETAIN.
GVL_IHM.Cycle.Cmd.BtnStart := FALSE;
GVL_IHM.Cycle.Cmd.BtnPause := FALSE;
GVL_IHM.Cycle.Cmd.BtnAbort := FALSE;
GVL_IHM.Cycle.Cmd.BtnReset := FALSE;

// === IMPLEMENTATION (corps du PROGRAM PRG_06_WinchControl) ===

// ── 0. COMMANDE DU BENNE (Séquence lente) ─────────────────────────────
// 🔧 REX 2026-07-08 : appelé EN PREMIER (avant l'arbitrage M1/M2 ci-dessous) — audit sécurité :
// l'ancien ordre (Benne appelé après l'arbitrage) faisait que M1_StartStop_Active lisait
// instBucket.Busy du scan PRÉCÉDENT, créant une fenêtre d'1 scan où M1 pouvait recevoir une
// commande manuelle au moment exact où le benne démarre. instBucket.M1_Busy/M2_Busy (ci-dessous)
// lisent en retour instWinchM1/M2.Busy du scan précédent (ces FB sont appelés plus loin, §6/§7) —
// acceptable : ça ne retarde que l'ACCEPTATION d'une nouvelle demande de ~1 scan (10ms), sans
// aucun impact sécurité (contrairement au cas inverse, qui pouvait faire bouger M1 pendant Busy).
instBucket(
    Enable              := NOT PRG_04_Modes.instModes.InhibitM2
                           AND PRG_02_Encoders.instEncoderAbsM1.EncoderAvailable
                           AND PRG_02_Encoders.instEncoderAbsM2.EncoderAvailable, // 🆕 Sécurisé : nécessite les deux codeurs valides et M2 non-inhibé
    Reset               := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk     := PRG_00_Inputs.EmergencyStopOk,
    Mode                := PRG_04_Modes.instModes.Mode,
    CmdOpen_IHM         := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnOpen OR PRG_05_Cycle.instCycle.CmdBucket_Open,
    CmdClose_IHM        := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnClose OR PRG_05_Cycle.instCycle.CmdBucket_Close,
    JoystickY_StartStop := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop,
    JoystickY_Direction := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.Direction,
    CablePosM1          := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    CablePosM2          := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    HomedM1             := PRG_02_Encoders.instHomingM1.Homed,
    HomedM2             := PRG_02_Encoders.instHomingM2.Homed,
    M1_Busy             := instWinchM1.Busy,   // 🆕 REX 2026-07-08
    M2_Busy             := instWinchM2.Busy,   // 🆕 REX 2026-07-08
    ConfirmOpenPosition := GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmOpenPos, // 🆕 REX 2026-07-08 — bouton IHM référencement benne ouvert
    ConfirmClosePosition:= GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnConfirmClosePos, // 🆕 REX 2026-07-08 — bouton IHM référencement benne fermé
    Config              := _BucketCfgPersist.Config,
    CfgTimeoutDuration     := GVL_IHM.M2TreuilBenne.Bucket.Cfg.CfgTimeoutDuration,
    BucketState        := _BucketState,
    InhibitM1           := PRG_04_Modes.instModes.InhibitM1, // 🆕 REX 2026-07-08
    InhibitM2           := PRG_04_Modes.instModes.InhibitM2,  // 🆕 REX 2026-07-08
    BypassGlobal        := GVL_IHM.M2TreuilBenne.Bucket.Bypass.Global      // 🌐 Bypass benne (RETAIN)
);

// 🆕 REX 2026-07-08 (4) — Concept 1 (écart synchro mineur) : bit0 seul (écart position, hors
// incohérence commande bit1) ne fait plus de SafeStop (fast) — bloque StartStop → rampe de décél
// NORMALE. Recalage : voir SyncEnable=FALSE (MAINT_N2), procédure déjà existante (mou de câble).
SyncMinorDeviation := (instWinchSync.ErrorId AND 16#0001) <> 16#0000;

// 🔧 REX 2026-07-08 (5) — audit sécurité : ne bloque plus StartStop dans les 2 sens (déblocage
// impossible sans Reset+MAINT_N2, régression terrain constatée, écart mécanique transitoire
// normal à l'arrêt). SignedDeltaPosM > 0 = M1 plus "haut" que M2 : la montée (Direction=+1)
// aggrave cet écart, la descente (-1) le réduit — et inversement si < 0. Seul le sens aggravant
// reste bloqué ; Méca E (FB_Safety_Winch, écart critique 2.0m) et bit1 (incohérence commande)
// restent le filet réel si l'écart continue de dériver malgré cette autorisation directionnelle.
// 🆕 REX 2026-07-08 (6) : gate global SyncSoftStopEnable — FALSE (défaut) = ces 2 sorties
// restent FALSE en permanence (bit0 déjà géré en SafeStop fast classique ci-dessus, §5bis) ;
// TRUE = active le blocage directionnel (nouvelle fonctionnalité, opt-in).
SyncMinorDeviationBlocksUp   := _SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM > 0.0);
SyncMinorDeviationBlocksDown := _SyncSoftStopEnable AND SyncMinorDeviation AND (instWinchSync.SignedDeltaPosM < 0.0);

// 🔧 REX 2026-07-19 : palier max — même valeur Auto ET Manuel depuis la suppression d'IHM_MANU
// (ex-plafond "essais progressifs" IHM_MANU, explicitement marqué TEMPORAIRE, retiré).
EffectiveMaxStepAscent   := _CommunCfgPersist.WinchMaxStepAscent;
EffectiveMaxStepDescente := _CommunCfgPersist.WinchMaxStepDescente;

// ── 1. ARBITRAGE DES CONSIGNES M1 (Joystick vs Cycle Automatique) ────────
IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
    // 🔧 REX 2026-07-08 (7) — review : gate directionnel absent de cette branche (bug trouvé en
    // review code), le cycle auto pouvait aggraver un écart mineur sans aucune protection quand
    // SyncSoftStopEnable=TRUE. Ajouté ici, symétrique à la branche manuelle ci-dessous.
    M1_Direction_Active := PRG_05_Cycle.instCycle.CmdWinchM1_Direction;
    // 🛡️ SEMI_AUTO reste conditionné par l'homme-mort : relâchement = arrêt,
    // nouvelle sollicitation valide = reprise à l'étape courante.
    M1_StartStop_Active := PRG_05_Cycle.instCycle.CmdWinchM1_StartStop
                            AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                            AND PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop
                            AND NOT ((SyncMinorDeviationBlocksUp   AND (M1_Direction_Active = 1))
                                 OR  (SyncMinorDeviationBlocksDown AND (M1_Direction_Active = -1)));
    M1_SpeedRef_Active  := MIN(PRG_05_Cycle.instCycle.CmdWinchM1_SpeedPct,
                               ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef));
ELSE
    // 🔧 REX 2026-07-19 : suppression IHM_MANU — MAINT_N1/MAINT_N2. 🆕 REX (session WINCH-BTN-01,
    // réouverture documentée T40) : le joystick n'est plus la SEULE source —
    // GVL_IHM.Modes.Cmd.TglJoystickMaster bascule vers les boutons IHM maintenus (BtnUp/BtnDown),
    // homme-mort joystick réel TOUJOURS exigé en parallèle (même leçon que le précédent bug
    // Translation M3, AF_Partie-11 v1.9 §6bis — jamais implicite). Voir
    // DOC/AUDITS/WinchIhmButtons/REGISTRE_ACTIONS_WinchIhmButtons_v1.0.md.
    // 🆕 Sélection treuil (TASK-0001, MAINT_N2 uniquement, voir FB_Modes.JoystickWinchSelectArbitrated) :
    // 1=M1 seul, 2=M2 seul, 3=Couplé — forcé à 3 (Couplé) hors MAINT_N2, IDENTIQUE quelle que
    // soit la source (joystick ou boutons) — pas de duplication de la logique de sélection.
    // 🔧 REX 2026-07-08 : + AND DeadmanArmed — NOT Busy seul insuffisant (rampe joystick met du
    // temps à redescendre à 0 après désarmement homme-mort ⇒ StartStop reste TRUE le temps de la
    // décél, M1 bougeait/frein décollait à la fin d'un cycle benne). DeadmanArmed reste FALSE
    // en continu jusqu'au repassage neutre + réappui, sans dépendre du temps de rampe.
    // 🔧 REX 2026-07-08 (5) : Direction assignée AVANT StartStop (nécessaire pour le gate directionnel ci-dessous).
    IF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
        // Source = joystick (comportement historique, inchangé)
        M1_Direction_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.Direction;
        M1_StartStop_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop AND NOT instBucket.Busy
                                AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                AND (PRG_04_Modes.instModes.JoystickWinchSelectArbitrated = 1
                                     OR PRG_04_Modes.instModes.JoystickWinchSelectArbitrated = 3)
                                AND NOT ((SyncMinorDeviationBlocksUp   AND (M1_Direction_Active = 1))
                                     OR  (SyncMinorDeviationBlocksDown AND (M1_Direction_Active = -1))); // 🔧 REX 2026-07-08 (5)
        M1_SpeedRef_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef;
    ELSE
        // 🆕 Source = boutons IHM maintenus — pilotage direct par 6 boutons (M1 Up/Down, M2 Up/Down, Both Up/Down)
        // Remplacent l'ancien sélecteur JoystickWinchSelectArbitrated.
        // Priorité : Both > M1/M2 individuels
        IF GVL_IHM.Commun.BtnWinchBothUp OR GVL_IHM.M1TreuilRetenue.Cmd.BtnUp THEN
            M1_Direction_Active := 1;
        ELSIF GVL_IHM.Commun.BtnWinchBothDown OR GVL_IHM.M1TreuilRetenue.Cmd.BtnDown THEN
            M1_Direction_Active := -1;
        ELSE
            M1_Direction_Active := 0;
        END_IF;
        M1_StartStop_Active := (M1_Direction_Active <> 0) AND NOT instBucket.Busy
                                AND (PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                     OR GVL_IHM.M1TreuilRetenue.Bypass.Global)
                                AND NOT ((SyncMinorDeviationBlocksUp   AND (M1_Direction_Active = 1))
                                     OR  (SyncMinorDeviationBlocksDown AND (M1_Direction_Active = -1)));
        M1_SpeedRef_Active  := 100.0;
    END_IF;
END_IF;

// ── 2. ARBITRAGE DES CONSIGNES M2 (Benne vs Cycle Automatique vs Joystick) ──
IF instBucket.Busy THEN
    M2_StartStop_Active := instBucket.M2_StartStop;
    M2_Direction_Active := instBucket.M2_Direction;
    M2_SpeedRef_Active  := 15.0; // Vitesse lente forcée pour fermeture benne
ELSE
    IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
        // 🔧 REX 2026-07-08 (7) — review : gate directionnel absent de cette branche, ajouté
        // symétrique à la branche manuelle ci-dessous (signe M2, voir note ci-dessous).
        M2_Direction_Active := PRG_05_Cycle.instCycle.CmdWinchM2_Direction;
        // 🛡️ Même garde homme-mort que M1 : le cycle ne poursuit jamais un mouvement
        // après relâchement du joystick.
        M2_StartStop_Active := PRG_05_Cycle.instCycle.CmdWinchM2_StartStop
                                AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                AND PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop
                                AND NOT ((SyncMinorDeviationBlocksUp   AND (M2_Direction_Active = -1))
                                     OR  (SyncMinorDeviationBlocksDown AND (M2_Direction_Active = 1)));
        M2_SpeedRef_Active  := MIN(PRG_05_Cycle.instCycle.CmdWinchM2_SpeedPct,
                                   ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef));
    ELSE
        // 🔧 REX 2026-07-19 : suppression IHM_MANU — MAINT_N1/MAINT_N2. 🆕 REX (session WINCH-BTN-01) :
        // idem M1 (voir bandeau branche M1 ci-dessus) — GVL_IHM.Modes.Cmd.TglJoystickMaster bascule la
        // SOURCE, JoystickWinchSelectArbitrated reste l'unique sélecteur treuil (2=M2 seul, 3=Couplé,
        // forcé à 3 hors MAINT_N2), IDENTIQUE quelle que soit la source.
        // 🔧 REX 2026-07-08 : + AND DeadmanArmed, même raison que M1 ci-dessus
        // 🔧 REX 2026-07-08 (5) : Direction assignée AVANT StartStop (gate directionnel)
        // 🐛 REX 2026-07-08 (7) — BUG CORRIGÉ (review code) : signe inversé pour M2. SignedDeltaPosM
        // (référentiel M1 : CablePosM1-CablePosM2+Offset) > 0 signifie M1 en avance — pour RATTRAPER,
        // M2 doit MONTER (+1), pas descendre. Donc BlocksUp (écart M1-en-avance) doit bloquer côté M2
        // le sens qui AGGRAVE, c-à-d Direction=-1 (descendre, M2 prend encore plus de retard) — PAS
        // Direction=+1 (monter, qui RATTRAPE). Symétrique inversé par rapport à M1 (qui utilise +1/-1
        // directement car SignedDeltaPosM est déjà dans SON référentiel). Même inversion appliquée
        // à la branche boutons IHM ci-dessous (BtnUp M2 = Direction -1, RATTRAPE si M1 en retard).
        IF GVL_IHM.Modes.Cmd.TglJoystickMaster THEN
            M2_Direction_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.Direction;
            M2_StartStop_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.StartStop
                                    AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                    AND (PRG_04_Modes.instModes.JoystickWinchSelectArbitrated = 2
                                         OR PRG_04_Modes.instModes.JoystickWinchSelectArbitrated = 3)
                                    AND NOT ((SyncMinorDeviationBlocksUp   AND (M2_Direction_Active = -1))
                                         OR  (SyncMinorDeviationBlocksDown AND (M2_Direction_Active = 1))); // 🔧 REX 2026-07-08 (7)
            M2_SpeedRef_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdY.SpeedRef;
        ELSE
            // 🆕 Source = boutons IHM maintenus (WINCH-BTN-01) — BtnUp M2 = enroulage/montée (+1),
            // 🆕 Source = boutons IHM maintenus — pilotage direct par 6 boutons (M1 Up/Down, M2 Up/Down, Both Up/Down)
            // Priorité : Both > M2 > M1
            IF GVL_IHM.Commun.BtnWinchBothUp OR GVL_IHM.M2TreuilBenne.Cmd.BtnUp THEN
                M2_Direction_Active := 1;
            ELSIF GVL_IHM.Commun.BtnWinchBothDown OR GVL_IHM.M2TreuilBenne.Cmd.BtnDown THEN
                M2_Direction_Active := -1;
            ELSE
                M2_Direction_Active := 0;
            END_IF;
            M2_StartStop_Active := (M2_Direction_Active <> 0)
                                    AND (PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                         OR GVL_IHM.M2TreuilBenne.Bypass.Global)
                                    AND NOT ((SyncMinorDeviationBlocksUp   AND (M2_Direction_Active = -1))
                                         OR  (SyncMinorDeviationBlocksDown AND (M2_Direction_Active = 1)));
            M2_SpeedRef_Active := 100.0;
        END_IF;
    END_IF;
END_IF;

// ── 2bis. COUPURE IMMÉDIATE M1/M2 AU SCAN EXACT DE FIN DE CYCLE BENNE ─────
// 🆕 REX 2026-07-08 : instBucket est appelé en premier (§0), donc son Busy est frais dans CE scan
// (voir §1/§2 ci-dessus) — mais AxisCmdY.StartStop/Direction viennent de FB_Joystick_0 (PRG_01),
// calculé AVANT ce scan de PRG_06. Le désarmement homme-mort sur front descendant de Benne.Busy
// (FB_Joystick §4ter-ter) ne prend donc effet qu'au scan SUIVANT (~10ms de retard structurel). Si
// l'opérateur tient encore le manche poussé au moment exact où le benne termine, M1 ET M2
// recevaient pendant ce scan la commande manche brute (RelayFwd/Rev + BrakeCmd qui s'engage puis se
// coupe aussitôt = "clignotement" du frein, constaté sur site). On force ici l'arrêt immédiat,
// sans attendre le désarmement (qui reste nécessaire pour la suite : repassage au neutre exigé).
BenneBusyFallEdge(CLK := instBucket.Busy);
IF BenneBusyFallEdge.Q THEN
    M1_StartStop_Active := FALSE;
    M2_StartStop_Active := FALSE;
END_IF;

// ── 3. SURVEILLANCE ÉCART DE SYNCHRONISATION ────────────────────────────
instWinchSync(
    // 🐛 REX 2026-07-08 (7) — BUG CORRIGÉ (retour terrain, simulation) : écart transitoire (~0.27m)
    // constaté UNIQUEMENT à l'approche d'une butée (haute 8,0 m ici), pas pendant le pilotage normal
    // (précision <0.001m confirmée par l'opérateur). Cause : ForbidAscent/ForbidDescent coupent
    // M1/M2 au même scan (couplage croisé), mais leur arrêt PHYSIQUE (rampe de décél, même en
    // simulation) n'est jamais parfaitement simultané à la position exacte — écart normal et non
    // significatif à ce moment précis, pas une vraie désynchro. Suppression pendant qu'un des deux
    // treuils est en butée (Ascent OU Descent), même principe que la suppression pendant BenneBusy
    // déjà existante. Lu avec 1 scan de retard (ForbidAscent/DescentMx_Active calculés plus bas dans
    // ce fichier) — acceptable, même raisonnement que SyncMinorDeviation ci-dessous.
    Enable          := PRG_04_Modes.instModes.SyncEnable AND NOT instBucket.Busy
                        AND NOT PRG_04_Modes.instModes.InhibitM1 AND NOT PRG_04_Modes.instModes.InhibitM2
                        AND NOT (ForbidAscentM1_Active OR ForbidAscentM2_Active
                                 OR ForbidDescentM1_Active OR ForbidDescentM2_Active), // 🆕 REX 2026-07-08 (7)
    Reset           := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk := PRG_00_Inputs.EmergencyStopOk,
    Mode            := PRG_04_Modes.instModes.Mode,
    CablePosM1      := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    CablePosM2      := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    HomedM1         := PRG_02_Encoders.instHomingM1.Homed,
    HomedM2         := PRG_02_Encoders.instHomingM2.Homed,
    SyncEnable      := PRG_04_Modes.instModes.SyncEnable,
    CfgSyncToleranceM  := _SyncCfgPersist.CfgSyncTolerance_M,
    ActiveOffsetM   := instBucket.ActiveOffsetM,

    RelayFwdM1      := instWinchM1.RelayFwd,
    RelayFwdM2      := instWinchM2.RelayFwd,
    RelayRevM1      := instWinchM1.RelayRev,
    RelayRevM2      := instWinchM2.RelayRev,
    Contactor1_M1   := instWinchM1.Contactor1,
    Contactor1_M2   := instWinchM2.Contactor1,
    Contactor2_M1   := instWinchM1.Contactor2,
    Contactor2_M2   := instWinchM2.Contactor2,
    Contactor3_M1   := instWinchM1.Contactor3,
    Contactor3_M2   := instWinchM2.Contactor3,
    Contactor4_M1   := instWinchM1.Contactor4,
    Contactor4_M2   := instWinchM2.Contactor4,
    BypassGlobal    := GVL_IHM.M1M2Sync.Bypass.Global
);

// Table active M2 (verrouille TOUS les paliers sur la combinaison réelle du palier 1 si
// vitesse lente requise pour le benne — REX 2026-07-08 : l'ancienne version mettait
// TOUS les contacteurs à FALSE pour tous les paliers, y compris le palier 1 lui-même, ce qui
// donnait un mouvement à vitesse quasi nulle/insuffisante (résistance rotorique maximale, aucun
// contacteur de vitesse engagé). Le palier 1 réel (`WinchSpeedStepTable.P1Rx`) engage déjà le
// contacteur le plus lent prévu pour un fonctionnement normal — on le duplique sur les 5 paliers
// pour que M2 reste TOUJOURS à cette vitesse pendant le benne, quelle que soit l'amplitude
// joystick (peu importe le palier sélectionné par l'hystérésis, le résultat est identique).
IF instBucket.M2_ForceSlowSpeed THEN
    M2_SpeedStepTableActive.P1R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P1R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P1R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P1R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P2R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P2R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P2R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P2R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P3R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P3R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P3R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P3R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P4R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P4R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P4R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P4R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.P5R1 := _WinchSpeedStepTable.P1R1;
    M2_SpeedStepTableActive.P5R2 := _WinchSpeedStepTable.P1R2;
    M2_SpeedStepTableActive.P5R3 := _WinchSpeedStepTable.P1R3;
    M2_SpeedStepTableActive.P5R4 := _WinchSpeedStepTable.P1R4;
    M2_SpeedStepTableActive.StepThreshold_Pct := _WinchSpeedStepTable.StepThreshold_Pct;
ELSE
    M2_SpeedStepTableActive := _WinchSpeedStepTable;
END_IF;

// ── 5. CALCUL DES LIMITES BASSES ACTIVES ET DU BLOCAGE DE DESCENTE ──────
// 🔧 REX 2026-07-07 : limite légale appliquée sur LimitLegalEnabled SEUL, plus de garde
// Mode=SEMI_AUTO — la limite légale doit stopper la descente dans TOUS les modes dès qu'elle
// est activée (constat terrain : ne s'arrêtait pas en MAINT_N1/N2 alors qu'attendu).
BottomLimitM1_Active := _WinchM1CfgPersist.CfgCableLimitDescent_M;
IF _CommunCfgPersist.LimitLegalEnabled THEN
    BottomLimitM1_Active := MAX(BottomLimitM1_Active, _CommunCfgPersist.LimitLegalDepthMinAllowed_M);
END_IF;

BottomLimitM2_Active := _WinchM2CfgPersist.CfgCableLimitDescent_M;
IF _CommunCfgPersist.LimitLegalEnabled THEN
    BottomLimitM2_Active := MAX(BottomLimitM2_Active, _CommunCfgPersist.LimitLegalDepthMinAllowed_M);
END_IF;

// ── 5bis. COUPLAGE CROISÉ M1/M2 — REX 2026-07-07 ────────────────────────
// Hors synchro (Benne.Busy ou SyncEnable=FALSE N2) : chaque treuil réagit à SA PROPRE limite/
// défaut uniquement (commande indépendante voulue). En synchro (SyncActive, mouvement cohérent
// voulu) : n'importe quel arrêt (SafeStop, limite câble, limite légale, fin de course haut) sur
// UN treuil coupe IMMÉDIATEMENT les deux — pas d'attente du filtre 500ms de FB_WinchSync.
// 🔧 REX 2026-07-07 : instBucket.M1SlipDetected ajouté à M1 uniquement (Méca C couche 1) — M2
// est déjà arrêté par son propre mécanisme SevereError interne à FB_Bucket, pas besoin ici.
// 🔧 REX 2026-07-08 (4) : instWinchSync.Error (bit0+bit1) → SEUL bit1 (incohérence commande,
// grave) reste ici en SafeStop fast. Bit0 (écart mineur) → arrêt rampe normale via StartStop
// (voir SyncMinorDeviation, §1/§2 plus haut) — Concept 1, ne pas dégrader le comportement voulu.
// 🆕 REX 2026-07-08 (6) : _SyncSoftStopEnable=FALSE (défaut) → comportement D'AVANT,
// bit0 réintégré ici en SafeStop fast classique comme n'importe quel autre défaut winch. TRUE →
// bit0 exclu d'ici, géré exclusivement par le gate directionnel StartStop (§1/§2).
SafeStopM1_Raw      := PRG_03_Safety.instSafetyWinchM1.SafeStop
                       OR ((instWinchSync.ErrorId AND 16#0002) <> 16#0000)
                       OR (NOT _SyncSoftStopEnable AND ((instWinchSync.ErrorId AND 16#0001) <> 16#0000))
                       OR instBucket.M1SlipDetected;
SafeStopM2_Raw      := PRG_03_Safety.instSafetyWinchM2.SafeStop
                       OR ((instWinchSync.ErrorId AND 16#0002) <> 16#0000)
                       OR (NOT _SyncSoftStopEnable AND ((instWinchSync.ErrorId AND 16#0001) <> 16#0000));

ForbidDescentM1_Raw := (NOT GVL_IHM.M1TreuilRetenue.Bypass.Global AND PRG_03_Safety.instSafetyWinchM1.ForbidDescent)
                       OR (_CommunCfgPersist.LimitLegalEnabled
                           AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M));
ForbidDescentM2_Raw := (NOT GVL_IHM.M2TreuilBenne.Bypass.Global AND PRG_03_Safety.instSafetyWinchM2.ForbidDescent)
                       OR (_CommunCfgPersist.LimitLegalEnabled
                           AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M));

// 🔧 REX 2026-07-15 (6) — demande utilisateur : arrêt réel encodeur en fonctionnement NORMAL,
// distinct du capteur physique (bit5/Méca D côté FB_Safety_Winch). Seuil = CableLimitAscentMx_M,
// limite ABSOLUE indépendante (même principe que CableLimitDescentM1/2_M côté descente) —
// ex-calcul en MARGE sous HomingTargetMx_M retiré : HomingTargetMx_M (8,5 m)
// est réservée à l'approche petite vitesse du capteur physique pendant un Homing explicite, PAS
// à l'exploitation normale, qui doit s'arrêter proprement à 8,0 m sans
// jamais réveiller le capteur physique (bit5/Méca D traitent son activation hors référencement
// comme une ANOMALIE — roue libre/contacteur collé — pas un fonctionnement normal).
// Même principe que la limite légale de descente ci-dessus (condition LIVE, pas de bit
// ErrorId/Reset dédié) — passe par ForbidAscentMx_Raw pour bénéficier DU MÊME couplage croisé
// M1/M2 que le capteur physique (sinon un treuil qui atteint la limite une fraction de seconde
// avant l'autre crée un écart RelayFwdM1<>RelayFwdM2 qui déclenche à tort le défaut FB_WinchSync
// bit1 "incohérence de commande" — REX terrain 2026-07-08, testé et corrigé).
// Bypass en MAINT_N2 via `HomingApproachEnable` (FB_Modes, même pattern que SyncEnable) :
// nécessite MAINT_N2 ET une case IHM activée consciemment pour dépasser CableLimitAscentMx_M
// et aller chercher le capteur physique en petite vitesse (Homing).
// 🆕 REX 2026-07-15 (8) : flag dédié — miroir IHM (GVL_IHM.M1TreuilRetenue.CableLimitAscentReached, voir
// PRG_09_Supervision), symétrique à CableLimitDescentReached. Réutilisé ci-dessous dans ForbidAscentM1_Raw.
CableLimitAscentM1Reached := PRG_02_Encoders.instHomingM1.Homed
                             AND NOT PRG_02_Encoders.instHomingM1.HomingSuspect
                             AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM >= _WinchM1CfgPersist.CfgCableLimitAscent_M)
                             AND NOT PRG_04_Modes.instModes.HomingApproachEnable;

ForbidAscentM1_Raw  := NOT GVL_IHM.M1TreuilRetenue.Bypass.Global AND (
                          PRG_03_Safety.instSafetyWinchM1.ForbidAscent
                          OR (PRG_02_Encoders.instHomingM1.Homed
                              AND NOT PRG_02_Encoders.instHomingM1.HomingSuspect
                              AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM >= _WinchM1CfgPersist.CfgTopSensorPos_M))
                          OR CableLimitAscentM1Reached
                       );
// 🐛 REX 2026-07-08 (7) — BUG CORRIGÉ (retour terrain) / REX 2026-07-08 (2) :
// La butée haute de M2 n'est décalée de l'OffsetCloseM QUE si le benne est fermé (IsClosed)
// ou en cours de fermeture (CloseReq). Sinon (benne ouvert/en cours d'ouverture), M2 doit
// s'arrêter à la butée normale (CableLimitAscentM2_M) pour s'arrêter proprement en même temps que M1.
M2_LimitShift := SEL(_BucketState.IsClosed OR instBucket.CloseReq, 0.0, _BucketCfgPersist.Config.OffsetCloseM);

// 🆕 REX 2026-07-15 (8) : idem M1 (voir ci-dessus).
CableLimitAscentM2Reached := PRG_02_Encoders.instHomingM2.Homed
                             AND NOT PRG_02_Encoders.instHomingM2.HomingSuspect
                             AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM >= (_WinchM2CfgPersist.CfgCableLimitAscent_M + M2_LimitShift))
                             AND NOT PRG_04_Modes.instModes.HomingApproachEnable;

ForbidAscentM2_Raw  := NOT GVL_IHM.M2TreuilBenne.Bypass.Global AND (
                          PRG_03_Safety.instSafetyWinchM2.ForbidAscent
                          OR (PRG_02_Encoders.instHomingM2.Homed
                              AND NOT PRG_02_Encoders.instHomingM2.HomingSuspect
                              AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM >= (_WinchM2CfgPersist.CfgTopSensorPos_M + M2_LimitShift)))
                          OR CableLimitAscentM2Reached
                       );

SafeStopM1_Active      := SafeStopM1_Raw      OR (instWinchSync.SyncActive AND SafeStopM2_Raw);
SafeStopM2_Active      := SafeStopM2_Raw      OR (instWinchSync.SyncActive AND SafeStopM1_Raw);
ForbidDescentM1_Active := ForbidDescentM1_Raw OR (instWinchSync.SyncActive AND ForbidDescentM2_Raw);
ForbidDescentM2_Active := ForbidDescentM2_Raw OR (instWinchSync.SyncActive AND ForbidDescentM1_Raw);
ForbidAscentM1_Active  := ForbidAscentM1_Raw  OR (instWinchSync.SyncActive AND ForbidAscentM2_Raw);
ForbidAscentM2_Active  := ForbidAscentM2_Raw  OR (instWinchSync.SyncActive AND ForbidAscentM1_Raw);

// ── 6. EXÉCUTION DU PILOTAGE DU TREUIL M1 ───────────────────────────────
instWinchM1(
    Enable                  := StubMachineEnableN1
                               AND (PRG_04_Modes.instModes.Mode <> E_Mode.DISABLE)
                               AND NOT PRG_04_Modes.instModes.InhibitM1, // 🔧 WINCH-CORE-01 : DISABLE neutralise réellement M1
    Reset                   := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk         := PRG_00_Inputs.EmergencyStopOk,
    Mode                    := PRG_04_Modes.instModes.Mode,
    StartStop               := M1_StartStop_Active,
    SafeStop                := SafeStopM1_Active,
    ForbidDescent           := ForbidDescentM1_Active,
    ForbidAscent            := ForbidAscentM1_Active,
    Direction               := M1_Direction_Active,
    SpeedRefPct             := M1_SpeedRef_Active,
    SpeedStepTable          := _WinchSpeedStepTable,
    // 🔧 REX 2026-07-15 (9) : EffectiveMaxStepDescente/Ascent (voir calcul plus haut) — Auto garde
    // WinchMaxStepDescente/5 inchangés, Manu applique en plus WinchMaxStepFwd/Rev (essais progressifs).
    CfgMaxStepDescente         := EffectiveMaxStepDescente,
    MaxStepAscent           := EffectiveMaxStepAscent,
    MeasuredSpeedBand       := PRG_03_Safety.instLoadEstimatorM1.SpeedBand,
    SpeedGuardEnable        := SpeedGuardEnableM1,
    SpeedGuardReady         := PRG_03_Safety.instSpeedMonitorM1.SpeedStable
                               AND NOT PRG_03_Safety.instSpeedMonitorM1.SpeedVariationConfirmed
                               AND NOT instWinchSync.Error,
    HomingApproachActive    := PRG_04_Modes.instModes.HomingApproachEnable, // 🆕 REX 2026-07-08 : vitesse lente en approche
    FwdRevSpeedFeedbackOff  := PRG_00_Inputs.M1FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback           := PRG_00_Inputs.M1BrakeFeedback,
    BypassContactorCheck    := GVL_IHM.M1TreuilRetenue.Bypass.Global OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal),
    CfgRampAccelRate           := _WinchM1CfgPersist.CfgRampAccelRate,
    CfgRampDecelNormalRate     := _WinchM1CfgPersist.CfgRampDecelNormalRate,
    CfgRampDecelFastRate       := _WinchM1CfgPersist.CfgRampDecelFastRate,
    Homed                   := PRG_02_Encoders.instHomingM1.Homed,
    HomingSuspect           := PRG_02_Encoders.instHomingM1.HomingSuspect, // 🆕 Câblage de l'incertitude M1
    CablePosM               := PRG_02_Encoders.instEncoderScaleM1.CablePosM,
    // 🔧 REX 2026-07-15 (6) : CableLimitAscentM1_M (limite ABSOLUE d'exploitation normale, ex-
    // HomingTargetM1_M) — la rampe/ralentissement de FB_Winch cible désormais la même limite que
    // ForbidAscentM1_Raw ci-dessus, pas le capteur physique (réservé au Homing).
    TopLimitM               := _WinchM1CfgPersist.CfgCableLimitAscent_M,
    BottomLimitM            := BottomLimitM1_Active,
    CfgSlowdownDistanceM       := _CommunCfgPersist.WinchSlowdownDistance_M,
    CfgSlowSpeedPct            := _CommunCfgPersist.WinchSlowSpeed_Pct,
    // 🌐 Bypass Global M1 (GVL_IHM.M1TreuilRetenue.Bypass.Global)
    BypassGlobal            := GVL_IHM.M1TreuilRetenue.Bypass.Global
);

// ── 7. EXÉCUTION DU PILOTAGE DU TREUIL M2 ───────────────────────────────
instWinchM2(
    Enable                  := StubMachineEnableN1
                               AND (PRG_04_Modes.instModes.Mode <> E_Mode.DISABLE)
                               AND NOT PRG_04_Modes.instModes.InhibitM2, // 🔧 WINCH-CORE-01 : DISABLE neutralise réellement M2
    Reset                   := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk         := PRG_00_Inputs.EmergencyStopOk,
    Mode                    := PRG_04_Modes.instModes.Mode,
    StartStop               := M2_StartStop_Active,
    SafeStop                := SafeStopM2_Active,
    ForbidDescent           := ForbidDescentM2_Active,
    ForbidAscent            := ForbidAscentM2_Active,
    Direction               := M2_Direction_Active,
    SpeedRefPct             := M2_SpeedRef_Active,
    SpeedStepTable          := M2_SpeedStepTableActive,
    // 🔧 REX 2026-07-15 (9) : idem M1 (voir §6 ci-dessus).
    CfgMaxStepDescente         := EffectiveMaxStepDescente,
    MaxStepAscent           := EffectiveMaxStepAscent,
    MeasuredSpeedBand       := PRG_03_Safety.instLoadEstimatorM2.SpeedBand,
    SpeedGuardEnable        := SpeedGuardEnableM2,
    SpeedGuardReady         := PRG_03_Safety.instSpeedMonitorM2.SpeedStable
                               AND NOT PRG_03_Safety.instSpeedMonitorM2.SpeedVariationConfirmed
                               AND NOT instWinchSync.Error,
    HomingApproachActive    := PRG_04_Modes.instModes.HomingApproachEnable, // 🆕 REX 2026-07-08 : vitesse lente en approche
    FwdRevSpeedFeedbackOff  := PRG_00_Inputs.M2FwdRevSpeedFeedbackOff, // 🔧 REX 2026-07-07
    BrakeFeedback           := PRG_00_Inputs.M2BrakeFeedback,
    BypassContactorCheck    := GVL_IHM.M2TreuilBenne.Bypass.Global OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal),
    CfgRampAccelRate           := _WinchM2CfgPersist.CfgRampAccelRate,
    CfgRampDecelNormalRate     := _WinchM2CfgPersist.CfgRampDecelNormalRate,
    CfgRampDecelFastRate       := _WinchM2CfgPersist.CfgRampDecelFastRate,
    Homed                   := PRG_02_Encoders.instHomingM2.Homed,
    HomingSuspect           := PRG_02_Encoders.instHomingM2.HomingSuspect, // 🆕 Câblage de l'incertitude M2
    CablePosM               := PRG_02_Encoders.instEncoderScaleM2.CablePosM,
    // 🔧 REX 2026-07-15 (6) : idem M1 (voir ci-dessus), + M2_LimitShift (décalage benne fermé).
    TopLimitM               := _WinchM2CfgPersist.CfgCableLimitAscent_M + M2_LimitShift,
    BottomLimitM            := BottomLimitM2_Active,
    CfgSlowdownDistanceM       := _CommunCfgPersist.WinchSlowdownDistance_M,
    CfgSlowSpeedPct            := _CommunCfgPersist.WinchSlowSpeed_Pct,
    // 🌐 Bypass Global M2 (GVL_IHM.M2TreuilBenne.Bypass.Global)
    BypassGlobal            := GVL_IHM.M2TreuilBenne.Bypass.Global
);

// ── 8. ALIMENTATION PRG_10_Outputs (sorties physiques) ──────────────────
// 🔴🔧 REX 2026-07-07 : PRG_10_Outputs est une tâche indépendante (MainTask, PouList),
// jamais appelée avec paramètres — ses VAR_INPUT restaient à FALSE en permanence, y compris
// sur machine réelle (aucun relais/contacteur/frein ne s'activait jamais). Alimentation directe
// ici, AVANT PRG_10_Outputs dans l'ordre de tâche (position 6 < 10, même cycle API).
PRG_10_Outputs.M1RelayFwd        := instWinchM1.RelayFwd;
PRG_10_Outputs.M1RelayRev        := instWinchM1.RelayRev;
PRG_10_Outputs.M1SpeedContactor1 := instWinchM1.Contactor1;
PRG_10_Outputs.M1SpeedContactor2 := instWinchM1.Contactor2;
PRG_10_Outputs.M1SpeedContactor3 := instWinchM1.Contactor3;
PRG_10_Outputs.M1SpeedContactor4 := instWinchM1.Contactor4;
PRG_10_Outputs.M1BrakeCmd        := instWinchM1.BrakeCmd;

PRG_10_Outputs.M2RelayFwd        := instWinchM2.RelayFwd;
PRG_10_Outputs.M2RelayRev        := instWinchM2.RelayRev;
PRG_10_Outputs.M2SpeedContactor1 := instWinchM2.Contactor1;
PRG_10_Outputs.M2SpeedContactor2 := instWinchM2.Contactor2;
PRG_10_Outputs.M2SpeedContactor3 := instWinchM2.Contactor3;
PRG_10_Outputs.M2SpeedContactor4 := instWinchM2.Contactor4;
PRG_10_Outputs.KoboldContactorCmd := PRG_05_Cycle.instCycle.KoboldContactorCmd;
PRG_10_Outputs.M2BrakeCmd        := instWinchM2.BrakeCmd;

// 🧪 Références pour tests PLC (fenêtre de passage GVL_Simulation)
// 🔧 REX 2026-07-17 : ":=" sur une REFERENCE TO fait une COPIE DE VALEUR (écrit à travers la
// référence), PAS un rebind -- sur une référence pas encore liée (1er scan), ça écrit à une
// adresse invalide -> ACCESS VIOLATION runtime CODESYS. "REF=" est l'opérateur dédié au rebind.
GVL_Simulation.LinkBucket   REF= instBucket;
GVL_Simulation.LinkWinchM2  REF= instWinchM2;

// === IMPLEMENTATION (corps du PROGRAM PRG_07_TranslationControl) ===

// ── 0. DÉCODAGE MOT CAPTEURS (exécuté en position 0 dans PRG_00_Inputs) ──────

// ── 1. ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ──────────────────
IF PRG_04_Modes.instModes.Mode = E_Mode.SEMI_AUTO THEN
    // Mode Auto/Semi-Auto : Consigne issue du séquenceur de cycle
    M3_PositioningActive  := TRUE;
    SelTarget    := PRG_05_Cycle.instCycle.CmdTranslationM3_Target;
    // 🛡️ SEMI_AUTO reste conditionné par l'homme-mort : relâchement = arrêt,
    // nouvelle sollicitation valide = reprise à l'étape courante.
    M3_StartStop_Active  := PRG_05_Cycle.instCycle.CmdTranslationM3_Start
                            AND PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                            AND PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.StartStop;
    M3_SpeedRef_Active   := MIN(_TranslationAutoSpeedCap_Pct,
                                ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.SpeedRef));

    // Détermination automatique du sens de marche selon la cible :
    // - Trémie (cible 1) = Marche Avant (Direction := 1)
    // - P2/P1/Maintenance (cibles 2/3/4) = Marche Arrière (Direction := -1)
    IF SelTarget = 1 THEN
        M3_Direction_Active := 1;
    ELSE
        M3_Direction_Active := -1;
    END_IF;
// ── 1bis. MAINT_N1/N2 — 2ᵉ source d'arbitrage (mirroir PRG_06_WinchControl §1/§2) ──
// 🔧 REX 2026-07-19 : ex-libellé "IHM_MANU" (bypass supprimé) — cette branche est désormais
// gatée par Mode (MAINT_N1/N2), pas par un flag ManuActive séparé.
// 🆕 REX 2026-07-16 : remplace l'ex-bypass direct M3_CommandWord dans PRG_10_Outputs — M3 est
// désormais piloté par la MÊME instance instTranslationM3 (FB_Translation) qu'en Auto, avec la
// rampe accel/décel et l'interlock changement de sens natifs, sous surveillance réelle de
// FB_Safety_Translation (voir PRG_03_Safety, Enable désormais inconditionnel).
ELSIF (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N1)
   OR (PRG_04_Modes.instModes.Mode = E_Mode.MAINT_N2) THEN
    // 🛠️ Maintenance N1/N2 : sous-mode explicite IHM.
    // SelPositioning=FALSE : jog libre, aucun capteur n'arrête hors fins de course.
    // SelPositioning=TRUE : le capteur de SelTarget arrête le mouvement.
    M3_PositioningActive := GVL_IHM.TranslationM3.Cmd.SelPositioning;
    SelTarget := SEL(M3_PositioningActive,
                             0,
                             StubTranslationPositionSelect_IHM);

    IF NOT GVL_IHM.TranslationM3.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnFwd THEN
        M3_Direction_Active := 1;   // → Trémie (+1)
    ELSIF NOT GVL_IHM.TranslationM3.Cmd.TglJoystickMaster AND GVL_IHM.TranslationM3.Cmd.BtnRev THEN
        M3_Direction_Active := -1;  // → Maintenance (-1)
    ELSIF GVL_IHM.TranslationM3.Cmd.TglJoystickMaster THEN
        M3_Direction_Active := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.Direction;
    ELSE
        // Boutons sélectionnés sans BtnFwd/BtnRev : jamais de reprise joystick implicite.
        M3_Direction_Active := 0;
    END_IF;
    // 🛡️ REX 2026-07-19 (revue mission IHM_MANU) : DeadmanArmed exigé même en pilotage boutons
    // IHM (BtnFwd/BtnRev), pas seulement en pilotage joystick — sinon les boutons IHM
    // permettaient un mouvement M3 sans homme-mort (écart relevé par la revue de sécurité).
    // 🌐 Bypass.Global = TRUE → ignore la condition homme-mort (test/simulation)
    M3_StartStop_Active := (M3_Direction_Active <> 0)
                           AND (PRG_01_Diagnostics.FB_Joystick_0.DeadmanArmed
                                OR GVL_IHM.TranslationM3.Bypass.Global)
                           AND (NOT GVL_IHM.TranslationM3.Cmd.TglJoystickMaster
                                OR PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.StartStop);

    // 🎯 Vitesse : conserve GVL_IHM.TranslationM3.Cmd.SetFreq_Hz (consigne Hz réglable opérateur,
    // limitée par PRG_10_Outputs à _TranslationMaxFreq_Hz) comme cible pleine échelle — identique
    // pour boutons HMI ET joystick (reproduit exactement l'ex-bypass PRG_10_Outputs, ex-lignes
    // 250-251/271-272 : SetFreqHz = 100%, déflexion joystick = % de cette cible). Convertie en
    // pourcentage car SpeedRefPct (entrée FB_Translation) est une échelle 0-100%, pas des Hz.
    // 🔧 Si SetFreq_Hz = 0 (pas configuré), on utilise une vitesse par défaut de 30%.
    FreqPct := SEL(GVL_IHM.TranslationM3.Cmd.SetFreq_Hz > 0.0,
                  (GVL_IHM.TranslationM3.Cmd.SetFreq_Hz / _TranslationMaxFreq_Hz) * 100.0,
                  30.0); // défaut 30% si SetFreq_Hz non renseigné
    M3_SpeedRef_Active := SEL(GVL_IHM.TranslationM3.Cmd.TglJoystickMaster,
                              FreqPct,
                              (ABS(PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.SpeedRef) / 100.0) * FreqPct);
ELSE
    // Mode Manuel/Maintenance : Consignes issues du Joystick et sélecteur HMI
    M3_PositioningActive := FALSE;
    SelTarget    := StubTranslationPositionSelect_IHM;
    M3_StartStop_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.StartStop;
    M3_Direction_Active  := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.Direction;
    M3_SpeedRef_Active   := PRG_01_Diagnostics.FB_Joystick_0.AxisCmdX.SpeedRef;
END_IF;

// 🔄 Inversion de sens IHM (mise en service)
IF GVL_IHM.TranslationM3.Cmd.InvertDirection THEN
    M3_Direction_Active := M3_Direction_Active * (-1);
END_IF;

// 🛡️ Limitation finale M3 : toute source de commande (joystick, IHM ou cycle) arrive
// au variateur dans la plage physique autorisée 0..100 %. Ce garde-fou complète
// les limitations de FB_AxisScale/FB_Ramp et ne remplace pas la chaîne Safety.
M3_SpeedRef_Active := LIMIT(0.0, ABS(M3_SpeedRef_Active), 100.0);

// 🆕 REX 2026-07-18 : cible Maintenance (4) bloquée hors MAINT_N2 (AF_Partie-02 v2.12 §3bis) —
// arbitrage centralisé dans FB_Modes (aucun re-test de Mode ici), refuse toute cible si interdite.
IF (SelTarget = 4) AND NOT PRG_04_Modes.instModes.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// Câblage du capteur de butée de la cible sélectionnée (PV exclu : jamais une cible d'arrêt)
CASE SelTarget OF
    1: M3_PositionSensorTarget := PRG_00_Inputs.TranslationPosTremie;
    2: M3_PositionSensorTarget := PRG_00_Inputs.TranslationPosP2;
    3: M3_PositionSensorTarget := PRG_00_Inputs.TranslationPosP1;
    4: M3_PositionSensorTarget := PRG_00_Inputs.TranslationPosMaintenance;
ELSE
    M3_PositionSensorTarget := FALSE;   // Aucun capteur visé
END_CASE;

// ── 2. EXÉCUTION DU PILOTAGE DU TRANSLATION M3 ──────────────────────────────
instTranslationM3(
    Enable                  := PRG_06_WinchControl.StubMachineEnableN1
                               AND (PRG_04_Modes.instModes.Mode <> E_Mode.DISABLE), // 🔧 WINCH-CORE-01 : DISABLE neutralise M3
    Reset                   := PRG_09_Supervision.FaultMachineReset_IHM,
    EmergencyStopOk         := PRG_00_Inputs.EmergencyStopOk,
    Mode                    := PRG_04_Modes.instModes.Mode,
    StartStop               := M3_StartStop_Active,
    SafeStop                := PRG_03_Safety.instSafetyTranslationM3.SafeStop,
    Direction               := M3_Direction_Active,
    SpeedRefPct             := M3_SpeedRef_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensor          := PRG_00_Inputs.TranslationPosPV, // 🆕 remplace ApproachTime (timer) — ralentissement avant Trémie uniquement
    LimitSwitchFwd          := PRG_00_Inputs.instPositionDecoder.LimitSwitchFwd, // 🆕 dérivé du mot capteurs (extrême Trémie, mot=11111)
    LimitSwitchRev          := PRG_00_Inputs.instPositionDecoder.LimitSwitchRev, // 🆕 dérivé du mot capteurs (extrême Maintenance, mot=00000)
    DriveStatusWord         := PRG_00_Inputs.M3_StatusWord_Filtered,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_00_Inputs.M3_ActualFrequencyHz_Filtered) / 100.0,
    CfgRampAccelRate           := _TranslationRampAccelRate_Pct,      // 🔧 PERSISTENT depuis GVL_PERSISTENT
    CfgRampDecelNormalRate     := _TranslationRampDecelNormal_Pct,    // 🔧 idem
    CfgRampDecelFastRate       := _TranslationRampDecelFast_Pct,      // 🔧 idem
    DriveFreqScaleMaxHz     := _TranslationMaxFreq_Hz,             // 🔧 source unique depuis PERSISTENT
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_00_Inputs.M3BrakeFeedback, instTranslationM3.BrakeCmd),
    BypassContactorCheck    := GVL_IHM.TranslationM3.Bypass.Global OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal),
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch
);

// 🔴 Recopie commande de frein translation
PRG_10_Outputs.TranslationBrakeCmd := instTranslationM3.BrakeCmd;

// === IMPLEMENTATION (corps du PROGRAM PRG_08_AuxiliaryControl) ===

// 🌡️ Retour thermique brut (NC) — entrée physique ThermHydraulique_DI ;
// tant que non câblé, ce point lira FALSE côté image process réelle si absent, d'où l'OR simulation.
HydraulicFaultOk := ThermHydraulique_DI OR (GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorHydraulicThermalIsReal);

// === IMPLEMENTATION (corps du PROGRAM PRG_09_Supervision) ===

// ── 0. HORLOGE CLIGNOTEMENT SYSTÈME (GVL_Global.BlinkClock) ───────────────
// 🧩 Réutilisation lib Util (Partie3 §0) : bloc standard BLINK, pas de TON maison —
// gère nativement un rythme allumé/éteint ASYMÉTRIQUE (TimeHigh ≠ TimeLow), contrairement
// au motif TON manuel de FB_Output.st (symétrique 500/500, propre à l'option relais).
// 🔧 REX 2026-07-16 : durées réglables sans recompiler (GVL_PERSISTENT._BlinkTimeOn/_BlinkTimeOff,
// défaut 1s allumé / 800ms éteint) — un seul rythme partagé pour tous les voyants IHM/diag qui
// clignotent pareil.
// 💡 Un voyant a besoin d'un AUTRE rythme ? Instancier son propre BLINK localement (Util) avec
// ses propres TimeHigh/TimeLow — ne pas détourner ce bit partagé pour un rythme différent.
instBlink1Hz(
    ENABLE   := TRUE,
    TIMEHIGH := _BlinkTimeOn,
    TIMELOW  := _BlinkTimeOff
);
GVL_Global.BlinkClock := instBlink1Hz.OUT;


// ── 1. ACQUISITION DES DEMANDES / BOUTONS DE L'IHM ────────────────────────
GVL_Modes_Stub.ModeRequest_IHM         := GVL_IHM.Modes.Cmd.SelMode;
GVL_Modes_Stub.SyncEnableRequest_IHM   := GVL_IHM.M1M2Sync.Cmd.SelSyncEnable; // 🔧 REX 2026-07-08 : renommé, polarité inversée
StubTranslationPositionSelect_IHM          := GVL_IHM.TranslationM3.Cmd.SelTarget;

// 🧪 Commandes de test Translation depuis la supervision.
// Verrouillage obligatoire : aucune surcharge IHM ne peut être active hors simulation.
IF GVL_Simulation.SimulationModeActive THEN
    GVL_PLC_Tests.OverrideM3SensorsWordActive := GVL_IHM.TranslationM3.Test.SensorsWordActive;
    GVL_PLC_Tests.OverrideM3SensorsWord       := GVL_IHM.TranslationM3.Test.SensorsWord;
    GVL_PLC_Tests.OverrideM3AtTremie          := GVL_IHM.TranslationM3.Test.AtTremie;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen    := GVL_IHM.TranslationM3.Test.BrakeStuckOpen;
    GVL_PLC_Tests.OverrideM3PhantomFreq       := GVL_IHM.TranslationM3.Test.PhantomFreq;
ELSE
    GVL_PLC_Tests.OverrideM3SensorsWordActive := FALSE;
    GVL_PLC_Tests.OverrideM3AtTremie          := FALSE;
    GVL_PLC_Tests.OverrideM3BrakeStuckOpen    := FALSE;
    GVL_PLC_Tests.OverrideM3PhantomFreq       := FALSE;
END_IF;

// Signal d'acquittement défauts domaine sécurité/métier — JAMAIS Modes/Cycle (REX 2026-07-07)
FaultMachineReset_IHM := GVL_IHM.Modes.Cmd.BtnFaultReset
                    OR GVL_IHM.M1TreuilRetenue.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnReset;

// 🔴 REX 2026-07-07 : au moins un défaut actif dans le domaine couvert par FaultMachineReset_IHM
// (même périmètre exact que les 17 blocs alimentés par ce reset — voir bandeau en tête de fichier).
// Sert à savoir, côté IHM, quand un appui sur BtnFaultReset est utile/attendu.
GVL_IHM.Modes.State.AnyFaultActive :=
       PRG_01_Diagnostics.instDiagCanOpen.Error
    OR PRG_01_Diagnostics.instDiagEthercat.Error
    OR PRG_01_Diagnostics.FB_Joystick_0.Error
    OR (NOT PRG_04_Modes.instModes.InhibitM1 AND (
           PRG_02_Encoders.instEncoderAbsM1.Error
        OR PRG_02_Encoders.instHomingM1.Error
        OR PRG_02_Encoders.instEncoderSafetyM1.Error
        OR PRG_03_Safety.instSafetyWinchM1.Error
        OR PRG_06_WinchControl.instWinchM1.Error
    ))
    OR (NOT PRG_04_Modes.instModes.InhibitM2 AND (
           PRG_02_Encoders.instEncoderAbsM2.Error
        OR PRG_02_Encoders.instHomingM2.Error
        OR PRG_02_Encoders.instEncoderSafetyM2.Error
        OR PRG_03_Safety.instSafetyWinchM2.Error
        OR PRG_06_WinchControl.instWinchM2.Error
    ))
    OR PRG_03_Safety.instSafetyTranslationM3.Error
    OR PRG_06_WinchControl.instWinchSync.Error
    OR PRG_06_WinchControl.instBucket.Error
    OR PRG_07_TranslationControl.instTranslationM3.Error
    OR PRG_10_Outputs.RedundancyTestFailed
    OR PRG_10_Outputs.EmergencyArmingFailed;

// 🧨 REX 2026-07-07 : remontée IHM de la coupure puissance amont — polarité "alarme" (TRUE=
// problème), PAS celle de PowerCutOff_A_RQ (qui est en fail-safe maintenu, TRUE=OK depuis
// l'inversion de polarité). On relit directement les .PowerCutOff sources, pas la sortie physique.
GVL_IHM.Modes.State.PowerCutOffActive := PRG_03_Safety.instSafetyWinchM1.PowerCutOff
                                 OR PRG_03_Safety.instSafetyWinchM2.PowerCutOff
                                 OR PRG_03_Safety.instSafetyTranslationM3.PowerCutOff
                                 OR GVL_IHM.Modes.Cmd.BtnEmergencyCutOff;

// 🆕 REX 2026-07-08 : thermique frein commun M1/M2/M3 — signal UNIQUE (1 seul fil, pas de sens à
// le dupliquer par axe), remonté une seule fois au niveau global GVL_IHM (même principe que
// TopPositionSensorActive ci-dessus, PAS dans WinchM1/WinchM2/Translation).
GVL_IHM.Commun.BrakeThermalFault := NOT PRG_00_Inputs.BrakeThermalFeedback;
GVL_IHM.Commun.PhaseRotationFault := NOT PRG_00_Inputs.PhaseRotationOk; // 🆕 REX 2026-07-08 — commun M1/M2/M3, invisible IHM avant
GVL_IHM.Commun.HydraulicThermalFault := NOT PRG_08_AuxiliaryControl.HydraulicFaultOk; // 🆕 REX 2026-07-18 — diagnostic seul, aucune commande PLC

// 💓 Heartbeat IHM↔PLC — le toggle IHM est lu directement en PRG_01 ; ici, on publie
// les diagnostics calculés au même scan pour l'affichage et l'historisation IHM.
GVL_IHM.Commun.TglHeartbeatPlc  := PRG_01_Diagnostics.instIhmHeartbeat.TglHeartbeatPlc;
GVL_IHM.Commun.HeartbeatIhmOk      := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmOk;
GVL_IHM.Commun.HeartbeatIhmTimeout := PRG_01_Diagnostics.instIhmHeartbeat.HeartbeatIhmTimeout;
GVL_IHM.Commun.HeartbeatIhmElapsed := PRG_01_Diagnostics.instIhmHeartbeat.TimeSinceIhmEdge;

// 🔧 REX 2026-07-07 — Séquence réarmement AU (voir DOC/AF_Partie-01_Analyse_Fonctionnelle_v1.6.md §Sécurité électrique)
// EmergencyArmingBusy couvre TOUTE la séquence (auto-test A/B + pulse + confirmation + verrouillage),
// pas seulement le pulse — ArmingSeqStep<>0 englobe déjà tout sauf le verrouillage final.
GVL_IHM.Modes.State.EmergencyChainOk    := PRG_00_Inputs.EmergencyChain;
GVL_IHM.Modes.State.PowerContactorOk    := PRG_00_Inputs.EmergencyStopOk;
GVL_IHM.Modes.State.EmergencyArmingBusy := (PRG_10_Outputs.ArmingSeqStep <> 0) OR PRG_10_Outputs.EmergencyArmingLockoutActive;
GVL_IHM.Modes.State.EmergencyArmable    := PRG_00_Inputs.EmergencyChain
                                    AND (PRG_10_Outputs.ArmingSeqStep = 0)
                                    AND NOT PRG_10_Outputs.EmergencyArmingLockoutActive
                                    AND NOT PRG_10_Outputs.RedundancyTestFailed;
GVL_IHM.Modes.State.RedundancyTestFailed := PRG_10_Outputs.RedundancyTestFailed;
GVL_IHM.Modes.State.EmergencyArmingFailed := PRG_10_Outputs.EmergencyArmingFailed;

// 🔧 REX 2026-07-07 : ancien pont IF/ELSIF vers GVL_Encoder_Stub supprimé (bugué — ne pouvait
// homer qu'un seul treuil à la fois). GVL_IHM.M1TreuilRetenue/M2.BtnHome sont désormais câblés
// directement dans PRG_02_Encoders.st (instHomingM1/M2.Home) — homing simultané possible.

// ℹ️ BtnCalibrate joystick : lu directement depuis GVL_IHM.JOY1Joystick.Cmd.BtnCalibrate dans PRG_01_Diagnostics (ligne 48)


// ── 2. INITIALISATION IHM DEPUIS GVL_PERSISTENT (Boot) ───────────────────
// 🐛 FIX 2026-07-23 : sentinelles `= 0.0` remplacées par un flag `Initialized`/`CfgInitialized`
// dédié (défaut FALSE non ambigu). L'ancienne sentinelle `CfgTopSensorPos_M = 0.0` ne se
// déclenchait JAMAIS (défaut struct réel = 8.5, ST_WinchCfg.st) → ce bloc M1/M2 ne s'exécutait
// plus après un reset RETAIN (ex. changement de struct ST_*HMI, comme lors de cette session) et
// TOUTE la config (paliers, rampes, limites câble, synchro...) retombait au défaut struct brut
// sans jamais se resynchroniser depuis le vrai PERSISTENT. Idem pour `Sync.CfgSyncTolerance_M`
// (défaut réel 0.25, piège documenté REX 2026-07-08 (5) ci-dessous, désormais clos).
// 📄 Voir DOC/AF_Partie-07_Interface_IHM_v1.8.md.
instCfgPersistBridgeWinchM1(Hmi := GVL_IHM.M1TreuilRetenue.Cfg, Persist := _WinchM1CfgPersist);
IF instCfgPersistBridgeWinchM1.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeWinchM2(Hmi := GVL_IHM.M2TreuilBenne.Cfg, Persist := _WinchM2CfgPersist);
IF instCfgPersistBridgeWinchM2.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeSync(Hmi := GVL_IHM.M1M2Sync.Cfg, Persist := _SyncCfgPersist);
IF instCfgPersistBridgeSync.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeBucket(Hmi := GVL_IHM.M2TreuilBenne.Bucket.Cfg, Persist := _BucketCfgPersist);
IF instCfgPersistBridgeBucket.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCommun(Hmi := GVL_IHM.Commun.Cfg, Persist := _CommunCfgPersist);
IF instCfgPersistBridgeCommun.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycle(Hmi := GVL_IHM.Cycle.Cfg, Persist := _CycleCfgPersist);
IF instCfgPersistBridgeCycle.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// ── 2bis. ACQUITTEMENT RESTAURATION CONFIG (front, doctrine reset=front) ───
// 🐛 FIX 2026-07-23 : `ConfigRestoredFromPersistent` ne doit JAMAIS disparaître tout seul —
// même doctrine que les défauts métier (cause disparue + appui reset conscient pour effacer).
// Tant que l'opérateur n'a pas vérifié/acquitté, le bit reste visible à l'IHM.
instAckConfigRestored(CLK := GVL_IHM.Commun.BtnAckConfigRestored);
IF instAckConfigRestored.Q THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
END_IF;

// 🌐 Restauration des bypass RETAIN au boot UNIQUEMENT — co-localisation flag Initialized
// Après ça, seule la sauvegarde IHM→RETAIN fonctionne (jamais l'inverse).
// Évite le bug où une écriture IHM était écrasée par la restauration.
IF NOT GVL_IHM.TranslationM3.Bypass.Initialized THEN
    IF BypassTranslationGlobal THEN
        GVL_IHM.TranslationM3.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.TranslationM3.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M1TreuilRetenue.Bypass.Initialized THEN
    IF BypassWinchM1Global THEN
        GVL_IHM.M1TreuilRetenue.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1TreuilRetenue.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M2TreuilBenne.Bypass.Initialized THEN
    IF BypassWinchM2Global THEN
        GVL_IHM.M2TreuilBenne.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M2TreuilBenne.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.Network.Bypass.Initialized THEN
    IF BypassNetworkGlobal THEN
        GVL_IHM.Network.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.Network.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M1M2Sync.Bypass.Initialized THEN
    IF BypassSyncGlobal THEN
        GVL_IHM.M1M2Sync.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1M2Sync.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M2TreuilBenne.Bucket.Bypass.Initialized THEN
    IF BypassBucketGlobal THEN
        GVL_IHM.M2TreuilBenne.Bucket.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M2TreuilBenne.Bucket.Bypass.Initialized := TRUE;
END_IF;

// 🌐 BypassRestoreDone est désormais 100% orphelin (tous les bypass ont migré sur leur propre flag .Initialized).
// 🐛 FIX 2026-07-23 : BypassRestoreDone en VAR RETAIN (évite re-forcage au boot si GVL_IHM intact).
IF NOT BypassRestoreDone THEN
    BypassRestoreDone := TRUE;
END_IF;


// ── 3. PROPAGATION DES RÉGLAGES IHM → PERSISTANCE ───────────────────────
// 🐛 FIX 2026-07-23 : chaque bloc ci-dessous est désormais gardé par le flag `Cfg.Initialized`/
// `Sync.CfgInitialized` posé en §2 — défense en profondeur : même si l'ordre du fichier changeait
// un jour, on ne peut plus écraser le vrai PERSISTENT avec une valeur GVL_IHM fraîchement
// resettée au défaut struct AVANT que la restauration (§2) ait eu lieu. Revue sécurité 2026-07-23.
// 🌐 Sauvegarde des bypass RETAIN (survit au warm restart / download)
BypassTranslationGlobal     := GVL_IHM.TranslationM3.Bypass.Global;
BypassWinchM1Global         := GVL_IHM.M1TreuilRetenue.Bypass.Global;
BypassWinchM2Global         := GVL_IHM.M2TreuilBenne.Bypass.Global;
BypassSyncGlobal            := GVL_IHM.M1M2Sync.Bypass.Global;
BypassNetworkGlobal         := GVL_IHM.Network.Bypass.Global;
BypassBucketGlobal          := GVL_IHM.M2TreuilBenne.Bucket.Bypass.Global;
// 🔧 REX 2026-07-07 : plus de garde Mode=SEMI_AUTO, cohérent avec PRG_06_WinchControl.st §5
// (la limite légale s'applique désormais dans tous les modes dès qu'elle est activée).
GVL_IHM.Commun.LimitLegalReached         := _CommunCfgPersist.LimitLegalEnabled
                                            AND ((NOT PRG_04_Modes.instModes.InhibitM1 AND (PRG_02_Encoders.instEncoderScaleM1.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M))
                                                 OR (NOT PRG_04_Modes.instModes.InhibitM2 AND (PRG_02_Encoders.instEncoderScaleM2.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M)));

GVL_IHM.Commun.TopPositionSensorActive   := NOT PRG_00_Inputs.TopPositionSensor;


// ── 4. BYPASS DE SIMULATION POUR L'IHM (état effectif par device, voir DOC/AF_Partie-13_Fonction_Simulation_v1.2.md) ──────
// 🔧 REX (session Bypass) : structs Bypass dedies par metier (voir DOC/AUDITS/Bypass/REGISTRE_ACTIONS_Bypass_v1.0.md)
// — ContactorFeedback reste par axe (materiel propre a chaque treuil/translation), SlackCable et
// TopPositionSensor passent dans Commun.Bypass (capteur physique UNIQUE partage M1/M2, plus de duplication).
GVL_IHM.M1TreuilRetenue.Bypass.ContactorFeedback := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM1ContactorFeedbackIsReal;
GVL_IHM.M2TreuilBenne.Bypass.ContactorFeedback := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM2ContactorFeedbackIsReal;
GVL_IHM.TranslationM3.Bypass.ContactorFeedback := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorM3ContactorFeedbackIsReal;
GVL_IHM.Commun.Bypass.SlackCable        := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorSlackCableIsReal;
GVL_IHM.Commun.Bypass.TopPositionSensor := GVL_Simulation.SimulationModeActive AND NOT GVL_Simulation.SensorTopPositionIsReal;


// ── 5. MAPPING ÉTATS TREUIL M1 → IHM ─────────────────────────────────────
GVL_IHM.M1TreuilRetenue.State.Position_M                 := PRG_02_Encoders.instEncoderScaleM1.CablePosM;
GVL_IHM.M1TreuilRetenue.State.MeasuredSpeed_Mps          := PRG_03_Safety.instSafetyWinchM1.MeasuredSpeedMps;
GVL_IHM.M1TreuilRetenue.State.SpeedDelta_Mps             := PRG_03_Safety.instSpeedMonitorM1.SpeedDeltaMps;
GVL_IHM.M1TreuilRetenue.State.SpeedVariationDetected   := PRG_03_Safety.instSpeedMonitorM1.SpeedVariationDetected;
GVL_IHM.M1TreuilRetenue.State.SpeedVariationConfirmed  := PRG_03_Safety.instSpeedMonitorM1.SpeedVariationConfirmed;
GVL_IHM.M1TreuilRetenue.State.SpeedStable             := PRG_03_Safety.instSpeedMonitorM1.SpeedStable;
GVL_IHM.M1TreuilRetenue.State.SpeedMonitorError        := PRG_03_Safety.instSpeedMonitorM1.Error;
GVL_IHM.M1TreuilRetenue.State.SpeedMonitorErrorId      := PRG_03_Safety.instSpeedMonitorM1.ErrorId;
GVL_IHM.M1TreuilRetenue.State.EstimatedLoadPct          := PRG_03_Safety.instLoadEstimatorM1.EstimatedLoadPct;
GVL_IHM.M1TreuilRetenue.State.LoadEstimateConfigured   := PRG_03_Safety.instLoadEstimatorM1.Configured;
GVL_IHM.M1TreuilRetenue.State.SpeedGuardLimited        := PRG_06_WinchControl.instWinchM1.SpeedGuardLimited;
GVL_IHM.M1TreuilRetenue.State.SpeedRef_Pct               := PRG_06_WinchControl.instWinchM1.SpeedRamp.Current;
